UPDATE submission_sites SET rw_source_lead='A 92,000-star hand-curated index of MCP servers where entries arrive by pull request, with a fast lane reserved for contributions drafted by agents.', rw_what_you_get='A one-line mention in a widely read README that feeds a large ecosystem of downstream MCP lists, putting your server in front of developers browsing by category rather than by search.', rw_you_need='["A public code repository, since every listing links to one and the whole format is a server name pointing at its repo","A GitHub account to fork the index and open the pull request from","A category that honestly fits one of the roughly fifty existing headings"]', rw_eligibility='To be listed you need a public repository, a GitHub account to submit a pull request from, and a category that genuinely matches one of the fifty or so headings in the index. Entries are rejected when there is only a hosted server with no repository to link to, or when the project is a client, framework or directory rather than an MCP server, because each of those has its own list.', rw_submit_steps='["1 Pick the right heading. The README groups servers under roughly fifty categories from Aggregators to Workplace and Productivity; read the one-line blurb under each and choose where a newcomer would naturally look.","2 Fork the repository and create a branch off main, then edit README.md in place. There is no form, generator or separate data file — the README itself is the list.","3 Add one line in the house format: the repository path as link text, the legend emoji, then a dash and a short description. The legend key near the top of the README defines the language, cloud-versus-local marker and supported operating systems.","4 Open a pull request with one server per request. Contributions authored by an agent should end the title with the robot marker described in CONTRIBUTING to qualify for the fast merge lane."]', rw_submit_requirements='["A public repository URL","A single sentence describing what the server does","The legend emoji for language, cloud or local, and operating system","An install command, commonly appended to the description"]', rw_rejection_reasons='["Hosted-only servers with no public repository to link to, and projects that are clients, frameworks or directories instead of MCP servers"]', rw_gotchas='["Several thousand pull requests sit open against the repository, so expect a wait and avoid timing a launch around the listing appearing.","Every entry must point to a repository; a hosted-only server is not eligible until you publish a small public repo with a README and connection details.","GitHub marks external links in a rendered README as nofollow, so the value here is discovery by readers and scrapers rather than link equity."]', rw_faq='[{"question":"How long does approval take for Awesome MCP Servers?","answer":"The list does not state a review time, and the large open pull request queue suggests it can take a while."},{"question":"Is submitting to Awesome MCP Servers free?","answer":"Yes. Contributions are free; the cost is opening a pull request against the public repository."},{"question":"Does an Awesome MCP Servers listing pass link equity?","answer":"No. Links in the rendered README are nofollow, and the site carries a domain rating of 97."},{"question":"Do I need to link back to Awesome MCP Servers?","answer":"No return link or badge is required."},{"question":"What gets a submission rejected?","answer":"Hosted servers without a public repository, and anything that is a client, framework or directory rather than an MCP server."}]', rw_summary='Awesome MCP Servers is a community-maintained directory of MCP servers, assembled through GitHub pull requests and organised into roughly fifty categories. Entries are free and nofollow, with no return link required, and the list''s domain rating is 97.', rw_fact_points='["Submission happens through a GitHub pull request","The listing is free and carries a nofollow link","No badge or return link is expected","Projects are accepted across MCP servers, open source and developer tools"]', rw_submission_checks='["Confirm you have a public repository, since the list is built entirely from links to repos.","Choose the category a stranger would search, not the one that flatters your project.","Follow the exact line format in the README, including the legend emoji.","Do not plan a launch around the listing; the review queue is long."]', rw_seo_title='Awesome MCP Servers: Submit via PR, DR 97', rw_seo_description='How to submit to Awesome MCP Servers: free pull-request listing, nofollow link, no badge. Steps and pitfalls from the 2026-11-16 snapshot.' WHERE slug='awesome-mcp-servers';
UPDATE submission_sites SET rw_source_lead='The MCP registry that publishes by connecting to your live server rather than reading a form, listing it the moment the inspection passes.', rw_what_you_get='A dofollow listing generated automatically from your live MCP server — its tool list and descriptions become the page — with a quality score you can improve in Settings.', rw_you_need='["A live MCP server at an HTTP URL answering initialize and tools/list","An account via Google, GitHub or email","Tool descriptions worth reading, because they are the listing copy"]', rw_eligibility='You need a live, reachable MCP server at an HTTP URL and an account. Anything that is not an MCP server, or that their inspector cannot reach at publish time, is rejected — the publish step is a live connection, not a form.', rw_submit_steps='["1 Sign in. /servers/new goes to a WorkOS sign-in offering email, Google and GitHub; the namespace is derived from the account, not chosen.","2 Name the server and give the URL: a server id under your namespace and the HTTP URL where it answers. No listing copy is requested here.","3 Declare connection settings or skip. A parameter builder covers values users must supply; skipping is fine for a server whose useful tools work unauthenticated, though a config-schema warning is logged either way.","4 Watch the inspection, then publish. They connect, read metadata, count tools and generate the listing — one run took nine seconds and found eleven tools — and Publish stays disabled until it finishes.","5 Fill what inspection cannot see. The page goes live with no description and a quality score; Settings carries display name, markdown description, homepage, GitHub repo and icon, which raised the score from 45 to 69 in one walk."]', rw_submit_requirements='["An account via Google, GitHub or email through WorkOS","A live MCP server at an HTTP URL — a live connection, not a form","A server id that becomes the listing slug","A display name and markdown description","A homepage URL, the followed outbound link","A GitHub repository and custom icon, otherwise the homepage favicon is used"]', rw_rejection_reasons='["Anything that is not an MCP server, and any server their inspector cannot reach at publish time"]', rw_gotchas='["The listing publishes with no description at all: tool definitions come from your server but prose does not, so the page reads No description and scores low until you write one in Settings.","Your tool schemas are the listing copy — whatever you wrote in each tool''s description is what a stranger reads before installing, with no separate field to fix it.","Publishing needs the server live and reachable at the moment you press the button, because the flow connects rather than queueing a form."]', rw_faq='[{"question":"How long does Smithery approval take?","answer":"Listings go live instantly once the live inspection passes."},{"question":"Is submitting to Smithery free?","answer":"Yes, publishing is free."},{"question":"Does a Smithery listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 77."},{"question":"Do I need to link back to Smithery?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Anything that is not an MCP server, or a server their inspector cannot reach at publish time."}]', rw_summary='Smithery is an MCP registry that generates listings by connecting to your live server and inspecting its tools. Publishing is free and dofollow with no backlink requirement, and listings go live instantly after inspection; domain rating is 77.', rw_fact_points='["Listings publish instantly after a live server inspection","Submission is free and carries a dofollow link","No badge or return link is expected","Accepts MCP servers, developer tools, AI tools and open source"]', rw_submission_checks='["Have your MCP server live and reachable at publish time.","Write clear tool descriptions — they become the listing copy.","Expect no prose description initially; add one in Settings to raise the quality score.","Set a homepage URL, which is the followed outbound link."]', rw_seo_title='Smithery: Free Live MCP Listing, DR 77', rw_seo_description='How to publish on Smithery: free instant dofollow MCP listing via live inspection, no backlink. Steps and gotchas from the 2026-11-16 snapshot.' WHERE slug='smithery';
UPDATE submission_sites SET rw_source_lead='An 89,000-server MCP marketplace you publish to with a CLI rather than a form, shipping an Agent Skill so your agent can handle it.', rw_what_you_get='A dofollow listing in a large MCP marketplace, published from your GitHub repo through a CLI, with an official skill that lets an agent run the whole flow.', rw_you_need='["A GitHub repository, against which ownership is verified","Node.js 22 or later to run their CLI","An lhm.plugin.json manifest in the repository"]', rw_eligibility='You need a GitHub repository for ownership verification, Node.js 22 or later for the CLI, and an lhm.plugin.json manifest. A server with no GitHub repo, or anything that is not an MCP plugin or server, is rejected.', rw_submit_steps='["1 Read their publishing skill. The URL is an Agent Skill describing the whole flow; fetching it returns the file with every reference appended in one request.","2 Install the CLI, @lobehub/market-cli on npm, needing Node.js 22 or later. Their docs insist you never make raw HTTP calls: auth is OIDC PKCE with automatic refresh and the CLI handles it.","3 Log in and connect GitHub. Login is browser OIDC; GitHub is connected separately because that is how repository ownership is verified.","4 Write the manifest and publish. An lhm.plugin.json in the repo describes the listing and the CLI publishes a version from it; claiming an existing plugin is a separate command."]', rw_submit_requirements='["A GitHub repository for the server","Node.js 22 or later and the @lobehub/market-cli package","An lhm.plugin.json manifest","An agent able to run the CLI, since they publish a skill for exactly that"]', rw_rejection_reasons='["A server with no GitHub repository, since ownership is verified through GitHub, and anything that is not an MCP plugin or server"]', rw_gotchas='["There is no submit form: /mcp/submit errors out, and the only supported route is a CLI release from a GitHub repository — a developer workflow rather than a listing form.","Ownership is verified through a connected GitHub account, so a server you did not publish yourself must be claimed rather than added.","The CLI needs Node.js 22 or later, a real gate on an older machine that is not mentioned anywhere on the marketplace page."]', rw_faq='[{"question":"How long does LobeHub MCP approval take?","answer":"Listings typically go live the same day."},{"question":"Is publishing to LobeHub MCP free?","answer":"Yes, publishing is free."},{"question":"Does a LobeHub MCP listing provide a dofollow link?","answer":"Yes, listings carry a dofollow link on a domain rated 74."},{"question":"Do I need to link back to LobeHub MCP?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"A server with no GitHub repository, or anything that is not an MCP plugin or server."}]', rw_summary='LobeHub MCP Marketplace is an 89,000-server registry published to through a CLI from a GitHub repo, with an official Agent Skill for automation. Listings are free, dofollow and need no backlink; domain rating is 74.', rw_fact_points='["Publishing is a CLI workflow from GitHub, typically live the same day","Submission is free and carries a dofollow link","No badge or return link is expected","Accepts MCP servers, developer tools, open source and agent skills"]', rw_submission_checks='["Use the CLI rather than looking for a form — /mcp/submit does not work.","Ensure Node.js 22 or later is available on the publishing machine.","Prepare an lhm.plugin.json manifest in the repository.","Claim rather than add a server you did not originally publish."]', rw_seo_title='LobeHub MCP: Free CLI Listing, DR 74', rw_seo_description='How to publish to LobeHub MCP Marketplace: free dofollow CLI listing, no backlink, Agent Skill. Steps and requirements from the 2026-11-16 snapshot.' WHERE slug='lobehub-mcp';
UPDATE submission_sites SET rw_source_lead='A four-million-developer publishing community where your submission is an article you write, and the link inside it is followed even from a brand-new account.', rw_what_you_get='A published article in front of a large developer audience, with a dofollow link in the body — unusual at this domain rating, and available even from a day-old account.', rw_you_need='["Something worth saying at article length — there is no form or product field, only a post","A sign-in through Apple, Facebook, GitHub, Google, MLH or Twitter, or an email and password","A product a developer audience has a reason to care about"]', rw_eligibility='There is no submission form: you write an article, so you need something worth saying at length and a product developers care about. Sign in with one of six providers or email and password. A press release with a link tacked on gets buried and downvoted, and an empty profile with a link in the bio is not a launch.', rw_submit_steps='["1 Sign in with Apple, Facebook, GitHub, Google, MLH or Twitter, or an email and password. Google takes about a minute end to end.","2 Get through five onboarding screens: profile, tags to follow, suggested follows, special initiatives and newsletter. Read them instead of clicking Continue, because most options arrive pre-ticked.","3 Write the post in the plain-markdown editor with a title, up to four tags, an optional cover image, and Advanced Options for a canonical URL if you are cross-posting.","4 Tag for the audience you want. #showdev is the \"I built this\" tag; add the two or three topic tags describing what the post is about, not what you are selling.","5 Publish and stay in the comments. It goes live immediately with no review queue, and the comments decide whether it turns into readers."]', rw_submit_requirements='["A post with a title, markdown body and up to four tags","An account through one of six providers, or email and password","A cover image","A canonical URL if the post also lives on your own blog"]', rw_rejection_reasons='["A press release with a link at the bottom, which the feed buries and the community downvotes, and an empty profile with only a bio link"]', rw_gotchas='["There is no submission form — the article is the submission, and the return depends on it being worth reading on its own. Budget an afternoon, not ten minutes of pasting.","The link in the body is followed: the anchor to an author''s own site on a post from a day-old account carries rel=\"noopener noreferrer\" and nothing else, which is unusual at this domain rating.","Four tags is the hard limit and they decide reach. #showdev is the launch tag; spending all four on your product''s jargon puts the post in front of nobody.","Onboarding arrives pre-ticked: it follows twenty people, five organisations and several \"special initiative\" accounts before you have seen a single post."]', rw_faq='[{"question":"How long does DEV Community approval take?","answer":"Posts go live immediately with no review queue."},{"question":"Is posting on DEV Community free?","answer":"Yes, publishing is free."},{"question":"Does a DEV Community post provide a dofollow link?","answer":"Yes, the link in the article body is dofollow on a domain rated 91."},{"question":"Do I need to link back to DEV Community?","answer":"No backlink is required."},{"question":"What gets a post downvoted?","answer":"Press releases with a link tacked on, and empty profiles whose only content is a bio link."}]', rw_summary='DEV Community is a large developer publishing platform where the submission is an article you write rather than a form. Posts are free, appear instantly, carry a dofollow link and need no backlink; the domain rating is 91.', rw_fact_points='["Posts go live instantly with no review queue","Submission is free and the in-body link is dofollow","No badge or return link is expected","Accepts developer tools, side projects, open source and articles"]', rw_submission_checks='["Treat the article as the submission — it must be worth reading on its own.","Use #showdev for a launch and spend your remaining tags on real topics.","Read the onboarding screens; options are pre-ticked and will follow accounts for you.","Set a canonical URL if you are cross-posting from your own blog."]', rw_seo_title='DEV Community: Free Post, DR 91', rw_seo_description='How to post on DEV Community: free instant article, dofollow in-body link, no backlink. Steps and pitfalls from the 2026-11-16 snapshot.' WHERE slug='dev-community';
UPDATE submission_sites SET rw_source_lead='A Docker-maintained catalogue of MCP servers where listings arrive as pull requests and are reviewed by the Docker team.', rw_what_you_get='A verified entry in Docker''s official MCP catalogue, with a dofollow link from a high-authority domain and distribution to Docker Desktop users browsing for servers.', rw_you_need='["A GitHub account to open the submission pull request","A permissive licence such as MIT or Apache 2 — GPL is explicitly excluded","Either a Dockerfile in a public repository or a publicly reachable HTTP endpoint for a hosted server","A documentation URL"]', rw_eligibility='Submissions need a GitHub account, an OSI-friendly licence (MIT and Apache 2 are named; GPL is excluded), and either a Dockerfile in a public repo or a public HTTP endpoint for remote servers, plus a documentation URL. Anything that is not an MCP server, or that carries a GPL licence, is rejected.', rw_submit_steps='["1 Fork the registry at github.com/docker/mcp-registry and clone it locally.","2 Generate the entry with their tooling: task wizard for a containerised server or task remote-wizard for a hosted one. Both write a server.yaml under servers/.","3 Open a pull request whose title and description explain the entry, and make sure CI passes.","4 Wait for a Docker reviewer to approve. Any test credentials go through a linked Google form rather than into the pull request.","5 On merge, commits are squashed and the catalogue entry appears roughly a day later."]', rw_submit_requirements='["A server.yaml produced by their Go tooling rather than hand-written","An icon URL pointing to a hosted image","A documentation URL for remote servers"]', rw_rejection_reasons='["Projects that are not MCP servers, and anything under a GPL licence"]', rw_gotchas='["A hosted server needs no Dockerfile, but the README leads with the two container options and tucks the remote-server path into a later section.","GPL is ruled out by name, so the licence is decided before anything else is reviewed.","A Docker employee reviews against quality and security standards, and no review window is published.","The container route needs Go, Docker Desktop and Task, so it is a submission from a development machine rather than a browser."]', rw_faq='[{"question":"How long does Docker MCP Catalog approval take?","answer":"No review time is published; the listing appears about a day after a reviewer merges the pull request."},{"question":"Is submitting to Docker MCP Catalog free?","answer":"Yes, the pull-request submission is free."},{"question":"Does a Docker MCP Catalog listing provide a dofollow link?","answer":"Yes. The listing carries a dofollow link on a domain rated 92."},{"question":"Do I need to link back to Docker MCP Catalog?","answer":"No return link is required."},{"question":"What causes a rejection?","answer":"Anything that is not an MCP server, and any project under a GPL licence."}]', rw_summary='Docker MCP Catalog is Docker''s official registry of MCP servers, curated through GitHub pull requests and reviewed by the Docker team. Listings are free, pass a dofollow link, and require no backlink; the domain rating is 92.', rw_fact_points='["Submission is a GitHub pull request reviewed by Docker staff","The listing is free and dofollow","No badge or return link is expected","A permissive licence — not GPL — is required"]', rw_submission_checks='["Confirm your licence is MIT, Apache 2 or similar; GPL entries are rejected.","Generate server.yaml with the official Task tooling rather than writing it yourself.","Decide early whether you are submitting a containerised or a hosted server; the two use different generators.","Expect a human security review from Docker with no published time window."]', rw_seo_title='Docker MCP Catalog: Submit via PR, DR 92', rw_seo_description='How to submit to Docker MCP Catalog: free pull-request listing, dofollow link, Docker team review. Steps and requirements from the 2026-11-16 snapshot.' WHERE slug='docker-mcp-catalog';
UPDATE submission_sites SET rw_source_lead='The default launch stage for new products: a single day of concentrated traffic followed by a permanent listing and backlink.', rw_what_you_get='A day of intense exposure to an audience that actively looks for new products, plus a lasting product page with a dofollow backlink from a domain rated 91.', rw_you_need='["A social login — LinkedIn, GitHub, X, Google, Facebook or Apple; there is no email sign-up","A live product that anyone can try without booking a sales call","A 240x240 thumbnail and at least three gallery images or a short demo video"]', rw_eligibility='You need a social account to sign in, a working product people can try immediately, and basic media — a 240px square thumbnail plus three gallery images or a short video. Waitlists, landing pages without a product, and re-launching the same product within six months are rejected.', rw_submit_steps='["1 Sign in with a social account. LinkedIn, GitHub and X appear as labelled buttons; Google, Facebook and Apple are unlabelled icons beneath them. There is no email or password route, so the launch stays tied to that identity.","2 Paste your product URL. The new-post page asks only for the link, scrapes the page, then fills the launch name from your page title — usually not your product name, so check it.","3 Fill in the main details: name (40 characters), tagline (60), links, an open-source toggle, an X handle, a description (500) and up to three launch tags. The first comment is drafted here and posts automatically at launch.","4 Add media: a 240x240 thumbnail under 2MB (pre-filled from your favicon) and a gallery, where the first image becomes the social preview; three or more is recommended. Video and interactive demo are optional.","5 Complete the makers, extras and checklist sections. The launch checklist scores you against required and strongly recommended items and shows a completion percentage.","6 Choose Create draft to save and keep editing, or Schedule launch for later to commit. A draft page states plainly that it is not yet scheduled."]', rw_submit_requirements='["A social account for sign-in","A working product URL","A 240x240 thumbnail under 2MB","Three or more gallery images","A tagline up to 60 characters","A description up to 500 characters","Up to three launch tags","A first comment that posts with the launch"]', rw_rejection_reasons='["Waitlists and landing pages with no working product, and products re-launched within six months"]', rw_gotchas='["Sign-in is social-only and half the providers are unlabelled, so the launch is permanently attached to whichever identity you choose.","The launch name is auto-filled from your page title, not your product name — check and correct it.","The first comment is composed in the form and posts automatically at launch, so write it before you schedule.","Create draft and Schedule launch sit side by side; only the latter commits, and a draft explicitly says it is not scheduled.","Soliciting upvotes in public draws a penalty — share the link without the ask.","One launch per product per six months, so do not spend it before you have an audience."]', rw_faq='[{"question":"How long does Product Hunt approval take?","answer":"Submissions typically go live the same day."},{"question":"Is launching on Product Hunt free?","answer":"Yes, submitting a product is free."},{"question":"Does Product Hunt provide a dofollow backlink?","answer":"Yes, the product page links dofollow on a domain rated 91."},{"question":"Do I need to link back to Product Hunt?","answer":"No backlink is required."},{"question":"What gets a launch rejected?","answer":"Waitlists and landing pages without a working product, or reposting the same product within six months."}]', rw_summary='Product Hunt is the default launch platform for new products, offering a day of concentrated traffic and a permanent dofollow listing. Submission is free, no backlink is required, and the domain rating is 91.', rw_fact_points='["Launch goes live the same day","Submission is free and carries a dofollow link","No badge or return link is expected","Accepts web apps, mobile apps, AI tools, dev tools and free tools"]', rw_submission_checks='["Have a working product ready — waitlists and empty landing pages are rejected.","Sign in with the identity you want permanently tied to the launch.","Correct the auto-filled launch name; it comes from your page title.","Write the first comment before scheduling, since it posts automatically.","Do not publicly ask for upvotes, which draws a penalty."]', rw_seo_title='Product Hunt: Free Launch, DR 91', rw_seo_description='How to launch on Product Hunt: free same-day listing, dofollow link, no backlink required. Steps, media specs and pitfalls from the 2026-11-16 snapshot.' WHERE slug='product-hunt';
UPDATE submission_sites SET rw_source_lead='A product directory built to be read by AI assistants as much as by people, with an MCP server and an API, where the free lane waits behind the paid.', rw_what_you_get='A dofollow product page that assistants can read through an MCP server and API, published after a free queue of roughly seven weeks or immediately on a paid launch.', rw_you_need='["An account via an emailed six-digit code or Google sign-in","A live product with a name, tagline, description, URL and square logo","About seven weeks of patience for the free queue"]', rw_eligibility='There is no structural bar: the free lane accepts anyone willing to wait. You need an account, a live product with basic details and logo, and patience for the free queue.', rw_submit_steps='["1 Sign in with an emailed six-digit code or Continue with Google; the Cloudflare check on the click normally clears itself.","2 Fill one long form: basic info with logo and screenshots, then categories, use cases, audiences, pricing, platforms and alternatives, then optional MRR, X handle, LinkedIn, discount code and first comment. Choosing MCP as a platform adds a server URL field.","3 Submit. Files upload, a security check runs and the product is saved as Ready to launch — not yet in any queue.","4 Choose the free queue. The plans page puts $39, $89 and $229 tiers above a Free launch queue card; its button opens a 40% off offer, and Wait in queue beneath that is the free way through.","5 Wait your turn. A dialog confirms queue position and estimated wait, the dashboard row reads In launch queue, and they email when it publishes."]', rw_submit_requirements='["An account","A product name up to 40 characters","A one-line tagline up to 60 characters","A description up to 5,000 characters","A website URL","A square PNG or JPG logo up to 1024x1024 and 5MB","Up to 10 screenshots, PNG or JPG, 5MB each","Up to 3 categories, 3 use cases, 3 audiences and 5 platforms","Optional alternatives and a first comment"]', rw_rejection_reasons='["Nothing structural — the free lane accepts anyone willing to wait"]', rw_gotchas='["The free queue is long and says so: 2,936 products were ahead at one check, quoted at about a month and 19 days, and choosing your own launch date is paid.","Your listing page exists as soon as you queue but is noindex until publication, so search engines and assistants find nothing while you wait; their own comparison table sells indexing from day one.","Pressing Submit does not queue anything — the product is saved as Ready to launch and only joins the queue from the plans page, through a 40% off dialog whose quiet Wait in queue button is the free exit. Leave before that and you are in no queue."]', rw_faq='[{"question":"How long does PeerPush approval take?","answer":"The free queue typically takes one to two months; paid launches go live immediately."},{"question":"How much does PeerPush cost?","answer":"The free queue is $0. Paid launches are $39 one-time, $89 with 7-day promotion and $229 with 30-day promotion, with always-on promotional options. Joining the free queue first opens a 30-minute 40% off offer on paid plans."},{"question":"Does a PeerPush listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 74."},{"question":"Do I need to link back to PeerPush?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Nothing structural; the free lane accepts anyone willing to wait."}]', rw_summary='PeerPush is an AI-readable product directory with an MCP server and API, offering a free queue of about seven weeks or immediate paid launches. Listings are dofollow with no backlink requirement; domain rating is 74.', rw_fact_points='["Free launch queue runs one to two months; paid is immediate","Submission is free and carries a dofollow link","No badge or return link is expected","Accepts SaaS, AI tools, developer tools, mobile apps, MCP servers and productivity tools"]', rw_submission_checks='["Expect a long free queue; choose a paid launch only if timing matters.","Complete the Submit step and then explicitly join the queue on the plans page.","Know that your page is noindex until it publishes.","Use the MCP platform option to add your server URL if relevant."]', rw_seo_title='PeerPush: Free AI-Readable Listing, DR 74', rw_seo_description='How to submit to PeerPush: free queued or instant paid dofollow listing, no backlink, MCP/API readable. Steps from the 2026-11-16 snapshot.' WHERE slug='peerpush';
UPDATE submission_sites SET rw_source_lead='An open-source project tracker that takes a repository URL, approves it instantly and links out dofollow.', rw_what_you_get='A dofollow listing in a library-tracking directory, created immediately from a repository URL — though it earns discovery only if people actually discuss the project.', rw_you_need='["A public repository URL — the only field the first screen asks for","A one or two sentence description, which the form asks for by name"]', rw_eligibility='You need a public repository URL and a one or two sentence description. A hosted product with no public repository is rejected, because the entire record is built around a repo URL.', rw_submit_steps='["1 Paste the repository URL. The first screen is a single field and a Continue button; no account is requested at any point.","2 Fill in what the scraper could not read: name, a one or two sentence description, comma-separated topics, an official website URL, a docs URL, the language and the licence.","3 Answer the self-hosted question honestly. The checkbox is for full-featured software that runs on its own, not a library or package — a hosted service is not that.","4 Submit and it is live. The confirmation says the submission was approved automatically and drops you on a page inviting you to suggest an alternative to your own project."]', rw_submit_requirements='["A public repository URL","A one or two sentence description","Topics, website URL, docs URL, language and licence"]', rw_rejection_reasons='["A hosted product with no public repository, since the whole record centres on a repo URL"]', rw_gotchas='["This is a library tracker, not a launch board: their own description is tracking mentions of software libraries on social networks, so an undiscussed project sits unranked rather than gaining an audience.","The self-hosted checkbox is about whether the software runs on its own, not where you host it; a hosted service with a metadata-only repo fits neither category and the form has no answer for it.","Approval is automatic, so whatever you type goes live immediately — there is no review to catch a description you would have rewritten."]', rw_faq='[{"question":"How long does LibHunt approval take?","answer":"Listings are approved automatically and go live instantly."},{"question":"Is submitting to LibHunt free?","answer":"Yes, submission is free."},{"question":"Does a LibHunt listing provide a dofollow link?","answer":"Yes, listings carry a dofollow link on a domain rated 66."},{"question":"Do I need to link back to LibHunt?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"A hosted product with no public repository."}]', rw_summary='LibHunt is an open-source project tracker that builds a listing from a repository URL and approves it instantly. Submission is free and dofollow with no backlink requirement; domain rating is 66.', rw_fact_points='["Listings are approved automatically and publish instantly","Submission is free and carries a dofollow link","No badge or return link is expected","Accepts open source projects, developer tools and MCP servers"]', rw_submission_checks='["Have a public repository URL ready — it is the basis of the whole listing.","Write the one or two sentence description yourself; there is no review afterward.","Answer the self-hosted checkbox according to the software''s nature, not its hosting."]', rw_seo_title='LibHunt: Free OSS Listing, DR 66', rw_seo_description='How to submit to LibHunt: free instant repo-based listing, dofollow link, no backlink. Steps and gotchas from the 2026-11-16 snapshot.' WHERE slug='libhunt';
UPDATE submission_sites SET rw_source_lead='A registry of 74,016 MCP servers that indexes them automatically, grades each one for licence, quality and maintenance, and charges only for hosting.', rw_what_you_get='An automatically generated listing with a dofollow link and public letter grades, indexed whether you ask or not — with paid hosting available if you want to run the server on Glama.', rw_you_need='["An MCP server with a public repository for them to index","A licence, one of the three things every listing is graded on","An account if you want to add or claim the listing rather than wait to be indexed"]', rw_eligibility='You need an MCP server with a public repository, a licence, and — to add or claim rather than wait — an account. A closed-source server with nothing public to index is not listed unless you take the paid hosting route.', rw_submit_steps='["1 Check whether you are already listed. They call themselves a superset of the official MCP Registry and index continuously, so a public server is often present before you submit anything.","2 Press Add Server, beside the sort dropdown on /mcp/servers above the results.","3 Create an account through the sign-up modal — Google, GitHub or Discord as an icon row, or an email route with a name field and a robot checkbox.","4 Claim the listing. Around 2,546 servers carry a Claimed attribute, a state separate from simply being indexed."]', rw_submit_requirements='["A public repository for the MCP server","A licence, graded on every listing","An account via Google, GitHub, Discord or email to add or claim","A README and maintenance activity, both feeding the letter grades"]', rw_rejection_reasons='["A closed-source server with nothing public to index, unless you use the paid hosting route"]', rw_gotchas='["Every listing shows three public letter grades — licence, quality and maintenance — computed from the repository; an unmaintained or unlicensed server displays a C to everyone who looks.","Indexed and claimed are different states: only about 2,546 of 74,016 servers are claimed, so an existing listing is not necessarily one you control.","The email sign-up ends in a robot checkbox, so an account cannot be created end to end without a person."]', rw_faq='[{"question":"How long does Glama approval take?","answer":"Public servers are usually indexed the same day; claiming or adding goes through an account."},{"question":"How much does Glama cost?","answer":"Listing an open-source server is free. Paid workspaces and hosting start at $9 a month (Starter) up to $26 a month (Pro); hosting is a separate product, not a listing fee."},{"question":"Does a Glama listing provide a dofollow link?","answer":"Yes, listings carry a dofollow link on a domain rated 73."},{"question":"Do I need to link back to Glama?","answer":"No backlink is required."},{"question":"What gets a server rejected?","answer":"A closed-source server with nothing public to index, unless you use the paid hosting route."}]', rw_summary='Glama is a large MCP server registry that indexes public repositories automatically and grades each server on licence, quality and maintenance. Listings are free and dofollow with no backlink required; hosting is a separate paid service. Domain rating is 73.', rw_fact_points='["Public servers are indexed automatically, often the same day","Listing is free and dofollow; hosting is a separate paid product","No badge or return link is expected","Accepts MCP servers, open source, developer tools and AI agents"]', rw_submission_checks='["Search first — your public server may already be indexed.","Add a licence and keep the repo maintained; both feed public letter grades.","Claim the listing to control it, since indexed does not mean claimed.","Consider paid hosting only if you want Glama to run the server, not to get listed."]', rw_seo_title='Glama MCP Registry: Free Listing, DR 73', rw_seo_description='How to get listed on Glama: free auto-indexed MCP server, dofollow link, no backlink. Grades and claiming from the 2026-11-16 snapshot.' WHERE slug='glama';
UPDATE submission_sites SET rw_source_lead='A directory of Cursor plugins where an MCP server counts as one, and the listing is the installable config block itself.', rw_what_you_get='A dofollow listing that tells Cursor users exactly what to install, on a domain rated 71, published once an automated security check clears the config.', rw_you_need='["Something a Cursor user installs: an MCP server, rule, skill, agent, hook, LSP server or command","A Google or GitHub account"]', rw_eligibility='You need something installable into Cursor — an MCP server, rule, skill, agent, hook, LSP server or command — and a Google or GitHub account. A product with nothing to install into an editor is rejected, because the listing is a config block rather than a description.', rw_submit_steps='["1 Sign in with Google or GitHub on the page that appears as soon as you open the submit URL.","2 Pick a lane. Auto reads a public GitHub repo and fills the form; Manual is the other tab and needs no repo.","3 Describe the plugin: name, description, optional logo, repository, homepage and keywords.","4 Add a component — pick the type, name it and paste the content. For an MCP server that content is the config block a client would use.","5 Publish. The page is created immediately but stays hidden while an automated security agent reads what you pasted."]', rw_submit_requirements='["The component content — the config block pasted in, not a link to it","A logo"]', rw_rejection_reasons='["A product with nothing installable into an editor, since the listing is a config block rather than a description"]', rw_gotchas='["The listing is a config block, not marketing copy: whatever you paste is what a Cursor user is told to install, so it must be correct rather than persuasive.","The page only goes live after an automated security agent has read it, and no time window is published.","The Auto lane needs a public GitHub repo; a closed-source product must use the separate Manual tab, which is a distinct control rather than a fallback."]', rw_faq='[{"question":"How long does Cursor Directory approval take?","answer":"No review time is published; the page stays hidden until an automated security check completes."},{"question":"Is submitting to Cursor Directory free?","answer":"Yes, listing a plugin is free."},{"question":"Does a Cursor Directory listing provide a dofollow link?","answer":"Yes, the listing carries a dofollow link on a domain rated 71."},{"question":"Do I need to link back to Cursor Directory?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"A product with nothing installable into an editor, because the listing is a config block."}]', rw_summary='Cursor Directory lists installable Cursor plugins, including MCP servers, as config blocks. Listings are free and dofollow with no backlink requirement, going live after an automated security check; domain rating is 71.', rw_fact_points='["Listings go live after an automated security check, with no published window","Submission is free and carries a dofollow link","No badge or return link is expected","Accepts developer tools, MCP servers and AI tools"]', rw_submission_checks='["Prepare an accurate install config block — it is the listing itself.","Use the Manual tab if your project is closed-source and has no public repo.","Expect a short hold while the security agent checks the pasted content."]', rw_seo_title='Cursor Directory: Free Plugin, DR 71', rw_seo_description='How to submit to Cursor Directory: free dofollow plugin listing, no backlink. Config-block rules and steps from the 2026-11-16 snapshot.' WHERE slug='cursor-directory';
UPDATE submission_sites SET rw_source_lead='The official MCP server registry, published to from the command line, and the destination the protocol''s own repository now points every builder toward.', rw_what_you_get='A verified entry in the canonical MCP registry that clients and discovery tools pull from, giving your server a durable, standards-based listing.', rw_you_need='["A published package or a publicly reachable server URL — the registry stores metadata pointing at it","A namespace you can prove you own: a GitHub account, a domain you control, or a key you can serve","A server.json describing the server, scaffolded by the publisher tool"]', rw_eligibility='You need a published package or a public server URL, a namespace you can prove through GitHub or a domain, and a server.json describing the server. A remote server nobody outside your network can reach, or a name in a namespace you cannot prove, is refused at publish time rather than at review.', rw_submit_steps='["1 Decide the namespace first. GitHub auth gives names under io.github.<account>/; domain auth gives your own reverse-domain prefix, which is what a product with its own site wants.","2 Prove the namespace. GitHub uses a device-code login; a domain is verified with a TXT record on the apex or by serving a key at /.well-known/mcp-registry-auth, the easier route if you already deploy static files.","3 Install the publisher and scaffold server.json. mcp-publisher ships as a binary or via Homebrew, and its init command writes a template from what it can read in your project.","4 Describe the server honestly. A packaged server lists its registry type, identifier and version; a hosted one uses a remotes array naming streamable-http or sse and the URL it answers on.","5 Publish and verify through the API. The publish command returns as soon as the entry is live; search the registry API for your name to confirm what actually landed."]', rw_submit_requirements='["A server.json scaffolded by mcp-publisher init","Namespace proof: a GitHub login, a DNS TXT record, or a key at a well-known path","A published package identifier or a public URL for a hosted server","An ownership marker inside the package for packaged servers"]', rw_rejection_reasons='["A server unreachable outside your network, or a name in a namespace you cannot prove — both refused at publish time"]', rw_gotchas='["This is a command-line publish, not a form: no page to fill in, no review queue, and no human in the loop.","The namespace fixes your name permanently. GitHub auth means io.github.<account>/<name> forever; a product with its own domain wants domain auth, and switching later means republishing under a new name.","The registry is in preview and warns that breaking changes and data resets may happen before general availability.","The DNS check wants a TXT record on the domain apex, and a stale record from an earlier key is tried first and fails the whole publish."]', rw_faq='[{"question":"How long does MCP Registry approval take?","answer":"Entries go live instantly on publish; there is no review queue."},{"question":"Is publishing to MCP Registry free?","answer":"Yes, publishing is free."},{"question":"Does an MCP Registry listing provide a dofollow link?","answer":"No. Links are nofollow on a domain rated 91."},{"question":"Do I need to link back to MCP Registry?","answer":"No backlink is required."},{"question":"What makes a publish fail?","answer":"A server that is not publicly reachable at its declared URL, or a name in a namespace you cannot prove."}]', rw_summary='MCP Registry is the official command-line-published registry for MCP servers. Entries are free and instant with no backlink required, links are nofollow, and the domain rating is 91.', rw_fact_points='["Publishing is instant from the command line with no review queue","Submission is free and links are nofollow","No badge or return link is expected","Accepts MCP servers, developer tools and open source projects"]', rw_submission_checks='["Choose your namespace carefully — GitHub or domain auth fixes your server name permanently.","Scaffold server.json with the official publisher rather than hand-writing it.","Make sure a hosted server is publicly reachable at the URL it declares.","Verify the published entry through the registry API, not just the success message."]', rw_seo_title='MCP Registry: CLI Publish, DR 91', rw_seo_description='How to publish to MCP Registry: free instant CLI listing, nofollow link, no backlink. Namespace and steps from the 2026-11-16 snapshot.' WHERE slug='mcp-registry';
UPDATE submission_sites SET rw_source_lead='An MCP server and client directory that is not accepting submissions right now and points you to the Official MCP Registry instead.', rw_what_you_get='A future listing once the pause lifts — but currently the only available path is to publish to the Official MCP Registry, which they ingest from automatically.', rw_you_need='["An MCP server or client, the only thing they list","A listing on the Official MCP Registry, their stated route in"]', rw_eligibility='They list only MCP servers and clients, and direct you to publish on the Official MCP Registry. For now everyone is effectively declined, because both submissions and changes to existing listings are paused.', rw_submit_steps='["1 Check whether the pause has lifted. /submit renders a notice rather than a form: submissions and changes are paused during a directory overhaul.","2 Publish to the Official MCP Registry instead. Their own advice is that this is the best first step even when they are not paused, and they pick entries up automatically once they return.","3 Revisit the use-case index. Submit use case is a separate route from Submit server/client, so check whether that one is also paused."]', rw_submit_requirements='["An MCP server or client","A listing on the Official MCP Registry, which they say they read from","A use case, which has its own separate route"]', rw_rejection_reasons='["Everyone at present — submissions and changes are both paused"]', rw_gotchas='["Submissions were still paused as of 1 September 2026, and the on-site notice is stale, saying paused until mid-August; their advice to publish to the Official MCP Registry stands.","Submissions are paused, and so are edits to existing listings, so a wrong or stale entry cannot be corrected either.","The notice says until mid-August without a year and was still up on 19 August 2026, so the date is not one you can plan around.","The recommended route, the Official MCP Registry, is a submission on a different site, so following their advice means leaving and doing something else."]', rw_faq='[{"question":"How long does PulseMCP approval take?","answer":"No review time is published, and submissions are currently paused."},{"question":"Is submitting to PulseMCP free?","answer":"Yes, though submissions are paused at present."},{"question":"Does a PulseMCP listing provide a dofollow link?","answer":"Yes, listings carry a dofollow link on a domain rated 70."},{"question":"Do I need to link back to PulseMCP?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"At the moment everyone, since submissions and changes are both paused."}]', rw_summary='PulseMCP is an MCP server and client directory that has paused submissions and edits while overhauling its pipeline, directing builders to the Official MCP Registry in the meantime. Listings are normally free and dofollow with no backlink; domain rating is 70.', rw_fact_points='["Submissions and changes are currently paused","Listings are free and dofollow with no backlink requirement","Publishing to the Official MCP Registry is the recommended route","Focuses on MCP servers, developer tools and open source"]', rw_submission_checks='["Check whether the pause has lifted before planning around this directory.","Publish to the Official MCP Registry, which they ingest from automatically.","Note that existing listings cannot currently be corrected either."]', rw_seo_title='PulseMCP: Submissions Paused, DR 70', rw_seo_description='PulseMCP is an MCP directory currently pausing submissions; publish to the Official MCP Registry instead. Free dofollow, no backlink.' WHERE slug='pulsemcp';
UPDATE submission_sites SET rw_source_lead='A community that rewards revenue numbers and thoughtful post-mortems rather than launch announcements.', rw_what_you_get='A product page plus the chance to reach a founder audience that engages with specifics — what you tried, what it earned and what failed — though the link itself is nofollow.', rw_you_need='["An Indie Hackers profile","Something to say beyond \"we launched\""]', rw_eligibility='You need a profile and something substantive to add beyond announcing a launch. Pure promotion with no story or numbers behind it is rejected; the community responds to transparent detail about what you built and earned.', rw_submit_steps='["1 Sign in. Both /products/new and /new-post route through the account; there is no anonymous path.","2 Create the product page with four required fields: product name, a tagline up to 60 characters, the website, and a square or circular logo at least 200x200. It goes live immediately with no review.","3 Attach the logo via the button control — the file input only appears after you click it — and wait for \"Image Uploaded\".","4 Finish the page on the second form at /product/<slug>/edit, where the description, X handle, category tags and seven required business questions live: start date, whether founders code, founder and employee counts, business model, funding and side-project versus full-time origin. The create form mentions none of this and the page publishes without it.","5 Then post something worth reading. The product page alone does nothing; the community responds to what you tried, what it earned and what failed."]', rw_submit_requirements='["An account","A product name (name only)","A tagline up to 60 characters","A live product URL","A square or circular logo at least 200x200","A description up to 220 characters","A start date from their dropdowns","Founder skillset, founder count, headcount, business model, funding and initial commitment from fixed lists","An X handle","Category tags from their fixed list","Revenue numbers"]', rw_rejection_reasons='["Pure promotion with no story or numbers behind it"]', rw_gotchas='["It is a community, not a directory; a product page with no participation behind it gets no attention.","Revenue transparency is the norm and earns engagement, so decide in advance how open you want to be.","The product page alone does almost nothing, and /new-post refuses a new account with \"your account cannot create posts yet\" and no criteria. The Write a new post box on your own product page opens an inline composer that works from the same account.","Searching for free Indie Hackers upvotes surfaces services selling them, but the rules treat bought or traded votes as manipulation and paying risks the listing."]', rw_faq='[{"question":"How long does Indie Hackers approval take?","answer":"Product pages go live immediately with no review."},{"question":"Is submitting to Indie Hackers free?","answer":"Yes, creating a product page is free."},{"question":"Does an Indie Hackers listing provide a dofollow link?","answer":"No. Links are nofollow on a domain rated 81."},{"question":"Do I need to link back to Indie Hackers?","answer":"No backlink is required."},{"question":"What gets a submission ignored?","answer":"Pure promotion with no story or numbers behind it."}]', rw_summary='Indie Hackers is a founder community where you create a product page and earn attention through transparent posts about revenue and lessons learned. Pages are free and instant with a nofollow link and no backlink requirement; domain rating is 81.', rw_fact_points='["Product pages publish instantly with no review","Submission is free and links are nofollow","No badge or return link is expected","Accepts SaaS, indie products, side projects and startups"]', rw_submission_checks='["Plan a substantive post, not just a product page — the page alone earns no attention.","Decide how much revenue detail you are comfortable sharing.","Complete the seven business questions on the edit form after the page is created.","Do not buy or trade upvotes; the rules treat it as manipulation."]', rw_seo_title='Indie Hackers: Free Product Page, DR 81', rw_seo_description='How to list on Indie Hackers: free instant product page, nofollow link, no backlink. Steps and community norms from the 2026-11-16 snapshot.' WHERE slug='indie-hackers';
UPDATE submission_sites SET rw_source_lead='An MCP server registry that reads your GitHub repo for you — which is also why a closed-source server cannot get in.', rw_what_you_get='A dofollow listing generated automatically from your GitHub repository, with the name, description, language, tools and README pulled in for you.', rw_you_need='["A public GitHub repository","An MCP server"]', rw_eligibility='You need a public GitHub repository and an MCP server. Closed-source or hosted-only servers without a public repo are rejected, because the listing is generated by reading the repository.', rw_submit_steps='["1 Open the form — no account needed. /submit is public and nothing is gated; only the repository requirement stands in the way.","2 Supply a public repo URL. The GitHub repository is the only required field; npm and PyPI package names, a description capped at 100 characters and a contact email are optional.","3 Let them fill the rest. They auto-detect name, description, language, licence, tools and README from the repo, and generate a description if you leave it blank."]', rw_submit_requirements='["A public GitHub repository","A description up to 100 characters","A contact email","An npm package name","A PyPI package name"]', rw_rejection_reasons='["Closed-source or hosted-only MCP servers with no public repository"]', rw_gotchas='["You may already be listed: they pull servers from the official MCP Registry themselves, and the submit page says so. If yours is there, email them to claim the entry for a verified badge and edit access rather than submitting again.","The GitHub repo URL is required, so a hosted closed-source server needs a separate metadata repo. Source is not required — a server.json, README and licence suffice — but a human reviews every entry, so treat that as a floor.","Because the listing is generated from the repo, a thin README makes a thin listing; write the 100-character description yourself.","Nothing validates the repository while you fill the form: detection runs on submit, so a private or misspelled URL is caught only afterwards and there is no way to test one without using the attempt."]', rw_faq='[{"question":"How long does MCP.Directory approval take?","answer":"Listings typically go live the same day after a human review."},{"question":"Is submitting to MCP.Directory free?","answer":"Yes, submission is free."},{"question":"Does an MCP.Directory listing provide a dofollow link?","answer":"Yes, listings carry a dofollow link on a domain rated 33."},{"question":"Do I need to link back to MCP.Directory?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"A closed-source or hosted-only MCP server with no public repository."}]', rw_summary='MCP.Directory is an MCP server registry that generates listings from a public GitHub repository. Submission is free and dofollow with no backlink requirement, and listings usually go live the same day; domain rating is 33.', rw_fact_points='["Listings are generated from a GitHub repo and reviewed by a human, typically the same day","Submission is free and carries a dofollow link","No badge or return link is expected","Accepts MCP servers and open source projects"]', rw_submission_checks='["Search first — your server may already be pulled in from the official registry.","Have a public GitHub repository; a hosted closed-source server needs a metadata repo.","Write the 100-character description yourself rather than leaving it to generation.","Double-check the repo URL, since it is only validated at submit time."]', rw_seo_title='MCP.Directory: Free Repo Listing, DR 33', rw_seo_description='How to submit to MCP.Directory: free dofollow listing generated from your GitHub repo, no backlink. Steps and pitfalls from the 2026-11-16 snapshot.' WHERE slug='mcp-directory';
UPDATE submission_sites SET rw_source_lead='A free curated SaaS directory that is also an MCP server, so an agent can find your listing as quickly as a person can.', rw_what_you_get='A hand-curated dofollow listing discoverable both in the browser and through their MCP server, with random rotation for badged entries and no way to buy position.', rw_you_need='["An account via Google sign-in or an emailed code","A live SaaS product","Profile material: hero image, gallery, use cases and integrations"]', rw_eligibility='You need an account, a live SaaS product and some profile material. Nothing is structurally excluded, but every listing is manually curated before it appears.', rw_submit_steps='["1 Sign in with Continue with Google, or an emailed magic link plus a sign-in code. /submit redirects to /login with a next parameter.","2 Fill the profile. Beyond the basics they take a hero image, gallery and custom blocks for use cases, integrations, ideal-for and key features, plus demo and docs links.","3 Wait for curation. Listings are reviewed by hand, in around 24 hours by their own estimate.","4 Decide about the badge. It is the only ranking lever: badged listings are shuffled fresh on every visit, so the order rotates rather than being sold."]', rw_submit_requirements='["An account via Google or an emailed code","A SaaS name, description and URL","A hero image and gallery","Use cases, integrations and key-feature blocks","Demo and docs links","Their badge, which ranks you above unbadged listings"]', rw_rejection_reasons='["Nothing is structurally excluded, though every listing is manually curated"]', rw_gotchas='["The link is genuinely dofollow, as they state explicitly: a direct anchor with no rel=nofollow and no tracking redirect, confirmed on a live listing.","Ranking is badge or nothing: badged listings rotate randomly on each visit and unbadged ones sit below them; there is no way to buy or earn a fixed position.","The directory is the free half of a paid MCP gateway product, so the pricing page you land on first is for the gateway at $29 and $99 a month, not for the listing."]', rw_faq='[{"question":"How long does Tulimoa approval take?","answer":"Listings are curated by hand and typically go live the same day, around 24 hours."},{"question":"Is submitting to Tulimoa free?","answer":"Yes, the listing is free; the separate MCP gateway is paid."},{"question":"Does a Tulimoa listing provide a dofollow link?","answer":"Yes, a direct dofollow link on a domain rated 29."},{"question":"Do I need to link back to Tulimoa?","answer":"No backlink is required, though their badge is the only ranking lever."},{"question":"What gets a submission rejected?","answer":"Nothing structurally; all listings are manually curated."}]', rw_summary='Tulimoa is a free hand-curated SaaS directory that is also an MCP server, so listings are discoverable by agents and people alike. The dofollow link needs no backlink, the badge drives rotating rank, and domain rating is 29.', rw_fact_points='["Listings are manually curated, typically within about 24 hours","Submission is free and carries a dofollow link","No required backlink, though the badge drives ranking","Accepts AI tools and MCP servers"]', rw_submission_checks='["Prepare a hero image, gallery and use-case blocks for a fuller profile.","Expect roughly a day for manual curation.","Display their badge if you want to rotate above unbadged listings.","Ignore the gateway pricing page — the listing itself is free."]', rw_seo_title='Tulimoa: Free Dofollow SaaS Listing, DR 29', rw_seo_description='How to submit to Tulimoa: free curated dofollow SaaS listing, no backlink, MCP-readable. Badge ranking and steps from the 2026-11-16 snapshot.' WHERE slug='tulimoa';
UPDATE submission_sites SET rw_source_lead='A product board where every listing is also a Solana token, so submitting means minting a tradeable asset against your product''s name.', rw_what_you_get='A dofollow listing on a trading-style leaderboard where a name, tagline, token address, market cap and holder count show for each product.', rw_you_need='["A crypto wallet, since Wallet is a first-class nav item and every listing carries a token","An account via Sign in","A willingness to have a token minted against your product''s name"]', rw_eligibility='You need an account, a connected crypto wallet and acceptance of a token being minted for your product — the token is not optional. Anyone unwilling to attach a tradeable token, or unable to connect a wallet, is effectively excluded.', rw_submit_steps='["1 Sign in and connect a wallet. The nav is Home, Game Cup, Notifications, Wallet, Profile, Submit product, Founder guide; Wallet sits beside Profile.","2 Open the real submit route. /submit 404s; the working path is /projects/submit via the Submit Product control.","3 Read the founder guide first — a dedicated nav item explains the token mechanics rather than the submission page.","4 List the product. The entry renders a name, tagline, token address, market cap, holder count and comment count."]', rw_submit_requirements='["An account on the site","A crypto wallet","Product name, URL and a one-line tagline","A logo for the leaderboard row"]', rw_rejection_reasons='["Anyone unwilling to have a tradeable token attached to their product, or unable to connect a wallet"]', rw_gotchas='["Every listing is a Solana token: the board sorts by market cap, each row shows a token address, and the pitch is to list and earn, so submitting mints a tradeable asset rather than a plain directory entry.","It is a trading leaderboard, so a listing rises or falls on token purchases rather than on whether people like the product.","The site is a single-page app that renders nothing to a plain fetch, so it is invisible to non-browser clients including most link checkers."]', rw_faq='[{"question":"How long does Orynth approval take?","answer":"No review time is published."},{"question":"Is submitting to Orynth free?","answer":"The listing itself is free, though a token is minted against the product name."},{"question":"Does an Orynth listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 74."},{"question":"Do I need to link back to Orynth?","answer":"No backlink is required."},{"question":"Who cannot submit?","answer":"Anyone unwilling to attach a tradeable token to their product, or unable to connect a wallet."}]', rw_summary='Orynth is a product board where every listing is also a Solana token and the leaderboard sorts by market cap. Submission is free and dofollow with no backlink requirement; domain rating is 74.', rw_fact_points='["Every listing mints a tradeable Solana token","Submission is free and carries a dofollow link","No badge or return link is expected","Accepts indie products, SaaS, AI tools and developer tools"]', rw_submission_checks='["Decide first whether you are comfortable minting a token against your product name.","Connect a crypto wallet before starting — it is mandatory.","Use /projects/submit, not /submit which is broken.","Read the founder guide to understand the token mechanics."]', rw_seo_title='Orynth: Free Token Listing, DR 74', rw_seo_description='How to list on Orynth: free dofollow product board where every entry is a Solana token, no backlink. Steps and caveats from the 2026-11-16 snapshot.' WHERE slug='orynth';
UPDATE submission_sites SET rw_source_lead='One of the largest AI directories, at 5.1 million monthly visits, with a single $99 lane and no free option anywhere in the form.', rw_what_you_get='A permanent dofollow listing with at least six followed links, a border highlight and placement in Just Launched, live within 48 hours.', rw_you_need='["A $99 payment — the form has no free path","An AI product with a name and website URL","An account via the Login control"]', rw_eligibility='You need to pay $99, have an AI product with a name and URL, and an account. Anyone not paying is excluded, because the form''s only button is Pay $99.', rw_submit_steps='["1 Pick the right product. /submit is a menu of six things they sell: Submit AI, Advertise AI, guest posts and link insertions, Update AI, Submit GPT and More Business. Only the first is a listing.","2 Enter the name and URL — two fields at the top, with an upsell to buy a .AI domain if you have no site.","3 Choose who writes the listing. Generated by Toolify hands the copy and every translation to their model; Do it myself lets you write English only, which they then translate.","4 Pay $99. The total is fixed and Pay is the only button; the listing appears in the main list and in Just Launched within 48 hours."]', rw_submit_requirements='["A $99 payment","An account on the site","A product name and website URL","A choice of who writes the copy — Toolify''s model or yourself","Your own English description if you write it yourself"]', rw_rejection_reasons='["Anyone not paying — the form''s only button is Pay $99"]', rw_gotchas='["There is no free lane in the submission form: it opens at $99 with Pay as the only button, on a page that also sells advertising, guest posts, link insertions and GPT listings.","The default hands your listing copy and all translations to their model. Choosing Do it myself limits you to English and they translate the rest anyway, so non-English versions are never your words.","The submit page is a menu of six products, only one of which is a listing, so it is easy to buy advertising or a guest post while trying to get listed."]', rw_faq='[{"question":"How long does Toolify approval take?","answer":"Listings go live within 48 hours with no queue."},{"question":"How much does Toolify cost?","answer":"A one-time $99 listing includes a border highlight, at least six followed links and a permanent entry within 48 hours. Advertising, guest posts, link insertions, GPT submissions and updates are sold separately."},{"question":"Does a Toolify listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 73."},{"question":"Do I need to link back to Toolify?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Anyone not paying, since the form''s only button is Pay $99."}]', rw_summary='Toolify is a major AI directory with 5.1 million monthly visits and a single $99 listing lane and no free option. The dofollow listing needs no backlink and goes live within 48 hours; domain rating is 73.', rw_fact_points='["Paid-only at $99, live within 48 hours","Listing is dofollow with at least six followed links","No badge or return link is expected","Accepts AI tools, SaaS, marketing, productivity and developer tools"]', rw_submission_checks='["Make sure you intend a listing — the submit page also sells ads, guest posts and link insertions.","Write your own English copy if the wording matters to you; translations are always automated.","Expect to pay $99, as there is no free lane."]', rw_seo_title='Toolify: $99 AI Listing, DR 73', rw_seo_description='How to submit to Toolify: paid $99 dofollow AI listing within 48 hours, at least six followed links, no backlink. Steps from the 2026-11-16 snapshot.' WHERE slug='toolify';
UPDATE submission_sites SET rw_source_lead='The most technically discerning free audience on the web, and one of the least tolerant of marketing.', rw_what_you_get='Direct feedback from experienced developers in a single discussion thread, with a brief traffic spike if the post gains traction — but only a nofollow link.', rw_you_need='["An account, with a username and password only","A title starting with \"Show HN:\"","Something people can actually try, ideally without signing up","Work you made yourself and can defend in the thread"]', rw_eligibility='You need an account, a title prefixed with "Show HN:", and something people can genuinely try — ideally without a signup — that you made yourself and can discuss. Blog posts, sign-up pages, newsletters, lists, landing pages, fundraisers, throwaway one-offs and unfinished work are treated as off topic.', rw_submit_steps='["1 Read the guidelines and judge fit honestly. Show HN is for something people can run or hold; lists and reading material are explicitly off topic, so lead with the part people use.","2 Remove friction. They ask for a try without signups or emails and say you will get more feedback that way.","3 Fill in three fields: title, url and text — and that is the whole form. If you supply a url the text box is ignored, so the title carries your entire pitch.","4 Begin the title with \"Show HN: \" within 80 characters. It first appears on /shownew and only reaches the Show page after passing a small points threshold.","5 Post the first comment yourself, right away. Since the text field is ignored, the explanation belongs in a comment; then stay around to answer, as the rules require."]', rw_submit_requirements='["A Hacker News account (username and password)","A title beginning \"Show HN:\" within 80 characters","A live URL usable without a signup","A first comment posted immediately after","Time to answer the discussion"]', rw_rejection_reasons='["Blog posts, sign-up pages, newsletters, lists and other reading material; landing pages and fundraisers; quickly generated one-offs; work that is not ready for users"]', rw_gotchas='["Lists and reading material are named as off topic, so a directory is borderline — lead with what a reader can do, not the catalogue.","The text field is ignored when a url is present, so the explanation must go in a comment posted after submitting.","Sign-in needs a plain username and password with no social login, so an agent cannot create or use an account.","Anything behind a signup or email is discouraged, and they say plainly you will get less feedback.","New features and version bumps generally do not qualify as a Show HN.","The submit page rate-limits aggressively, so an automated fetch will likely hit a 429 even when the site is fine."]', rw_faq='[{"question":"How long does Show HN approval take?","answer":"Posts appear instantly, though reaching the Show page requires clearing a small points threshold."},{"question":"Is submitting to Show HN free?","answer":"Yes, posting is free."},{"question":"Does Show HN provide a dofollow link?","answer":"No. Links are nofollow on a domain rated 91."},{"question":"Do I need to link back to Show HN?","answer":"No return link is required."},{"question":"What gets a Show HN post rejected?","answer":"Off-topic reading material, landing pages and fundraisers, quick one-offs, and work not ready for users."}]', rw_summary='Show HN is a Hacker News format for sharing something you built with a highly technical audience. Posts are free and appear instantly, links are nofollow, and no backlink is required; the domain rating is 91.', rw_fact_points='["Posts go live instantly with no review queue","Submission is free and links are nofollow","No badge or return link is expected","Accepts developer tools, web apps, open source and free tools"]', rw_submission_checks='["Be sure the submission is something people can actually run or try.","Make it usable without a signup to earn more feedback.","Put the entire pitch in the title — the text field is ignored when a url is present.","Post the first comment immediately and stay in the thread to answer."]', rw_seo_title='Show HN: Free Post, DR 91', rw_seo_description='How to post to Show HN: free instant listing, nofollow link, no backlink. Title rules, requirements and pitfalls from the 2026-11-16 snapshot.' WHERE slug='show-hn';
UPDATE submission_sites SET rw_source_lead='A 3-million-pageview AI directory with no free lane: $47 to be listed, $229 to be featured, and an automatic refund if editors say no.', rw_what_you_get='A permanent dofollow listing and a Just Landed homepage slot for $47, or seven days of featured homepage and category placement for $229; rejected submissions are refunded automatically.', rw_you_need='["A $47 payment — there is no free tier anywhere in the flow","An AI product, given the catalogue","Something an editor will pass, since acceptance is a human decision"]', rw_eligibility='Both lanes are paid, starting at $47, and acceptance is a human editorial decision. Anyone not paying is excluded, and anything the editors decline gets an automatic refund rather than an appeal.', rw_submit_steps='["1 Pick a tier. /submit is a two-card chooser: Fast Track at $47 and Featured at $229 — there is no free card.","2 Sign in via the Sign In control in the header beside Submit.","3 Fill the listing and pay. The tier is chosen first, so payment is part of submission rather than an upsell afterward.","4 Wait for editorial review. Every submission is reviewed, and a tool that is not accepted is refunded automatically."]', rw_submit_requirements='["A payment of $47 or $229","An account on the site","A tool name, live URL and description","A logo and screenshots"]', rw_rejection_reasons='["Anyone not paying — both lanes are paid with no free option, and anything editorial review declines, which is refunded automatically"]', rw_gotchas='["There is no free tier: both cards are paid and the cheaper is $47, charged before anyone at the directory has looked at the tool.","Paying does not buy acceptance — every submission faces editorial review and a rejection is refunded, so the $47 is a deposit on a decision whose criteria are unpublished.","The $229 Featured placement lasts seven days while the $47 listing is permanent, so the premium buys a week rather than a better listing."]', rw_faq='[{"question":"How long does TopAI.tools approval take?","answer":"Listings go live within 48 hours after editorial review."},{"question":"How much does TopAI.tools cost?","answer":"Fast Track is $47 one-time for a permanent listing and a Just Landed homepage slot. Featured is $229 for seven days of homepage and category placement, boosted search and faster verification. Rejections are refunded."},{"question":"Does a TopAI.tools listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 65."},{"question":"Do I need to link back to TopAI.tools?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Anyone not paying, or anything editorial review declines — which triggers an automatic refund."}]', rw_summary='TopAI.tools is a high-traffic AI directory with no free lane: $47 for a permanent dofollow listing or $229 for seven featured days, with editorial review and automatic refunds on rejection. No backlink is required; domain rating is 65.', rw_fact_points='["Paid-only: $47 permanent or $229 for seven featured days","Listings are dofollow with no backlink requirement","Editorial review with automatic refund on rejection","Accepts AI tools, SaaS, productivity, developer and marketing tools"]', rw_submission_checks='["Choose Fast Track for a permanent listing; Featured buys only a week of placement.","Expect to pay before review, with a refund if the editors decline.","Have a tool name, live URL, description and logo ready."]', rw_seo_title='TopAI.tools: $47 AI Listing, DR 65', rw_seo_description='How to submit to TopAI.tools: $47 dofollow listing or $229 featured, editorial review with refund, no backlink. Steps from the 2026-11-16 snapshot.' WHERE slug='topai-tools';
UPDATE submission_sites SET rw_source_lead='A developer blogging platform where the submission is an article you write, and the link inside it is nofollow ugc.', rw_what_you_get='A published article distributed through tag feeds to a developer audience, with your own blog subdomain — but the outbound link only earns readers, not link equity.', rw_you_need='["Something to say at article length — there is no product form","A sign-in via Google, GitHub or an emailed link"]', rw_eligibility='There is no submission form: you publish an article, so you need something genuinely worth saying to developers. Sign in with Google, GitHub or an email link. A product with nothing to say to developers goes nowhere, because the feed is organised by tags and an unread launch post reaches nobody.', rw_submit_steps='["1 Sign in. Get started on the homepage goes to /login with Google, GitHub or an emailed link.","2 Set up a blog on a yourname.hashnode.dev subdomain, or map your own domain to it.","3 Write the post in the markdown editor with a cover image and tags; the link to your product goes in the body and is nofollow ugc.","4 Publish. It goes live at once on your blog and in the tag feeds; the CLI, MCP server and agent skill publish the same way."]', rw_submit_requirements='["A post at article length","A cover image","Tags"]', rw_rejection_reasons='["A product with nothing to say to developers — a launch post nobody reads reaches nobody"]', rw_gotchas='["There is no submission form; the article is the submission, so the return depends on it being worth reading rather than on pasting a link.","Every outbound link in a post carries nofollow and ugc, so a post earns only readers; nothing about a Pro plan changes that.","The feed is organised by tag, and a post tagged only with your product''s own vocabulary lands in a feed nobody follows."]', rw_faq='[{"question":"How long does Hashnode approval take?","answer":"Posts go live instantly."},{"question":"Is posting on Hashnode free?","answer":"Yes, publishing is free."},{"question":"Does a Hashnode post provide a dofollow link?","answer":"No. Links are nofollow ugc on a domain rated 83."},{"question":"Do I need to link back to Hashnode?","answer":"No backlink is required."},{"question":"What makes a post ineffective?","answer":"A product with nothing to say to developers, since the tag-based feed means an unread launch post reaches nobody."}]', rw_summary='Hashnode is a developer blogging platform where your submission is an article, not a form. Posts are free, publish instantly and carry a nofollow ugc link; no backlink is required, and the domain rating is 83.', rw_fact_points='["Posts publish instantly with no review queue","Submission is free and links are nofollow ugc","No badge or return link is expected","Accepts developer tools, side projects, open source and articles"]', rw_submission_checks='["Write an article worth reading on its own — there is no product form.","Expect no link equity; every outbound link is nofollow ugc.","Tag with real topics developers follow, not your product''s own jargon."]', rw_seo_title='Hashnode: Free Dev Post, DR 83', rw_seo_description='How to post on Hashnode: free instant article, nofollow ugc link, no backlink. Requirements and pitfalls from the 2026-11-16 snapshot.' WHERE slug='hashnode';
UPDATE submission_sites SET rw_source_lead='Paste a URL and let their AI draft the listing, then choose a lane: free with a badge and a week-long check, or paid for instant placement.', rw_what_you_get='A dofollow listing with AI-drafted copy and feature bullets, published after a week if you display their badge, or immediately on a paid plan.', rw_you_need='["A Google account or email sign-in","A live URL — the only input the create step asks for","Their badge on your homepage on the free lane","An English-language version of your site","A domain rating above zero"]', rw_eligibility='You need an account, a live URL, an English site and a domain rating above zero; the free lane also requires their badge on your homepage. Brand-new domains with a rating of zero and sites with no English version fail the verification checklist outright.', rw_submit_steps='["1 Sign in. Submit in the nav points to /login — /submit itself is a 404 — and the card offers Continue with Google or Continue with Email.","2 Paste a URL and let their AI write it. Add startup takes only the URL and generates the name, category, tagline, description and six feature bullets from a scrape in about half a minute.","3 Correct what it wrote. The edit form is where the listing is decided; on this walk the AI''s tagline misdescribed the product. Location and a founder checkbox sit at the bottom, each adding a dofollow link.","4 Choose Verified and put their badge up. The Promote tab holds three lanes: Verified is free with a badge on your homepage; Highlight and Spotlight are monthly and publish instantly.","5 Tick the checklist and verify. Four conditions: badge visible, English site, a working product, and domain rating above zero. Tick the box to enable Verify now; the stated review is seven days."]', rw_submit_requirements='["An account via Google or email","A live URL","Their badge on your homepage on the free lane","Name, tagline, description and one category from 59","Six feature bullets prefilled by their AI","A domain rating above zero and an English site","Country, which adds a followed link","Founder checkbox, which adds another and puts the startup on your profile","Monthly recurring revenue"]', rw_rejection_reasons='["A brand-new domain with a domain rating of zero, and a site with no English version"]', rw_gotchas='["Their AI writes the entire listing from a scrape before you see it and can get the positioning wrong — read all eight fields, not just the name.","A domain rating of zero fails the free lane''s own checklist, so a new domain is refused rather than queued.","Two promised followed links are opt-in switches at the bottom of the edit form — a country and a founder checkbox; skipping them makes the listing worth less than the plan implies.","/submit is a 404: the nav''s Submit link points at /login, and the real control is Add startup inside the dashboard."]', rw_faq='[{"question":"How long does Startup Fame approval take?","answer":"The free verified lane has a stated review of about seven days; paid lanes publish instantly."},{"question":"How much does Startup Fame cost?","answer":"There is a free lane with a badge. Highlight is $19 a month and Spotlight $99 a month (marked down from $149), both publishing instantly with no badge."},{"question":"Does Startup Fame provide a dofollow link?","answer":"Yes, listings carry a dofollow link on a domain rated 83."},{"question":"Do I need to link back to Startup Fame?","answer":"Yes, the free verified lane expects their badge on your homepage."},{"question":"What causes a rejection?","answer":"A brand-new domain with a domain rating of zero, or a site with no English version."}]', rw_summary='Startup Fame is a startup directory that drafts listings from a URL using AI. The free lane adds a dofollow link for a badge after about seven days; paid tiers skip the queue. Domain rating is 83.', rw_fact_points='["Free lane publishes in about a week with a badge","Paid lanes publish instantly with no badge","Listings are dofollow and require a backlink on the free lane","Accepts startups, SaaS, AI tools, developer tools and more"]', rw_submission_checks='["Read every AI-prefilled field — the generated tagline can misdescribe your product.","Ensure your domain has a rating above zero and an English version before applying.","Place their badge on your homepage if using the free lane.","Toggle the country and founder options to claim the extra followed links."]', rw_seo_title='Startup Fame: Free Badge Listing, DR 83', rw_seo_description='How to submit to Startup Fame: free badge listing in ~7 days or instant paid tiers, dofollow link. Steps and requirements from the 2026-11-16 snapshot.' WHERE slug='startup-fame';
UPDATE submission_sites SET rw_source_lead='A 20,000-startup AI directory where a free profile goes live in a minute and the launch story is the paid part.', rw_what_you_get='A dofollow profile in a large AI startup database, live immediately and enriched daily with founders, funding and hiring data; paid extras add a news story and homepage boost.', rw_you_need='["An account","A company website"]', rw_eligibility='You need an account and a company website. A product with no AI angle is rejected, since this is an AI startup directory by name.', rw_submit_steps='["1 Sign in. The Sign In button goes to /auth with Continue with Google or email and password behind a Cloudflare check; a six-step tour and a partner promo follow — close both.","2 Choose and search. Submit Profile offers Organization, Person, Funding Round or Investment Fund. Organization asks you to search the name first; an existing profile is claimed, a new one created.","3 Add profile details: name, contact email, LinkedIn URL, website, a one-liner up to 140 characters, up to five sectors from a searchable list and a description — or paste the site and let their AI fill it.","4 Create the profile. It is live immediately at /organizations/your-slug, marked Claimed and Active, with a daily enrichment pass announced. An upsell follows: a $360 Google News launch story and a $10-a-day Boost, with a $30 launch credit on the account for 24 hours."]', rw_submit_requirements='["A company website","A company name","A contact email","A one-liner up to 140 characters","Up to five sectors","A description","A logo and header image, with the header cropped to 1200x630 and uploaded as WebP"]', rw_rejection_reasons='["A product with no AI angle — this is an AI startup directory"]', rw_gotchas='["The Organization card does nothing while signed out, and sign-in is followed by a six-step tour and a partner promo before the wizard is usable.","A daily pass enriches your profile from the web with founders, funding, hiring and screenshots, so the page shows more than you typed and not all of it is yours to edit first.","The launch story and boost are the paid part, offered the moment the profile exists at $360 and $10 a day; the free profile is just a row in a 20,000-company database."]', rw_faq='[{"question":"How long does StartupHub.ai approval take?","answer":"Free profiles go live immediately."},{"question":"How much does StartupHub.ai cost?","answer":"The profile is free. Paid extras are a $360 staff-written Google News launch story and a $10-a-day Boost; Pro Lite at $30 a month is a research plan that does not affect the listing."},{"question":"Does a StartupHub.ai profile provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 63."},{"question":"Do I need to link back to StartupHub.ai?","answer":"No backlink is required."},{"question":"What gets a profile rejected?","answer":"A product with no AI angle."}]', rw_summary='StartupHub.ai is a 20,000-company AI startup directory where a free dofollow profile publishes instantly and is enriched daily. A paid launch story and boost are optional; no backlink is required, and domain rating is 63.', rw_fact_points='["Free profiles go live instantly","Submission is free and carries a dofollow link","No badge or return link is expected","Focuses on AI startups, AI tools and SaaS products"]', rw_submission_checks='["Ensure your product has a clear AI angle.","Complete the sectors and one-liner; a daily pass will enrich the rest.","Close the post-sign-in tour and partner promo before using the wizard.","Treat the launch story and boost as optional paid extras, not part of the free profile."]', rw_seo_title='StartupHub.ai: Free AI Profile, DR 63', rw_seo_description='How to list on StartupHub.ai: free instant dofollow startup profile, no backlink. Paid extras and steps from the 2026-11-16 snapshot.' WHERE slug='startuphub-ai';
UPDATE submission_sites SET rw_source_lead='Daily launches aimed at small products, with far less competition than the major boards — but no visible free route.', rw_what_you_get='A same-day launch with 30 days of exposure, featured placement, a marketplace deal and a dofollow link from a domain rated 62 or above.', rw_you_need='["Payment — no free submission is visible to a logged-out visitor","A live product URL","Product copy and images"]', rw_eligibility='There is a paid lane only, with no free route visible before signing in, and a live URL is required. Products without a working URL are rejected.', rw_submit_steps='["1 Create an account at /signup. There is no way to see the launch flow without one.","2 Open New Launch from the nav, also bound to Cmd+S. /submit redirects to /premium#pricing whether signed in or not.","3 Meet the single option. A Pick your Launch modal offers exactly one lane — Pro Launch — with no free tier beside it.","4 Understand the fee: skip the queue and publish now or schedule, 30 days of exposure, featured placement, a marketplace deal with a top spot, a DR 60+ dofollow backlink, SEO pages, guest posts and a 48-hour boost."]', rw_submit_requirements='["Payment","An account","A live product URL","Product copy and images"]', rw_rejection_reasons='["Products with no live URL"]', rw_gotchas='["The /submit URL redirects to /premium#pricing whether you are signed in or not, so there is no form to find by guessing paths; every obvious route returns 404.","The New Launch control in the nav opens the paid modal, not a form, and Cmd+S is bound to the same thing.","The phrase Skip the queue implies a free queue exists somewhere, but nothing in the signed-in flow offers one.","Pro Launch is capped at 40 spots a month, so your preferred date may be unavailable."]', rw_faq='[{"question":"How long does MicroLaunch approval take?","answer":"Paid launches go live the same day."},{"question":"How much does MicroLaunch cost?","answer":"Pro Launch is $39 with code LAUNCH20 (list $49), with 50% off for open source and students."},{"question":"Does a MicroLaunch listing provide a dofollow link?","answer":"Yes, a dofollow link from a domain rated 62, plus SEO pages and guest posts."},{"question":"Do I need to link back to MicroLaunch?","answer":"No backlink is required."},{"question":"What gets a launch rejected?","answer":"Products with no live URL."}]', rw_summary='MicroLaunch is a daily launch board for small products with a paid-only route and little competition. A same-day Pro Launch costs $39 with a code, includes a dofollow link and needs no backlink; domain rating is 62.', rw_fact_points='["Paid launches go live the same day","Paid only, with a dofollow link and no backlink requirement","Accepts SaaS products, AI tools, startups and indie products","Pro Launch is capped at 40 spots a month"]', rw_submission_checks='["Expect a paid-only flow — there is no visible free lane.","Have a live URL, product copy and images ready before paying.","Use code LAUNCH20 for the discounted price, or check the open-source/student discount.","Book early; the monthly launch slots are limited."]', rw_seo_title='MicroLaunch: Paid Launch, DR 62', rw_seo_description='How to launch on MicroLaunch: paid same-day launch, dofollow link, no backlink. Pricing and steps from the 2026-11-16 snapshot.' WHERE slug='microlaunch';
UPDATE submission_sites SET rw_source_lead='A 149,000-tool catalogue on a DR 79 domain where listings publish in seconds — if an on-the-spot classifier decides you are a developer tool.', rw_what_you_get='A catalogue page in a large technology stack directory, created in seconds — though the Visit Website link is nofollow ugc, so this is placement rather than a backlink.', rw_you_need='["An account via Google or GitHub","A live site their scraper can read","A documentation URL, marked required","A features list","A product a classifier will file under developer tools, SaaS or technology platforms"]', rw_eligibility='You need a Google or GitHub account, a live site the scraper can read, a docs URL and a features list, and your product must be classifiable as a developer tool, SaaS product or technology platform. Anything outside those categories is refused on the spot.', rw_submit_steps='["1 Sign in. List a Tool opens a sign-in card first, with Google or GitHub and no email option.","2 Provide the URL — a single field. They scrape the site and pre-fill the following screen from it.","3 Correct the scraper''s mistakes. It puts your page title in Tool Name and your product name in One-line description; both usually need swapping back.","4 Write the features as a semicolon-separated list, rendered as chips as you type.","5 Submit and read the response: either the tool page appears immediately, or a red box says the classifier refused it."]', rw_submit_requirements='["An account","A live website URL","A documentation URL","A tool name","A one-line description","A short description of two or three sentences","A semicolon-separated features list","A square logo, scraped from the site"]', rw_rejection_reasons='["Anything the classifier reads as outside developer tools, SaaS products and technology platforms"]', rw_gotchas='["A classifier decides at submit time, not a human later. A first attempt was refused for not fitting the supported categories, then accepted when the copy led with the MCP server and API.","A refusal still consumes the attempt: after rejection the form asked to wait 58 minutes before another submission.","The scraper crosses two fields — page title into Tool Name and site name into One-line description — so submitting unchecked publishes your headline as the product name.","The Visit Website link is rel=\"nofollow ugc\" even on a live page, so this is catalogue placement, not link equity.","The pre-filled description is scraped from your homepage verbatim, including numbers that go stale quickly."]', rw_faq='[{"question":"How long does StackShare approval take?","answer":"Accepted tools appear immediately; a classifier decides on the spot."},{"question":"Is submitting to StackShare free?","answer":"Yes, listing a tool is free."},{"question":"Does a StackShare listing provide a dofollow link?","answer":"No. The Visit Website link is nofollow ugc on a domain rated 79."},{"question":"Do I need to link back to StackShare?","answer":"No backlink is required."},{"question":"What gets a tool rejected?","answer":"Anything the classifier places outside developer tools, SaaS products and technology platforms."}]', rw_summary='StackShare is a 149,000-tool technology catalogue where listings publish in seconds if an automated classifier accepts them. Submission is free, links are nofollow ugc and no backlink is required; domain rating is 79.', rw_fact_points='["Accepted tools publish instantly after an automated classification","Submission is free and links are nofollow ugc","No badge or return link is expected","Accepts developer tools, SaaS products, AI tools, B2B software and APIs"]', rw_submission_checks='["Lead your description with concrete developer-tool or API language to satisfy the classifier.","Correct the scraper''s swapped name and description fields before submitting.","Have a documentation URL ready — it is required.","Do not resubmit immediately after a refusal; there is a cooldown of about an hour."]', rw_seo_title='StackShare: Free Tool Listing, DR 79', rw_seo_description='How to list on StackShare: free instant placement, nofollow ugc link, no backlink. Classifier rules and gotchas from the 2026-11-16 snapshot.' WHERE slug='stackshare';
UPDATE submission_sites SET rw_source_lead='A brand-new weekly launch board: free, instant, genuinely dofollow, and currently only a handful of products deep.', rw_what_you_get='A free, instant dofollow listing with an SEO page, badge HTML and ready-made share posts, in a low-competition weekly board.', rw_you_need='["An account, created with one Google click","A live URL they can link to","A name under 60 characters and a tagline under 80","One or two categories from a fixed list of twelve"]', rw_eligibility='You need an account, a live URL and a short name and tagline with one or two categories. Anything with no live URL is rejected because the whole listing is built around the outbound link; beyond that there is no published content policy, so acceptance rests with the owner.', rw_submit_steps='["1 Sign in first. /launch redirects to /login; Continue with Google creates the account in one click and shares it with saasgrave.org. Email and password is the other option.","2 Ignore the AI autofill. The form opens with a URL box and a Fill with AI button that writes every field; paste your own copy instead — there are only five required fields.","3 Fill the five essentials: product name, tagline, website, logo URL and one or two categories. The logo is a URL you host, not an upload, and previews live beside the field.","4 Open the collapsed Make the page work harder section. It holds description, audience, pricing, problem, solution, differentiator, keywords and the first comment — this is the entire SEO page; skipping it leaves only a tagline.","5 Press Launch it. No review, queue or upsell: you land on your live product page with badge HTML and three ready-made share posts above it."]', rw_submit_requirements='["A sign-in via Google or email and password","A product name up to 60 characters","A tagline up to 80 characters","A live website URL","One or two categories from their list","A logo URL you host","Description, audience, pricing, problem, solution, differentiator and keywords","A first comment pinned above the discussion, up to 800 characters"]', rw_rejection_reasons='["Anything with no live URL, since the outbound link is the basis of the listing, and whatever the owner decides on the day — there is no published guidelines or content policy"]', rw_gotchas='["There is no date picker: your launch drops into the current ISO week and the board resets Monday, so launching late in a week wastes that cycle.","Nothing on the site can edit a live launch, and the pinned first comment is cut at 800 characters with no counter or warning and no way to restore it.","The link is dofollow, but every page declares a canonical on launches.saasgrave.org, a host that redirects straight back — whether the link is credited to a resolving URL is their bug, not something you can fix."]', rw_faq='[{"question":"How long does Saasgrave approval take?","answer":"Listings go live instantly with no review or queue."},{"question":"Is submitting to Saasgrave free?","answer":"Yes, launching is free."},{"question":"Does a Saasgrave listing provide a dofollow link?","answer":"Yes, a genuinely dofollow link, though no domain rating is published."},{"question":"Do I need to link back to Saasgrave?","answer":"No backlink is required."},{"question":"What gets a launch rejected?","answer":"Anything with no live URL, or whatever the owner decides, since there is no published content policy."}]', rw_summary='Saasgrave Launches is a new free weekly launch board with instant, genuinely dofollow listings and no review or upsell. You need a live URL and short product copy; there is no published content policy and no domain rating.', rw_fact_points='["Listings publish instantly with no review or queue","Submission is free and carries a dofollow link","No badge or return link is expected","Accepts SaaS products, AI tools, developer tools, marketing tools and indie projects"]', rw_submission_checks='["Fill the collapsed detail section — it is the entire SEO value of the listing.","Launch early in the week; the board resets Monday with no date picker.","Write the first comment under 800 characters; it cannot be edited afterward.","Host your own logo URL, or accept the favicon fallback."]', rw_seo_title='Saasgrave Launches: Free Dofollow Launch', rw_seo_description='How to launch on Saasgrave Launches: free instant dofollow listing, no backlink, weekly board. Steps and caveats from the 2026-11-16 snapshot.' WHERE slug='saasgrave-launches';
UPDATE submission_sites SET rw_source_lead='A professional network for builders with a weekly project spotlight, where launching is gated behind identity verification.', rw_what_you_get='A dofollow listing in a weekly launch cycle with upvotes, ratings and comments, attached to a real verified builder profile.', rw_you_need='["An account, a completed profile and then a verified profile — by government ID or employer","A live project to show"]', rw_eligibility='You need an account, a completed profile and a verified profile (government ID or workplace), plus a live project. Anyone unwilling to verify their identity cannot use the Launchpad.', rw_submit_steps='["1 Create an account with email and password or Continue with Google at /login.","2 Complete the profile. Clicking Launch first opens a Welcome modal asking for first name, last name, a 120-character bio and a username; a LinkedIn autofill option is pre-ticked.","3 Get verified. Clicking Launch again opens Get verified to Launch; verification is by government ID or workplace, and also unlocks Inbox, Articles, scheduling and a custom domain.","4 Launch into a weekly cycle at /launchpad/YYYY/week/NN, where entries carry upvotes, ratings and comment counts."]', rw_submit_requirements='["An account","A completed profile with name, username and a bio up to 120 characters","A verified profile via government ID or workplace","A live project URL"]', rw_rejection_reasons='["Anyone unwilling to verify their identity with the platform, since the Launchpad requires it"]', rw_gotchas='["The Launchpad is gated on identity verification, not just an account: verification needs a government ID or employer check, which no agent can or should perform.","There are three sequential gates — sign in, complete the profile, then verify — each appearing only after the last, with no warning about the next.","The profile modal pre-ticks Autofill from LinkedIn, which would import personal details; untick it if unwanted.","It is a professional network, so the launch hangs off a real named profile; the signup identity becomes the public face of the launch.","The site is bot-protected and returns 403 to non-browser requests, so an HTTP probe makes it look dead."]', rw_faq='[{"question":"How long does Peerlist approval take?","answer":"Launches run in weekly cycles, so a submission typically appears within about a week."},{"question":"Is submitting to Peerlist free?","answer":"Yes, launching is free."},{"question":"Does a Peerlist listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 77."},{"question":"Do I need to link back to Peerlist?","answer":"No backlink is required."},{"question":"Who cannot launch on Peerlist?","answer":"Anyone unwilling to complete identity verification, which the Launchpad requires."}]', rw_summary='Peerlist is a builder network with a weekly launchpad where entries are tied to a verified real profile. Launching is free and dofollow with no backlink requirement; domain rating is 77.', rw_fact_points='["Launches run in weekly cycles","Submission is free and carries a dofollow link","No badge or return link is expected","Identity verification is required to launch"]', rw_submission_checks='["Complete identity verification before attempting to launch — it is mandatory.","Fill the profile carefully; your signup identity becomes the public face of the launch.","Untick the pre-checked LinkedIn autofill if you do not want personal details imported."]', rw_seo_title='Peerlist: Free Verified Launch, DR 77', rw_seo_description='How to launch on Peerlist: free dofollow weekly launchpad, no backlink, but identity verification required. Steps and gates from the 2026-11-16 snapshot.' WHERE slug='peerlist';
UPDATE submission_sites SET rw_source_lead='An AI tools directory on a badge-first flow, with Google as the only sign-in and a house ad for a paid submission service on every page.', rw_what_you_get='A dofollow listing in an AI directory once their crawler finds your badge linking to the listing, with a detailed profile of categories, screenshots and pricing.', rw_you_need='["A Google account — the only sign-in offered","A product homepage you can edit to install the badge","An AI product, since every category is AI-related"]', rw_eligibility='You need a Google account, an AI product and a homepage you can edit to carry their badge. Pages you cannot add a badge to, and anything without an AI angle, are rejected.', rw_submit_steps='["1 Sign in with Google. Log in with Google is the only option on /get-started; there is no email route.","2 Pick the FREE plan. A three-card chooser opens: FREE, BASIC at $25 and PREMIUM at $50 — only the free card is a listing here.","3 Step 1: enter your homepage. /submit is three steps; one Website URL field and a Generate Badge button, and the URL must be the product homepage.","4 Step 2: install and verify the badge. They derive the listing URL from the domain and give light and dark snippets that must link to it followed from your homepage or footer, then you click Verify Badge.","5 Step 3: fill the listing details, unlocked by the badge check — site name up to 40 characters, a screenshot up to 10MB, a square icon up to 5MB, up to four categories from about fifty, a pricing model, a 150-character short description, a 1,500-character about and a terms checkbox."]', rw_submit_requirements='["A Google account","A product homepage you can edit","Their badge on that page linking to your listing as a followed link","A site name, screenshot and square icon","Up to four categories and a pricing model","A short description and a longer about","Acceptance of the terms checkbox"]', rw_rejection_reasons='["A page you cannot add a badge to, and anything without an AI angle"]', rw_gotchas='["The badge comes before the form: listing details are hidden until their crawler finds the badge on your live site, so a deploy must happen midway through submission.","Sign-in is Google-only with no email route, so a maker without Google cannot list at all.","Two of the three plan cards do not list you here at all — they buy a submission service for other directories, yet sit beside the free card with no visible difference in kind."]', rw_faq='[{"question":"How long does Good AI Tools approval take?","answer":"Listings go live immediately once the badge check passes."},{"question":"Is submitting to Good AI Tools free?","answer":"The listing is free; the paid cards are for a separate submission service."},{"question":"Does a Good AI Tools listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 74."},{"question":"Do I need to link back?","answer":"Yes, their badge must link to the listing from your homepage or footer."},{"question":"What gets a submission rejected?","answer":"A page you cannot add a badge to, or anything without an AI angle."}]', rw_summary='Good AI Tools is an AI directory with a badge-first free listing: install their followed badge, then complete the profile. A dofollow link is included and a backlink is required; domain rating is 74.', rw_fact_points='["Listings publish instantly after badge verification","Submission is free and carries a dofollow link","A badge backlink is required","Accepts AI tools, automation, productivity, developer tools and Chrome extensions"]', rw_submission_checks='["Be ready to deploy a badge to your live homepage midway through the flow.","Use a Google account — there is no email sign-in.","Ignore the paid cards; only the FREE plan lists you here."]', rw_seo_title='Good AI Tools: Free Badge Listing, DR 74', rw_seo_description='How to submit to Good AI Tools: free dofollow listing, install their badge first, no email sign-in. Steps and requirements from the 2026-11-16 snapshot.' WHERE slug='good-ai-tools';
UPDATE submission_sites SET rw_source_lead='A curated web design gallery that charges nothing to submit, accepts on taste alone, and treats a month of silence as the rejection.', rw_what_you_get='A dofollow feature in a design-focused gallery, with an entry on your profile''s Made tab if you claim authorship.', rw_you_need='["An account, since submissions attach to a profile and a Made tab","A website that withstands a hands-on design review","Patience — up to a month, with silence as the answer"]', rw_eligibility='You need an account and a site that stands up to a design review, which is the sole criterion. Functional but ordinary sites are usually declined, and anyone needing a decision on a schedule is out of luck.', rw_submit_steps='["1 Read the guidelines at /submission-guidelines, where the whole policy lives: free, open to all, hand-curated, with a review from a few days to a month.","2 Create an account and submit from the interface; /submit itself is a 404 and the control lives in the UI.","3 Tick the authorship checkbox if it is your own site to add the entry to the Made tab on your profile; submitting others'' sites is allowed and is most of the gallery.","4 Wait, and read the silence: a feature comes with an email, and no word within a month means it will not happen — there is no other notification."]', rw_submit_requirements='["An account on the gallery","A live website URL","The authorship checkbox for your own site","A page type from their dozen categories"]', rw_rejection_reasons='["A functional but ordinary site — they curate by hand and decline most submissions, and anyone needing a decision on a schedule"]', rw_gotchas='["Acceptance is a design judgement and most submissions are declined; stated criteria are current trends, aesthetics, usability, accessibility and content, so a working site is not enough.","Rejection is silence: they email only if featured, and their guidelines say a month with no reply means no — there is nothing to check.","Templates are a separate route with a different deal: free to submit, but an approved template gets a payment link before featuring, the opposite of the website policy."]', rw_faq='[{"question":"How long does Landbook approval take?","answer":"Two to four weeks; a month of silence is the rejection."},{"question":"Is submitting to Landbook free?","answer":"Yes, submitting a website is free."},{"question":"Does a Landbook feature provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 73."},{"question":"Do I need to link back to Landbook?","answer":"No backlink is required."},{"question":"What gets a site rejected?","answer":"A functional but ordinary site, since curation is by hand and most submissions are declined."}]', rw_summary='Landbook is a hand-curated web design gallery with free submissions and a dofollow link. Acceptance is purely a design judgement taking up to a month, with silence as rejection; no backlink is required and domain rating is 73.', rw_fact_points='["Review takes two to four weeks with silence as rejection","Submission is free and carries a dofollow link","No badge or return link is expected","Accepts design work, marketing sites, web apps, SaaS and design resources"]', rw_submission_checks='["Expect a tough design review — a working site is not sufficient.","Wait up to a month; no email within that time means rejection.","Tick authorship if it is your own site to attach the entry to your Made tab."]', rw_seo_title='Landbook: Free Design Gallery, DR 73', rw_seo_description='How to submit to Landbook: free curated design gallery, dofollow link, no backlink. Review takes up to a month — 2026-11-16 snapshot.' WHERE slug='land-book';
UPDATE submission_sites SET rw_source_lead='A 9,100-maker launch board with no free lane of its own; the pricing page points free submitters to the operator''s two smaller sites.', rw_what_you_get='A week-long homepage launch with a dofollow link from a DR 74 domain, no badge to install and a shot at a weekly Winner badge.', rw_you_need='["A $12 payment — there is no free launch on this site","An account and a live product","A name, description and tags"]', rw_eligibility='You need to pay, have an account and a live product, and supply a name, description and tags. The pricing page answers the search for a free launch with links to the operator''s two other directories.', rw_submit_steps='["1 Read the pricing page first: the absence of a free lane is disclosed under Looking for a Free Launch?, linking to SaaSGrow.app and StartupTrusted.","2 Pick Basic at $12 for one followed link or Pro at $15 for three. Both skip the queue and neither needs a badge.","3 Submit the product at /submit. There is also a /submit-directories route, a separate list of other directories rather than part of this flow.","4 Get a week on the homepage, competing for a Winner badge awarded to the top three products of the week."]', rw_submit_requirements='["A payment of $12 or $15","An account on the site","A product name, live URL, description and tags","A logo and images for the homepage card"]', rw_rejection_reasons='["Anyone not paying — the pricing page''s answer to looking for a free launch is a link to two other directories"]', rw_gotchas='["There is no free launch here at all; the pricing page points to SaaSGrow.app and StartupTrusted, the same operator''s smaller sites, so free means launching elsewhere.","Pro buys two links you could get for nothing: its extra backlinks come from the operator''s own smaller sites, both of which accept listings directly at no cost."]', rw_faq='[{"question":"How long does LaunchIgniter approval take?","answer":"Paid launches go live immediately with no queue."},{"question":"How much does LaunchIgniter cost?","answer":"Basic is $12 one-time for a week on the homepage and a lifetime dofollow link from a DR 74 domain. Pro is $15 and adds followed links from the operator''s two other sites."},{"question":"Does a LaunchIgniter listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 74."},{"question":"Do I need to link back to LaunchIgniter?","answer":"No backlink or badge is required."},{"question":"Is there a free option?","answer":"No; the pricing page directs free seekers to the operator''s two other directories."}]', rw_summary='LaunchIgniter is a maker launch board with a paid-only $12 or $15 lane, a week on the homepage and a dofollow link with no badge. Domain rating is 74; there is no free launch on this site.', rw_fact_points='["Paid launches go live immediately with a week on the homepage","Paid only, dofollow, no badge required","No return link is expected","Accepts SaaS, indie products, AI tools, developer tools, mobile apps and no-code tools"]', rw_submission_checks='["Expect to pay; the free option points to the operator''s other sites.","Choose Basic unless you specifically want the operator''s extra links.","Have a name, description, tags and logo ready for the homepage card."]', rw_seo_title='LaunchIgniter: $12 Launch, DR 74', rw_seo_description='How to launch on LaunchIgniter: paid $12 or $15 dofollow launch, no badge, no backlink. Free option points elsewhere — 2026-11-16 snapshot.' WHERE slug='launchigniter';
UPDATE submission_sites SET rw_source_lead='A 1,900-server MCP index built entirely from GitHub, and the only way in is an email to the operator.', rw_what_you_get='A dofollow listing shaped like a GitHub repository page, with stars, forks and an outbound link to your repo.', rw_you_need='["A public GitHub repository — every listing is built from one"]', rw_eligibility='You need a public GitHub repository, since every listing is keyed on owner and repo and shows stars and forks. Closed-source servers have nothing to build from, and anything that merely uses AI rather than being an MCP server is out of scope.', rw_submit_steps='["1 Confirm your server has a public repository. Listings are keyed on owner and repo and display stars and forks, which is the shape they accept.","2 Email them. The Submit link in the header and footer is a mailto to the operator; there is no form anywhere on the site."]', rw_submit_requirements='["A public GitHub repository","Contact by email only"]', rw_rejection_reasons='["A closed-source MCP server with no public repository to build the listing from, and anything that merely uses AI rather than being an MCP server"]', rw_gotchas='["There is no submission form — both Submit links are mailto, so getting listed means writing to a person and waiting.","Every listing is a GitHub repository down to the URL shape and star count, so a closed-source server has nothing to list.","/categories/submit-mcp-server looks like a submission page but is actually a category of servers whose names contain those words.","The outbound link goes to the GitHub account rather than a product site, so the link value lands on github.com, not your domain."]', rw_faq='[{"question":"How long does MCP Server Finder approval take?","answer":"No review time is published; submission is by email and a person handles it."},{"question":"Is submitting to MCP Server Finder free?","answer":"Yes, though it is by email rather than a form."},{"question":"Does a listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 14, pointing to your GitHub repo."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"A closed-source server with no public repository, or a product that is not an MCP server."}]', rw_summary='MCP Server Finder is a GitHub-derived index of about 1,900 MCP servers, submitted by email rather than a form. Listings are free and dofollow with no backlink requirement, but the link points to GitHub; domain rating is 14.', rw_fact_points='["Submission is by email with no form","Listings are free and carry a dofollow link","No badge or return link is expected","Only MCP servers with a public GitHub repository are listed"]', rw_submission_checks='["Have a public GitHub repository ready — it is the basis of the listing.","Submit by email to the operator, not through a form.","Know that the outbound link points to GitHub, not your product domain."]', rw_seo_title='MCP Server Finder: Free Email Listing, DR 14', rw_seo_description='How to get listed on MCP Server Finder: free dofollow GitHub-based MCP listing submitted by email, no backlink. Steps from the 2026-11-16 snapshot.' WHERE slug='mcp-server-finder';
UPDATE submission_sites SET rw_source_lead='A large free-resources library for designers whose advertised submit page contains no submission form — only a newsletter box.', rw_what_you_get='A listing among downloadable design resources with a dofollow link, if you can find a working way to reach the operator.', rw_you_need='["A free downloadable resource — the library is built from these, not products","A working route in, which the submit page does not currently provide"]', rw_eligibility='You need a free downloadable resource such as a mockup, icon or logo pack, plus some way to contact the operator. Products you sign into do not fit, and the advertised submit page currently has no form.', rw_submit_steps='["1 Open the advertised submit page at /submit-freebie/, which renders with the right title.","2 Look for the form and find only a newsletter: the only forms served are site search and two Mailchimp signups, with no field for a resource, URL or name.","3 Fall back to a contact route: with no form on the page, anything you want listed has to go through whatever contact address the site offers."]', rw_submit_requirements='["A free resource worth hosting","A contact route, since the submit page provides no form"]', rw_rejection_reasons='["A product rather than a downloadable resource, and anything requiring a working submit form today, since the advertised one has none"]', rw_gotchas='["The submit page carries no submission form — only site search and two newsletter signups — so following their Submit Freebie link leaves nowhere to type.","The library is made of downloadable resources, not products, so a SaaS or app has nothing to submit even once a form appears.","No review time is published and there is no account, so even a successful contact leaves nothing to check."]', rw_faq='[{"question":"How long does Freebie Supply approval take?","answer":"No review time is published."},{"question":"Is submitting to Freebie Supply free?","answer":"Yes, though the submit page has no working form."},{"question":"Does a listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 72."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"A product rather than a downloadable resource, or anything needing a submit form that does not exist."}]', rw_summary='Freebie Supply is a large library of free design resources with a dofollow link and no backlink requirement. The advertised submit page currently has no form, so contact is by other means; domain rating is 72.', rw_fact_points='["No working submission form at present","Listings carry a dofollow link and need no backlink","Accepts design resources and design work","Submission is free"]', rw_submission_checks='["Prepare a downloadable resource, not a SaaS product.","Expect to contact the operator, since the submit page has no form.","There is no account or status page to check afterward."]', rw_seo_title='Freebie Supply: Free Design Resource, DR 72', rw_seo_description='Freebie Supply is a free design-resource library with a dofollow link and no backlink, but its submit page has no form. Details from the 2026-11-16 snapshot.' WHERE slug='freebie-supply';
UPDATE submission_sites SET rw_source_lead='A weekly launch board running about 107 launches a week that ships its own MCP server, so an agent can draft the listing while a human still has to publish.', rw_what_you_get='A dofollow listing in a weekly launch cycle with community voting and a shot at being published by an admin on the chosen Monday.', rw_you_need='["An account via Google sign-in or email and password","A live product URL","A square logo and at least one 16:9 screenshot","For the free lane: their badge on your homepage and three community voting rounds"]', rw_eligibility='You need an account, a live product URL, a square logo and a 16:9 screenshot; the free lane also needs their badge and three voting rounds. No structural rules are published — an admin reviews every listing before it goes live.', rw_submit_steps='["1 Sign in with Google or email and password; both the form and the plan step need a session.","2 Fill the listing: name, tagline, description, website URL, up to three categories, a logo and up to five screenshots. Use cases, alternatives, pricing, FAQ, a keyword and a first comment are optional. Submit launch saves a draft.","3 Pick a plan at /submit/plan/. Free asks for three pick-a-winner voting rounds — two live launches side by side — and their badge with a verify button.","4 Pick a launch week. On free the next four weeks were full in one walk, so the first open week was over three weeks out.","5 Wait for review: the product reads In review until an admin publishes it on the Monday of the chosen week."]', rw_submit_requirements='["An account via Google or email and password","A live product URL","A product name up to 40 characters","A tagline up to 60 characters","A description up to 3,000 characters","Up to three categories","A square logo at least 512x512","One to five 16:9 screenshots at least 1920x1080","Optional pricing details and first comment","Their badge on your homepage for the free launch"]', rw_rejection_reasons='["No structural rule is published; every listing is reviewed by an admin before going live"]', rw_gotchas='["The free badge check reads the submitted URL, not your homepage: submit a subpage with the badge only on root and it says No badge found; the workaround is to continue anyway and leave it to manual review.","Free launches queue by the week and weeks fill — on 2 October the next four were full, pushing a free launch to 26 October; paid tiers publish immediately.","Anything not 16:9 is centre-cropped, and the first screenshot becomes the social image, so a square or phone-shaped shot loses most of itself."]', rw_faq='[{"question":"How long does Nick Launches approval take?","answer":"Two to four weeks: free launches wait for an open week, while paid tiers publish instantly."},{"question":"How much does Nick Launches cost?","answer":"There is a free lane with a badge and voting rounds. Paid tiers are $19, $39, $99 and $199 for increasing featured time and reach; optional directory-submission add-ons are extra."},{"question":"Does a Nick Launches listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 72."},{"question":"Do I need to link back?","answer":"Yes, the free lane requires their badge on your homepage."},{"question":"What gets a listing rejected?","answer":"No fixed rule is published; an admin reviews every listing before it is published."}]', rw_summary='Nick Launches is a high-volume weekly launch board with a free badge-and-voting lane and paid tiers that publish instantly. Listings are dofollow and the domain rating is 72; the free lane requires a badge.', rw_fact_points='["Free launches queue by the week and can wait weeks; paid is instant","Submission is free with a badge lane, and listings are dofollow","A badge backlink is required on the free lane","Accepts SaaS, AI tools, developer tools, indie products, marketing and productivity tools"]', rw_submission_checks='["Use the homepage URL for the badge check, or expect a manual review.","Prepare 16:9 screenshots; anything else is cropped.","Book early — free launch weeks fill quickly.","Use the shipped MCP server if you want an agent to draft the listing."]', rw_seo_title='Nick Launches: Free Weekly Launch, DR 72', rw_seo_description='How to launch on Nick Launches: free badge lane with weekly queue or instant paid tiers, dofollow link. Steps and pitfalls from the 2026-11-16 snapshot.' WHERE slug='nick-launches';
UPDATE submission_sites SET rw_source_lead='Two directories on one domain: free hosting for open source, and a 122,100-title business catalogue whose links all pass through a nofollow redirect.', rw_what_you_get='A business software listing in a huge catalogue, though outbound links are nofollow and the whole request is bundled with marketing consent.', rw_you_need='["A square logo, required by the business form","A description up to 1,000 characters and a named audience","One category from about 2,830","Agreement to their terms, bundled with consent to receive marketing"]', rw_eligibility='You need a square logo, a description and audience, a category and acceptance of terms and marketing consent. Consumer apps are out of scope — the business directory is organised around software a company buys — and anyone unwilling to opt into their communications cannot proceed.', rw_submit_steps='["1 Pick which SourceForge you are on. Create a Project is the open-source side with hosting, releases and download stats; Add a Commercial Product is the business directory, and the two share only a domain.","2 Decline the consent wall. The vendor form opens behind a cookie dialog naming 31 third parties; I DO NOT ACCEPT dismisses it.","3 Fill the company half: name, email, company, job title and website are required; phone, founding year and location are not. It is a vendor form, so it asks who you are first.","4 Fill the software half: title up to 60 characters, the required logo, a description up to 1,000 characters, the audience in your own words, one category from about 2,830, a starting price and checkbox rows for free options, support, training and deployment.","5 Consent and wait. The last control is a required checkbox agreeing to terms, privacy and receiving communications; the page calls it a request for a business listings page and gives no time."]', rw_submit_requirements='["Your name, email, company and job title","A product website","A software title up to 60 characters","A square logo in JPG, GIF or PNG","A description up to 1,000 characters","A described audience","One of about 2,830 categories","Agreement to terms and to receiving communications","Optional starting price and feature checkboxes"]', rw_rejection_reasons='["A consumer app, since the directory is organised around software a company buys, and anyone unwilling to accept the bundled marketing consent"]', rw_gotchas='["The required consent checkbox bundles agreeing to terms and agreeing to receive communications; there is no way to accept one without the other.","It is a request, not a submission: the page''s own subtitle says Request a business listings page and nothing says how long it takes.","The category select holds about 2,830 options and only one can be chosen, burying the most important discovery decision in an unreadable list."]', rw_faq='[{"question":"How long does SourceForge approval take?","answer":"No review time is published; the form calls itself a request for a listings page."},{"question":"Is submitting to SourceForge free?","answer":"Yes, the business listing request is free."},{"question":"Does a SourceForge listing provide a dofollow link?","answer":"No. Links are nofollow through a redirect on a domain rated 92."},{"question":"Do I need to link back?","answer":"No return link is required."},{"question":"What gets a listing rejected?","answer":"A consumer app, since the catalogue targets business software, or unwillingness to accept the bundled marketing consent."}]', rw_summary='SourceForge houses both free open-source hosting and a 122,100-title business software catalogue. The business listing is free with a nofollow link and no backlink, but requires bundled marketing consent; domain rating is 92.', rw_fact_points='["Business listing is a free request with no published timeline","Listings carry nofollow links and need no backlink","Marketing consent is bundled into the required terms","Targets B2B software, SaaS, open source, developer and enterprise tools"]', rw_submission_checks='["Use the Add a Commercial Product route, not Create a Project.","Prepare a square logo and a 1,000-character description with a clear audience.","Be aware that accepting terms also opts you into their communications.","Choose the single category carefully from the large list."]', rw_seo_title='SourceForge: Free Business Listing, DR 92', rw_seo_description='How to request a SourceForge business listing: free, nofollow link, no backlink, but marketing consent required. Steps from the 2026-11-16 snapshot.' WHERE slug='sourceforge';
UPDATE submission_sites SET rw_source_lead='An AI and SaaS directory with a two-day review and a dofollow link on live listings, whose free lane costs only a badge in your footer.', rw_what_you_get='A dofollow listing reviewed within two days, with a free lane priced by a permanent footer badge rather than a fee.', rw_you_need='["An account via the Sign In control","Their badge in your website footer on the free lane","A product name, URL and description"]', rw_eligibility='You need an account, a product name, URL and description, and a footer you can add their badge to on the free lane. A site where you cannot place the badge needs the $9.90 paid lane.', rw_submit_steps='["1 Choose a plan. /pricing lists four paid tiers and a free lane at the bottom under Or; the free card carries the badge embeds.","2 Sign in through the modal opened by the header''s Sign In button. Google and GitHub are the only providers.","3 Fill the listing with product details and one of 24 categories, from Image Generation and Chatbots to Browser Extensions and No Code.","4 Take a badge embed — dark, light or transparent — and add a followed link back to them in your footer.","5 Wait two days: the free lane states a review within two days, quick for this bracket."]', rw_submit_requirements='["An account on the site","A product name, URL and description","One of 24 categories","Their badge in your footer for the free lane","A logo and screenshots"]', rw_rejection_reasons='["A site you cannot add a footer badge to, unless you take the $9.90 lane"]', rw_gotchas='["The free lane''s price is a permanent footer badge, worded on the pricing card as a benefit of the free plan rather than its cost.","Monthly Promotion is a subscription dressed as a $5 offer: $5 for the first month then $10, buying a monthly re-float to the top of the list.","Featured and Ultimate bundle AI-written blog posts about your product, so their model''s copy gets published under those tiers."]', rw_faq='[{"question":"How long does DeepLaunch approval take?","answer":"One to two days; the free lane states a review within two days."},{"question":"How much does DeepLaunch cost?","answer":"There is a free lane with a footer badge. Paid options are $9.90 one-time with no badge, $5 then $10 monthly promotion, $29.90 monthly Featured and $199 yearly Ultimate."},{"question":"Does a DeepLaunch listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 70."},{"question":"Do I need to link back?","answer":"Yes, the free lane requires their badge in your footer."},{"question":"What gets a listing rejected?","answer":"A site that cannot carry a footer badge, unless you pay the $9.90 lane."}]', rw_summary='DeepLaunch.io is an AI and SaaS directory with a two-day review and a dofollow link. The free lane requires a footer badge, no backlink is otherwise expected, and domain rating is 70.', rw_fact_points='["Free listings review within two days","Submission is free and carries a dofollow link","A footer badge is required on the free lane","Accepts AI tools, SaaS, no-code, developer tools, design and marketing tools"]', rw_submission_checks='["Be ready to place a permanent footer badge if using the free lane.","Ignore the subscription tiers unless you want monthly re-promotion.","Note that higher tiers publish AI-written posts about your product."]', rw_seo_title='DeepLaunch.io: Free Badge Listing, DR 70', rw_seo_description='How to submit to DeepLaunch.io: free two-day dofollow listing with a footer badge, no email sign-in. Pricing and steps from the 2026-11-16 snapshot.' WHERE slug='deeplaunch';
UPDATE submission_sites SET rw_source_lead='A 780,000-visitor AI ecosystem catalogue whose only listing route is a $199-a-year subscription — and it does not say so until the Stripe page.', rw_what_you_get='A dofollow listing in a heavily visited AI catalogue, rented by annual subscription rather than bought with a one-time fee.', rw_you_need='["$199 a year — there is no free route","A Google account or an email and password login","A tool name and a URL beginning https://"]', rw_eligibility='You need to subscribe for $199 a year, sign in with Google or email, and supply a name and HTTPS URL. Anyone not paying is excluded, and anything without an AI or MCP angle is out of place in the catalogue.', rw_submit_steps='["1 Find the right URL. /submit is a 404; the header''s Submit a Tool control points to /friends/launch-tool, the only entry point.","2 Sign in with Google or email and password; a signed-out visitor bounces to /signin and back.","3 Fill two fields — Tool Name and Tool URL — plus a checkbox for a free social boost to their X and LinkedIn accounts. That is the whole form.","4 Continue to Subscription, which goes straight to Stripe, where the price appears for the first time: $199 a year, billed annually."]', rw_submit_requirements='["$199 a year","A Google account or an email and password login","A tool name and an HTTPS URL","An optional checkbox for a free social boost"]', rw_rejection_reasons='["Anyone not paying, since the only button goes to a Stripe subscription, and anything without an AI or MCP angle"]', rw_gotchas='["The price appears only on the Stripe page: the launch page lists benefits, visitor stats and newsletter numbers, and the button says Continue to Subscription without ever naming $199 a year.","It is a subscription, not a one-time listing fee — the listing is rented at $199 a year rather than bought once.","The submit path most would guess, /submit, is a 404; the working entry is /friends/launch-tool, reachable only from the header control."]', rw_faq='[{"question":"How long does OpenTools approval take?","answer":"Three to five days after subscribing."},{"question":"How much does OpenTools cost?","answer":"The listing is a $199 annual subscription billed yearly, described on the Stripe page as Premium Listing; there is no monthly or free tier. Sponsorship and sales routes are separate."},{"question":"Does an OpenTools listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 69."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Anyone not paying, or anything without an AI or MCP angle."}]', rw_summary='OpenTools is a high-traffic AI catalogue where the only listing route is a $199 annual subscription revealed at Stripe. The dofollow listing needs no backlink and takes three to five days; domain rating is 69.', rw_fact_points='["Paid-only at $199 a year, revealed at checkout","Listings go live in three to five days and are dofollow","No badge or return link is expected","Focuses on AI tools, MCP servers, developer tools, AI models and SaaS"]', rw_submission_checks='["Expect a $199 annual subscription, not a one-time fee.","Use the header''s Submit a Tool route; /submit is broken.","Have a tool name and an HTTPS URL ready."]', rw_seo_title='OpenTools: $199/yr AI Listing, DR 69', rw_seo_description='How to list on OpenTools: $199 annual dofollow subscription revealed at Stripe, no backlink, 3-5 day review. Steps from the 2026-11-16 snapshot.' WHERE slug='opentools';
UPDATE submission_sites SET rw_source_lead='Five design links a day — and only five — hand-picked by an editor.', rw_what_you_get='A dofollow link in a tightly curated daily design newsletter, if an editor chooses your submission among the pitch pile.', rw_you_need='["An account — the submit page shows nothing until you are logged in","Something genuinely about design"]', rw_eligibility='You need an account and something genuinely about design. Anything outside design is rejected, since the whole feed is five design links a day.', rw_submit_steps='["1 Log in. The submit page shows only a log-in or sign-up prompt until you do.","2 Submit a link rather than a product listing.","3 Wait for the day: five links go out each weekday and an editor picks them."]', rw_submit_requirements='["A single URL — a link, not a product profile"]', rw_rejection_reasons='["Anything outside design, since the daily feed is strictly five design links"]', rw_gotchas='["Only five links are published a day, so this is a pitch to an editor rather than an entry in a directory.","The unit is a link, not a product page, so there is nothing permanent to point at afterward.","Design only — most products not made for designers are ruled out."]', rw_faq='[{"question":"How long does Sidebar approval take?","answer":"No review time is published; an editor picks five links each weekday."},{"question":"Is submitting to Sidebar free?","answer":"Yes, submitting a link is free."},{"question":"Does a Sidebar link provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 70."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a link rejected?","answer":"Anything outside design, since the feed is five design links a day."}]', rw_summary='Sidebar is a curated daily design newsletter publishing five links a weekday. A featured link is free and dofollow with no backlink requirement; domain rating is 70, and selection is entirely at an editor''s discretion.', rw_fact_points='["Only five design links are published each weekday","Submission is free and carries a dofollow link","No badge or return link is expected","Accepts design tools and design resources"]', rw_submission_checks='["Treat this as a pitch to an editor, not a directory entry.","Make sure your link is genuinely about design.","Expect no permanent listing page afterward."]', rw_seo_title='Sidebar: Free Design Link, DR 70', rw_seo_description='How to submit to Sidebar: free dofollow design link in a five-a-day curated feed, no backlink. Steps and selection odds from the 2026-11-16 snapshot.' WHERE slug='sidebar-io';
UPDATE submission_sites SET rw_source_lead='The hackathon world''s project gallery: free, instant, nofollow, and gated at the first step by a reCAPTCHA.', rw_what_you_get='An instantly published project page in a maker-focused gallery, with a dofollow-free outbound link — useful for credibility and demos, not SEO.', rw_you_need='["An account via GitHub, Google, Facebook, LinkedIn or email and password","A project name of 60 characters or fewer","A human to solve the reCAPTCHA on the first step"]', rw_eligibility='You need an account, a short project name and a person to pass the reCAPTCHA. A commercial pitch with nothing built does not fit — the gallery is for real projects, usually with a repo and a demo.', rw_submit_steps='["1 Sign in with one of four social buttons — GitHub, Facebook, Google, LinkedIn — or email and password; Google creates the account on the spot.","2 Skip the recommendations wizard. First sign-in lands on a form asking specialty, skills, location, occupation, school and birth month; going straight to /software/new bypasses it.","3 Name the project and pass the reCAPTCHA. Step one is the name alone, capped at 60 characters, with an Import from GitHub shortcut; Save and continue will not post until the check is solved.","4 Fill the project page at /software/<slug>/edit: a 200-character elevator pitch, up to 25 Built with tags, and a markdown story whose Inspiration and What it does headings are convention, not separate fields, plus a thumbnail, gallery, Try it out links and video.","5 Save and it publishes at once with no review or queue; Edit project stays available to finish the story afterward."]', rw_submit_requirements='["An account via a social provider or email and password","A project name up to 60 characters","A human to solve the reCAPTCHA","An elevator pitch up to 200 characters","At least one Built with tag","The project story in markdown","A 3:2 thumbnail under 5MB","An optional GitHub repo for the importer","Gallery images and a demo video"]', rw_rejection_reasons='["A commercial pitch with nothing built — the gallery is for projects, usually with a repo and demo"]', rw_gotchas='["A reCAPTCHA guards the first step before any project content is requested, so nothing here can be automated end to end.","First sign-in drops you into a recommendations wizard asking school and birth month; none of it is needed — go straight to /software/new.","The page is written for a hackathon entry, with story headings asking what inspired you and what you learned; a product listing pasted into that shape reads as an ad.","Whatever your account is called is printed under the project as creator, often the product name rather than a person''s on a launch account."]', rw_faq='[{"question":"How long does Devpost approval take?","answer":"Projects publish instantly with no review."},{"question":"Is submitting to Devpost free?","answer":"Yes, posting a project is free."},{"question":"Does a Devpost project provide a dofollow link?","answer":"No. Links are nofollow on a domain rated 88."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a project rejected?","answer":"A commercial pitch with nothing built; the gallery expects real projects with a repo and demo."}]', rw_summary='Devpost is a hackathon project gallery where submissions publish instantly and free. Links are nofollow with no backlink requirement, a reCAPTCHA gates the first step, and domain rating is 88.', rw_fact_points='["Projects publish instantly with no review","Submission is free and links are nofollow","No badge or return link is expected","Accepts developer tools, open source, side projects, AI tools and mobile apps"]', rw_submission_checks='["Have a person ready to solve the reCAPTCHA.","Skip the recommendations wizard by going straight to /software/new.","Write the story in a hackathon voice, not as a product pitch.","Import from GitHub to save filling the basics."]', rw_seo_title='Devpost: Free Project Gallery, DR 88', rw_seo_description='How to post on Devpost: free instant project gallery, nofollow link, no backlink, reCAPTCHA required. Steps from the 2026-11-16 snapshot.' WHERE slug='devpost';
UPDATE submission_sites SET rw_source_lead='A maker profile page that costs $25 to publish, with its startups landing on a 5,700-product Discover feed.', rw_what_you_get='A dofollow maker page and an entry for each startup on a large Discover feed, once you buy a pass to publish.', rw_you_need='["An Indie Page account and a handle","A startup to add to your page","$25 or $45 once, to publish the page at all"]', rw_eligibility='You need an account, a handle, a startup and a one-time pass to publish. A product with no live URL has nothing for the Discover feed to point at.', rw_submit_steps='["1 Claim a page. Pick a handle and sign up from the homepage with Google, Twitter or an emailed link; signup is a homepage section, not its own route.","2 Build it in the editor with a name, bio and avatar, then Add Startup with a URL — it fetches the name and lets you set a tagline and logo. Everything auto-saves as a draft.","3 Pay to deploy. Deploy goes to /admin/upgrade: $25 a year or $45 once. Until then the page shows a draft with an upgrade banner and your startups are not on the feed.","4 Appear on Discover. Each startup goes on the feed under its category, ranked by the page''s traffic score; there is no review."]', rw_submit_requirements='["A handle","A startup name, tagline and URL","A logo"]', rw_rejection_reasons='["A product with no live URL for the Discover feed to point at"]', rw_gotchas='["Free stops at the editor: Deploy is the upgrade page, and a page plus product cannot reach Discover for $0.","Discover is a by-product of a profile page, so your product sits under your name rather than on its own page — the maker page is the listing.","The feed ranks by the page''s traffic score, so a page nobody visits sits at the bottom of its category."]', rw_faq='[{"question":"How long does Indie Page approval take?","answer":"Publishing is instant once a pass is bought; there is no review."},{"question":"How much does Indie Page cost?","answer":"Building the page and adding startups is free in the editor, but publishing needs a pass: $25 a year or $45 once, both adding a custom domain, analytics and other maker tools."},{"question":"Does an Indie Page listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 67."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"A product with no live URL for the Discover feed to point at."}]', rw_summary='Indie Page is a maker profile platform where a free editor builds the page but a $25 or $45 pass is required to publish and reach its Discover feed. Listings are dofollow with no backlink; domain rating is 67.', rw_fact_points='["Publishing requires a paid pass; there is no review","Listings are dofollow with no backlink requirement","The maker page, not the product, is the listing","Accepts indie startups, side projects and solopreneur products"]', rw_submission_checks='["Expect to pay before anything becomes public.","Have a live product URL — it is what Discover points at.","Drive traffic to your maker page; feed rank uses its traffic score."]', rw_seo_title='Indie Page: Paid Maker Page, DR 67', rw_seo_description='How to list on Indie Page: free editor but $25 or $45 pass to publish, dofollow Discover listing, no backlink. Steps from the 2026-11-16 snapshot.' WHERE slug='indie-page';
UPDATE submission_sites SET rw_source_lead='An AI tools directory that will not show you the listing form until their badge is live on your site and their crawler has seen it.', rw_what_you_get='A dofollow listing in an AI directory, unlocked only after a followed badge to your listing URL is deployed and verified on your homepage.', rw_you_need='["A Google account — the only sign-in offered","A product homepage whose HTML you control","Their badge on that page or in its footer, linking followed to your listing URL"]', rw_eligibility='You need a Google account, a homepage you can edit and their followable badge installed there. A page you cannot change cannot pass the badge check, and anything that is not a software tool is out of place in the AI and automation taxonomy.', rw_submit_steps='["1 Sign in with Google. Log in with Google is the only option on /submit while signed out, with Create an account leading to the same place; there is no email form.","2 Step 1: enter your homepage — one Website URL field and a Generate Badge button. The URL must be the product homepage that the check will fetch.","3 Step 2: install and verify the badge. They derive the listing URL from the domain and provide light and dark snippets that must link to it followed; a Website URL to Check field is what the crawler fetches, then Verify Badge.","4 Step 3: fill the listing details, unlocked by the badge check — site name up to 40 characters, a screenshot up to 10MB, a square icon up to 5MB, up to four categories from about fifty, a pricing model, a 150-character short description, a 1,500-character about and a terms checkbox."]', rw_submit_requirements='["A Google account","A product homepage you can edit","Their badge linking to your listing URL as a followed link","A site name, screenshot and square icon","Up to four categories and a pricing model","A short description and longer about","Acceptance of the terms checkbox"]', rw_rejection_reasons='["A product on a page you cannot edit, since the badge check is step two of three with no way past it, and anything that is not a software tool"]', rw_gotchas='["The badge is step two of three, not a final polish: you cannot see the listing form until their crawler finds the badge live, so budget for a deploy midway through submission.","The badge must link to one exact URL generated from your domain and be followed; pointing at their homepage or wrapping it nofollow fails with no indication which went wrong.","Sign-in is Google-only — no email route or other provider — so a Google account you cannot open means no listing.","Every page including the submit flow carries an ad for a paid submission service from the same operator, upselling against the free lane you are filling."]', rw_faq='[{"question":"How long does Acid Tools approval take?","answer":"Listings go live instantly once the badge is verified."},{"question":"Is submitting to Acid Tools free?","answer":"The listing is free; a separate paid submission service is advertised."},{"question":"Does an Acid Tools listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 66."},{"question":"Do I need to link back?","answer":"Yes, a followed badge to your listing URL is required."},{"question":"What gets a submission rejected?","answer":"A page you cannot edit to install the badge, or anything that is not a software tool."}]', rw_summary='Acid Tools is an AI tools directory with a badge-gated free listing: install a followed badge midway through the flow to unlock the form. The listing is dofollow and needs a backlink; domain rating is 66.', rw_fact_points='["Listings publish instantly after badge verification","Submission is free and carries a dofollow link","A followed badge is required","Accepts AI tools, automation, productivity, developer tools, Chrome extensions and chatbots"]', rw_submission_checks='["Be ready to deploy a badge to your live homepage during submission.","Link the badge to the exact generated listing URL, followed.","Use a Google account — there is no other sign-in."]', rw_seo_title='Acid Tools: Free Badge Listing, DR 66', rw_seo_description='How to submit to Acid Tools: free dofollow listing, install their followed badge first, Google sign-in only. Steps from the 2026-11-16 snapshot.' WHERE slug='acid-tools';
UPDATE submission_sites SET rw_source_lead='Free to list, with no card up front and an application rather than a form, reviewed by a buyer-focused marketplace.', rw_what_you_get='A dofollow B2B listing in a buyer-oriented comparison catalogue, placed after a manual review rather than published on submit.', rw_you_need='["A vendor account on the partner portal — full name, company, phone, work email and password, all required","A live product URL","Something a business buyer would compare against alternatives"]', rw_eligibility='You need a vendor account, a live product and something in a procurement category. A product with no business buyer is rejected, since every category is organised around buying decisions.', rw_submit_steps='["1 Read the listing criteria on the Get Listed page, above the apply button.","2 Create a vendor account. Apply to get listed goes to a separate portal requiring full name, company, job title, phone, a work email and a password — personal addresses like Gmail are refused — then a six-digit code is emailed.","3 Add the product on the form behind the account.","4 Wait for manual review against the criteria; the Get Listed page says new listings are reviewed within two weeks, usually faster."]', rw_submit_requirements='["Vendor account: name, company, job title, phone, work email and password","A live B2B product URL"]', rw_rejection_reasons='["A product with no business buyer, since every category is a procurement one"]', rw_gotchas='["It is an application, not a publishing form: the language is apply and criteria throughout, and every submission is reviewed within two weeks.","Applying is not a form on the marketing page — it hands you to a separate vendor portal where the account comes first, a phone number and a work-domain email are required, Gmail is refused by name, and a six-digit code is sent before you continue.","The site is built around buyers, so a listing competes with review scores and comparison tables rather than a launch feed.","Claiming your own profile afterward is a separate paid product."]', rw_faq='[{"question":"How long does SpotSaaS approval take?","answer":"One to two weeks; the site says within two weeks, usually faster."},{"question":"Is submitting to SpotSaaS free?","answer":"Yes, the application and listing are free; claiming a profile is a separate paid product."},{"question":"Does a SpotSaaS listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 66."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"A product with no business buyer, since every category is about procurement."}]', rw_summary='SpotSaaS is a free B2B comparison directory where listing is an application through a separate vendor portal, reviewed within two weeks. Listings are dofollow with no backlink; domain rating is 66.', rw_fact_points='["Application reviewed within one to two weeks","Submission is free and carries a dofollow link","No badge or return link is expected","Accepts B2B and SaaS products"]', rw_submission_checks='["Use a work-domain email; personal addresses are refused.","Prepare a phone number and vendor details for the separate portal.","Expect a manual review against published criteria.","Frame the product for a business buyer comparing alternatives."]', rw_seo_title='SpotSaaS: Free B2B Listing, DR 66', rw_seo_description='How to get listed on SpotSaaS: free dofollow B2B listing via vendor application, no backlink, reviewed in two weeks — 2026-11-16 snapshot.' WHERE slug='spotsaas';
UPDATE submission_sites SET rw_source_lead='A DR 83 founder network where a free company profile pulls in your markets, team and investors — but links back nofollow.', rw_what_you_get='A company profile inside a large founder network, surfaced through accelerator, deal and jobs feeds, with a nofollow outbound link.', rw_you_need='["An account — the whole gate","A company with a live site","A category, location and founding year"]', rw_eligibility='You need an account, a company with a live site, and a category, location and founding year. Nothing is published as a rejection rule; the network is broad and profiles are free.', rw_submit_steps='["1 Make an account first — nothing is addable without one. Options are Google, email, and LinkedIn or Facebook behind Continue another way.","2 Add your Company or Organization: a name and a website, and the page exists immediately. An invite-team screen follows and can be cancelled.","3 Work the editor''s nine sections: Overview, Investors, Page Info, Team, Decks and Media, Product, Traction, Recommendations and Advanced. It saves as you go.","4 Fill the markets picker properly — a closed vocabulary that rejects invented phrases and adds a parent category per pick; they ask for five or more.","5 Check Advanced before leaving: Stealth mode and Disable visibility on search engines both live there, unticked by default."]', rw_submit_requirements='["An account","A company name and live URL","A one-line description","Categories from a closed list","A location and founding year","Team members and investors","Software pricing and features, which unlock reviews"]', rw_rejection_reasons='["Nothing published as a rule — the founder network is broad and profiles are free"]', rw_gotchas='["The outbound link is rel=noopener noreferrer nofollow even on an established profile, so a DR 83 domain buys nothing in link terms.","It is not a launch board: no launch day, upvote or front page; the page earns traffic through accelerator, deal and jobs feeds.","There is no review or queue — the page is public from the moment you name it, so a half-filled one is public too.","Everything is behind an account; there is no anonymous submit form anywhere.","The profile is public and semi-collaborative: employees can attach themselves and users can leave software reviews, both visible on the page."]', rw_faq='[{"question":"How long does F6S approval take?","answer":"Profiles go live instantly with no review."},{"question":"Is submitting to F6S free?","answer":"Yes, company profiles are free."},{"question":"Does an F6S profile provide a dofollow link?","answer":"No. Links are nofollow on a domain rated 83."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a profile rejected?","answer":"Nothing published as a rule; the network is broad and profiles are free."}]', rw_summary='F6S is a large founder network where a free company profile publishes instantly with a nofollow link and no backlink requirement. Profiles are enriched with markets, team and investors; domain rating is 83.', rw_fact_points='["Profiles publish instantly with no review","Submission is free and links are nofollow","No badge or return link is expected","Accepts startups, SaaS, B2B software and AI tools"]', rw_submission_checks='["Expect no SEO value — the outbound link is nofollow.","Fill at least five markets from the closed vocabulary.","Check Advanced for stealth and search-engine visibility settings.","Complete the profile; a partial one is public immediately."]', rw_seo_title='F6S: Free Founder Profile, DR 83', rw_seo_description='How to create an F6S company profile: free instant listing, nofollow link, no backlink. Profile sections and gotchas from the 2026-11-16 snapshot.' WHERE slug='f6s';
UPDATE submission_sites SET rw_source_lead='An AI directory whose free lane is paid for with a permanent dofollow link back, and whose intake refuses directories in its own words.', rw_what_you_get='A dofollow listing reviewed within two to four weeks, free if you keep a followed link live on your site permanently.', rw_you_need='["An email address you can open for the sign-in link","A site where a badge or text link can stay live permanently","An AI tool — the intake makes you attest you are not a directory, agency or job board"]', rw_eligibility='You need an email sign-in, a permanent home for their link and an AI tool. Directories, agencies, job boards and non-AI services are rejected on the free package; mature or NSFW tools use a separate intake.', rw_submit_steps='["1 Sign in with the emailed link — no password, Google or GitHub. /submit and /pricing redirect to /login until you follow it.","2 Choose a package. Submit a tool lands on /pricing: Free, Basic at $49, Pro at $30 plus $19 a month, plus a separate tab for NSFW tools.","3 Put their link up first. The free package opens a backlink dialog with a badge embed or plain text link; the intake unlocks only after verification.","4 Attest and submit for verification: four checkboxes — link is up, this is an AI tool not a directory, agency or job board, it is not NSFW, and you are authorised and understand the link must stay live.","5 Return for the real intake after the crawler visits. The details URL is dead until the link is found, then unlocks copy, two images, a category and a keyword.","6 Wait for review. Submitting redirects to the dashboard and the row turns Pending Review; up to four weeks free versus four days on Basic, and under review is not yet a listing."]', rw_submit_requirements='["An email address for the sign-in link","Their badge or a text link, live and crawlable before the intake opens","A tool name up to 160 characters","A short description of 10 to 75 characters and a longer one up to 8,000, both plain text","A 1200x630 listing image up to 5MB and a square logo up to 2MB","A primary keyword and a category","An optional submitter avatar, social profile and competitor URLs"]', rw_rejection_reasons='["Directories, agencies, job boards and non-AI services on the free package — attesting otherwise does not settle it, since a human judges at review after the badge is up; and mature or NSFW tools, which have their own intake"]', rw_gotchas='["The AI-tool question is decided at review, not at the form: a required checkbox asks you to attest, then a reviewer checks, and a directory can be refused after both forms and the badge are done.","The free listing is rented, not owned — it stays active only while your badge or link is up, so removing the link later removes the listing.","The requested backlink is explicitly dofollow, with a snippet shipping rel=dofollow noopener: you are paying for a followed link with a followed link.","A refusal costs the badge work, not just the wait, because the link goes live before the intake opens."]', rw_faq='[{"question":"How long does Dang.ai approval take?","answer":"Two to four weeks on the free package; Basic cuts review to four days."},{"question":"How much does Dang.ai cost?","answer":"Free is $0 paid for with a crawlable dofollow link. Basic is $49 with no backlink and four-day review; Pro is $30 plus $19 a month with four categories and featured placement. Paid lanes accept products the free one refuses."},{"question":"Does a Dang.ai listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 82."},{"question":"Do I need to link back?","answer":"Yes — the free package requires a permanent dofollow link to the site."},{"question":"What gets a submission rejected?","answer":"Directories, agencies, job boards and non-AI services on the free lane; NSFW tools need their separate intake."}]', rw_summary='Dang.ai is an AI directory where the free listing is funded by a permanent dofollow link back and takes two to four weeks to review. A dofollow link is included and a backlink is required; domain rating is 82.', rw_fact_points='["Free listings take two to four weeks; Basic four days","Submission is free and carries a dofollow link","A permanent dofollow backlink is required on the free lane","Accepts AI tools, chatbots, marketing, productivity, design and automation tools"]', rw_submission_checks='["Be ready to host a permanent dofollow link before the intake opens.","Attest honestly — a human decides AI eligibility at review.","Expect the listing to disappear if you remove the link later.","Consider Basic if you want no backlink and a four-day review."]', rw_seo_title='Dang.ai: Free Link-Backed Listing, DR 82', rw_seo_description='How to submit to Dang.ai: free dofollow AI listing funded by a permanent link back, 2-4 week review. Steps and rules from the 2026-11-16 snapshot.' WHERE slug='dang-ai';
UPDATE submission_sites SET rw_source_lead='Ten dollars, listed within two days, and the link really is followed.', rw_what_you_get='A dofollow listing within 48 hours for a one-time $10 payment, with no backlink required.', rw_you_need='["A live product URL","An email address they can reply to","Willingness to pay — the form has a single paid plan"]', rw_eligibility='You need a live product, a reachable email and payment. Anyone unwilling to pay is excluded, since the only plan on the form is the paid one.', rw_submit_steps='["1 Fill the form: name, URL, a title and a detailed description, with more fields folded under Provide more.","2 Take the plan — one radio option, 10 USD presented as 4,000 credits.","3 Wait for the email. They say they will contact you by email if the tool is accepted, within 48 hours."]', rw_submit_requirements='["A detailed description — a paragraph, not a tagline"]', rw_rejection_reasons='["Anyone unwilling to pay, since the single plan on the form is the paid one"]', rw_gotchas='["The only plan on the form is the paid one, so there is nothing to press unless you are spending the ten dollars.","Acceptance arrives by email rather than a page, so there is no status to check after paying.","Provide more folds away half the form, and opening it clears what you already typed underneath."]', rw_faq='[{"question":"How long does Tap4 AI approval take?","answer":"One to two days, with a reply promised within 48 hours."},{"question":"How much does Tap4 AI cost?","answer":"A one-time 10 USD, sold as 4,000 credits, for a listing within 48 hours; there is no free lane."},{"question":"Does a Tap4 AI listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 61."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Anyone unwilling to pay — the form has only the paid plan."}]', rw_summary='Tap4 AI is a paid AI directory with a single $10 one-time listing, dofollow and live within two days. No backlink is required; domain rating is 61.', rw_fact_points='["Paid-only at $10, listed within 48 hours","Submission is free of backlink requirements and carries a dofollow link","No badge or return link is expected","Accepts AI tools and SaaS products"]', rw_submission_checks='["Expect to pay $10 — there is no free lane.","Write a real paragraph for the description.","Acceptance comes by email; there is no status page."]', rw_seo_title='Tap4 AI: $10 Dofollow Listing, DR 61', rw_seo_description='How to submit to Tap4 AI: $10 one-time dofollow listing within 48 hours, no backlink. Steps and caveats from the 2026-11-16 snapshot.' WHERE slug='tap4-ai';
UPDATE submission_sites SET rw_source_lead='Twelve hand-picked tools a day, with a free lane that trades one dofollow link for a badge and a short review.', rw_what_you_get='A listing with a logo, screenshot, headline and description plus one followed link, in a daily directory that files tools across 124 categories.', rw_you_need='["A live URL — the only input the first step asks for","Their badge or a plain link to the directory on your homepage or footer, on the free lane","A tool name within 24 characters and a headline within 92","A contact email"]', rw_eligibility='You need a live URL, a short name and headline, an email, and a badge or plain link back on the free lane. Anything judged low quality or spam — alongside adult content, gambling and drugs — is declined.', rw_submit_steps='["1 Pick a lane at /submit. Two cards: Free continues with a hidden plan set to free; Pro is a Stripe checkout at $25.20 after their coupon.","2 Give them the URL and wait. Step one takes only the URL and spends about half a minute writing a description and screenshotting the site.","3 Swap the screenshot if it caught something. The capture is live, so a consent banner or modal open at that moment appears in the listing; Upload my own image sits next to Retake.","4 Correct what their AI wrote. The review step is prefilled and, on one walk, the 24-character name field held the homepage headline. There is a logo upload, a letter-logo fallback checkbox, one category from 124 and an email.","5 Verify the badge. Submit for verification registers without publishing; four 148x40 badge designs are offered, and a plain link back will do. Verify my website publishes it — on one walk instantly rather than the quoted 72 hours."]', rw_submit_requirements='["A live URL","A tool name up to 24 characters","A headline up to 92 characters","One category from 124","A contact email","Their badge or a link to the directory on your homepage or footer, free lane","A logo image or letter-logo fallback","A long description and your own screenshot"]', rw_rejection_reasons='["Anything judged low quality or spam, with adult content, gambling and drugs named explicitly"]', rw_gotchas='["Their AI fills the listing from a scrape before you see the form and can put the homepage headline in the name field — read every prefilled field, not just the obviously wrong one.","The screenshot is taken live, so whatever your consent banner is doing at that moment is what the listing shows.","Leaving the flow loses your place: re-entering the URL says the site is already in the review queue, with a link back to the badge step, and nothing warns you until you try."]', rw_faq='[{"question":"How long does approval take?","answer":"The card quotes 72 hours, but listings can go live the moment the badge check passes."},{"question":"How much does it cost?","answer":"There is a free lane with a badge. Pro is $36 once, discounted to $25.20 with a FROGDR code, buying three followed links, two categories, a 24-hour review, homepage features and no badge."},{"question":"Does a listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 81."},{"question":"Do I need to link back?","answer":"Yes, the free lane expects a badge or plain link back from your site."},{"question":"What gets a submission rejected?","answer":"Anything judged low quality or spam, including adult content, gambling and drugs."}]', rw_summary='Twelve Tools is a daily curated directory publishing twelve tools across 124 categories. The free lane gives a dofollow link for a badge with a short review; a Pro tier removes the badge. Domain rating is 81.', rw_fact_points='["Free lane publishes after a badge check, quoted at 72 hours","Submission is free and carries a dofollow link","A badge or backlink is required on the free lane","Accepts SaaS, AI tools, developer tools, directories, design, marketing and productivity tools"]', rw_submission_checks='["Read every AI-prefilled field — the name field can hold your homepage headline.","Check the live screenshot for consent banners or modals before accepting it.","Place the badge or link back before starting; verification depends on it.","Finish the flow in one session — leaving puts the URL back in the queue."]', rw_seo_title='Twelve Tools: Free Badge Listing, DR 81', rw_seo_description='How to submit to Twelve Tools: free dofollow listing for a badge, short review, Pro upgrade. Steps and gotchas from the 2026-11-16 snapshot.' WHERE slug='twelve-tools';
UPDATE submission_sites SET rw_source_lead='A curated tools directory whose $19 tier arrives preselected, and whose free lane is one followed link for a footer badge.', rw_what_you_get='A dofollow listing that goes live once their checker finds your badge, with a free lane priced by a footer badge or a $19 instant tier.', rw_you_need='["An account via Google, GitHub or email and password behind a Cloudflare check","A logo file, required by the form","Their badge in your footer on the free lane","One category from about twenty"]', rw_eligibility='You need an account, a logo, a category and — on the free lane — a footer badge. A maker unwilling to host the badge stays Not Published.', rw_submit_steps='["1 Sign in. /submit redirects to /sign-in?from=submit; Google and GitHub sit under the email form and a Cloudflare check clears itself.","2 Fill four fields and pick a lane: tool name, website URL, one category and a logo, with an optional app image and toggles for a promo code and marketplace listing. Plan cards sit beside the form, not after it.","3 Review the AI-written listing. Continue creates the tool and lands on a page with the description prefilled from a scrape, a 1,000-character budget on free and a badge panel marked Pending.","4 Save, then verify the badge. Save and continue stores the listing and returns to a profile page where it reads Not Published; Verify badge now is what publishes it."]', rw_submit_requirements='["An account via Google, GitHub or email and password","A tool name and website URL","One category","A logo image up to 5MB","Their badge in your site''s footer on the free lane","An optional markdown description and app image"]', rw_rejection_reasons='["A maker who will not host a badge on the free lane — the listing stays Not Published without one"]', rw_gotchas='["The $19 Premium card arrives preselected with a Continue to Payment ($19) button; selecting the free card first changes it to Continue to Review (Free).","Their AI writes the description from a scrape before you see the review page, so what it wrote publishes unless you replace it.","The listing is created then held as Not Published until their checker finds the badge, with a Publish instantly for $19 link under the verify button."]', rw_faq='[{"question":"How long does Findly.tools approval take?","answer":"Instant once the badge is verified; the listing otherwise stays Not Published."},{"question":"How much does Findly.tools cost?","answer":"The free lane needs a footer badge. Premium is $19 once for four permanent dofollow links, an editable profile, a longer description, no badge and instant approval; an SEO package is extra."},{"question":"Does a Findly.tools listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 80."},{"question":"Do I need to link back?","answer":"Yes, on the free lane a badge in your footer is required."},{"question":"What gets a listing rejected?","answer":"Not hosting the badge on the free lane leaves the listing unpublished."}]', rw_summary='Findly.tools is a curated tools directory with a free badge-funded lane and a $19 instant tier. Listings are dofollow with a backlink required on free; domain rating is 80.', rw_fact_points='["Free listings publish when the badge is verified; $19 is instant","Submission is free on the badge lane and carries a dofollow link","A footer badge is required on the free lane","Accepts AI tools, developer tools, productivity, marketing, directories, design, no-code and browser extensions"]', rw_submission_checks='["Select the free card explicitly — $19 Premium is preselected.","Replace the AI-written description if it misstates your product.","Install the footer badge before verifying, or the listing stays Not Published."]', rw_seo_title='Findly.tools: Free Badge Listing, DR 80', rw_seo_description='How to submit to Findly.tools: free dofollow listing with a footer badge or $19 instant tier. Pick the free card first — 2026-11-16 snapshot.' WHERE slug='findly-tools';
UPDATE submission_sites SET rw_source_lead='A 9,000-strong gallery of one-page websites, free to submit and followed on the way out, accepting exactly one kind of site.', rw_what_you_get='A dofollow listing among thousands of single-page sites, judged on visual design rather than product features.', rw_you_need='["A site that is genuinely one page — the whole editorial premise","A design worth showing, since this is a curated gallery not a listing service"]', rw_eligibility='You need a genuinely single-page site with a design worth featuring. Multi-page sites and apps with separate sub-pages are rejected — the gallery''s name is the rule — and a product with nothing visual to show does not fit an entry built from a screenshot.', rw_submit_steps='["1 Check the premise first. They carry over nine thousand entries, every one a single page; this is eligibility, not preference.","2 Open the free submit form. Submit Free is the lane, with paid options alongside it on the same page.","3 Give two URLs plus a first name, email, the site URL and a separate demo URL, and a confirmation checkbox.","4 Wait on curation. It is an editorial gallery with no published review time, so the entry appearing is the only signal."]', rw_submit_requirements='["A one-page website","A first name","An email address","A site URL — no copy fields on the form","A separate demo URL"]', rw_rejection_reasons='["A multi-page site or an app with a marketing site and sub-pages, and a product with nothing visual to show"]', rw_gotchas='["The eligibility rule is the name: a site with an about and pricing page is not one page, and submitting one wastes the slot rather than earning leniency.","It is a design gallery, so judgement is on how the page looks, not what the product does; a plain but useful site is a weak entry.","No review time is published anywhere, so there is nothing to check or chase."]', rw_faq='[{"question":"How long does One Page Love approval take?","answer":"No review time is published; curation is editorial."},{"question":"Is submitting to One Page Love free?","answer":"Yes, there is a free lane; templates and promotion are sold separately."},{"question":"Does a listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 79."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a site rejected?","answer":"A multi-page site, or a product with nothing visual to show."}]', rw_summary='One Page Love is a curated gallery of over 9,000 single-page websites with a free dofollow submission. Only genuinely one-page, visually strong sites are accepted; no backlink is required and domain rating is 79.', rw_fact_points='["Editorial curation with no published timeline","Submission is free and carries a dofollow link","No badge or return link is expected","Accepts design work, web apps and marketing sites"]', rw_submission_checks='["Confirm your site is truly one page.","Expect the judgement to be about visual design.","No status to check — the listing appearing is the signal."]', rw_seo_title='One Page Love: Free Design Listing, DR 79', rw_seo_description='How to submit to One Page Love: free dofollow listing in a curated one-page site gallery, no backlink. Eligibility and steps from the 2026-11-16 snapshot.' WHERE slug='one-page-love';
UPDATE submission_sites SET rw_source_lead='A Shopify-built AI directory whose free lane wants a link back and up to 90 days, behind the longest submission form in this directory.', rw_what_you_get='A dofollow listing with two categories and three tags on the free lane, in exchange for a badge link and a long wait.', rw_you_need='["A link back to the directory on your site, with its URL in the form, for the free lane","An AI, automation or SaaS angle — non-AI tools may be refused","HTTPS, a square 500x500 logo with a background colour","Five feature bullets, a tagline of at most 12 words and a description of at most 50"]', rw_eligibility='You need a link back for the free lane, an AI or automation story, HTTPS and a set of structured copy and assets. Anything without an AI angle, and any site not on HTTPS, is rejected.', rw_submit_steps='["1 Read the comparison table first. The submit page opens with three tiers and a feature grid; Free says up to 90 days by the table but 60 by the form''s own card, with two categories and three tags.","2 Put their logo on your site. A banner makes a link back mandatory for free listings and points at brand guidelines; the form asks for the URL of the page carrying it.","3 Fill the long form: personal details, tool details, a structured overview of what it is, how it works, use cases, API, compatibility and community, five feature bullets, platform checkboxes, pricing model, billing options and lowest price, plus optional social handles and integration checklists.","4 Agree to the terms and pick a tier — a required checkbox and the listing type, with Free With Backlink above Priority at $99 and Premium at $199."]', rw_submit_requirements='["Your name, company and email","The URL of the page carrying their link, on the free lane","A tool name and URL","A 500x500 JPG logo with a background colour","A tagline up to 12 words and a description up to 50 words","A long structured overview","Five feature bullets up to 300 characters each","Platform compatibility, pricing model, billing options and lowest price","Optional social handles and integration checklists"]', rw_rejection_reasons='["Anything with no AI or automation story, which the terms name, and any site not served over HTTPS"]', rw_gotchas='["The two published waits disagree: the comparison table says up to 90 days and the form''s listing card says 60 — plan for the longer.","The last step is a terms checkbox you must tick yourself, so an agent cannot finish the form.","Free listings are capped at two categories and three tags versus seven and ten on Premium, so discovery is deliberately narrower on the badge lane."]', rw_faq='[{"question":"How long does ToolPilot approval take?","answer":"Two to three months; the site''s own figures say up to 60 or 90 days."},{"question":"How much does ToolPilot cost?","answer":"There is a free lane with a backlink. Priority is $99 once for seven-day listing; Premium is $199 the first month then $39 monthly with editor polish and a homepage feature."},{"question":"Does a ToolPilot listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 78."},{"question":"Do I need to link back?","answer":"Yes, the free lane requires a link back to the directory."},{"question":"What gets a listing rejected?","answer":"Anything without an AI or automation story, and any site not on HTTPS."}]', rw_summary='ToolPilot is an AI directory with a free badge-funded lane that can take up to 90 days, plus paid instant tiers. The listing is dofollow and needs a backlink; domain rating is 78.', rw_fact_points='["Free lane takes two to three months; paid is within seven days","Submission is free and carries a dofollow link","A badge backlink is required on the free lane","Accepts AI tools, chatbots, automation, SaaS, developer and marketing tools"]', rw_submission_checks='["Expect a long free-lane wait; upgrade if timing matters.","Install their logo link before submitting the free tier.","Have HTTPS and a 500x500 logo ready.","Be prepared for an unusually long, structured form."]', rw_seo_title='ToolPilot: Free Badge Listing, DR 78', rw_seo_description='How to submit to ToolPilot: free dofollow listing with a badge and up to 90-day wait, or paid instant tiers. Steps from the 2026-11-16 snapshot.' WHERE slug='toolpilot';
UPDATE submission_sites SET rw_source_lead='Free if you file a GitHub repo, $69 if your server is hosted: the same product is free or paid depending on which tab you fill in.', rw_what_you_get='A dofollow listing that links to your GitHub repo on the free queue, or to your own site with an Official badge on the paid lane.', rw_you_need='["A public GitHub repository for the server or skill on the free tier","An email address they can reach"]', rw_eligibility='You need a public repository and an email for the free tier. A hosted server with nothing public to point at has no free option — the remote lane is $69 only.', rw_submit_steps='["1 Pick what you are filing. Two tabs choose MCP Server or Agent Skill, and two more choose GitHub repo or Remote MCP — that second choice decides the price.","2 On the repo lane, give a URL and an email. That is the whole form: no account, product page or assets.","3 On the remote lane, fill the long form: server name, endpoint URL, a short description up to 200 characters, a full description, a dynamic client registration checkbox, up to five categories, provider, website, use cases and an FAQ.","4 Change the tier before submitting. The paid card is preselected; choosing Free Queue changes the button from Get listed now to Submit to free queue.","5 Read the success panel below the button, which states the current free wait rather than issuing a reference; they email when the listing goes live."]', rw_submit_requirements='["A public GitHub repository URL on the free tier","A contact email","For the remote lane: server name, endpoint URL, short and full descriptions and up to five categories"]', rw_rejection_reasons='["A hosted server with nothing public to point at, since the remote lane is $69 with no free option"]', rw_gotchas='["The free queue exists only on the GitHub repo lane; switch to Remote MCP because your server is hosted and the $0 card disappears, leaving one $69 option.","The free listing links to the repository you file, not your product — a Try Now link to your own domain is a paid feature, so the dofollow lands on GitHub.","The paid card is preselected with a generic Get listed now button; the label changes to Submit to free queue only after you choose free.","Free is four to six weeks against 24 hours paid, and that gap is what is being sold."]', rw_faq='[{"question":"How long does MCP Market approval take?","answer":"One to two months on the free queue; paid listings go live within 24 hours."},{"question":"How much does MCP Market cost?","answer":"On the GitHub repo lane, $29 lists within 24 hours with an Official badge and a Try Now link, versus $0 and 4-6 weeks on the free queue. The Remote MCP lane has no free option — a single $69 card."},{"question":"Does an MCP Market listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 56."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"A hosted server with nothing public to point at — the remote lane is paid only."}]', rw_summary='MCP Market is an MCP and agent-skill directory where a GitHub repo lists free on a queue while a hosted server costs $69. The dofollow link needs no backlink; domain rating is 56.', rw_fact_points='["Free queue takes four to six weeks; paid is 24 hours","Submission can be free and carries a dofollow link","No badge or return link is expected","Accepts MCP servers, agent skills and dev tools"]', rw_submission_checks='["Use the GitHub repo tab for the free lane; Remote MCP is paid only.","Select the free card explicitly — the paid one is preselected.","Know that a free listing''s dofollow points to GitHub, not your domain."]', rw_seo_title='MCP Market: Free Repo Listing, DR 56', rw_seo_description='How to submit to MCP Market: free dofollow GitHub listing on a queue or $69 hosted, no backlink. Tier and tab traps from the 2026-11-16 snapshot.' WHERE slug='mcpmarket';
UPDATE submission_sites SET rw_source_lead='Eight launch slots a day, a free lane priced at a badge, and a streak that only pays out if you keep coming back.', rw_what_you_get='A dofollow listing on a chosen launch day, with streak rewards for repeated launches and a badge-funded free lane.', rw_you_need='["A live URL their scraper can read","An account via Google or an emailed magic link","A category from their list of fourteen","Their badge on your site, unless you pay to skip it"]', rw_eligibility='You need a live URL, an account, a category and — on the free lane — a badge. Spam, deceptive listings, vote or rank manipulation, tools you have no right to list and malware or illegal links are rejected.', rw_submit_steps='["1 Sign in and set up the profile with Google or a magic link, then a display name, handle and one checkbox. The name prefills from Google and is printed under the launch, so correct it.","2 Paste your URL and let it scrape. The first field fills logo, product name and pitch on blur — and files them in the wrong boxes, so check the preview card.","3 Fill the listing: a category, a tagline up to 80 characters, a pitch up to 2,000, up to eight screenshots, optional X handles and an I built this checkbox.","4 Choose how to list. Free picks any upcoming day with an open one of eight spots and goes live that morning; $29 takes tomorrow with no badge, $49 pins a sponsor slot, $59 is both.","5 Add the badge and verify. The free lane ends on a snippet and a Verify & schedule button; their checker must find the badge before the day is booked."]', rw_submit_requirements='["A live product URL","An account via Google or an emailed magic link","A product name and one category","A tagline up to 80 characters","A pitch up to 2,000 characters","A square PNG or JPG logo under 2MB","Up to eight screenshots","Their badge on your site for the free lane"]', rw_rejection_reasons='["Spam, misleading or deceptive listings, and anything manipulating votes, ranks or streaks; tools you have no right to list or misrepresenting authorship; malware and illegal or infringing links"]', rw_gotchas='["The scraper files values in the wrong boxes — a page title landed in Product name and the product name in Tagline — with no flag; the preview card is the only place to see it.","Their terms state the reversal: a free listing''s link is nofollow until the checker finds the badge, and removing it reverts the link. Dofollow lasts exactly as long as the badge.","The Your X field prefills with your Launch Streak handle rather than your X account, so a listing can credit a stranger''s profile; clear it unless it is yours.","The badge snippet links to /marketing/<slug>, which 404s until launch day; the live page in the meantime is /streak-preview/<slug>, so the badge points nowhere until the morning it goes live."]', rw_faq='[{"question":"How long does Launch Streak approval take?","answer":"Listings go live same day on the chosen launch morning."},{"question":"How much does Launch Streak cost?","answer":"There is a free badge lane. $29 takes tomorrow''s slate with no badge, $49 pins a sponsor slot immediately, and $59 is both."},{"question":"Does a Launch Streak listing provide a dofollow link?","answer":"Yes, but only while the free-lane badge is live; without it the outbound link is nofollow."},{"question":"Do I need to link back?","answer":"Yes on the free lane — the badge governs whether the link is followed."},{"question":"What gets a listing rejected?","answer":"Spam, deceptive listings, vote or rank manipulation, tools you cannot list, and malware or illegal links."}]', rw_summary='Launch Streak is an eight-slot-a-day launch board with a badge-funded free lane and paid instant options. Outbound links are dofollow only while the badge is live; domain rating is not published.', rw_fact_points='["Free launches go live on a chosen morning with a badge","Free lane carries a dofollow link while the badge is live","A badge backlink is required on the free lane","Accepts AI tools, dev tools, SaaS, design, productivity, mobile, no-code and marketing tools"]', rw_submission_checks='["Correct the scraped name and tagline in the preview card.","Keep the badge live — removing it turns the link nofollow.","Clear the prefilled X handle unless it is yours.","Expect the badge link to 404 until launch day."]', rw_seo_title='Launch Streak: Free Badge Launch', rw_seo_description='How to launch on Launch Streak: free badge-funded same-day launch with a dofollow link while the badge is live. Steps and traps from the 2026-11-16 snapshot.' WHERE slug='launch-streak';
UPDATE submission_sites SET rw_source_lead='Open source only, with the whole index framed as a replacement for something paid.', rw_what_you_get='A dofollow listing as an open-source alternative to a named proprietary tool, discoverable by people looking to switch.', rw_you_need='["A genuinely open-source project — the whole premise","A proprietary product that yours is an alternative to","A public repository"]', rw_eligibility='You need a genuinely open-source project and a proprietary tool it replaces. Closed-source products are rejected however good they are, because the index exists to replace them.', rw_submit_steps='["1 Open /submit, linked from the header as Submit project.","2 Name what you replace. The index is organised by the proprietary tool each project is an alternative to, so that framing matters more than the category."]', rw_submit_requirements='["A public repository — the project must be open source"]', rw_rejection_reasons='["Any closed-source product, however good, because the index exists to replace them"]', rw_gotchas='["Closed-source products are not eligible at all — the bar is the licence, not the pitch.","Listings are organised around the paid product you replace, so a project with no obvious proprietary counterpart is a harder fit than its category suggests.","They publish no review window anywhere."]', rw_faq='[{"question":"How long does OpenSourceAlternative.to approval take?","answer":"No review window is published."},{"question":"Is submitting to OpenSourceAlternative.to free?","answer":"Yes, submission is free."},{"question":"Does a listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 50."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a project rejected?","answer":"Any closed-source product — the index only lists open-source alternatives."}]', rw_summary='OpenSourceAlternative.to is a free directory of open-source alternatives to proprietary tools, with a dofollow link and no backlink requirement. Only genuine open-source projects are listed; domain rating is 50.', rw_fact_points='["Open-source projects only, with no published review window","Submission is free and carries a dofollow link","No badge or return link is expected","Accepts developer tools and indie products"]', rw_submission_checks='["Confirm your project is genuinely open source.","Frame it clearly as an alternative to a named proprietary tool.","Expect no published timeline for review."]', rw_seo_title='OpenSourceAlternative.to: Free OSS Listing, DR 50', rw_seo_description='How to submit to OpenSourceAlternative.to: free dofollow open-source listing, no backlink. Name the proprietary tool you replace — 2026-11-16 snapshot.' WHERE slug='opensourcealternative';
UPDATE submission_sites SET rw_source_lead='119 full-stack starter kits, free to submit in five fields, with room for your affiliate link.', rw_what_you_get='A dofollow listing among a large collection of SaaS starter kits, with your affiliate link accepted if you have one.', rw_you_need='["A full-stack boilerplate or starter kit able to build a complete SaaS application","A profile picture URL","Your full name and email"]', rw_eligibility='You need a full-stack starter kit and basic submitter details. Themes, plugins and UI kits are rejected explicitly — the collection is only complete application boilerplates.', rw_submit_steps='["1 Check the scope. The submit page says plainly: full-stack boilerplates and starter kits only, free or premium; no themes, plugins or UI kits.","2 Fill five fields: your full name, email, a profile picture URL, the boilerplate URL and optionally an affiliate link. All but the affiliate field are required.","3 Submit the request. There is no account and no payment; the button says Submit your request, which is what it is."]', rw_submit_requirements='["A full-stack SaaS boilerplate","Your full name and email","A profile picture URL","The boilerplate URL","An affiliate programme link"]', rw_rejection_reasons='["Themes, plugins and UI kits, which are named and rejected explicitly"]', rw_gotchas='["Scope is enforced on the form itself — full-stack kits only, with themes, plugins and UI kits called out as unwelcome.","They ask for your affiliate link and run affiliate URLs on their own outbound links, so assume the listing is monetised.","No review time is published, no account exists and the button says Submit your request, so there is nothing to check afterward."]', rw_faq='[{"question":"How long does approval take?","answer":"No review time is published."},{"question":"Is submitting free?","answer":"Yes, listing a boilerplate is free."},{"question":"Does a listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 31."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Themes, plugins and UI kits — only full-stack boilerplates are accepted."}]', rw_summary='Best SaaS Boilerplates is a collection of 119 full-stack starter kits with a free five-field submission and a dofollow link. No backlink is required; domain rating is 31.', rw_fact_points='["Free request with no published review time","Submission carries a dofollow link","No badge or return link is expected","Accepts full-stack boilerplates and developer tools"]', rw_submission_checks='["Confirm your product is a full-stack kit, not a theme, plugin or UI kit.","Have a profile picture URL ready.","Expect affiliate monetisation on outbound links."]', rw_seo_title='Best SaaS Boilerplates: Free Listing, DR 31', rw_seo_description='How to submit to Best SaaS Boilerplates: free dofollow listing for full-stack starter kits, no backlink. Scope and steps from the 2026-11-16 snapshot.' WHERE slug='best-saas-boilerplates';
UPDATE submission_sites SET rw_source_lead='A daily launch board with about 4,900 products already on it, free to join, with no way in without an email-and-password account.', rw_what_you_get='A dofollow listing grouped by post date, with a shot at being picked as Hack of the Day.', rw_you_need='["A live product URL","An account created with email and password","A logo and a one-line tagline"]', rw_eligibility='You need a live URL, an email-and-password account and basic product details. No submission policy is published, so nothing structural is stated as a rejection reason.', rw_submit_steps='["1 Create an account with a name, email, password and confirmation at /register; there is no Google or GitHub option, so this step is manual.","2 Open Submit a Hack. /add-product redirects to login until signed in; the header CTA and three footer links point to the same form.","3 Fill the listing — live entries show a name, one-line tagline, long description, up to three category tags, a logo and the outbound website link, which is what the form collects.","4 Watch for the daily slot. Products are grouped by the date posted and one is picked as Hack of the Day; recent days carried between one and ten submissions."]', rw_submit_requirements='["An account via email and password, with no social login","A product name and one-line tagline","A long description of several paragraphs","A logo image","A live website URL","Up to three category tags"]', rw_rejection_reasons='["Nothing published — they state no submission policy at all"]', rw_gotchas='["No Google or GitHub sign-in: an email-and-password account is the only route, so an agent cannot complete it end to end.","They publish no policy, guidelines or review time; the only turnaround evidence is that listings carry their post date, including today''s.","Listing URLs are raw UUIDs with no keyword in them; the dofollow link is the entire value."]', rw_faq='[{"question":"How long does The Hack Stack approval take?","answer":"Listings go live the same day."},{"question":"Is submitting to The Hack Stack free?","answer":"Yes, submission is free."},{"question":"Does a listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 22."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"No policy is published, so nothing structural is stated."}]', rw_summary='The Hack Stack is a free daily launch board of about 4,900 products with a dofollow link and no backlink requirement. An email-and-password account is mandatory; domain rating is 22.', rw_fact_points='["Listings publish the same day","Submission is free and carries a dofollow link","No badge or return link is expected","Accepts indie products, SaaS, AI tools and web apps"]', rw_submission_checks='["Create an email-and-password account — there is no social login.","Write a multi-paragraph description; live listings are detailed.","Expect a UUID listing URL with no keyword value."]', rw_seo_title='The Hack Stack: Free Daily Launch, DR 22', rw_seo_description='How to submit to The Hack Stack: free same-day dofollow launch, no backlink, email account required. Steps and caveats from the 2026-11-16 snapshot.' WHERE slug='the-hack-stack';
UPDATE submission_sites SET rw_source_lead='The largest AI tool index, with heavy search traffic and paid submission.', rw_what_you_get='A dofollow listing generated from your URL in a heavily searched AI index, with basic analytics and optional newsletter and traffic bonuses.', rw_you_need='["An AI tool, GPT or non-human AI persona","Payment from $49, unless editors pick you for a free listing","A live URL they can scrape"]', rw_eligibility='You need a genuine AI tool, GPT or AI persona, a scrapeable URL and payment. Anything without a real AI component is rejected, and the free listing is an editorial pick rather than a tier.', rw_submit_steps='["1 Go to the launch page. /submit redirects to /launch/; no account is needed to fill the form, and edit access comes later by email verification.","2 Give them the URL — one field. They scrape it to build the whole tool page, and every submission is reviewed by hand.","3 Optionally schedule. A checkbox reveals a datetime picker with a timezone selector, defaulted to your local zone.","4 Pick a package and pay. Website Only is $49 for a permanent listing, estimated clicks, basic analytics and a PPC bonus; Maximum Exposure is $347 with about ten times the traffic and a newsletter spot; custom plans are quote-only."]', rw_submit_requirements='["A genuine AI tool, GPT or AI persona","Payment from $49","A live URL they can scrape","An email you can verify for edit access","An optional launch date and timezone"]', rw_rejection_reasons='["Anything without a genuine AI component, and products that are not tools, GPTs or AI personas"]', rw_gotchas='["The free listing is not a selectable tier — editors pick one tool from a thread at their discretion; every route on the launch page is paid.","No account is needed to fill the form, so it looks free until the package selector; edit access is granted by email verification afterward.","They state exactly what they accept, so a product with only a token AI feature is the wrong shape.","The whole page is generated from your URL by their scraper, so a thin homepage becomes a thin listing you cannot fix until verification.","Everything sits behind a Cloudflare challenge, so an automated fetch sees a challenge page rather than the form."]', rw_faq='[{"question":"How long does approval take?","answer":"One to two weeks."},{"question":"How much does it cost?","answer":"$49 for Website Only or $347 for Maximum Exposure; a free listing is an editorial pick, not a tier."},{"question":"Does a listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 77."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Anything without a genuine AI component, or products outside tools, GPTs and AI personas."}]', rw_summary='There''s An AI For That is the largest AI tool index with paid listings from $49 and a dofollow link, no backlink required. A free listing is an editorial pick; domain rating is 77.', rw_fact_points='["Paid from $49 with a 1-2 week review","Listings carry a dofollow link and need no backlink","Free listing is editor-selected, not a tier","Accepts genuine AI tools, GPTs and AI personas"]', rw_submission_checks='["Expect to pay — there is no free tier to select.","Have a genuine AI angle, not a token feature.","Give a rich homepage; the scraper builds the whole listing from it.","Verify your email afterward to gain edit access."]', rw_seo_title='There''s An AI For That: $49 AI Listing, DR 77', rw_seo_description='How to submit to There''s An AI For That: paid $49+ dofollow AI listing, no backlink, editorial free pick. Steps and rules from the 2026-11-16 snapshot.' WHERE slug='theres-an-ai-for-that';
UPDATE submission_sites SET rw_source_lead='A 2,200-site directory that dropped its free lane: $29 once, published in minutes, with no badge asked for.', rw_what_you_get='A dofollow listing published in minutes from a URL and a short review, with no badge or backlink required.', rw_you_need='["A live URL — the only input the first step asks for","$29, since there is no longer a free lane","A name within 28 characters and a headline within 140"]', rw_eligibility='You need a live URL, the $29 fee and a short name and headline. Adult content, gambling, drug-related sites and anything judged low quality or spam are rejected.', rw_submit_steps='["1 Start the paid submission. /submit is now a single $29 card; Start Submission goes to /submit-your-website with plan=paid, and there is no free card beside it.","2 Give a URL and let their AI read it. Step one asks only for the URL, then spends about half a minute writing a description and taking a screenshot.","3 Fix what their AI wrote. The review step is prefilled — the name field held the homepage headline on one walk. Name is capped at 28 characters, headline at 140, the long description is optional, and one category from about ninety plus an email is needed.","4 Pay $29 once. The card promises publishing in minutes with no review wait and no badge."]', rw_submit_requirements='["A live URL","A website name up to 28 characters","A headline up to 140 characters","One category from about ninety","A contact email","A one-time $29 fee","An optional long description and your own screenshot"]', rw_rejection_reasons='["Adult content, gambling and drug-related sites, and anything judged low quality or spam"]', rw_gotchas='["The free lane no longer exists: /submit shows one $29 card and the submission page opens with plan=paid, so a free-only budget has nothing to do here.","Their AI fills the listing from a scrape before you see the form and can put the homepage headline in the name field — check every prefilled field against your own copy.","The screenshot is taken live, so whatever your consent banner is doing appears in the listing image; Upload my own image sits next to Retake."]', rw_faq='[{"question":"How long does Wired Business approval take?","answer":"Listings publish in minutes with no review wait."},{"question":"How much does it cost?","answer":"A one-time $29 — the only card now; the former free badge lane is gone."},{"question":"Does a listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 77."},{"question":"Do I need to link back?","answer":"No backlink or badge is required."},{"question":"What gets a submission rejected?","answer":"Adult content, gambling, drug-related sites and anything judged low quality or spam."}]', rw_summary='Wired Business is a paid-only directory where a $29 one-time fee publishes a dofollow listing in minutes. No badge or backlink is required; domain rating is 77.', rw_fact_points='["Paid-only at $29, published in minutes","Submission carries a dofollow link with no badge required","No return link is expected","Accepts SaaS, AI tools, developer tools, directories, productivity, marketing, browser extensions and marketplaces"]', rw_submission_checks='["Expect to pay $29 — there is no free lane.","Correct every AI-prefilled field, especially the name.","Replace the live screenshot if a banner or modal is captured."]', rw_seo_title='Wired Business: $29 Listing, DR 77', rw_seo_description='How to submit to Wired Business: $29 one-time dofollow listing published in minutes, no badge or backlink. Steps from the 2026-11-16 snapshot.' WHERE slug='wired-business';
UPDATE submission_sites SET rw_source_lead='Early-stage startups shown to an audience that expects rough edges.', rw_what_you_get='A dofollow listing plus newsletter exposure to an early-adopter audience, with paid tiers setting how soon you appear.', rw_you_need='["An account","Payment from $39","A startup that is genuinely new or upcoming"]', rw_eligibility='You need an account, payment and a genuinely new or pre-launch startup. Established products past their launch window are rejected, since the whole premise is early access.', rw_submit_steps='["1 Sign in. /submit redirects to /sign_in with email and password, a social button or a magic link.","2 Give them the URL. The first step asks only for the website, then spends about 30 seconds drafting the listing from your homepage, app stores, logo and topics.","3 Review their draft. A screen shows the name, pitch, description, topics and logo they wrote; everything is editable and usually close but not your own words.","4 Hit the paywall. Looks good leads to the plan step where the free route used to be: Lite is $39 for a random day within about two weeks, Standard $99 gets featured before Wednesday, Premium $299 features you today. All include the dofollow link and newsletter."]', rw_submit_requirements='["An account","Payment from $39","A live product URL","A new or upcoming startup"]', rw_rejection_reasons='["Established products past their launch window — the whole premise is early access"]', rw_gotchas='["There is no free submission any more: the FAQ still mentions a regular review, but the wizard ends at a paywall with $39 as the cheapest option.","You do not see the price until the final step, after their AI has drafted and you have approved the entire listing.","They write the listing from your homepage — name, pitch, description, topics and logo — so read it before approving.","Payment happens before selection, though a full refund is promised if your startup is not selected.","The audience wants unfinished things, so a mature product is a poor fit however good it is."]', rw_faq='[{"question":"How long does BetaList approval take?","answer":"One to two weeks on the cheapest tier; higher tiers feature sooner or the same day."},{"question":"How much does it cost?","answer":"$39 Lite, $99 Standard, $299 Premium — there is no free route."},{"question":"Does a BetaList listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 76."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a startup rejected?","answer":"Established products past their launch window; the premise is early access."}]', rw_summary='BetaList is an early-stage startup launch platform with paid tiers from $39 and a dofollow listing plus newsletter exposure. No backlink is required; domain rating is 76.', rw_fact_points='["Paid-only from $39, featured within two weeks or sooner","Listings carry a dofollow link and need no backlink","AI drafts the listing from your homepage","Accepts new or pre-launch startups and web/SaaS products"]', rw_submission_checks='["Be genuinely early-stage — mature products do not fit.","Review every AI-drafted field before approving.","Expect the price only at the final step.","Know that payment precedes selection, with a refund if rejected."]', rw_seo_title='BetaList: $39 Startup Launch, DR 76', rw_seo_description='How to launch on BetaList: paid $39+ dofollow early-stage startup listing, no backlink, AI-drafted copy. Steps from the 2026-11-16 snapshot.' WHERE slug='betalist';
UPDATE submission_sites SET rw_source_lead='A 3,000-tool AI index that trades a dofollow listing for a plain text link back, and asks you to name the page carrying it.', rw_what_you_get='A dofollow listing in a broad AI index, in exchange for a plain text link to the directory on your own site.', rw_you_need='["An account via Google, GitHub or email and password","A link to the directory somewhere on your site, plus the URL of that page","An AI product aimed at end users","A description of 10 to 300 characters"]', rw_eligibility='You need an account, a consumer-facing AI product, a text link back on your site and its page URL. Cryptocurrency projects, products not aimed at end users and sites judged uninformative are rejected.', rw_submit_steps='["1 Put their link on your site. Step one is adding an anchor titled MossAI Tools — a plain text link, not an image badge — and separately giving the URL of the page carrying it.","2 Sign in. The submit page shows the rules to everyone but replaces the form with a Login Required panel; Google, GitHub and email/password are offered.","3 Fill the form: website name up to 50 characters, product name up to 30, a description of 10 to 300, a website URL, one of seventeen categories, at least one tag that loads only after a category is chosen, an email and the page URL with their link.","4 Wait for manual review. Every submission is reviewed by hand and their own precautions say submitting does not guarantee publication; no review time is published."]', rw_submit_requirements='["An account via Google, GitHub or email and password","A link to the directory on your own site","The URL of the page carrying that link","A website name and product name","A description of 10 to 300 characters","A live URL","One category from seventeen and at least one tag","A contact email"]', rw_rejection_reasons='["Anything cryptocurrency-related, named twice in their criteria; products not aimed at end users; and sites judged uninformative"]', rw_gotchas='["The link back is a field, not an honour system: the last input asks for the URL of the page carrying their link, so you must name that page.","Cryptocurrency products are refused outright, appearing in both the disapproval criteria and the tips for a faster review.","The tags field stays disabled until a category is picked, so filling top to bottom in one pass leaves a required tag empty.","No review time is published, and their precautions add that submitting does not guarantee publication."]', rw_faq='[{"question":"How long does MossAI approval take?","answer":"No review time is published; every submission is reviewed by hand."},{"question":"Is submitting to MossAI free?","answer":"Yes, the listing is free."},{"question":"Does a MossAI listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 76."},{"question":"Do I need to link back?","answer":"Yes, a plain text link to the directory on your site is required."},{"question":"What gets a submission rejected?","answer":"Cryptocurrency projects, products not for end users, and sites judged uninformative."}]', rw_summary='MossAI is a 3,000-tool AI index where a free dofollow listing requires a plain text link back on your site. No badge is needed; domain rating is 76 and review is manual.', rw_fact_points='["Manual review with no published timeline","Submission is free and carries a dofollow link","A text link back is required","Accepts AI tools, chatbots, developer, design, productivity, marketing and education tools"]', rw_submission_checks='["Install their text link on your site before filling the form.","Pick a category first so the tags field unlocks.","Avoid any cryptocurrency framing — it is rejected twice over."]', rw_seo_title='MossAI: Free AI Listing, DR 76', rw_seo_description='How to submit to MossAI: free dofollow AI tool listing in exchange for a text link back. Eligibility and steps from the 2026-11-16 snapshot.' WHERE slug='mossai';
UPDATE submission_sites SET rw_source_lead='A small, well-run tools directory with daily and weekly leaderboards, where the free line is closed to new products.', rw_what_you_get='A dofollow listing on a curated tools directory with daily and weekly leaderboards, once an upvote threshold is met.', rw_you_need='["An account — asked for only after the scrape","A live product URL with a real meta description","A paid launch slot, since the free line is closed"]', rw_eligibility='You need a live URL with a good meta description for their scraper to draft from, an account and a paid launch slot. Products with nothing at the URL to scrape are rejected.', rw_submit_steps='["1 Give the URL first. /submit-a-tool asks only for a product name and address; no account is needed yet, and the button reads Preview when logged out.","2 Let their AI draft it and check every field. They scrape your page and pre-fill category, pricing, three tags, tagline and a rich description — confidently wrong in places.","3 Fix the General tab: a name up to 30 characters, a slug up to 50, the URL, one of five categories, Free/Freemium/Paid pricing, exactly three tags from a controlled list, an open-source toggle, an 80-character tagline and a rich description.","4 Add media: a square logo at least 128x128, one to three images with a consistent aspect ratio and an optional launch video URL.","5 Save — and stop there if not ready. Saving puts the product in a waiting line but does not launch it; a separate Schedule your launch step picks the day."]', rw_submit_requirements='["An account asked for after the scrape","A live product URL and a good meta description","A square logo at least 128x128","One to three images","Exactly three tags from their list","A name, slug and tagline within limits","A paid launch slot"]', rw_rejection_reasons='["Products with nothing at the URL to scrape"]', rw_gotchas='["The free waiting line is closed to new products: saving is still free, but scheduling offers only $29.99 to pick a date or $14.99 to be assigned one, so an unpaid product sits Not scheduled and never publishes.","The submit path is /submit-a-tool; a bare /submit returns 404, making submissions look closed.","Their AI fills the form and gets things wrong with confidence — a free product tagged Freemium, a funding tag with no relevance — so read every field.","Tags are exactly three from a controlled list; there is no Marketing or Launch tag, so a wrong pick costs a slot.","The logo and gallery share one file input: uploading a gallery image after the logo silently replaces it. Upload gallery first or recheck the logo."]', rw_faq='[{"question":"How long does Uneed approval take?","answer":"One to two weeks; a listing needs 10 upvotes to stay published and 20 for the dofollow link."},{"question":"How much does Uneed cost?","answer":"Joining the line is free but currently closed to new products. Paid slots are $14.99 to be assigned a date or $29.99 to pick one; fast-track and skip-the-line are also paid."},{"question":"Does a Uneed listing provide a dofollow link?","answer":"Yes, once the listing reaches 20 upvotes, on a domain rated 75."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Products with nothing at the URL for their scraper to read."}]', rw_summary='Uneed is a curated tools directory with daily and weekly leaderboards where listings are free to save but need a paid slot to launch. The dofollow link needs no backlink; domain rating is 75.', rw_fact_points='["Free line closed; paid slots launch a listing","Submission is free to save and links are dofollow after 20 upvotes","No badge or return link is expected","Accepts SaaS, AI tools, developer tools, web apps and startups"]', rw_submission_checks='["Expect to pay for a launch slot — the free line is closed.","Review every AI-drafted field; the scraper is often wrong.","Choose exactly three tags from the controlled list.","Upload gallery images before the logo to avoid replacing it."]', rw_seo_title='Uneed: Paid Slot Tool Listing, DR 75', rw_seo_description='How to list on Uneed: free to save but paid slot required to launch, dofollow after 20 upvotes, no backlink. Steps from the 2026-11-16 snapshot.' WHERE slug='uneed';
UPDATE submission_sites SET rw_source_lead='A five-country local business directory with 18 million listings, where the free tier is a real page and the paid one is $3.60 a month.', rw_what_you_get='A free local business page with a map, opening times and a dofollow link, in a directory split across five countries.', rw_you_need='["A presence in Australia, Canada, New Zealand, the UK or the US","An owner account created from the Owners Login route","A business description of 500 characters or less on the free tier","A trading location"]', rw_eligibility='You need a physical presence in one of five countries, an owner account and a trading location. Businesses outside those countries, and any listing with no address — including software products — have nowhere to fit.', rw_submit_steps='["1 Pick a country. The whole site is split five ways — Australia, Canada, New Zealand, the UK and the US — and the listing lives in one of them.","2 Open List Your Business. /listing.php is the plans page and entry point; the guessable /list-your-business returns 404.","3 Register an owner account at /login.php; reviewers have a separate route.","4 Fill the free listing: a corporate page, a location map, opening times, detailed information, a contact email, one image and a description up to 500 characters, in one category."]', rw_submit_requirements='["An owner account","A business name, address and one of the five countries","A description up to 500 characters on the free tier","One category","One main image"]', rw_rejection_reasons='["A business outside the five countries, and anything with no trading location — a software product with no address has nothing to put in the form"]', rw_gotchas='["The free listing allows exactly one category and a 500-character description, both visible only once you start writing.","A corporate logo is a paid feature: the free page shows one main image but not your logo, an odd split discovered after writing the listing.","The directory exists only for five countries, so a business elsewhere has nowhere to be listed."]', rw_faq='[{"question":"How long does A-Z Business Finder approval take?","answer":"Listings go live instantly."},{"question":"How much does it cost?","answer":"There is a free tier. Premium starts at $3.60 a month and adds a logo, more images and descriptions, keywords and up to five categories — it is a subscription."},{"question":"Does a listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 73."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"A business outside the five countries, or anything with no trading location."}]', rw_summary='A-Z Business Finder is a local business directory across five countries with a free listing page and a dofollow link, no backlink required. Paid Premium adds logo and more detail; domain rating is 73.', rw_fact_points='["Free listings publish instantly","Submission is free and carries a dofollow link","No badge or return link is expected","For local businesses and professional services in five countries"]', rw_submission_checks='["Confirm you have a trading address in one of the five countries.","Expect one category and a 500-character limit on free.","A logo needs the paid tier; the free page shows one main image."]', rw_seo_title='A-Z Business Finder: Free Local Listing, DR 73', rw_seo_description='How to list on A-Z Business Finder: free dofollow local business page in five countries, no backlink. Limits and tiers from the 2026-11-16 snapshot.' WHERE slug='a-z-business-finder';
UPDATE submission_sites SET rw_source_lead='A 550,000-product SaaS database where submitting is one URL, a Turnstile and a day''s wait.', rw_what_you_get='A listing in a huge SaaS database, written by their crawler from your site, with a claim step to correct it afterward.', rw_you_need='["A SaaS website URL"]', rw_eligibility='You need a SaaS website URL. Anything that is not SaaS has nowhere to fit in a one-field form on a SaaS database.', rw_submit_steps='["1 Paste the URL — one field, a newsletter tick box and a Cloudflare Turnstile that must clear first.","2 Submit Your SaaS. The page says it is submitted and moves straight to an analytics upsell with your email prefilled; Skip for now is the way past it.","3 Wait a day. They say listed within 24 hours, with the profile written by their crawler from your site.","4 Claim it. Get Verified and Update Profile on the listing is where you correct what the crawler wrote."]', rw_submit_requirements='["A website URL"]', rw_rejection_reasons='["Anything that is not SaaS — the one-field form has nowhere to put a book, an app-store listing or a service"]', rw_gotchas='["The form is a single URL field: the crawler writes the profile from your site, so what your homepage says is what the listing says until you claim it.","A Cloudflare Turnstile guards the form and Submit does nothing until it passes; signed out, it can show an interactive human check that a person must tick.","The success page is an upsell for their analytics product with your email prefilled; Skip for now gets past it."]', rw_faq='[{"question":"How long does SaaS Browser approval take?","answer":"Listings go live within 24 hours."},{"question":"Is submitting to SaaS Browser free?","answer":"Yes, submission is free."},{"question":"Does a SaaS Browser listing provide a dofollow link?","answer":"No. Links are nofollow on a domain rated 74."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Anything that is not a SaaS product."}]', rw_summary='SaaS Browser is a large SaaS database with a one-URL free submission and a same-day crawler-written listing. Links are nofollow with no backlink requirement; domain rating is 74.', rw_fact_points='["Listings go live within 24 hours","Submission is free and links are nofollow","No badge or return link is expected","Accepts SaaS products only"]', rw_submission_checks='["Give a rich homepage — the crawler writes the profile from it.","Pass the Cloudflare check and skip the analytics upsell.","Claim the listing afterward to correct crawler errors."]', rw_seo_title='SaaS Browser: Free SaaS Listing, DR 74', rw_seo_description='How to submit to SaaS Browser: free one-URL SaaS listing in 24 hours, nofollow link, no backlink. Claim step and caveats from the 2026-11-16 snapshot.' WHERE slug='saasbrowser';
UPDATE submission_sites SET rw_source_lead='The best-known review platform on the web, whose free business account is four screens long and needs a phone number before it will finish.', rw_what_you_get='A free business profile on a review platform with a strong brand-name search result, though the outbound link is nofollow.', rw_you_need='["A phone number, required on the third screen with no way past it","A first and last name for the signer","A business website","A revenue bracket and a headcount bracket"]', rw_eligibility='You need to supply a phone number, a personal name, a business website and revenue and headcount brackets. Anyone unwilling to give a phone number cannot complete signup.', rw_submit_steps='["1 Business details: country, business name and website. The name field is a company lookup rather than a plain text box.","2 Additional details: job title, annual revenue and employee count, all required; revenue brackets start at $0 to 4.99 million.","3 Personal details: first name, last name, a phone country code and a phone number — all four required, and this is where the flow stops without a number.","4 Activate by email: the fourth screen takes an address and sends a link; an address on your own domain sets up faster, another triggers an ownership check.","5 Accept the terms on a final checkbox, which also agrees to performance suggestions and company updates; Complete setup stays disabled until ticked."]', rw_submit_requirements='["A business country, name and website","A job title","An annual revenue bracket","An employee count bracket","A first and last name","A phone number","An email on your own domain, or an extra ownership check"]', rw_rejection_reasons='["Anyone unwilling to provide a phone number, since the flow cannot be completed without one"]', rw_gotchas='["A phone number is mandatory on the third of four screens, with no skip or alternative, so a maker who will not share one cannot sign up.","The business name field is a company lookup, so a sole trader or young company gets No results found; the way through is a Type my business details manually row above the results.","The links are nofollow — outbound anchors on a review page carry rel=nofollow noopener, so this is worth doing for the brand-name search result, not the backlink.","The final checkbox bundles accepting terms and agreeing to marketing, with no way to take the account without it.","If the domain was ever claimed here, signup refuses it and offers a callback rather than saying an account exists; logging in is the way in, even to an empty profile."]', rw_faq='[{"question":"How long does Trustpilot approval take?","answer":"Business accounts activate instantly after email verification."},{"question":"How much does Trustpilot cost?","answer":"The account is free; paid plans exist for review invitations and widgets, and signup asks for no card."},{"question":"Does a Trustpilot listing provide a dofollow link?","answer":"No. Links are nofollow on a domain rated 94."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a signup rejected?","answer":"Anyone unwilling to provide a phone number, which the flow requires."}]', rw_summary='Trustpilot is the best-known review platform, with a free business account that requires a phone number across four signup screens. Listing links are nofollow with no backlink requirement; domain rating is 94.', rw_fact_points='["Accounts activate instantly after email verification","Submission is free and links are nofollow","No badge or return link is expected","Accepts any live website, B2B software, SaaS and business services"]', rw_submission_checks='["Have a phone number ready — there is no way around it.","Use an email on your own domain to avoid an ownership check.","Look for the manual business-details option if the company lookup finds nothing.","Expect a nofollow link; the value is the brand-name search result."]', rw_seo_title='Trustpilot: Free Business Profile, DR 94', rw_seo_description='How to create a free Trustpilot business profile: four signup screens, phone number required, nofollow link, no backlink. Steps from the 2026-11-16 snapshot.' WHERE slug='trustpilot';
UPDATE submission_sites SET rw_source_lead='A daily launch feed with a thirty-day queue unless you pay or install their badge.', rw_what_you_get='A dofollow listing in a daily launch feed, published after a 30-day queue or immediately with their badge or a Priority Pass.', rw_you_need='["An account via Google, GitHub or an emailed login code","A profile with a headline and bio, asked for right after sign-in","A tagline, description and category"]', rw_eligibility='You need an account, a profile and basic product copy. Nothing structural is rejected — the only barrier is the 30-day free queue unless you pay or add their badge.', rw_submit_steps='["1 Sign in with Google, GitHub or an emailed login code.","2 Fill the profile: where you heard about them, a headline and an about, before anything can be submitted.","3 Fetch the details with a name and URL; their scraper reads the site and prefills the rest.","4 Basic info: a tagline, description and categories on top of what the scrape found.","5 Media and social: a logo, product images, social links and optional co-makers.","6 Publish. Pressing Publish opens the Priority Pass dialog; the free route is the second choice, Launch after 30 days, which asks for a date and ends on Schedule. Continue without a pass only closes the dialog."]', rw_submit_requirements='["A product logo","A one-line tagline","A paragraph description"]', rw_rejection_reasons='["Nothing structural — the only constraint is a 30-day free queue for anyone in a hurry"]', rw_gotchas='["The free queue is thirty days; the two ways to shorten it are the Priority Pass offered at the last click, or their badge on your site, which lets a free launch go live at once.","Their scraper can sit on Retrieving product information for a long time before finishing.","The profile step comes before the product form, so the first thing asked for is a bio rather than the product."]', rw_faq='[{"question":"How long does Product Watch approval take?","answer":"Free launches go live after a 30-day queue, or immediately with the badge; no review time is published."},{"question":"How much does it cost?","answer":"Free to submit. A Priority Pass at publish skips the queue and adds featured placement and upvote boosts; the free badge also removes the wait."},{"question":"Does a listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 72."},{"question":"Do I need to link back?","answer":"No backlink is required, though a badge removes the free queue."},{"question":"What gets a submission rejected?","answer":"Nothing structural; the constraint is the 30-day free wait."}]', rw_summary='Product Watch is a daily launch feed with a dofollow listing and a 30-day free queue, shortened by their badge or a paid Priority Pass. No backlink is required; domain rating is 72.', rw_fact_points='["Free launches wait 30 days unless badged or boosted","Submission is free and carries a dofollow link","A badge removes the queue but is not required","Accepts indie products, SaaS, AI tools and developer tools"]', rw_submission_checks='["Expect a 30-day wait on free, or install the badge to skip it.","Choose Launch after 30 days in the final dialog — the pass is optional.","Fill the profile before the product form."]', rw_seo_title='Product Watch: Free Launch, DR 72', rw_seo_description='How to launch on Product Watch: free dofollow listing with a 30-day queue or instant with badge. Priority Pass and steps from the 2026-11-16 snapshot.' WHERE slug='productwatch';
UPDATE submission_sites SET rw_source_lead='A 30-million-listing global business directory that charges $3 once for a permanent listing, and says outright a free account cannot list anything.', rw_what_you_get='A permanent dofollow business listing in a huge directory, filed under a category and city, for a one-time $3.', rw_you_need='["$3 — a free account cannot create a listing","A business name, a real first and last name, and an email","A category and a location"]', rw_eligibility='You need to pay $3 and supply a business name, personal name, email, category and location. Anyone unwilling to pay is excluded — the reviewer account is explicitly barred from listing.', rw_submit_steps='["1 Choose the right account type. The signup offers a Reviewer Account and a business listing side by side, stating in capitals that a reviewer account cannot list a business.","2 Sign in with Google, or sign up with email: business name, first name, last name, email, password and confirmation.","3 Pay $3 via the Claim My Listing - $3 One Time button through Stripe. There is no free path to a listing.","4 Fill the profile with a category, location and business details — the fields the directory indexes on, with listings under /directory/<category>-in-<city>."]', rw_submit_requirements='["A one-time $3 via Stripe","An account via Google or email and password","A business name, first and last name and email","A category and a location","A website URL for the direct link"]', rw_rejection_reasons='["Anyone unwilling to pay $3 — the reviewer account is explicitly barred from listing, promoting or creating a business profile"]', rw_gotchas='["There is no free listing: the free Reviewer Account sits beside the flow and is stated in capitals not to create a business profile, easy to click past.","The $3 is per listing, not per account, so a company with several brands pays each time.","It is a business directory, not a launch platform: listings are filed under category and city, so a software product with no address must file somewhere it does not trade."]', rw_faq='[{"question":"How long does Bunity approval take?","answer":"Listings go live the same day."},{"question":"How much does it cost?","answer":"$3 one-time per listing through Stripe, with no recurring fee. The free account is a reviewer account that cannot list."},{"question":"Does a Bunity listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 70."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Anyone unwilling to pay $3; the free reviewer account cannot create a business profile."}]', rw_summary='Bunity is a large global business directory with a permanent $3 one-time dofollow listing and no backlink requirement. The free account is reviewer-only; domain rating is 70.', rw_fact_points='["Paid-only at $3 per listing, live same day","Listings carry a dofollow link and need no backlink","The free account cannot list","For B2B software, SaaS, professional and local businesses"]', rw_submission_checks='["Select the business listing, not the free Reviewer Account.","Expect to pay $3 for each listing you create.","Have a category and city — the directory indexes on both."]', rw_seo_title='Bunity: $3 Business Listing, DR 70', rw_seo_description='How to list on Bunity: $3 one-time dofollow business listing, no backlink. Free account is reviewer-only — 2026-11-16 snapshot.' WHERE slug='bunity';
UPDATE submission_sites SET rw_source_lead='A 20,000-tool AI directory with no free lane at all: the cheapest listing is $15.90, and the homepage link it buys is nofollow.', rw_what_you_get='A dofollow listing on the content page, with the copy written by their model from your site; homepage links stay nofollow on the cheapest tier.', rw_you_need='["Payment from $15.90 — there is no free route","A tool name, website URL and contact email","An AI angle, since the whole catalogue is AI tools"]', rw_eligibility='You need to pay, supply basic tool details and have an AI product. Anyone not paying is excluded, and a product with no AI story does not fit the catalogue.', rw_submit_steps='["1 Fill the three-field intake. /submit asks for a tool name, website URL and contact email, then Continue; nothing on this screen mentions money.","2 Choose a paid plan — Basic $15.90, Featured $19.90 or Sponsored $29.90 a month. There is no free option, so this is where it becomes a checkout.","3 Let ChatGPT write the page. Listing content is generated from your site by their model, which both paid tiers describe as a feature.","4 Wait for review — seven days on Basic, three on Featured."]', rw_submit_requirements='["A payment of at least $15.90","A tool name, website URL and contact email","A logo and screenshots"]', rw_rejection_reasons='["Anyone not paying, and any product with no AI story"]', rw_gotchas='["There is no free tier: the form asks for three fields and says nothing about money, and the price appears only at the plan step, so it reads free right up to checkout.","The $15.90 Basic tier lists Nofollow backlinks from homepage as one of its own bullets; the followed link on that tier is from the content page only, and followed links from every page start at $19.90.","The listing copy is written by their model from your site, so the page ranking on your product''s name is not your words — sold as a feature, with no alternative."]', rw_faq='[{"question":"How long does MagicBox.tools approval take?","answer":"About a week — seven days on Basic, three on Featured."},{"question":"How much does it cost?","answer":"Basic $15.90, Featured $19.90 a month, Sponsored $29.90 a month, with membership plans for daily submissions. There is no free tier."},{"question":"Does a MagicBox.tools listing provide a dofollow link?","answer":"Yes, a dofollow link from the content page; homepage links are nofollow on Basic, followed from every page on Featured and up. Domain rating is 69."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Anyone not paying, or a product with no AI story."}]', rw_summary='MagicBox.tools is a paid-only AI directory from $15.90 where the listing copy is AI-generated and the cheapest tier''s homepage link is nofollow. No backlink is required; domain rating is 69.', rw_fact_points='["Paid-only from $15.90 with a 3-7 day review","Content-page link is dofollow; homepage nofollow on Basic","No badge or return link is expected","Accepts AI tools, SaaS, productivity, developer and design tools"]', rw_submission_checks='["Expect the price only at the plan step — there is no free tier.","Upgrade to Featured if you need followed homepage links.","The listing copy is AI-written; check what ranks on your name."]', rw_seo_title='MagicBox.tools: $15.90 AI Listing, DR 69', rw_seo_description='How to submit to MagicBox.tools: paid $15.90+ AI listing with AI-written copy, no backlink. Homepage link nofollow on Basic — 2026-11-16 snapshot.' WHERE slug='magicbox-tools';
UPDATE submission_sites SET rw_source_lead='The awesome-MCP-servers catalogue as a website: a free five-field form, with a $39 fee if you want a faster review and a followed link.', rw_what_you_get='A free listing for your MCP server in a dedicated catalogue, with a dofollow link, Official badge and faster review on the paid tier.', rw_you_need='["An MCP server — the only thing the catalogue holds","A GitHub repository or documentation URL","A server name, short description, category and contact email"]', rw_eligibility='You need an MCP server or agent skill with a public GitHub or docs link, plus basic details. Anything that is not an MCP server or skill, and any server with nothing public to link to, is rejected.', rw_submit_steps='["1 Open /submit — a single page with five fields and no account: server name, short description, a GitHub or docs link, category and contact email.","2 Pick a category from fifteen, including Development, Productivity, Database, Search, Web Scraping, File System and Memory.","3 Choose free or $39. Listings are free, with a Premium Submit below for $39 one-time buying faster review, an Official badge and a followed link.","4 Wait. The confirmation says Submission Successful and states a review within 12 hours with an email on approval — something the form itself never mentions."]', rw_submit_requirements='["A server name and short description","A GitHub or documentation link","One of fifteen categories","A contact email"]', rw_rejection_reasons='["Anything that is not an MCP server or agent skill, and any server with nothing public to link to"]', rw_gotchas='["The followed link is one of the three things the $39 tier sells, so the free listing''s link is not followed and the page does not say so directly.","The $39 tier is sold as skipping a wait that turns out to be twelve hours: the free confirmation states review within 12 hours, which the pricing copy never mentions.","The listing is for the server, not your product — the link field asks for GitHub or docs, so a closed-source hosted server needs a public repo describing itself first."]', rw_faq='[{"question":"How long does MCP Servers approval take?","answer":"Same day; the free confirmation states a review within 12 hours."},{"question":"How much does it cost?","answer":"Free listing, or $39 one-time Premium for faster review, an Official badge and a followed link."},{"question":"Does an MCP Servers listing provide a dofollow link?","answer":"The free listing''s link is nofollow; a followed link comes with the $39 tier. Domain rating is 69."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Anything that is not an MCP server or agent skill, or a server with no public link."}]', rw_summary='MCP Servers is a dedicated MCP catalogue with a free five-field listing and a $39 tier for a dofollow link, badge and faster review. No backlink is required; domain rating is 69.', rw_fact_points='["Free listings review within 12 hours","Free link is nofollow; $39 adds a followed link and badge","No return link is expected","Accepts MCP servers, developer tools, agent skills and open source"]', rw_submission_checks='["Use a public GitHub or docs link — the listing is for the server.","The free link is nofollow; upgrade only if you need a followed link.","Expect an approval email within 12 hours."]', rw_seo_title='MCP Servers: Free MCP Listing, DR 69', rw_seo_description='How to submit to MCP Servers: free five-field MCP listing, nofollow link free or $39 dofollow. No backlink — 2026-11-16 snapshot.' WHERE slug='mcpservers-org';
UPDATE submission_sites SET rw_source_lead='A 4,500-site launch directory whose free link stays dofollow only while a reciprocal link to them is live on your site.', rw_what_you_get='Three placements at once — directory entry, launched-projects feed and leaderboard — with a dofollow link that lasts as long as your reciprocal link.', rw_you_need='["An account created at the signup route","A link to the directory or their badge on your site, for the free dofollow tier","A live site with a name and description"]', rw_eligibility='You need an account, a live site and — if the dofollow link matters — a reciprocal link or badge on your site. A site you cannot add a link to stays nofollow.', rw_submit_steps='["1 Sign up at the account route. Listings attach to the account and there is no cap on how many you add.","2 Add the site. One submission puts the project in the directory, the launched-projects feed and the leaderboard at once.","3 Put their link or badge up. The free tier''s terms say linking to the directory or embedding its badge makes the outbound link to you followed once detected; without it, it stays nofollow.","4 Wait for the check — the dofollow flips when they verify the reciprocal link, not when the listing is created."]', rw_submit_requirements='["An account on the site","A live site URL, name and description","A link to the directory or their badge for the free tier","A screenshot for the card"]', rw_rejection_reasons='["A site you cannot add a reciprocal link to, if the dofollow link is the point — without one the listing stays nofollow"]', rw_gotchas='["The free dofollow link is conditional and ongoing: it is followed while they detect your reciprocal link or badge, and nofollow otherwise — a standing condition, not a one-time check.","One submission produces three placements at once, all sharing the same tagline, so copy written for a directory row is also your launch line and leaderboard text."]', rw_faq='[{"question":"How long does ShowMySites approval take?","answer":"Listings go live the same day; the dofollow flip follows reciprocal-link detection."},{"question":"How much does it cost?","answer":"Free with a reciprocal link. Premium is $10 once per account, not a subscription, and removes the reciprocal-link requirement for all your listings; payment goes through Paddle."},{"question":"Does a ShowMySites listing provide a dofollow link?","answer":"Yes, while your reciprocal link or badge is live, on a domain rated 70."},{"question":"Do I need to link back?","answer":"Yes on the free tier — the reciprocal link governs whether your link is followed."},{"question":"What gets a listing rejected?","answer":"A site that cannot carry a reciprocal link, if the dofollow link is the point."}]', rw_summary='ShowMySites is a launch directory where one submission creates three placements, and the free dofollow link lasts only while a reciprocal link is live. Premium removes that requirement; domain rating is 70.', rw_fact_points='["Free dofollow link is conditional on a reciprocal link","Submission is free and one entry creates three placements","A reciprocal link or badge is needed for free dofollow","Accepts SaaS, indie products, AI tools, web apps, marketplaces and blogs"]', rw_submission_checks='["Keep the reciprocal link live — the dofollow status depends on it.","Write one tagline that works as a directory row, launch line and leaderboard text.","Consider the $10 one-time Premium to drop the link requirement."]', rw_seo_title='ShowMySites: Free Launch Listing, DR 70', rw_seo_description='How to list on ShowMySites: free dofollow launch with a reciprocal link, or $10 once without. Three placements per entry — 2026-11-16 snapshot.' WHERE slug='showmysites';
UPDATE submission_sites SET rw_source_lead='The AI tool index attached to a two-million-reader newsletter, where the free way in is an email to support and nobody promises a reply.', rw_what_you_get='A dofollow listing in an AI index run alongside a large newsletter, if an editor acts on the recommendation email.', rw_you_need='["An AI tool — the whole premise of the index","A live URL","A one-sentence description","A category from about twenty already in use"]', rw_eligibility='You need a genuine AI tool, a live URL and a short description. Anything that is not AI is rejected, and anyone needing a decision or a reply on a timetable will be disappointed.', rw_submit_steps='["1 Check you are in category. Supertools indexes AI tools — model releases, agents, coding and content tools — so ordinary software has nowhere to land.","2 Read /submit for the two lanes: Recommend a Tool, which is free, and Newsletter Feature, which is advertising. Neither has a form on the page.","3 Email the recommendation to support with the tool''s name, URL, category and a one-sentence description — the four things the page asks for.","4 Wait without a receipt. Nothing acknowledges the email, no queue is shown and no review time is published; the only way to know is to search the index later."]', rw_submit_requirements='["A tool name","A live URL","A one-sentence description","A category the index already runs","An email to support containing the whole submission"]', rw_rejection_reasons='["Anything that is not an AI tool, and anyone needing a decision or any reply on a schedule"]', rw_gotchas='["There is no form, receipt or published review time — the free route is a support email, so nothing confirms arrival and the answer is only visible by finding your own listing later.","The paid option beside it is not a faster lane: Newsletter Feature is advertising sold separately and does not put you in the index."]', rw_faq='[{"question":"How long does Supertools approval take?","answer":"No review time is published; an editor decides from the recommendation email."},{"question":"How much does it cost?","answer":"Recommending a tool is free via email. Newsletter Feature is a separate advertising product, not a listing faster lane."},{"question":"Does a listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 70."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Anything that is not an AI tool, or needing a reply on a timetable."}]', rw_summary='Supertools is an AI tool index tied to a large newsletter where free submissions are a support email with no receipt or published review time. Listings are dofollow with no backlink; domain rating is 70.', rw_fact_points='["Free recommendation by email with no published review time","Listing carries a dofollow link and needs no backlink","Newsletter feature is separate advertising","AI tools only"]', rw_submission_checks='["Email the four requested items — name, URL, category, one-line description.","Expect no acknowledgment; check the index yourself later.","Do not confuse the paid newsletter feature with a listing."]', rw_seo_title='Supertools: Free AI Index Listing, DR 70', rw_seo_description='How to submit to Supertools: free dofollow AI index listing via a support email, no backlink. Email process and caveats from the 2026-11-16 snapshot.' WHERE slug='supertools';
UPDATE submission_sites SET rw_source_lead='A daily launch board whose free tier promises a dofollow backlink and delivers one the instant you submit.', rw_what_you_get='A dofollow listing that goes live the moment you submit, with no review step, scheduled on a date you pick up to 180 days out.', rw_you_need='["An account via Google, GitHub or email and password","A square logo under 1MB","A short description, at least one category, one technology and one platform"]', rw_eligibility='You need an account and a set of project details. Nothing is refused — the project page publishes the instant you submit, with no review step anywhere.', rw_submit_steps='["1 Sign in. /projects/submit redirects to /sign-in with Google, GitHub or email and password; a cookie banner sits over the corner.","2 Step 1, Project Info: a name, website URL, a short description in a rich-text editor, a 1:1 logo under 1MB and an optional 16:9 product image.","3 Step 2, Details: up to three of 37 categories, up to five technology tags, one or more of five platforms, a pricing model and optional GitHub and X URLs.","4 Step 3, Launch Date: one tier and a date list 180 days out, each showing remaining free slots; launches run at 08:00 UTC.","5 Step 4, Review: a read-only summary, then Submit Project, which goes straight to a live page marked Scheduled."]', rw_submit_requirements='["A live URL and an account","A project name and rich-text short description","A 1:1 logo under 1MB","Up to three categories and five tech tags","At least one platform and a pricing model","Optional GitHub and X URLs","A launch date up to 180 days out"]', rw_rejection_reasons='["Nothing is refused — the page publishes the instant you submit, with no review"]', rw_gotchas='["Free slots are real: every date for the next month showed three to five free, so you can usually book tomorrow, unlike a sister site where the free lane was full and the link nofollow.","The description is a rich-text editor with headings and lists, so pasting from a document brings its formatting — paste as plain text unless intended.","The logo cap is 1MB and the only hard image limit; a 1024px PNG is usually fine, an uncompressed export is not.","Your page is public from submit, weeks before launch, but votes and comments stay shut until 08:00 UTC on the day.","Three categories is a hard cap over a scrolling list of 37 that swallows page scroll."]', rw_faq='[{"question":"How long does AI SaaS approval take?","answer":"Instant — the project page publishes the moment you submit."},{"question":"Is submitting to AI SaaS free?","answer":"Yes, submission is free."},{"question":"Does an AI SaaS listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 7."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a project rejected?","answer":"Nothing — there is no review step."}]', rw_summary='AI SaaS is a daily launch board with a free dofollow listing that publishes instantly and no review. You pick a launch date up to 180 days out; domain rating is 7.', rw_fact_points='["Listings publish instantly with no review","Submission is free and carries a dofollow link","No badge or return link is expected","Accepts AI tools, SaaS, marketing tools and dev tools"]', rw_submission_checks='["Paste description as plain text unless you want imported formatting.","Keep the logo under 1MB.","Know your page is public immediately, even weeks before launch."]', rw_seo_title='AI SaaS: Free Instant Launch, DR 7', rw_seo_description='How to submit to AI SaaS: free instant dofollow launch with a date up to 180 days out, no backlink. Form steps from the 2026-11-16 snapshot.' WHERE slug='ai-saas-org';
UPDATE submission_sites SET rw_source_lead='A tight AI-tools directory that trades a dofollow listing for a plain text link on your site, with no account in the way.', rw_what_you_get='A dofollow listing after manual review, in exchange for a plain text link back on your site.', rw_you_need='["A product fitting one of their AI categories","A square logo at a public URL","A text link back to them on your site on the free tier"]', rw_eligibility='You need a product in an AI-generation category and a text link back on the free tier. Products with no AI angle are rejected.', rw_submit_steps='["1 Check the category list first — everything is AI-generation shaped: text, image, audio, video, chat bots, agents and copilots.","2 Place their text link. The free tier wants a plain anchor to them on your site; there is no image badge.","3 Fill one short form: name, URL, logo URL, a 200-character description, a 500-character long description, category and email. No account needed.","4 Take the free button. Two buttons sit together, $25 and free; the free one posts to their API with a confirmation toast.","5 Wait for the email — manual review, typically 48 hours, then the listing goes live with a dofollow link."]', rw_submit_requirements='["A square logo at a public URL","A short 200-character description","A longer 500-character description","A text link to the directory on your site","A contact email"]', rw_rejection_reasons='["Products with no AI angle at all"]', rw_gotchas='["The advertised DR 63 is their own claim; no free rating service has a number for the domain.","The backlink is plain text, not a badge image, so it needs a spot your footer or links page will actually keep.","Categories are narrow and AI-only, so a marketing or productivity tool with a light AI angle is a poor bet."]', rw_faq='[{"question":"How long does AI Toolz Dir approval take?","answer":"One to two days; manual review is typically about 48 hours."},{"question":"How much does it cost?","answer":"Free with a text link back; $25 removes the backlink rule and halves the wait."},{"question":"Does a listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 68."},{"question":"Do I need to link back?","answer":"Yes, on the free tier a plain text link to the directory is required."},{"question":"What gets a submission rejected?","answer":"Products with no AI angle."}]', rw_summary='AI Toolz Dir is a tight AI directory with a free dofollow listing in exchange for a plain text link back, no account required. Review takes about 48 hours; domain rating is 68.', rw_fact_points='["Manual review in about 48 hours","Free listing is dofollow and needs a text link back","No badge image, just a plain anchor","Accepts AI tools, agents, chat bots and free tools"]', rw_submission_checks='["Place a plain text link on your site before submitting.","Fit a narrow AI-generation category.","Expect the link to be permanent on the free tier."]', rw_seo_title='AI Toolz Dir: Free AI Listing, DR 68', rw_seo_description='How to submit to AI Toolz Dir: free dofollow AI listing for a text link back, no account. Steps and categories from the 2026-11-16 snapshot.' WHERE slug='ai-toolz-dir';
UPDATE submission_sites SET rw_source_lead='A long-running startup tools directory whose whole submission is one Typeform, and which discards your entry if you apply from a Gmail address.', rw_what_you_get='A dofollow listing offered by email after the application — but only if you accept a paid annual plan.', rw_you_need='["A work or business email on your own domain","The first and last name of a real person","A product name, short and long descriptions","A website URL, one category and a logo file"]', rw_eligibility='You need a work-domain email, a personal name, product copy and a logo. A free-mail address ends the form with a dedicated rejection screen, and a product without a logo file cannot pass the required upload.', rw_submit_steps='["1 Open the listing form. /add-listing/ embeds a Typeform behind a single button; the embed can render blank on a slow load, so wait.","2 Identify yourself with first name, last name and email — the email question has its own rejection branch for non-work addresses.","3 Describe the product: name, a short description, a long description and the website URL, each on its own screen.","4 Categorise and upload: one category, then a required logo upload, then an optional video link.","5 Answer the advertising question. The last screen asks if you are interested in advertising, and the confirmation only says they will get back to you as soon as possible."]', rw_submit_requirements='["A work or business email — free-mail is rejected outright","A first and last name","A product name and short and long descriptions up to 500 characters","A website or product URL","One category","A logo file","An optional demo video link"]', rw_rejection_reasons='["A free-mail address, which hits a dedicated Sorry, we only accept work/business emails screen, and a product with no logo file, since the upload is required"]', rw_gotchas='["The form is free and mentions no price, but the application only earns an email offering a listing at $199 or $399 a year; without paying, nothing is published.","A Gmail, Outlook or other free-mail address ends the form, so most indie makers'' submissions never reach a person.","It is a Typeform with no save and no going back: it advances one question at a time and closing the tab loses the run.","The long description is capped at 500 characters, stated only on the question itself after you have written it."]', rw_faq='[{"question":"How long does Startup Stash approval take?","answer":"No review time is published; the free application only earns a paid-listing offer."},{"question":"How much does it cost?","answer":"Applying is free, but the listing is $199 a year Basic or $399 a year Premium, live within 72 hours of payment."},{"question":"Does a Startup Stash listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 65."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"A free-mail address, or a product with no logo file."}]', rw_summary='Startup Stash is a long-running startup tools directory whose free Typeform application only leads to a paid $199 or $399 annual listing. A work email and logo are mandatory; dofollow, no backlink, domain rating 65.', rw_fact_points='["Free application but paid listing, no published review time","Listing is dofollow with no backlink requirement","A work-domain email is mandatory","Accepts SaaS, startup, productivity, marketing and developer tools"]', rw_submission_checks='["Use a work-domain email — free-mail is rejected outright.","Have a logo file ready; the upload is required.","Expect a paid offer after the free application."]', rw_seo_title='Startup Stash: Paid Listing, DR 65', rw_seo_description='How to apply to Startup Stash: free Typeform but a $199+ annual listing, dofollow, work email required. Steps from the 2026-11-16 snapshot.' WHERE slug='startup-stash';
UPDATE submission_sites SET rw_source_lead='Eighty to one hundred and twenty dollars, sold through a listing broker rather than the directory itself.', rw_what_you_get='A permanent dofollow listing published by a third-party broker, with a report sent after it goes live.', rw_you_need='["A live product URL","A payment of 80 to 120 USD"]', rw_eligibility='You need a live URL and payment. Anyone not paying is excluded — there is no free submission form on the directory at all.', rw_submit_steps='["1 Open the submit page. It is a product page on a broker''s site wearing the directory''s name, not a form on the directory.","2 Buy the listing. Add to cart at 80 to 120 USD, alongside other directories the broker resells.","3 Wait for the report. They say 24 to 72 hours and send a report once it is published."]', rw_submit_requirements='["A one-off payment of 80 to 120 USD"]', rw_rejection_reasons='["Anyone not paying — there is no free submission form on the directory"]', rw_gotchas='["The submit page is a shop run by a third party reselling placements on several directories at once, so you are buying a service rather than filling a form.","There is no free lane and no self-service submission form on the directory itself.","Because a broker publishes the listing, the copy is written from whatever you hand over rather than typed by you."]', rw_faq='[{"question":"How long does AiForEveryone approval take?","answer":"One to two days; the broker promises 24 to 72 hours."},{"question":"How much does it cost?","answer":"80 to 120 USD one-off, sold through a broker rather than the directory."},{"question":"Does a listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 61."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Anyone not paying — there is no free form."}]', rw_summary='AiForEveryone is an AI directory whose listings are sold by a third-party broker for 80 to 120 USD. The dofollow listing needs no backlink and takes one to two days; domain rating is 61.', rw_fact_points='["Paid-only through a broker at 80-120 USD","Dofollow listing with no backlink requirement","A report is sent after publication","Accepts AI tools and SaaS products"]', rw_submission_checks='["Expect to buy through a third-party broker, not the directory.","Hand over clear copy — the broker writes the listing.","Wait 24 to 72 hours for the publication report."]', rw_seo_title='AiForEveryone: $80+ Listing, DR 61', rw_seo_description='How to submit to AiForEveryone: $80-120 dofollow listing via a third-party broker, no backlink. Process from the 2026-11-16 snapshot.' WHERE slug='aiforeveryone';
UPDATE submission_sites SET rw_source_lead='A human-edited general web directory from 2003 that still hands out dofollow links, now that the free lane is off and the only open door costs GBP 29.95.', rw_what_you_get='A dofollow listing in a long-established hand-edited directory, with priority placement above standard listings for a year.', rw_you_need='["A live URL that resolves directly, since redirects are not accepted","English-language content","A specific subcategory chosen before the form appears","GBP 29.95 while the free lane is closed"]', rw_eligibility='You need a directly resolving English URL, a specific subcategory and the fee. Adult content, gambling and anything not in English are rejected, and you must accept that they may edit your title and description.', rw_submit_steps='["1 Drill into a subcategory first. The Add Site link at index.php?a=0 refuses entries and tells you to pick a more specific shelf; browse to your category and use its own Add Site link.","2 Read the rules above the form: English only, no adult, no gambling, no redirects, and two you must accept — they may edit your title and description and move the listing at any time without notice.","3 Find out which lane is open. Standard Review is free but renders no form, only an apology about a backlog; Express Review is one URL field and a button, and the only working option.","4 Pay or leave. Express is GBP 29.95, buying queue priority rather than a decision: the page says the submission appears above standard listings if accepted. Stated wait is one day."]', rw_submit_requirements='["A website URL up to 105 characters with no redirect","The Express fee of GBP 29.95","English-language content","A specific subcategory picked before the form loads"]', rw_rejection_reasons='["Adult content, gambling, anything not in English, and anyone who needs their own title and description to survive — they reserve the right to edit both"]', rw_gotchas='["The free lane is switched off: the page still describes Standard Review then replaces its form with a backlog apology and no reopening date.","They reserve the right to rewrite your title and description and move your listing to another category at any time, both stated in the rules you accept.","The GBP 29.95 buys queue position, not a listing — their wording is appear above standard listings if accepted, with nothing said about a refund if rejected."]', rw_faq='[{"question":"How long does Directory World approval take?","answer":"One to two days; Express is usually within two business days."},{"question":"How much does it cost?","answer":"GBP 29.95, called an administration fee, buying priority review and a year above standard listings. The free Standard Review is currently disabled with no reopening date."},{"question":"Does a listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 61."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Adult or gambling content, non-English sites, and anyone who cannot accept edits to their title and description."}]', rw_summary='Directory World is a long-running hand-edited web directory with a dofollow link and no backlink requirement. The free lane is currently off; Express costs GBP 29.95 for priority review. Domain rating is 61.', rw_fact_points='["Free lane disabled; Express GBP 29.95 for priority","Listings carry a dofollow link and need no backlink","They may edit your title, description and category","English-only, no adult or gambling content"]', rw_submission_checks='["Pick a specific subcategory before the form will load.","Accept that they may rewrite your copy and move the listing.","The fee buys priority, not acceptance."]', rw_seo_title='Directory World: £29.95 Dofollow Listing, DR 61', rw_seo_description='How to list on Directory World: dofollow link with no backlink, free lane off, GBP 29.95 Express for priority. Rules from the 2026-11-16 snapshot.' WHERE slug='directory-world';
UPDATE submission_sites SET rw_source_lead='The highest-DR board here whose free listing links out dofollow, and the price is three real comments plus a badge on your site.', rw_what_you_get='A dofollow listing on a high-authority launch board, in exchange for a permanent badge and three thoughtful comments on other launches.', rw_you_need='["A live site with an English version and a domain rating above zero","Their badge in your header or footer","Three thoughtful comments on other launches","A square logo and at least three gallery images"]', rw_eligibility='You need an English site with a rating above zero, their badge and three genuine comments. A site with no English version, a zero rating or a refusal to display the badge is rejected.', rw_submit_steps='["1 Take the free lane from the pricing page. /submit shows four tiers; the free one is the plain card whose button says Submit under Free with embed badge.","2 Leave three comments. A counter on the launch page tracks them; they want thoughtful, specific ones and say Looks cool will not count.","3 Put the badge up and verify. Copy either badge, deploy it, tick the conditions box and press Verify Badge — it answers Verification Passed and turns the button into Next.","4 Fill the launch across five screens: name and tagline, three topics, description, features and use cases, then a logo and at least three gallery images, then pricing, makers and competitors.","5 Pick a date and decline the upsells. The last screen wants a launch date before its button lifts; submitting lands on an upsell page with Premium pre-ticked — untick it to keep the free lane."]', rw_submit_requirements='["A live product URL","A product name up to 40 characters and a tagline up to 60","A description, features list and use-case list","A square logo 250x250 or larger","At least three 1200x628 gallery images","One category and up to three topics","A launch date the form will not let you skip","Optional competitor, maker and social details"]', rw_rejection_reasons='["A site with no English version, a domain rating of zero, or refusing the badge that is the whole price of the free lane"]', rw_gotchas='["The free listing''s outbound link carries rel=noopener with no nofollow, which their pricing never says — the paid tiers sell a guaranteed high-authority backlink the free tier already gives.","The badge is not a courtesy: their crawler checks for it before the launch form opens, and the free tier is described in their own words as free with embed badge.","Three comments come before the form, not after, and generic ones are rejected — budget time to read three other launches.","Their badge URL contains a doubled slash which is correct and will 404 if tidied.","Every paid extra is pre-ticked — add-ons on the way in and Premium on the way out — so untick before each Submit or it becomes a checkout."]', rw_faq='[{"question":"How long does Fazier approval take?","answer":"Two to four weeks."},{"question":"How much does it cost?","answer":"Free with a badge and three comments. $29 Lite drops those requirements, $49 Premium adds 15 days of promotion, $119 Super pins the homepage."},{"question":"Does a Fazier listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 82."},{"question":"Do I need to link back?","answer":"Yes — the free lane requires their badge on your site."},{"question":"What gets a listing rejected?","answer":"No English version, a domain rating of zero, or refusing the badge."}]', rw_summary='Fazier is a high-authority launch board where the free dofollow listing costs a permanent badge and three genuine comments. No other backlink is required; domain rating is 82.', rw_fact_points='["Free lane needs a badge and three comments","Listing is dofollow on a DR 82 domain","A badge backlink is required on free","Accepts indie products, SaaS, AI tools, marketing and newsletters"]', rw_submission_checks='["Write three thoughtful comments on other launches before starting.","Install the badge exactly as given, including the doubled slash.","Pick a launch date and untick all pre-ticked upsells."]', rw_seo_title='Fazier: Free Badge Launch, DR 82', rw_seo_description='How to launch on Fazier: free dofollow listing for a badge and three comments, no other backlink. Rules and traps from the 2026-11-16 snapshot.' WHERE slug='fazier';
UPDATE submission_sites SET rw_source_lead='Registration is free and the queue is over eighty days, unless you pay to jump it.', rw_what_you_get='A dofollow startup listing after a long free queue, or within 24 hours on a paid fast track.', rw_you_need='["A Google, Facebook, LinkedIn or X account","A country and a state or region, both required","A founding date and an industry"]', rw_eligibility='You need a social account, a country and region, a founding date and an industry. A founder unwilling to publish a region as well as a country cannot complete the form.', rw_submit_steps='["1 Get past the bot check. A security interstitial appears on a first visit; wait for it rather than treating it as an outage.","2 Validate the URL. Create Startup begins at the URL-validation route, which checks the address before showing a form; the guessable submit path returns 404.","3 Sign in with Google, Facebook, LinkedIn or X — they state they take only your name, email and picture.","4 Fill the registration: startup name, legal name, a slogan up to 60 characters, country and state, URL, founding date, business type, industry, tags, description, socials, email and phone.","5 Wait, or pay to skip. Free registration joins a queue their own page describes as over eighty days; $25 buys approval within 24 hours."]', rw_submit_requirements='["A startup name and URL","A country and a state or region","A founding date","An industry","A contact email and description","Optional legal name, slogan, business type, tags, socials and phone"]', rw_rejection_reasons='["A founder unwilling to publish a region as well as a country, since both are required and both appear on the listing"]', rw_gotchas='["The free queue is over eighty days by their own account, and the paid product exists entirely to sell a way around it.","The form requires a state or region as well as a country, publishing a location a founder may only want to give at country level.","A founding date is mandatory down to the day, awkward for a product that never had a formal founding.","The site is bot-protected, so the first load shows a security check and the guessable submit path returns 404."]', rw_faq='[{"question":"How long does Startup Ranking approval take?","answer":"Two to three months on free; $25 fast track approves within 24 hours."},{"question":"How much does it cost?","answer":"Free registration with an 80+ day queue. Faster Approval is $25 Basic or $49 Premium, including 24-hour approval and a newsletter spotlight."},{"question":"Does a listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 61."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a startup rejected?","answer":"Unwillingness to publish a region as well as a country, since both are required."}]', rw_summary='Startup Ranking offers free registration with an 80+ day queue or a $25 fast track. Listings are dofollow with no backlink requirement; domain rating is 61.', rw_fact_points='["Free queue over 80 days; $25 approves in 24 hours","Listing is dofollow with no backlink","No badge or return link is expected","Accepts startups, SaaS and indie products"]', rw_submission_checks='["Expect a long free wait, or pay for speed.","Be ready to publish a region as well as a country.","Have an exact founding date — it is required."]', rw_seo_title='Startup Ranking: Free Listing, DR 61', rw_seo_description='How to submit to Startup Ranking: free dofollow startup listing with an 80-day queue or $25 fast track, no backlink. Steps from the 2026-11-16 snapshot.' WHERE slug='startupranking';
UPDATE submission_sites SET rw_source_lead='A 300-tool SaaS and AI directory where the free dofollow listing costs you a permanent badge instead of money.', rw_what_you_get='A dofollow listing after a badge check, with a description and introduction written to their format.', rw_you_need='["A live, working product","Ahrefs DR 5+ as stated on the free card","Their badge on your site, kept permanently"]', rw_eligibility='You need a live product, a domain rating above their floor on the free tier and a permanent badge. Crypto, adult, gambling, drugs, weapons, illegal services, unlaunched landing pages and undifferentiated clones are rejected.', rw_submit_steps='["1 Pick the free plan. /submit shows three tiers; Free needs the rating floor and a badge, and a browser dialog restates the terms before the form opens.","2 Fill the product form: URL, name, a 256-character description, a 500 to 2,000 character markdown introduction, categories and pricing tags. No account needed.","3 Upload media: a 1:1 logo and a 16:9 screenshot, PNG or JPEG, 1MB each. Uploads fire only after badge verification.","4 Place and verify the badge. Paste their snippet on your site, then click Verify Backlink; their bot fetches your page live, and the badge must stay up forever or the listing is delisted.","5 Submit past the upsell. The Submit button opens a premium modal every time; Continue with Free is the actual submission click."]', rw_submit_requirements='["A live product URL checked against Ahrefs before the form opens","A domain rating at their stated free-tier floor","A permanent dofollow badge snippet","A product name, categories and a 256-character description","A 500 to 2,000 character introduction","A 1:1 logo and 16:9 screenshot, PNG or JPEG up to 1MB","A contact email and optional social link"]', rw_rejection_reasons='["Crypto, adult, gambling, drugs, weapons and illegal services; landing pages for unlaunched ideas; clones without meaningful differentiation"]', rw_gotchas='["The free tier''s rating floor was raised and is checked against Ahrefs before the form will open at all.","Removing the badge means automatic delisting; their bot re-crawls your site on a schedule.","Submitting needs three ticks, one agreeing to terms and privacy, so the last click is a person''s even if an agent filled the rest.","The logo and screenshot are accepted into the form but not uploaded until the badge verifies, so a run that stops early leaves no assets behind."]', rw_faq='[{"question":"How long does Toolfio approval take?","answer":"Three to five days."},{"question":"How much does it cost?","answer":"Free with a permanent badge. Premium is $18.99 once for no badge, instant approval and three dofollow links; a review article is $39.99."},{"question":"Does a Toolfio listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 61."},{"question":"Do I need to link back?","answer":"Yes — the free tier requires a permanent badge."},{"question":"What gets a listing rejected?","answer":"Crypto, adult, gambling, drugs, weapons, illegal services, unlaunched landing pages and clones."}]', rw_summary='Toolfio is a SaaS and AI directory where the free dofollow listing requires a permanent badge and a minimum domain rating. No other backlink is needed; domain rating is 61.', rw_fact_points='["Free listing after badge verification in 3-5 days","Dofollow listing needs a permanent badge","A minimum Ahrefs rating applies on free","Accepts SaaS tools, AI tools, indie products and directories"]', rw_submission_checks='["Check your domain rating before starting — it gates the form.","Install the badge permanently; removal delists you.","Continue with Free at the last step; the upsell is pre-shown."]', rw_seo_title='Toolfio: Free Badge Listing, DR 61', rw_seo_description='How to submit to Toolfio: free dofollow listing for a permanent badge, DR floor applies, 3-5 day review. Steps from the 2026-11-16 snapshot.' WHERE slug='toolfio';
UPDATE submission_sites SET rw_source_lead='The only button on the form reads Pay, then Submit — a paid-only AI directory.', rw_what_you_get='A dofollow listing within 48 hours on the one-time tier, or 24 hours on the subscription.', rw_you_need='["A payment of at least $19.9","A website name and URL"]', rw_eligibility='You need a live URL and payment. Anything that is not an AI tool is rejected, and there is no free submission route.', rw_submit_steps='["1 Find the submit page. The nav''s Submit AI menu leads to the submit route; guessing a submit-ai path returns 404.","2 Fill two fields — a website name and URL — with radio buttons for the one-time or monthly plan.","3 Pay. The single action is labelled Pay, then Submit, through Stripe or PayPal.","4 Wait for the listing: 48 hours on the one-time tier, 24 on the subscription, eight hours on the $99 advertising tier."]', rw_submit_requirements='["A website name","A website URL","A payment of at least $19.9"]', rw_rejection_reasons='["Anything that is not an AI tool"]', rw_gotchas='["There is no free lane — the form''s only button is Pay, then Submit, and the radios choose between prices rather than paid and free.","The one-time and monthly tiers differ mainly in review speed, so paying monthly for one product buys 24 hours instead of 48.","The guessable submit path 404s; the working one is reached from the nav."]', rw_faq='[{"question":"How long does AI With Me approval take?","answer":"One to two days — 48 hours one-time, 24 monthly, 8 on the $99 advertising tier."},{"question":"How much does it cost?","answer":"$19.9 one-time, $29.9 a month for unlimited submissions, or $99 for 30 days of ads and an eight-hour review."},{"question":"Does a listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 59."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Anything that is not an AI tool."}]', rw_summary='AI With Me is a paid-only AI directory from $19.9 with a dofollow listing and no backlink requirement. Listing takes 24 to 48 hours; domain rating is 59.', rw_fact_points='["Paid-only from $19.9, listed in 24-48 hours","Listing is dofollow with no backlink","No badge or return link is expected","Accepts AI tools and SaaS products"]', rw_submission_checks='["Expect to pay — the only button is Pay, then Submit.","Use the nav''s submit route, not a guessed URL.","Pick monthly only if the faster 24-hour review is worth it."]', rw_seo_title='AI With Me: $19.9 AI Listing, DR 59', rw_seo_description='How to submit to AI With Me: paid $19.9+ dofollow AI listing in 24-48 hours, no backlink. Pay flow and tiers from the 2026-11-16 snapshot.' WHERE slug='aiwith-me';
UPDATE submission_sites SET rw_source_lead='A content-creation tools directory whose free lane trades three dofollow links for a permanent badge and a two-week wait.', rw_what_you_get='A dofollow listing with up to three links in a content-creation directory, published within two weeks on the badge-funded free lane.', rw_you_need='["An account via Google, GitHub or email and password","A live URL","Their badge on your site, verified before submission continues","A 16:9 image under 1MB","A fit with one of eighteen content-creation categories"]', rw_eligibility='You need a content-creation product, a live site and a verified badge on the free lane. A product with no content-creation angle, or a maker who will not host the badge, is rejected.', rw_submit_steps='["1 Sign in. /submit redirects to /auth/login; Google and GitHub sit under the email form and create the account on the spot.","2 Fill the details, step 1 of 3: a link, name, up to three categories, four required tag groups (difficulty, pricing, platforms, languages), a short description, a markdown introduction and one 16:9 image under 1MB.","3 Pick the lane, step 2 of 3. Submit creates the product as Submitting and moves to plans; Basic and Pro are Pay & Publish Right Now, while free reads Verify backlink first.","4 Verify the badge. The dialog gives a light or dark snippet pointing at your listing URL and reads Waiting for verification until their checker finds it — only then does free continue.","5 Wait two weeks. The free card says reviewed and listed within two weeks, against immediate listing on both paid tiers."]', rw_submit_requirements='["An account via Google, GitHub or email and password","A product name and live URL","Up to three of eighteen categories","Tags in four required groups","A short description and markdown introduction","One 16:9 PNG or JPEG image under 1MB","Their badge on your site for the free lane"]', rw_rejection_reasons='["A product with no content-creation angle at all, and a maker who will not host a badge on the free lane"]', rw_gotchas='["The free badge is checked before the submission continues, not after, so it must be live before you reach the plan step.","Both counters on the details step are labelled Words but count characters, mirroring the operator''s sister site."]', rw_faq='[{"question":"How long does Turbo0 approval take?","answer":"One to two weeks on free; paid tiers publish immediately."},{"question":"How much does it cost?","answer":"Free with a badge and two-week wait. Basic is $16.90 once for no badge and no queue; Pro is $69.90 adding a fifth link and features."},{"question":"Does a listing provide a dofollow link?","answer":"Yes, dofollow links on a domain rated 80."},{"question":"Do I need to link back?","answer":"Yes — the free lane requires a verified badge."},{"question":"What gets a listing rejected?","answer":"No content-creation angle, or refusing the badge on free."}]', rw_summary='Turbo0 is a content-creation tools directory where the free lane gives dofollow links for a permanent badge and a two-week wait. Paid tiers skip both; domain rating is 80.', rw_fact_points='["Free listings take two weeks; paid are immediate","Free lane gives multiple dofollow links","A verified badge is required on free","Accepts design, productivity, marketing, note-taking, website-builder and copywriting tools"]', rw_submission_checks='["Deploy the badge before reaching the plan step.","Fill all four required tag groups.","Use a 16:9 image under 1MB."]', rw_seo_title='Turbo0: Free Badge Listing, DR 80', rw_seo_description='How to submit to Turbo0: free dofollow listing for a badge and two-week wait, or instant paid tiers. Steps from the 2026-11-16 snapshot.' WHERE slug='turbo0';
UPDATE submission_sites SET rw_source_lead='No free lane at all: the form prints a $69.90 total directly above its submit button.', rw_what_you_get='A dofollow listing in fourteen languages with at least ten backlinks, a verified badge and listing within two business days.', rw_you_need='["A $69.90 payment before anything is submitted","A product name, website and contact email"]', rw_eligibility='You need to pay $69.90 and supply basic product details. Anything that is not an AI product is rejected, since the entire directory is AI-only.', rw_submit_steps='["1 Open Submit under Submit & Promote. The header splits submissions from sponsorship; the form is at /submit.","2 Read what the fee buys: pages in fourteen languages, at least ten backlinks, a Verified check, listing within two business days and a full refund if verification fails.","3 Fill the short form with a product name, website, email and a More Info box. No account is needed to see or fill it.","4 Pay. The button reads Submit under a line saying Total: $69.90; there is no free path past this point."]', rw_submit_requirements='["A product name and website","A contact email","A $69.90 payment","Optional more information such as social channels or a video"]', rw_rejection_reasons='["Anything that is not an AI product, since the directory is AI-only"]', rw_gotchas='["There is no free tier anywhere in the flow — the form itself prints Total: $69.90 right above the submit button.","The whole directory is AI-only, so a non-AI product has nothing to buy here.","The refund promise is tied to verification failing, not to changing your mind after listing."]', rw_faq='[{"question":"How long does AIPURE approval take?","answer":"One to two days; the fee promises listing within two business days."},{"question":"How much does it cost?","answer":"$69.90 one-time, down from $89.90 as a launch offer, with a full refund if verification fails. Sponsorship is separate."},{"question":"Does a listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 57, with at least ten backlinks promised."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Anything that is not an AI product."}]', rw_summary='AIPURE is a paid-only AI directory at $69.90 one-time, offering a dofollow listing in fourteen languages with no backlink required. Listing takes two business days; domain rating is 57.', rw_fact_points='["Paid-only at $69.90, listed within two days","Dofollow listing with no backlink","Pages in fourteen languages and a Verified badge","AI tools and SaaS products only"]', rw_submission_checks='["Expect to pay — there is no free tier.","Have a product name, website and email ready.","The refund applies only if their verification fails."]', rw_seo_title='AIPURE: $69.90 AI Listing, DR 57', rw_seo_description='How to submit to AIPURE: paid $69.90 dofollow AI listing in fourteen languages, no backlink. Fee and steps from the 2026-11-16 snapshot.' WHERE slug='aipure';
UPDATE submission_sites SET rw_source_lead='A genuinely free five-step launch with a dofollow link straight to your site and no badge asked for anywhere.', rw_what_you_get='A free launch listing with a direct dofollow link to your site, no badge and no return link required.', rw_you_need='["A Google or GitHub account, or an email and password","A square product icon and a 1200x630 hero image, both required","A description, one to three categories and at least one platform"]', rw_eligibility='You need an account and both required images. Anything needing a chosen launch date is a poor fit, since picking the date is a paid extra and the free lane takes what it is given.', rw_submit_steps='["1 Sign in first, or the submit route is invisible. Signed out there is no submit link; sign in at the auth page and a Submit button appears in the header.","2 Say whether you are the founder. Founder Launch gives attribution, profile visibility and a badge; Community Launch is for somebody else''s product.","3 Basic information then media: a name, tagline and website, then a required square icon and 1200x630 hero. Screenshots and a demo video are optional.","4 Product details: a description, up to three categories, at least one platform, up to five tags and a slug generated from the name.","5 Pick the plan, then review. Free is preselected and the review card restates it before Submit to Launch, followed by a first-comment prompt."]', rw_submit_requirements='["A product name, tagline and website URL","A square icon and a 1200x630 hero image","A description and one to three categories","At least one platform","Optional screenshots, demo video and X handle"]', rw_rejection_reasons='["Anything needing a particular launch day — picking the date is sold separately and the free lane takes what it is given"]', rw_gotchas='["Signed out there is no way in: no submit link appears anywhere until you have an account, so the flow looks nonexistent rather than login-gated.","The pricing page advertises a three-day queue, but the flow says free launches sit behind paid ones and the plan step quotes about seven days — believe the second.","Both images are required and unforgiving: a square icon and a 1200x630 hero, with no option to skip.","After submitting they ask to connect Stripe to verify revenue for a leaderboard badge; it is optional and described as read-only, but it is a payment-provider connection after the launch."]', rw_faq='[{"question":"How long does trylaunch approval take?","answer":"About a week on free; paid tiers skip the queue."},{"question":"How much does it cost?","answer":"Free lane with no badge required. Pro is $39 with a chosen date and promotion; extras are sold separately."},{"question":"Does a listing provide a dofollow link?","answer":"Yes, a direct dofollow link to your site on a domain rated 56."},{"question":"Do I need to link back?","answer":"No backlink or badge is required."},{"question":"What gets a launch rejected?","answer":"Anything needing a specific launch day, which is a paid feature."}]', rw_summary='trylaunch is a free five-step launch board with a direct dofollow link and no badge or backlink required. Free launches are scheduled behind paid ones in about a week; domain rating is 56.', rw_fact_points='["Free launch in about a week behind paid ones","Listing is dofollow with no badge required","No return link is expected","Accepts AI tools, SaaS, dev tools and startups"]', rw_submission_checks='["Sign in first — the submit link only appears afterward.","Prepare both a square icon and a 1200x630 hero.","Expect roughly seven days, not the three quoted on pricing."]', rw_seo_title='trylaunch: Free Dofollow Launch, DR 56', rw_seo_description='How to launch on trylaunch: free five-step dofollow launch, no badge or backlink, about a week on free. Steps from the 2026-11-16 snapshot.' WHERE slug='trylaunch';
UPDATE submission_sites SET rw_source_lead='A 6,500-example web design gallery curated by one person, with plain dofollow links and no submit form — the contact box is the whole route in.', rw_what_you_get='A dofollow listing as a design example in a hand-curated gallery, if the curator rates your site.', rw_you_need='["A live site of your own worth looking at — the gallery is about layout, not product","An email address, since there is no account or form beyond the contact box"]', rw_eligibility='You need a visually strong site of your own and an email. Products with no site to screenshot, and sites the curator does not rate — a taste call with no published bar — do not appear.', rw_submit_steps='["1 Pick a category first. The left rail lists 43 galleries from Accounting to Travel, and every item sits in exactly one; SaaS, Startup, Product and Marketplace are the plausible homes for software.","2 Look at what is already in it. The bar is visual and unstated, so the gallery itself is the only guide — open your category and see whether your homepage fits.","3 Send it through the contact form. /contact takes a name, an email and a message, and that is the whole mechanism: no account, upload or copy fields. It posts to a form host, so Submit takes you off-site to a generic success line.","4 Watch the category page. Nothing from the gallery acknowledges the message and the confirmation belongs to the form host; the only evidence is your card appearing, and the site says it adds items weekly."]', rw_submit_requirements='["A live site URL","Your email address","A category from 43, Accounting to Travel","A message saying what the site is"]', rw_rejection_reasons='["Products with no site of their own to screenshot, and sites the curator does not rate — a taste call with no published bar"]', rw_gotchas='["There is no submit form or account anywhere. A submission is a contact email to one person, answered only by the form host''s generic success page with no reference and no mention of your site.","The caption under your screenshot is the curator''s note on your layout, not anything you write, so entries describe the design rather than what your product does."]', rw_faq='[{"question":"How long does Websitevice approval take?","answer":"No review time is published; the gallery says new items are added weekly."},{"question":"Is submitting to Websitevice free?","answer":"Yes, via the contact form."},{"question":"Does a listing provide a dofollow link?","answer":"Yes, a plain dofollow link on a domain rated 55."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a site rejected?","answer":"Having no site to screenshot, or a layout the curator does not rate."}]', rw_summary='Websitevice is a one-person-curated web design gallery with free dofollow listings submitted through a contact form. No backlink is required; domain rating is 55, and selection is purely visual.', rw_fact_points='["Curated by one person with no published review time","Free submission via contact form, dofollow link","No badge or return link is expected","Accepts websites, marketing sites, SaaS and portfolios"]', rw_submission_checks='["Choose the right one of 43 categories in your message.","Expect no acknowledgment beyond the form host''s success page.","The curator writes the caption; it describes your layout."]', rw_seo_title='Websitevice: Free Design Gallery, DR 55', rw_seo_description='How to submit to Websitevice: free dofollow design-gallery listing via a contact form, no backlink. Process and caveats from the 2026-11-16 snapshot.' WHERE slug='websitevice';
UPDATE submission_sites SET rw_source_lead='The listing is free and links out dofollow; the $39 buys only the launch event, a distinction the form never spells out.', rw_what_you_get='A free dofollow listing that is live the moment you submit, with an optional paid launch event on top.', rw_you_need='["An account via magic link or email and password","A product name, tagline, website, location and description","An industry from their long list"]', rw_eligibility='You need an account and basic product details. No refused categories are stated in their guidelines at all.', rw_submit_steps='["1 Create the account first. /businesses/add says you must sign up or log in, offering a passwordless magic link or email and password.","2 Fill the product info: a name, tagline, website, location, description, an industry from a long list and an optional logo.","3 Press Next, which is the real submit. It answers Business added successfully and the page is live from that moment; nothing later is needed to have a listing.","4 Read the Launch Date step for what it is. The stepper says Launch Date, the panel says Launch Plan, and it offers one preselected Premium Launch with no free alternative — this buys a launch event, not the listing you already have.","5 Stop there and check the dashboard. Businesses You Manage should read one, and your product page should load with its Visit Website link."]', rw_submit_requirements='["A product name, tagline and website","A location","A description","An industry from their list","An optional square logo under 1MB"]', rw_rejection_reasons='["Nothing stated — their guidelines name no refused categories at all"]', rw_gotchas='["The second step looks like a paywall on the whole submission, but the listing went live at the previous step; the money buys a launch event on top.","The site is heavily ad-monetised to the point that ads cover the sign-in card and a consent panel sits over the form — expect to dismiss two overlays before typing.","There is no Google option; only a magic link and email with password.","The logo upload rejected a valid small square PNG with Failed to upload logo and left the listing without one; it is optional, so budget to add it by hand."]', rw_faq='[{"question":"How long does BusinessHunt approval take?","answer":"Instant — the listing is live the moment you submit."},{"question":"How much does it cost?","answer":"The listing is free. Premium Launch is $39 (struck from $99) for a launch event with promotion and a guest post; a sponsor slot is $5 a day. Neither is needed for the listing."},{"question":"Does a BusinessHunt listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 52."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Nothing is stated in their guidelines."}]', rw_summary='BusinessHunt is a free dofollow business listing that goes live instantly, with a $39 paid launch event sold in a later step. No backlink is required; domain rating is 52.', rw_fact_points='["Free listing publishes instantly","Dofollow link with no backlink requirement","The paid step buys a launch event, not the listing","Accepts indie products, SaaS, B2B software and marketing tools"]', rw_submission_checks='["Press Next to publish the free listing; ignore the Launch Plan upsell.","Dismiss ad and consent overlays before filling the form.","Add the logo manually later if the upload fails."]', rw_seo_title='BusinessHunt: Free Dofollow Listing, DR 52', rw_seo_description='How to list on BusinessHunt: free instant dofollow listing, no backlink. The $39 buys a launch event, not the listing — 2026-11-16 snapshot.' WHERE slug='businesshunt';
UPDATE submission_sites SET rw_source_lead='A large multilingual AI hub with an MCP section, and nothing under $69.', rw_what_you_get='A dofollow listing in a multilingual AI hub, with separate sections for tools, agents and MCP servers.', rw_you_need='["A payment of at least $69 — there is no free tier"]', rw_eligibility='You need to pay; there is no free listing at any level. The hub categorises AI tools, agents and MCP servers separately.', rw_submit_steps='["1 Pick the product type — AI Tool or AI Agent, which decides the section; there is a separate MCP section.","2 Pick a tier: VIP at $69 or SVIP at $99, both one-time.","3 Pay. They quote listing within 48 hours with no queue."]', rw_submit_requirements='["A one-time payment from $69"]', rw_rejection_reasons='["Anyone looking for a free listing, because there is not one"]', rw_gotchas='["There is no free lane and $69 is the cheapest listing, at the top of the range for this kind of directory.","They keep separate AI Tool, AI Agent and MCP sections, so an MCP server has a specific place rather than being filed as a generic tool.","The nine or more dofollow links advertised all come from creati.ai itself across language versions, not nine different domains."]', rw_faq='[{"question":"How long does Creati.ai approval take?","answer":"One to two days; they quote listing within 48 hours."},{"question":"How much does it cost?","answer":"$69 one-time VIP or $99 SVIP with a click guarantee. There is no free tier; ads and guest posts are separate."},{"question":"Does a listing provide a dofollow link?","answer":"Yes, dofollow links on a domain rated 51, across their language versions."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Anyone looking for a free listing — there is none."}]', rw_summary='Creati.ai is a multilingual AI hub with paid-only listings from $69 and a dofollow link, no backlink required. It has separate tool, agent and MCP sections; domain rating is 51.', rw_fact_points='["Paid-only from $69, listed within 48 hours","Dofollow link with no backlink requirement","Separate AI tool, agent and MCP sections","No free tier at any level"]', rw_submission_checks='["Expect to pay — there is no free lane.","Choose the right section: tool, agent or MCP.","The advertised dofollow links are all from their own language sites."]', rw_seo_title='Creati.ai: $69 AI Listing, DR 51', rw_seo_description='How to submit to Creati.ai: paid $69+ dofollow AI listing across a multilingual hub, no backlink. Tiers and sections from the 2026-11-16 snapshot.' WHERE slug='creati-ai';
UPDATE submission_sites SET rw_source_lead='Two backlinks per launch rather than one, because the same operator also runs a second directory and lists you on both.', rw_what_you_get='Two dofollow links from one submission — one from each of the operator''s two directories — once your badge is verified.', rw_you_need='["An account via Google or X, so the launch has a named owner","A live product URL","Their badge live on your site before a launch date can be picked"]', rw_eligibility='You need an owned account and a live URL. No content bar is published; the only stated requirement is an account behind the launch and the badge for the free lane.', rw_submit_steps='["1 Sign in with Google, or email and password.","2 Enter core details: website URL, product name, category, a 60-character tagline, a 300-character description, an optional problem line, a logo and at least one image. An Autofill with AI button only runs when clicked.","3 Badge setup. Their server fetches the URL from step one and looks for their snippet; the launch-date step stays locked until it finds it.","4 Pick a date and submit. Dates are daily with a spot count; the confirmation reads You are in the queue and says they review before the date."]', rw_submit_requirements='["An account via Google or X","A live product URL","Their badge live on your site before a launch date can be chosen"]', rw_rejection_reasons='["Nothing published as a content bar; the only stated requirement is an owned account behind the launch"]', rw_gotchas='["The badge is not the price of the link but the gate on the form: the launch-date step will not open until their server finds the snippet, so it must be live before you can finish.","Pro at $9.99 once is the same launch without the badge requirement.","Launches are daily with a spot count per date, so a same-day slot is often available."]', rw_faq='[{"question":"How long does DanielLaunches approval take?","answer":"Same day; launches are daily with numbered slots."},{"question":"How much does it cost?","answer":"Free with two backlinks from the operator''s two directories. Pro is $9.99 once and removes the badge requirement; paid placement is extra."},{"question":"Does a listing provide a dofollow link?","answer":"Yes — two dofollow links, one from each of the operator''s sites, including one on a domain rated 52."},{"question":"Do I need to link back?","answer":"Yes on the free lane — the badge gates the launch-date step."},{"question":"What gets a listing rejected?","answer":"Nothing content-wise is published; an owned account behind the launch is required."}]', rw_summary='DanielLaunches is a daily launch board where one submission yields two dofollow links from the operator''s two directories. The free lane needs a badge; domain rating is 52.', rw_fact_points='["Two dofollow links per free launch","Badge required to unlock the launch-date step","Daily launches with a slot count","Accepts indie projects, SaaS, AI tools and marketing tools"]', rw_submission_checks='["Install the badge before you can pick a launch date.","Expect two links from one submission.","Pro at $9.99 removes the badge if you prefer."]', rw_seo_title='DanielLaunches: Free Dual-Link Launch, DR 52', rw_seo_description='How to launch on DanielLaunches: free dofollow launch with two backlinks from one submission, badge required. Steps from the 2026-11-16 snapshot.' WHERE slug='daniellaunches';
UPDATE submission_sites SET rw_source_lead='No upvotes, no comments, no launch day — a badge and you are listed.', rw_what_you_get='An instant dofollow listing with a direct link, with no voting or scheduling involved.', rw_you_need='["A URL, an email, a name, a tagline and one of fourteen categories","Their badge on your site, unless you pay $9"]', rw_eligibility='You need basic details and either the badge or payment. Anyone willing to do neither has no lane.', rw_submit_steps='["1 Open the form via the homepage Launch button. There is no account and no /submit page.","2 Fill six fields: website, email, product name, tagline, category and an optional X handle.","3 Pick a lane: free with the badge, $9 without it, or $59 for a featured slot.","4 Verify and publish. They hand over a light or dark 188x56 badge snippet; Verify and publish looks for it and puts the listing live immediately."]', rw_submit_requirements='["Their 188x56 SVG badge, light or dark","A one-line tagline","An email, required","One of fourteen categories"]', rw_rejection_reasons='["Anyone who will neither carry the badge nor pay, since those are the only two lanes"]', rw_gotchas='["There is no review or queue: the badge check is the whole gate and the listing is live the second it passes.","The homepage sells sponsor tiles from $1 and shows what each is held for, so the top is an auction rather than a ranking.","Nothing is stored before the badge step, so closing the tab means refilling the six fields."]', rw_faq='[{"question":"How long does EasyLaunch approval take?","answer":"Instant — the listing goes live the moment the badge check passes."},{"question":"How much does it cost?","answer":"Free with their badge, $9 once to skip it, or $59 for 30 days pinned on the homepage. All three give the same followed link."},{"question":"Does a listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 51."},{"question":"Do I need to link back?","answer":"Yes on the free lane — the badge is the only gate."},{"question":"What gets a listing rejected?","answer":"Refusing both the badge and payment."}]', rw_summary='EasyLaunch is an instant dofollow listing with no voting or launch date: install their badge for free or pay $9 to skip it. No other backlink is required; domain rating is 51.', rw_fact_points='["Listings publish instantly after badge check","Free lane gives the same dofollow link as paid","A badge or payment is required","Accepts SaaS, indie products, AI tools and developer tools"]', rw_submission_checks='["Install the badge for the free lane, or pay $9 to skip it.","Fill the six fields in one session — nothing is saved early.","Ignore the sponsor tiles unless you want promotion."]', rw_seo_title='EasyLaunch: Free Instant Listing, DR 51', rw_seo_description='How to submit to EasyLaunch: free instant dofollow listing with a badge, or $9 without. No vote or launch day — 2026-11-16 snapshot.' WHERE slug='easylaunch';
UPDATE submission_sites SET rw_source_lead='A weekly launch board whose free dofollow link is a podium prize — the top three get the winner badge and the link.', rw_what_you_get='A dofollow listing awarded to the top three products in a weekly launch, or instant featured placement on the paid tier.', rw_you_need='["An account via Google or an emailed link","Their badge on your site for the free lane","Enough votes to place in the top three, for the link"]', rw_eligibility='You need an account, and on the free lane a badge and community support. No content bar is published; the stated constraints are about the queue and badge, not the product.', rw_submit_steps='["1 Sign in. /login offers Continue with Google or an emailed link; the products area is /my-products.","2 Add your first product via the Add your first product control, which routes to /submit/product — a bare /submit is not the path.","3 Fill their form with a name, website, tagline, description, a logo, at least one screenshot, categories and a Submitted by name; an optional rating of the experience sits at the end.","4 Submit and wait for the week. The form confirms with Form submitted; launches are weekly and numbered with a homepage countdown."]', rw_submit_requirements='["An account","A live product URL","A logo and at least one screenshot","A name to be listed under","Enough votes to place top three for the link"]', rw_rejection_reasons='["Nothing published as a content bar; the stated constraints are about the queue and badge rather than the product"]', rw_gotchas='["The free link is a podium prize rather than a badge trade: their submit page says the top three get the Winner Badge and the backlink, so placing is the price.","There is no /submit page — it returns Page not found; the real route is /submit/product, reached from My products.","Launches are weekly and numbered with a countdown, so a free launch is a scheduled slot rather than a same-day listing."]', rw_faq='[{"question":"How long does Launch List approval take?","answer":"One to two weeks; launches run in numbered weekly cycles."},{"question":"How much does it cost?","answer":"Free through the community queue with a badge and support; $19 once for Featured with seven days above the ranking and instant publication. No subscription."},{"question":"Does a listing provide a dofollow link?","answer":"Yes, for the top three on free, or with Featured, on a domain rated 51."},{"question":"Do I need to link back?","answer":"No return link is required, though the free lane needs their badge."},{"question":"What gets a listing rejected?","answer":"No content bar is published; constraints are about the queue and badge."}]', rw_summary='Launch List is a weekly launch board where the free dofollow link goes to the top three products, with a badge and community support required. Featured is $19 for instant placement; domain rating is 51.', rw_fact_points='["Free dofollow link is awarded to the top three weekly","Listing is dofollow; no return link required","A badge is needed for the free queue","Accepts indie projects, SaaS, AI tools and marketing tools"]', rw_submission_checks='["Expect the free link to depend on placing top three.","Use /submit/product, not /submit.","Pay $19 if you want instant, guaranteed placement."]', rw_seo_title='Launch List: Weekly Dofollow Launch, DR 51', rw_seo_description='How to launch on Launch List: free weekly dofollow link for the top three, badge needed, or $19 featured. Steps from the 2026-11-16 snapshot.' WHERE slug='launch-list';
UPDATE submission_sites SET rw_source_lead='A gallery of nothing but website footers, where submission is five fields and the link out is dofollow.', rw_what_you_get='A dofollow listing as a featured footer example, curated by a small team.', rw_you_need='["A live, publicly hosted site","A name and a URL for whoever is submitting"]', rw_eligibility='You need a live public site and your own name and URL. Staging sites and unhosted sites are rejected.', rw_submit_steps='["1 Open the submit page. One form at /submit, no account; it is framed as nominating footers you admire, and submitting your own uses the same form.","2 Give the site and designer. Site URL is the only required field about the work; the designer''s name and their site or social are optional.","3 Identify yourself. Your name and your own website or social URL are both required, and the handle is what they tag when a submission is featured.","4 Clear the Turnstile and send. A Cloudflare check sits on the form; everything is curated after that with no reply and no feature guaranteed."]', rw_submit_requirements='["A site URL","Your name","Your website or social URL","An optional designer name and their URL"]', rw_rejection_reasons='["Staging sites and unhosted sites"]', rw_gotchas='["A Cloudflare Turnstile guards the form, so this is one you finish by hand however the rest are automated.","They say plainly they cannot guarantee a feature or a reply, and with no queue or status page a passed-over submission looks exactly like a waiting one.","The two required fields about you are your name and your own URL, so anonymous submission is not possible even when nominating somebody else''s work."]', rw_faq='[{"question":"How long does Footer approval take?","answer":"No review time is published; curation is manual with no status page."},{"question":"Is submitting to Footer free?","answer":"Yes, submission is free."},{"question":"Does a listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 50."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a site rejected?","answer":"Staging sites and unhosted sites."}]', rw_summary='Footer is a curated gallery of website footers with a free five-field submission and a dofollow link. No backlink is required; domain rating is 50 and features are not guaranteed.', rw_fact_points='["Manual curation with no published review time","Free submission with a dofollow link","No badge or return link is expected","Accepts website footers and design work"]', rw_submission_checks='["Use a live public site — staging is rejected.","Pass the Cloudflare check yourself.","Expect no acknowledgment; a feature is not guaranteed."]', rw_seo_title='Footer: Free Design Gallery, DR 50', rw_seo_description='How to submit to Footer: free dofollow footer-gallery listing, no backlink. Five fields and a Turnstile — 2026-11-16 snapshot.' WHERE slug='footer-design';
UPDATE submission_sites SET rw_source_lead='Free AI tools only, and your product has to have been live for three months.', rw_what_you_get='A dofollow listing in a curated free-tools index, after a hands-on test of your product.', rw_you_need='["A tool that is fully free, or freemium with enough daily credits for real use","A product operational and stable for at least three months","A reputable domain and a description of purpose, features, use cases and benefits"]', rw_eligibility='You need a genuinely usable free tool that has been live three months and a thorough description. Anything under three months, paid-only tools and adult, political or racially insensitive content are rejected.', rw_submit_steps='["1 Read the guidelines — unusually specific, last updated in May 2025.","2 Check the floors: free or freemium with real daily credits, three months operational, a reputable domain.","3 Submit and wait. They test and review each tool by hand against a queue they reported at 503 deep."]', rw_submit_requirements='["A description covering purpose, features, use cases and benefits","Proof the product has been operational for three months"]', rw_rejection_reasons='["Anything under three months old, which is an explicit floor; paid-only tools; adult, political or racially insensitive content"]', rw_gotchas='["The three-month age floor is a real disqualifier that almost nobody else in this directory has — a product launched last month is ineligible however good.","They reported a queue over 503 deep and hand-test each tool, so this is a months-long wait rather than a launch.","Freemium is accepted only if the free tier has enough daily credits to be genuinely usable — a judgement they make, not a box you tick."]', rw_faq='[{"question":"How long does ScriptByAI approval take?","answer":"Two to three months; they hand-test each tool against a long queue."},{"question":"Is submitting to ScriptByAI free?","answer":"Yes, submission is free."},{"question":"Does a listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 50."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a tool rejected?","answer":"Anything under three months old, paid-only tools, and adult, political or racially insensitive content."}]', rw_summary='ScriptByAI is a hand-tested index of free AI tools with a three-month age floor and a long queue. Listings are dofollow with no backlink requirement; domain rating is 50.', rw_fact_points='["Hand-tested review taking two to three months","Free listing carries a dofollow link","No badge or return link is expected","Free or freemium AI tools only, three months old"]', rw_submission_checks='["Confirm your tool is at least three months old.","Ensure the free tier is genuinely usable daily.","Write a description covering purpose, features, use cases and benefits."]', rw_seo_title='ScriptByAI: Free AI Tool Listing, DR 50', rw_seo_description='How to submit to ScriptByAI: free dofollow listing for free AI tools, three-month age floor and hand review. Rules from the 2026-11-16 snapshot.' WHERE slug='scriptbyai';
UPDATE submission_sites SET rw_source_lead='A 200-tool developer and entrepreneur directory gated on DR 30, giving accepted listings a genuine dofollow link.', rw_what_you_get='A dofollow listing in a curated developer-tools directory, for sites with either DR 30 or 1,000 monthly visitors.', rw_you_need='["Ahrefs DR 30 or higher, or 1,000+ monthly visitors instead","A live product URL","A contact email"]', rw_eligibility='You need to clear the DR 30 floor or show 1,000 monthly visitors, plus a live URL and email. Tools clearing neither threshold are rejected.', rw_submit_steps='["1 Read the floor. The submit page opens with the requirements — DR 30 or 1,000+ monthly visitors — with affiliate offers for DR-raising services beneath.","2 Sign in first, though the page never asks. The form renders signed out, but sign in at the auth page by Google or magic link so the submission attaches to an account you can see.","3 Fill five fields: website URL, product name, your name, your email and an optional note. No logo, screenshot, category or description beyond the note.","4 Submit and watch the dashboard. There is no confirmation screen; the only evidence is a new row on your dashboard listing your tools."]', rw_submit_requirements='["A live website URL","A product name","Your name","A contact email","An optional note describing the tool"]', rw_rejection_reasons='["Tools that clear neither the DR 30 floor nor the 1,000-visitor one"]', rw_gotchas='["The form has no category field, so which of eighteen categories the listing lands in is their choice, not yours.","The requirements box says the URL field will tell you whether you clear DR 30, but nothing checks as you type — the verdict arrives only with review.","The newsletter opt-in below the note is ticked on load, so a submission subscribes you unless you notice."]', rw_faq='[{"question":"How long does Awesome Tools approval take?","answer":"No review time is published."},{"question":"Is submitting to Awesome Tools free?","answer":"Yes, submission is free."},{"question":"Does a listing provide a dofollow link?","answer":"Yes, a genuine dofollow link on a domain rated 43."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a tool rejected?","answer":"Clearing neither DR 30 nor 1,000 monthly visitors."}]', rw_summary='Awesome Tools is a curated developer directory with a dofollow listing and no backlink requirement, gated on DR 30 or 1,000 visitors. Domain rating is 43.', rw_fact_points='["Gated on DR 30 or 1,000 monthly visitors","Listing is dofollow with no backlink","No badge or return link is expected","Accepts developer, AI, SaaS, marketing, SEO and no-code tools"]', rw_submission_checks='["Check you clear DR 30 or 1,000 visitors before applying.","Sign in first so the submission is attached to your account.","Untick the pre-checked newsletter opt-in if unwanted."]', rw_seo_title='Awesome Tools: Free Dofollow Listing, DR 43', rw_seo_description='How to submit to Awesome Tools: free dofollow developer listing gated on DR 30 or 1,000 visitors, no backlink. Steps from the 2026-11-16 snapshot.' WHERE slug='awesome-tools';
UPDATE submission_sites SET rw_source_lead='Three fields and no account, and the submit button opens a pull request on their repository.', rw_what_you_get='A dofollow listing published by merging a pull request you open against their public repository.', rw_you_need='["Something a developer can use for free — the whole premise","A GitHub account, since the form ends in a pull request","Tags from their controlled list"]', rw_eligibility='You need a genuinely free developer resource, a GitHub account and tags from their list. Anything with no free tier at all is rejected.', rw_submit_steps='["1 Fill three fields: the link, a comma-separated tag list and a short answer to What is free. No account or sign-in on their side.","2 Submit. The button hands you to GitHub with a new Markdown file already written, its frontmatter filled with a title, thumbnail and snippet pulled from your page.","3 Open the pull request by committing the file. The maintainer merges it, and the repository shows the queue length."]', rw_submit_requirements='["An HTTP or HTTPS link","Comma-separated tags from their list","A few lines on what is free","A GitHub account the pull request is opened under"]', rw_rejection_reasons='["Anything with no free tier at all, since the site exists to list what is free for developers"]', rw_gotchas='["The listing is a pull request against a public repository, so the signed-in GitHub account is named publicly on it.","The repository carries hundreds of open pull requests — the real review queue, visible before you submit.","They generate the file''s title, thumbnail and snippet from your page rather than what you typed, so read the frontmatter before committing.","The premise is things free for developers, so a product whose free tier is only a trial is the wrong shape whatever the tags say."]', rw_faq='[{"question":"How long does Free Stuff for Developer approval take?","answer":"No review time is published; the public pull-request queue shows the backlog."},{"question":"Is submitting free?","answer":"Yes, submission is free via a GitHub pull request."},{"question":"Does a listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 41."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Anything with no free tier for developers."}]', rw_summary='Free Stuff for Developer is a repository-based directory where a three-field form opens a pull request for a dofollow listing. No backlink is required; domain rating is 41.', rw_fact_points='["Listing published by merging a GitHub pull request","Free submission with a dofollow link","No badge or return link is expected","Accepts developer tools, SaaS and indie products"]', rw_submission_checks='["Use a GitHub account you are comfortable being named publicly.","Review the auto-generated frontmatter before committing.","Make sure the free tier is real, not just a trial."]', rw_seo_title='Free Stuff for Developer: Free Listing, DR 41', rw_seo_description='How to submit to Free Stuff for Developer: free dofollow listing via a GitHub pull request, no backlink. Process from the 2026-11-16 snapshot.' WHERE slug='freestuffdev';
UPDATE submission_sites SET rw_source_lead='Product Hunt on the Steem blockchain: a dofollow link guarded by a private key and rewards that have collapsed to almost nothing.', rw_what_you_get='A dofollow product listing in a blockchain-based hunt ranking, with STEEM rewards tied to upvotes.', rw_you_need='["A Steem blockchain account","Your Steem private posting key, typed into their web form","A product not already hunted by someone else"]', rw_eligibility='You need a Steem account, its posting key and an unhunted product. Products already posted by another hunter and anything outside apps, software or gadgets are rejected.', rw_submit_steps='["1 Get a Steem account first. There is no signup on the site itself; you register a blockchain account elsewhere with its own key custody.","2 Sign in with a posting key. The sign-in asks for a Steem username and posting key, stored in your browser until logout — no OAuth, email link or password-only option.","3 Post the hunt on the form behind that login. A published hunt shows a name, tagline, an outbound CHECK IT OUT link, images and a description.","4 Compete for the day. Your hunt joins the Korean-time day''s ranking by Hunt Score and earns STEEM from upvotes before midnight KST."]', rw_submit_requirements='["A Steem account and its private posting key","A product name and one-line tagline","The product URL","A product description"]', rw_rejection_reasons='["Products already posted by another hunter, and anything outside apps, software and gadgets"]', rw_gotchas='["Signing in means typing a Steem private posting key into a web form — no OAuth, no email link, no way to post without handing over the key.","The crypto reward is the whole pitch and has collapsed: the site advertises a $1.44 average per hunt, and on one day all 33 products generated $0.02 between them.","Anyone can hunt any product, so a stranger may already have posted yours, written its description and taken the reward — a duplicate cannot be posted over it."]', rw_faq='[{"question":"How long does Steemhunt approval take?","answer":"Same day; hunts rank within the current Korean-time day."},{"question":"Is submitting to Steemhunt free?","answer":"Yes, though crypto rewards are now negligible."},{"question":"Does a listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 37."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a hunt rejected?","answer":"Products already posted by another hunter, or anything outside apps, software and gadgets."}]', rw_summary='Steemhunt is a blockchain-based product hunt with a dofollow link and no backlink requirement, but it requires typing a Steem private posting key into a web form. Rewards are now negligible; domain rating is 37.', rw_fact_points='["Hunts publish the same day and rank by upvotes","Listing is dofollow with no backlink","A Steem posting key is required to post","Accepts SaaS, developer tools, hardware and indie projects"]', rw_submission_checks='["Get a Steem account before starting — there is no signup here.","Be aware you must type a private posting key into the form.","Check whether a stranger has already hunted your product."]', rw_seo_title='Steemhunt: Free Blockchain Hunt, DR 37', rw_seo_description='How to submit to Steemhunt: free dofollow product hunt on Steem, no backlink, posting key required. Process and caveats from the 2026-11-16 snapshot.' WHERE slug='steemhunt';
UPDATE submission_sites SET rw_source_lead='A juried design award at 65 euros a shot, scored by eighteen judges on design, usability, creativity and content, with no free lane.', rw_what_you_get='A juried score and a Site of the Day distinction for outstanding design, with the site name and screenshot linking dofollow.', rw_you_need='["65 euros per site, or a 150 euro annual Pro membership","A site that can survive a design jury — design is 40% of the score, usability 30%, creativity 20%, content 10%","An account"]', rw_eligibility='You need to pay and submit a site strong enough to face a jury. A functional product with an ordinary site will be scored poorly against ambitious work, and there is no free route.', rw_submit_steps='["1 Decide whether the work can win. The published criteria are design 40%, usability 30%, creativity 20%, content 10% — this is a jury, not a directory, and the fee is spent whatever the score.","2 Pick a lane and pay. Standard Submission is 65 euros for one site; Pro at 150 euros a year includes one free submission and 30% off the rest.","3 Submit and wait for approval. Submissions are approved before scoring, and only approved sites go to the jury.","4 Sit through five days of voting. An approved site goes to at least 18 jury members, the three scores furthest from the average are discarded, and voting runs five days — though a high jury score plus ten Pro users can produce a Site of the Day sooner."]', rw_submit_requirements='["An account","65 euros per submission or a 150 euro annual Pro membership","A live site, which is what is judged","Credits for the people who made it"]', rw_rejection_reasons='["A functional product with an ordinary site, scored against the most ambitious work on the web; and anyone unwilling to pay, since there is no free route"]', rw_gotchas='["There is no free submission of any kind — every route to the jury is 65 euros a shot or a 150 euro membership, and the money buys a score, not a listing.","Approval comes before scoring, so a submission can be rejected outright and never reach the jury.","The jury weighting is public and is not about your product: design is 40% and content 10%, so a site that works well but looks ordinary is buying a low score.","The links are not uniform: the site name and screenshot are dofollow, while the Visit Site button a reader would click carries rel=nofollow."]', rw_faq='[{"question":"How long does Awwwards approval take?","answer":"Three to five days; jury voting runs five days for approved sites."},{"question":"How much does it cost?","answer":"65 euros per Standard Submission, or 150 euros a year for Pro with one free submission and discounts."},{"question":"Does an Awwwards listing provide a dofollow link?","answer":"The site name and screenshot links are dofollow on a domain rated 89, while the Visit Site button is nofollow."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"An ordinary site scored against the best on the web, or unwillingness to pay — there is no free lane."}]', rw_summary='Awwwards is a juried design award at 65 euros a shot with no free lane, scoring design, usability, creativity and content. The name and screenshot links are dofollow on a domain rated 89; no backlink is required.', rw_fact_points='["Juried scoring over five days, paid-only from 65 euros","Name and screenshot links are dofollow; Visit Site is nofollow","No badge or return link is expected","For design work, marketing sites, web apps and design tools"]', rw_submission_checks='["Expect to pay — there is no free submission.","Be judged on design first; an ordinary-looking site scores low.","Approval can fail before the jury sees your site."]', rw_seo_title='Awwwards: Juried Design Award, DR 89', rw_seo_description='How to submit to Awwwards: paid 65-euro juried design award, no backlink. Name and screenshot links dofollow, Visit Site nofollow — 2026-11-16 snapshot.' WHERE slug='awwwards';
UPDATE submission_sites SET rw_source_lead='Pre-revenue or completely free products only, published the moment you submit with a dofollow link and no queue.', rw_what_you_get='An instant dofollow listing for a product that charges nothing, with no review wait.', rw_you_need='["A product generating no revenue in any form","Full usability without payment or a credit card","An account via Google or email and password","At least two screenshots"]', rw_eligibility='You need a genuinely free product, an account and two screenshots. Freemium, free credits and trials paired with paid options are all ruled out as not free, as is anything needing a card for core features.', rw_submit_steps='["1 Sign in with Google or email and password at the auth page; /submit redirects there with a next parameter.","2 Basics: an icon, a name up to 60 characters, a tagline up to 100, a description up to 2,000, and a required choice between I built this and I am curating someone else''s project.","3 Details: one to three categories from eighteen, at least one platform, up to nine tags and supported languages.","4 Links and screenshots: website, GitHub, app stores, X and LinkedIn, then at least two and up to eight screenshots.","5 Submit. The page publishes immediately with a Vibe published link to the live page and an optional badge snippet."]', rw_submit_requirements='["An account via Google or email and password","An icon in PNG, JPG, WebP or SVG under 1MB","A name, tagline and description within limits","One to three categories and at least one platform","At least two screenshots up to eight","An optional badge for extra visibility"]', rw_rejection_reasons='["Freemium models, free credits and trials paired with paid options — all named as not free — and anything requiring a card for core features"]', rw_gotchas='["The eligibility rule is strict and specific: no revenue in any form, fully usable without payment, no card for core features.","There is no review queue — the listing goes live the moment you submit, so get the copy right before pressing the button.","The audience rates and follows rather than one-off upvoting, and the site carries a forum and blog, so the listing is meant to be discussed."]', rw_faq='[{"question":"How long does LeanVibe approval take?","answer":"Instant — the listing publishes the moment you submit."},{"question":"Is submitting to LeanVibe free?","answer":"Yes, submission is free."},{"question":"Does a listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 29."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a product rejected?","answer":"Freemium, free credits, trials with paid options, or anything needing a card for core features."}]', rw_summary='LeanVibe is an instant dofollow directory for fully free, pre-revenue products with no queue. No backlink is required; domain rating is 29 and freemium models are excluded.', rw_fact_points='["Listings publish instantly with no review","Free submission with a dofollow link","No badge or return link is expected","Accepts free indie products, SaaS, AI tools and developer tools"]', rw_submission_checks='["Ensure your product charges nothing and needs no card.","Prepare at least two screenshots.","Get the copy right before submitting — there is no review."]', rw_seo_title='LeanVibe: Free Instant Listing, DR 29', rw_seo_description='How to submit to LeanVibe: free instant dofollow listing for fully free products, no backlink. Strict eligibility and steps from the 2026-11-16 snapshot.' WHERE slug='leanvibe';
UPDATE submission_sites SET rw_source_lead='One of ten sites on a shared engine, where the follow survives the copy-paste.', rw_what_you_get='A dofollow listing behind a Google login, after filling a form whose fields are hidden until you sign in.', rw_you_need='["A live public URL","A Google account — the only sign-in offered"]', rw_eligibility='You need a live URL and a Google account. Nothing is published about who is refused.', rw_submit_steps='["1 Open the submit page. /submit shows a Log in to Submit panel instead of a form.","2 Log in with Google — the only provider, alongside a Create an account link.","3 Fill the listing form, which sits behind the login so its fields cannot be read in advance.","4 Wait. No review time is published anywhere on the site."]', rw_submit_requirements='["A live public URL","A Google account","A category from their tree"]', rw_rejection_reasons='["Nothing published about who is refused"]', rw_gotchas='["The submit page shows only a login panel, so there is no way to see what the form asks before committing an account.","Every page carries a sponsored ad for a paid service that submits to roughly 140 directories — a rival to doing it yourself, marked sponsored nofollow.","Ten sites share this exact codebase and copy, differing only in name and accent colour, so a run across them buys far less reach than the count suggests."]', rw_faq='[{"question":"How long does SaaS Branch approval take?","answer":"No review time is published."},{"question":"Is submitting to SaaS Branch free?","answer":"Yes, submission is free."},{"question":"Does a listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 27."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Nothing published about who is refused."}]', rw_summary='SaaS Branch is a free SaaS directory on a shared ten-site engine, with a dofollow listing and no backlink. The form is behind a Google login and no review time is published; domain rating is 27.', rw_fact_points='["Free dofollow listing with no backlink","Form hidden behind a Google login","No published review time","Accepts SaaS, AI tools, developer tools and web apps"]', rw_submission_checks='["Expect to sign in with Google before seeing the form.","No review timeline to plan around.","Ten sister sites share the same engine, so reach overlaps heavily."]', rw_seo_title='SaaS Branch: Free Dofollow Listing, DR 27', rw_seo_description='How to submit to SaaS Branch: free dofollow SaaS listing behind a Google login, no backlink. Shared-engine caveat from the 2026-11-16 snapshot.' WHERE slug='saas-branch';
