ed."]', rw_seo_title='AIToolex: Free Dofollow AI Listing, DR 26', rw_seo_description='How to submit to AIToolex: free dofollow AI listing behind a Google or GitHub login, no backlink. Steps from the 2026-11-16 snapshot.' WHERE slug='aitoolex';
UPDATE submission_sites SET rw_source_lead='Another of the ten, sold on connection rather than discovery, with a dofollow link behind a login.', rw_what_you_get='A dofollow listing available after signing in with Google, on a site pitched at connection over discovery.', rw_you_need='["A live public URL","A Google account — the only sign-in offered"]', rw_eligibility='You need a live URL and a Google account. Nothing is published about who is refused.', rw_submit_steps='["1 Open the submit page. /submit renders a Log in to Submit panel, not a form.","2 Log in with Google — the only provider, alongside a Create an account link.","3 Fill the listing form behind the login; its fields cannot be read in advance.","4 Wait. No review time is published anywhere on the site."]', rw_submit_requirements='["A live public URL","A Google account","A category from their tree"]', rw_rejection_reasons='["Nothing published about who is refused"]', rw_gotchas='["Only a login panel appears at the submit route, so the form stays invisible until you commit an account.","Every page carries a sponsored ad for a service that submits to roughly 140 directories — a competitor marked sponsored nofollow.","Ten sites share the same code and copy, changing only the name and accent colour, so a run across them delivers far less unique reach than the count suggests."]', rw_faq='[{"question":"How long does SaaS Networker approval take?","answer":"No review time is published."},{"question":"Is submitting to SaaS Networker free?","answer":"Yes, submission is free."},{"question":"Does a listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 26."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Nothing published about who is refused."}]', rw_summary='SaaS Networker is a free dofollow SaaS directory on a shared ten-site engine, with the form behind a Google login. No backlink or review timeline; domain rating is 26.', rw_fact_points='["Free dofollow listing with no backlink","Google login gates the form","No published review time","Accepts SaaS, AI tools, developer tools and web apps"]', rw_submission_checks='["Sign in with Google to reach the form.","Expect no published review timeline.","Reach overlaps with nine sister sites on the same engine."]', rw_seo_title='SaaS Networker: Free Dofollow Listing, DR 26', rw_seo_description='How to submit to SaaS Networker: free dofollow SaaS listing behind a Google login, no backlink. Shared-engine caveat from the 2026-11-16 snapshot.' WHERE slug='saas-networker';
UPDATE submission_sites SET rw_source_lead='Same engine, different paint, and the same Google-only way in.', rw_what_you_get='A dofollow listing available after a Google login, on one of ten identically built directories.', rw_you_need='["A live public URL","A Google account — the only sign-in offered"]', rw_eligibility='You need a live URL and a Google account. Nothing is published about who is refused.', rw_submit_steps='["1 Open the submit page. /submit shows a Log in to Submit panel rather than the form.","2 Log in with Google — the sole provider, with a Create an account link.","3 Complete the listing form, which only appears after login.","4 Wait. No review time is published anywhere on the site."]', rw_submit_requirements='["A live public URL","A Google account","A category from their tree"]', rw_rejection_reasons='["Nothing published about who is refused"]', rw_gotchas='["The submit route reveals only a login panel, so the form''s fields cannot be checked before signing in.","Every page carries a sponsored ad for a paid service that submits to around 140 directories, a rival marked sponsored nofollow.","Ten sites share this exact codebase and copy, differing only in name and accent colour, so submitting across them buys far less unique reach than the count implies."]', rw_faq='[{"question":"How long does SaaS Territory approval take?","answer":"No review time is published."},{"question":"Is submitting to SaaS Territory free?","answer":"Yes, submission is free."},{"question":"Does a listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 26."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Nothing published about who is refused."}]', rw_summary='SaaS Territory is a free dofollow SaaS directory on a shared ten-site engine, gated behind a Google login. No backlink or published review time; domain rating is 26.', rw_fact_points='["Free dofollow listing with no backlink","Google login gates the form","No published review time","Accepts SaaS, AI tools, developer tools and web apps"]', rw_submission_checks='["Sign in with Google before the form appears.","Expect no published review timeline.","Reach overlaps with nine sister sites on the same engine."]', rw_seo_title='SaaS Territory: Free Dofollow Listing, DR 26', rw_seo_description='How to submit to SaaS Territory: free dofollow SaaS listing behind a Google login, no backlink. Shared-engine caveat from the 2026-11-16 snapshot.' WHERE slug='saas-territory';
UPDATE submission_sites SET rw_source_lead='A marketplace of deal-hunting buyers, where real revenue buys real exposure on your terms.', rw_what_you_get='A dofollow listing on a deal marketplace that reaches buyers actively looking for lifetime software offers, in exchange for a revenue share.', rw_you_need='["A finished product with real customers","A willingness to sell lifetime deals","An accepted partner application"]', rw_eligibility='You need a product with customers and a lifetime deal you can afford. Pre-revenue products and anything that cannot support lifetime pricing economically are rejected.', rw_submit_steps='["1 Apply, do not submit. The partner site is a vendor application, not a listing form; there is no upfront fee and they take a revenue share.","2 Design the lifetime tiers, usually three with escalating limits, priced so a one-time payment still covers years of serving that user.","3 Negotiate the terms — the revenue share, the length of the deal window and whether the same deal can run elsewhere.","4 Staff support before launch: write the docs, clear the inbox and set roadmap expectations in the listing."]', rw_submit_requirements='["A finished product with customers","A lifetime deal structure you can afford","Support capacity for a spike","Business metrics such as MRR, customers and churn"]', rw_rejection_reasons='["Pre-revenue products with no customers, and anything that cannot support lifetime pricing economically"]', rw_gotchas='["This is a partner application with a review cycle and quarterly opening windows, not a directory submission.","There is no upfront fee, but the revenue share and lifetime discount are the real price, and both are permanent.","Lifetime buyers are the loudest reviewers and the least profitable users — price for that.","Refund windows are generous, so first-week gross revenue is not revenue yet."]', rw_faq='[{"question":"How long does AppSumo approval take?","answer":"One to two months; applications open by quarter and include a review cycle."},{"question":"How much does it cost?","answer":"No upfront fee — they take a revenue share instead."},{"question":"Does an AppSumo listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 83."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets an application rejected?","answer":"Pre-revenue products with no customers, or anything that cannot sustain lifetime pricing."}]', rw_summary='AppSumo is a lifetime-deal marketplace where a dofollow listing comes through a partner application and revenue share, not a listing fee. No backlink is required; domain rating is 83.', rw_fact_points='["Partner application with a quarterly review cycle","Dofollow listing with no backlink","Revenue share replaces an upfront fee","Accepts established SaaS with real customers"]', rw_submission_checks='["Expect an application and review, not instant publication.","Price lifetime tiers to sustain years of support.","Prepare metrics and support capacity before applying."]', rw_seo_title='AppSumo: Lifetime Deal Listing, DR 83', rw_seo_description='How to get listed on AppSumo: partner application with revenue share, dofollow link, no backlink. Pricing and fit from the 2026-11-16 snapshot.' WHERE slug='appsumo';
UPDATE submission_sites SET rw_source_lead='Scans the market, and asks you to sign in before it scans yours.', rw_what_you_get='A dofollow listing available after a Google login, on one of ten identically built directories.', rw_you_need='["A live public URL","A Google account — the only sign-in offered"]', rw_eligibility='You need a live URL and a Google account. Nothing is published about who is refused.', rw_submit_steps='["1 Open the submit page. /submit renders a Log in to Submit panel rather than a form.","2 Log in with Google — the only provider, alongside a Create an account link.","3 Fill the listing form behind the login; its fields cannot be read in advance.","4 Wait. No review time is published anywhere on the site."]', rw_submit_requirements='["A live public URL","A Google account","A category from their tree"]', rw_rejection_reasons='["Nothing published about who is refused"]', rw_gotchas='["The submit page shows only a login panel, so the form stays invisible until you commit an account.","Every page carries a sponsored ad for a service that submits to about 140 directories — a competitor marked sponsored nofollow.","Ten sites share the same code and copy, changing only the name and accent colour, so a run across them buys far less unique reach than the count suggests."]', rw_faq='[{"question":"How long does SaaS Scanner approval take?","answer":"No review time is published."},{"question":"Is submitting to SaaS Scanner free?","answer":"Yes, submission is free."},{"question":"Does a listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 24."},{"question":"Do I need to link back?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Nothing published about who is refused."}]', rw_summary='SaaS Scanner is a free dofollow SaaS directory on a shared ten-site engine, with the form behind a Google login. No backlink or review timeline; domain rating is 24.', rw_fact_points='["Free dofollow listing with no backlink","Google login gates the form","No published review time","Accepts SaaS, AI tools, developer tools and web apps"]', rw_submission_checks='["Sign in with Google to reach the form.","Expect no published review timeline.","Reach overlaps with nine sister sites on the same engine."]', rw_seo_title='SaaS Scanner: Free Dofollow Listing, DR 24', rw_seo_description='How to submit to SaaS Scanner: free dofollow SaaS listing behind a Google login, no backlink. Shared-engine caveat from the 2026-11-16 snapshot.' WHERE slug='saas-scanner';
UPDATE submission_sites SET rw_source_lead='An old-fashioned social bookmarking site where a free account earns an instant, genuinely followed story page — with a captcha as the only toll.', rw_what_you_get='A story page in a classic bookmarking feed with a followed outbound link, appearing within a minute of submitting despite the review wording.', rw_you_need='["A member account with a username, email and password","A live URL to submit","A person to solve the image captcha"]', rw_eligibility='You need a member account, a live URL and someone to solve an image captcha. Products already posted by another member are refused as duplicates.', rw_submit_steps='["1 Create an account at /user/sign-in/signup — /register and /signup both return 404. It is a plain form asking for a username, email and password twice; the username becomes your public byline.","2 Paste the URL at /story/submit. One URL field validates live, then their scraper pulls the page title and meta description.","3 Rewrite what the scraper filled in. The guidelines ask you to explain what the thing is and why it is worth a look.","4 Choose one of 16 real categories. The default ''all'' is not a real one and buries the story.","5 Solve the distorted-word captcha and submit. It says the story is queued for review, but it appears on /story/all right away."]', rw_submit_requirements='["A member account","A live URL","A story title and description","One of 16 categories","An image captcha solved by hand"]', rw_rejection_reasons='["Duplicate submissions of a URL someone has already posted"]', rw_gotchas='["Sign-up is at /user/sign-in/signup; the obvious paths all 404, making the site look closed to new members.","An image captcha guards the final submit, so a person has to be present however much of the form is automated.","Their scraper pulled a page title with a double-escaped &amp; into the field, which would publish literally — always read the prefilled title.","The category defaults to ''all'', which is not a real category; pick one of the 16.","It says submitted for review but the story is live within a minute, so treat the wording as boilerplate."]', rw_faq='[{"question":"How long does CoolPot approval take?","answer":"Listings go live instantly."},{"question":"How much does it cost to submit to CoolPot?","answer":"Submitting is free."},{"question":"Does CoolPot provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 22."},{"question":"Do I need to link back to CoolPot?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Duplicate submissions of a URL someone has already posted."}]', rw_summary='CoolPot is an old-style social bookmarking site where a free account earns an instant followed story page. No backlink is required and the domain rating is 22; an image captcha guards the final step.', rw_fact_points='["Story pages go live instantly","Submission is free and carries a dofollow link","No badge or return link is expected","Accepts websites, SaaS products, articles and startups"]', rw_submission_checks='["Sign up at the specific /user/sign-in/signup path.","Rewrite the scraped title and description before submitting.","Pick a real category, not the ''all'' default.","Have a person ready for the image captcha."]', rw_seo_title='CoolPot: Free Dofollow Story, DR 22', rw_seo_description='How to submit to CoolPot: free instant dofollow bookmark story, no backlink. Captcha and signup path from the 2026-11-16 snapshot.' WHERE slug='coolpot';
UPDATE submission_sites SET rw_source_lead='77 hand-picked developer tools, no paid placement and no account — one screen of fields and a human who emails you either way.', rw_what_you_get='A spot among 77 engineering tools with a followed link and a weekly-synced GitHub star count, decided by a person rather than a fee.', rw_you_need='["A genuinely useful developer tool","Documentation and active maintenance","One of 11 engineering categories","A contact email"]', rw_eligibility='You need a useful developer tool with documentation and active upkeep that fits one of 11 engineering categories. Anything outside engineering and abandoned or undocumented projects are refused.', rw_submit_steps='["1 Check you belong. The 11 categories are Generative AI, AI/ML, DevOps, Cloud, Observability, APIs, Frameworks, Databases, Security, Finance Tools and Learning Platforms. If none is honestly yours, stop.","2 Fill the one-screen form: name, description, website, category, pricing, optional GitHub URL, comma-separated tags and your email. No account, upload or images.","3 Submit for review. The button stays disabled until every required field is filled.","4 Wait for the verdict. A human reads each submission and emails either way; allow a few days."]', rw_submit_requirements='["A tool name and description","A website URL","One of 11 engineering categories","Pricing of Free, Freemium, Paid or Open Source","A contact email","An optional GitHub URL and tags"]', rw_rejection_reasons='["Anything that is not a developer tool, since all 77 entries are engineering, and abandoned or undocumented projects"]', rw_gotchas='["This is a developer-tools catalogue, not a general launch board; a marketing or consumer product has nowhere honest to file itself.","It is hand-curated with no paid lane, so the only lever is whether a person judges the tool useful, documented and maintained.","Listings show a GitHub star count synced weekly, so a closed-source tool sits beside projects with millions of stars."]', rw_faq='[{"question":"How long does DevPages approval take?","answer":"Three to five days; a human reviews each submission."},{"question":"How much does it cost to submit to DevPages?","answer":"Submitting is free, with no paid placement."},{"question":"Does DevPages provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 22."},{"question":"Do I need to link back to DevPages?","answer":"No backlink is required."},{"question":"What gets a tool rejected?","answer":"Anything that is not a developer tool, or abandoned or undocumented projects."}]', rw_summary='DevPages is a hand-curated catalogue of 77 developer tools with a free dofollow listing and no backlink requirement. A human reviews each submission in three to five days; domain rating is 22.', rw_fact_points='["Human review takes three to five days","Free listing with a dofollow link","No badge or return link is expected","Accepts developer tools, AI/ML, DevOps, APIs, databases and frameworks"]', rw_submission_checks='["Fit one of the 11 engineering categories honestly.","Have documentation and show active maintenance.","Expect a human verdict by email."]', rw_seo_title='DevPages: Free Dev Tool Listing, DR 22', rw_seo_description='How to submit to DevPages: free dofollow listing in a hand-curated 77-tool catalogue, no backlink. Eligibility and steps from the 2026-11-16 snapshot.' WHERE slug='devpages';
UPDATE submission_sites SET rw_source_lead='A directory-of-directories with a Product Hunt alternatives shelf, free and followed, doubling as the demo for a template that is for sale.', rw_what_you_get='A dofollow listing filed under one of six categories, created through a modal and held under review with no stated date.', rw_you_need='["A live, working product","An account via magic link, Google or GitHub","A logo already hosted at a public URL"]', rw_eligibility='You need a live product, an account and a publicly hosted logo URL. Nothing is published as a rejection rule beyond the six available categories.', rw_submit_steps='["1 Sign in first. Submit in the nav goes to /my-products, which needs an account; a magic link, Google or GitHub all work.","2 Open the dialog behind Add directory. There is no form on the page — only a Your Products List heading and the button that opens a modal.","3 Fill eight fields: name, logo URL, tagline, website, an optional affiliate URL, one of six categories, comma-separated tags and a pricing radio of Free, One-time fee or Subscription.","4 Press Create. The card appears immediately with an under-review badge and a promise of notification, but no review time is given."]', rw_submit_requirements='["An account via magic link, Google or GitHub","A product name and website URL","A logo hosted at a public URL","A tagline","One of six categories","A pricing answer","Optional tags and affiliate URL"]', rw_rejection_reasons='["Nothing stated beyond the six categories on offer"]', rw_gotchas='["The logo field takes a URL rather than a file, so it has to be hosted publicly before you start.","No review time is stated anywhere; the listing sits under review with a notification promise and no date.","The submit control and the form are in different places — nav Submit only reaches an empty products page, and the real form is a modal behind Add directory."]', rw_faq='[{"question":"How long does Indie Directory approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to Indie Directory?","answer":"Submitting is free."},{"question":"Does Indie Directory provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 22."},{"question":"Do I need to link back to Indie Directory?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Nothing stated beyond the six categories available."}]', rw_summary='Indie Directory is a free directory-of-directories with a dofollow listing and no backlink. The form sits behind an account and a modal, and no review time is published; domain rating is 22.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","Accepts directories, indie products, boilerplates, dev tools, AI tools and PH alternatives"]', rw_submission_checks='["Host your logo publicly before starting.","Find the form in the Add directory modal, not the nav.","Expect no stated review date."]', rw_seo_title='Indie Directory: Free Dofollow Listing, DR 22', rw_seo_description='How to submit to Indie Directory: free dofollow listing via a modal, no backlink, no published review time. Steps from the 2026-11-16 snapshot.' WHERE slug='indie-directory';
UPDATE submission_sites SET rw_source_lead='Sixty-nine dollars buys a permanent featured listing and a followed link on this design and WordPress blog with an AI section.', rw_what_you_get='A permanent featured product listing with homepage and category placement and a followed link, on an older design-and-WordPress audience.', rw_you_need='["A live product URL","A one-off $69 payment — there is no free lane"]', rw_eligibility='You need a live URL and to pay $69. Anyone not paying is excluded, since the single listing option is paid.', rw_submit_steps='["1 Pick the listing. There is one option: a single featured product listing at $69.","2 Pay once. They describe the listing as permanent, with homepage and category placement included.","3 Wait. No review window is published."]', rw_submit_requirements='["A one-off $69 payment","A live product URL"]', rw_rejection_reasons='["Anyone not paying, since there is no free lane"]', rw_gotchas='["There is exactly one option and it is paid, so nothing on the page is free.","It is a design and WordPress blog that added an AI section, so the audience is broader and older than a dedicated AI directory.","They advertise their own authority in the navigation — a marketing claim rather than a measurement you can check on the page."]', rw_faq='[{"question":"How long does Dessign approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to Dessign?","answer":"A one-off $69, struck through from $129, for a permanent featured listing with homepage and category placement."},{"question":"Does Dessign provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 79."},{"question":"Do I need to link back to Dessign?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Anyone not paying — there is no free lane."}]', rw_summary='Dessign is a design and WordPress blog with an AI section offering a single permanent $69 featured listing and a dofollow link. No backlink is required; domain rating is 79.', rw_fact_points='["Paid-only at $69 for a permanent listing","Listing is dofollow with no backlink","No badge or return link is expected","Accepts AI tools, design tools and SaaS products"]', rw_submission_checks='["Expect to pay — there is no free lane.","Have a live product URL ready.","No review timeline to plan around."]', rw_seo_title='Dessign: $69 Featured Listing, DR 79', rw_seo_description='How to submit to Dessign: $69 one-off permanent featured listing, dofollow link, no backlink. Scope and steps from the 2026-11-16 snapshot.' WHERE slug='dessign';
UPDATE submission_sites SET rw_source_lead='A Forem community for prompt engineering where you publish an article, and links inside it are followed.', rw_what_you_get='A dofollow link inside a published article on a prompt-engineering community, if the piece is worth reading to people who study model behaviour.', rw_you_need='["An account","An article worth reading — there is no product form"]', rw_eligibility='You need an account and something substantive to write. There is no submission form, so a product with nothing to say has nowhere to go.', rw_submit_steps='["1 Create an account. The flow is the Forem one used by dev.to.","2 Write a post in markdown with tags; links in the body are dofollow.","3 Publish. It goes live at once to the prompt-engineering audience."]', rw_submit_requirements='["An account","An article, not a listing","Tags for the post"]', rw_rejection_reasons='["There is no submission form at all, so a product with nothing to write about has nothing to do here"]', rw_gotchas='["This is a publication, not a directory — the only way in is writing something people want to read.","The audience is prompt engineering and model behaviour; a disguised advert will land badly with exactly the readers you wanted.","Their front page says every prompt is run in a sandbox against its target model and shown with its output, so an untested prompt post looks out of place."]', rw_faq='[{"question":"How long does PromptZone approval take?","answer":"Posts go live instantly."},{"question":"How much does it cost to post on PromptZone?","answer":"Posting is free."},{"question":"Does a PromptZone article provide a dofollow link?","answer":"Yes, links in the article body are dofollow on a domain rated 20."},{"question":"Do I need to link back to PromptZone?","answer":"No backlink is required."},{"question":"What gets a post ignored?","answer":"There is no submission form, so a product with nothing worth writing about has no route in."}]', rw_summary='PromptZone is a Forem prompt-engineering community where your submission is an article with dofollow body links. Posting is free and instant with no backlink requirement; domain rating is 20.', rw_fact_points='["Posts publish instantly with no review","Free article with dofollow body links","No badge or return link is expected","Accepts AI tools, developer tools and prompt-engineering content"]', rw_submission_checks='["Write something worth reading — there is no product form.","Test your prompt before posting; the audience expects sandbox-verified output.","Avoid an advert tone in front of a prompt-engineering audience."]', rw_seo_title='PromptZone: Free Dev Article, DR 20', rw_seo_description='How to post on PromptZone: free instant prompt-engineering article with dofollow links, no backlink. Requirements from the 2026-11-16 snapshot.' WHERE slug='promptzone';
UPDATE submission_sites SET rw_source_lead='An open-source, AI-only shelf where the outbound links follow — once you have an account to get past the login.', rw_what_you_get='A dofollow listing in an AI-tools directory that runs on open-source software, after signing in.', rw_you_need='["An AI product","A live public URL","An account"]', rw_eligibility='You need an AI product, a live URL and an account. A product with no AI surface has no shelf in a directory that is entirely AI tools.', rw_submit_steps='["1 Open the submit page at /submit. It renders the page but shows Login Required where the form should be when signed out.","2 Log in. A Login to Continue control replaces the form; there is no way past it as a guest.","3 Submit the tool from the same page once signed in."]', rw_submit_requirements='["A live public URL","An AI product","An account"]', rw_rejection_reasons='["A product without an AI surface, since the whole directory is AI tools"]', rw_gotchas='["The submit page renders fully when signed out and only says Login Required in the form area, so it looks available until you look closely.","No review time is published on the form or in the FAQ, so there is nothing to chase after sending.","The site is open source, so the listing rules are whatever the operator runs rather than a published policy you can hold them to."]', rw_faq='[{"question":"How long does Tap4 AI Directory approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to Tap4 AI Directory?","answer":"Submitting is free."},{"question":"Does a Tap4 AI Directory listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 20."},{"question":"Do I need to link back to Tap4 AI Directory?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"A product with no AI surface."}]', rw_summary='Tap4 AI Directory is a free open-source AI-tools directory with a dofollow listing and no backlink. A login gates the form and no review time is published; domain rating is 20.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","Accepts AI tools and SaaS products"]', rw_submission_checks='["Sign in before filling the form.","Have a clear AI angle — the directory is AI-only.","No timeline to chase after submitting."]', rw_seo_title='Tap4 AI Directory: Free Listing, DR 20', rw_seo_description='How to submit to Tap4 AI Directory: free dofollow AI listing behind a login, no backlink. Process from the 2026-11-16 snapshot.' WHERE slug='tap4ai';
UPDATE submission_sites SET rw_source_lead='A weekly founder-community showcase that publishes instantly, followed and free — on a site whose profile step quietly fails.', rw_what_you_get='An instant dofollow listing filed under the current week in a founder community centred on India, with a gallery and rich description.', rw_you_need='["An account, which Google sign-in creates in one click","A project name up to 50 characters and a tagline up to 60","A logo, ideally 500x500 and under 3MB","Agreement to their Spotlight and fair-use terms"]', rw_eligibility='You need an account, short project copy, a logo and acceptance of the Spotlight terms. Nothing is published beyond the conduct rules you tick.', rw_submit_steps='["1 Sign in with Google at /create/project. The Google route creates the account outright and returns you to the form.","2 Skip the profile step. Google sign-in lands on onboarding asking for a permanent username whose Save Details button validates but commits nothing; go straight to /create/project instead.","3 Fill the project: name, tagline, link, a 500x500 logo, up to three gallery images, up to three categories, an open-source flag and a rich description up to 10,000 characters.","4 Tick the required agreement covering the Spotlight terms, disclaimer, fair-use policy and site policies, then Submit. It publishes immediately at /spotlight/project/<id>."]', rw_submit_requirements='["A Google account, or username and password","A project name and tagline within limits","A project link and a 500x500 logo under 3MB","A description up to 10,000 characters","Optional gallery images and categories","Agreement to the terms"]', rw_rejection_reasons='["Nothing published beyond the terms you tick, which cover the usual conduct rules"]', rw_gotchas='["The profile step is broken and decides your public byline. Save Details validates the username then commits nothing, so the project ships credited to an auto-generated handle, and the page says usernames cannot be changed later.","It is a weekly showcase, so your entry scrolls away when the next week opens. Live vote counts are mostly zero to three — judge it as a free dofollow link, not a traffic source.","The link is genuinely followed and instant, which is rare at this price, but the audience is a founder community centred on India rather than tool buyers."]', rw_faq='[{"question":"How long does DesiFounder Spotlight approval take?","answer":"Instant — the listing publishes as soon as you submit."},{"question":"How much does it cost to submit to DesiFounder Spotlight?","answer":"Submitting is free."},{"question":"Does a DesiFounder Spotlight listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 17."},{"question":"Do I need to link back to DesiFounder Spotlight?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Nothing published beyond the conduct terms you tick."}]', rw_summary='DesiFounder Spotlight is a free weekly founder showcase with an instant dofollow listing and no backlink. The profile step fails silently, so navigate straight to the form; domain rating is 17.', rw_fact_points='["Listings publish instantly with no review","Free listing with a dofollow link","No badge or return link is expected","Accepts startups, SaaS, AI tools, indie projects and open source"]', rw_submission_checks='["Navigate straight to /create/project — the profile step does not save.","Expect an auto-generated byline; the username cannot be fixed later.","Judge it as a free link, not a traffic source."]', rw_seo_title='DesiFounder Spotlight: Free Launch, DR 17', rw_seo_description='How to submit to DesiFounder Spotlight: free instant dofollow founder listing, no backlink. Broken profile step warning from the 2026-11-16 snapshot.' WHERE slug='desifounder-spotlight';
UPDATE submission_sites SET rw_source_lead='Free, followed and same-day, behind the longest four-step form here — and a quiet board.', rw_what_you_get='A same-day dofollow launch with a full product card, in exchange for detailing your tech stack, features and selling points.', rw_you_need='["A live URL and a GitHub account — the only sign-in","A logo and at least one core feature and selling point, each described","A tech stack you can name"]', rw_eligibility='Nothing is refused on paper, but the form asks for a tech stack and development stage, so a product you cannot describe that way will stall.', rw_submit_steps='["1 Sign in with GitHub — the only option, requesting read-only access to your email addresses.","2 Basic info: name, tagline, URL, optional version, one category, description, target audience and up to five tags. An Auto-fill button reads your page metadata.","3 Product details: core features and unique selling points, each added one at a time with a title and description, then pricing model, development stage, a required comma-separated tech stack and optional coming-soon features and competitor analysis.","4 Media and launch settings: a logo and up to five screenshots, then a launch date, time slot and toggles for comments and feedback. Preview opens a full card with Submit inside it."]', rw_submit_requirements='["A GitHub account","A 512x512 PNG or JPG logo","Up to five screenshots","Up to five tags","A required comma-separated tech stack","Features and selling points with titles and descriptions"]', rw_rejection_reasons='["Nothing on paper, but a product that cannot be described with a tech stack and development stage will stall halfway through"]', rw_gotchas='["It is four steps and step three asks for things most launch forms do not: a tech stack, a development stage, and features and selling points written one at a time with a title and paragraph.","GitHub is the only way in — no Google option and no email and password.","The board is quiet; one product launched in the seven days before 30 August 2026, so this is a link and a page rather than an audience."]', rw_faq='[{"question":"How long does Indie Launchers approval take?","answer":"Instant — the launch goes live the same day."},{"question":"How much does it cost to submit to Indie Launchers?","answer":"Submitting is free."},{"question":"Does an Indie Launchers listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 17."},{"question":"Do I need to link back to Indie Launchers?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Nothing formally, but a product without a describable tech stack and stage will stall."}]', rw_summary='Indie Launchers is a free same-day dofollow launch board with an unusually detailed four-step form. GitHub sign-in is required and no backlink is needed; domain rating is 17.', rw_fact_points='["Launches go live instantly the same day","Free listing with a dofollow link","No badge or return link is expected","Accepts indie products, SaaS, AI tools, developer tools and startups"]', rw_submission_checks='["Have GitHub sign-in ready — it is the only route.","Prepare a tech stack, development stage and feature descriptions.","Expect a link, not significant traffic."]', rw_seo_title='Indie Launchers: Free Same-Day Launch, DR 17', rw_seo_description='How to launch on Indie Launchers: free instant dofollow launch, no backlink, GitHub sign-in. Four-step form details from the 2026-11-16 snapshot.' WHERE slug='indie-launchers';
UPDATE submission_sites SET rw_source_lead='Six fields on an off-site Airtable form, a one-to-two-day turnaround, and all 106 outbound links are plain followed links.', rw_what_you_get='A dofollow card in a Notion integration list, added within a day or two through a simple off-site form.', rw_you_need='["A product that genuinely integrates with or extends Notion","A live public URL"]', rw_eligibility='You need a real Notion integration and a live URL. Anything with no Notion connection is refused, however good the product.', rw_submit_steps='["1 Follow Submit new integration. The header link leaves the site for an Airtable form; there is no form on notionintegrations.com itself.","2 Fill six required fields: integration name, website link, category, tags, subtitle and pricing. No account, login or captcha.","3 Wait one to two days. The form states new integrations are typically added within that window."]', rw_submit_requirements='["An integration name","A website link","A category and tags from fixed lists","A subtitle","A pricing answer"]', rw_rejection_reasons='["Anything with no Notion connection, however good the product"]', rw_gotchas='["Submission leaves the site entirely for an Airtable form, with no account or record on the directory; the only thing to check is whether the card appears.","Every field is marked required, including tags and subtitle, so nothing can be left blank.","They give an unusually specific one-to-two-day window, so there is a real timeline to hold them to."]', rw_faq='[{"question":"How long does Notion Integrations approval take?","answer":"One to two days, stated directly on the form."},{"question":"How much does it cost to submit to Notion Integrations?","answer":"Submitting is free."},{"question":"Does a Notion Integrations listing provide a dofollow link?","answer":"Yes, all outbound links are bare dofollow links on a domain rated 18."},{"question":"Do I need to link back to Notion Integrations?","answer":"No backlink is required."},{"question":"What gets an integration rejected?","answer":"Anything with no Notion connection."}]', rw_summary='Notion Integrations is a Notion-only directory with a free dofollow card added in one to two days via an off-site form. No backlink is required; domain rating is 18.', rw_fact_points='["Listings added within one to two days","Free submission with a dofollow link","No badge or return link is expected","Accepts only products that integrate with Notion"]', rw_submission_checks='["Be ready to leave the site for the Airtable form.","Fill every field — all six are required.","Have a genuine Notion integration, not a generic product."]', rw_seo_title='Notion Integrations: Free Dofollow Card, DR 18', rw_seo_description='How to submit to Notion Integrations: free dofollow card in 1-2 days via an off-site form, no backlink. Steps from the 2026-11-16 snapshot.' WHERE slug='notion-integrations';
UPDATE submission_sites SET rw_source_lead='A trust leaderboard built from customer praise on X, so your listing is only as good as the testimonials people have already written.', rw_what_you_get='A dofollow trust profile built from real endorsements posted on X, with a separate paid hands-on review available.', rw_you_need='["Real customers who have praised you publicly on X","An account, which Google sign-in creates in one click","A founder identity to attach the product to, shown publicly"]', rw_eligibility='You need genuine public praise on X, an account and a founder identity. There is no formal rule, but a profile with no endorsements is an empty trust page.', rw_submit_steps='["1 Sign in. /login offers Continue with Google or a six-digit emailed code; no password either way.","2 Add the product at /for-founders, the founder side where you register a product and get a trust profile to fill.","3 Import praise from X and approve what you want public. Live profiles show tweets from named accounts — there is no field to type testimonials into.","4 Optionally buy a review. /get-reviewed is a separate $79 service, down from $159, for a hands-on written review with screenshots in about two business days via Stripe, no account needed."]', rw_submit_requirements='["An account via Google or an emailed code","A product name, description and URL","Public praise on X to import and approve","$79 optional for a hands-on written review"]', rw_rejection_reasons='["Nothing formal, though the practical bar is having genuine endorsements — with none, the page is an empty trust profile"]', rw_gotchas='["The listing is made of testimonials, so without any you publish an empty trust page. The leaderboard ranks on endorsement count and the top entries sit at 11 to 15, so joining with zero puts a public zero beside your name.","Endorsements are imported from X, not typed in — you need customers who have actually posted about you, making this a platform to return to rather than launch on.","The $79 hands-on review is a separate product. Listing is free; the review is what buys an original write-up."]', rw_faq='[{"question":"How long does Endors approval take?","answer":"The listing publishes instantly; the optional review takes about two business days."},{"question":"How much does it cost to submit to Endors?","answer":"Listing is free. A hands-on written review is $79, reduced from $159."},{"question":"Does an Endors listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 15."},{"question":"Do I need to link back to Endors?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Nothing formal, but with no genuine endorsements the trust page is empty."}]', rw_summary='Endors is a free dofollow trust profile built from praise posted on X, with a separate $79 hands-on review. No backlink is required; domain rating is 15, and the listing depends on real testimonials.', rw_fact_points='["Profile publishes instantly","Free listing with a dofollow link","No badge or return link is expected","Accepts SaaS, developer tools, AI tools and indie products"]', rw_submission_checks='["Have real customer praise on X before starting.","Expect to import tweets, not type testimonials.","Treat the $79 review as a separate paid product."]', rw_seo_title='Endors: Free Trust Profile, DR 15', rw_seo_description='How to list on Endors: free instant dofollow trust profile from X praise, no backlink. $79 review is separate — 2026-11-16 snapshot.' WHERE slug='endors';
UPDATE submission_sites SET rw_source_lead='The alarming Google permissions are optional; the real wall here is a public repository.', rw_what_you_get='A dofollow listing that points to your GitHub repository, in an MCP-server index you reach by signing in with Google.', rw_you_need='["A public GitHub repository for the server","A Google account"]', rw_eligibility='You need a public GitHub repo and a Google account. The repository field is required and the listing is built around it, so a closed-source or hosted-only server has nothing to put in that field.', rw_submit_steps='["1 Open /submit. It answers Authentication Required and offers exactly one method: Sign in with Google.","2 Read the consent screen before accepting. The OAuth request comes from a third party called Highlight, asking for Google Calendar read/write, calendar events and contacts access on top of email and profile.","3 Decide whether that is worth a listing. There is no email route, no GitHub route and no form to fill without it; leave the extra scopes unticked and sign-in still completes."]', rw_submit_requirements='["A public GitHub repository — the one required field","A Google account for identity; the extra scopes are optional","A long summary, a language and at least one category"]', rw_rejection_reasons='["A closed-source or hosted-only MCP server, since the required repository field cannot be left empty"]', rw_gotchas='["The sign-in looks alarming but the calendar and contacts permissions are three unticked optional boxes on a second screen; leave them alone and it still works.","The real wall is the repository. GitHub Repository is required on both the Regular and SSE tab, so a hosted server with no public source cannot be submitted.","The listing links to the repository rather than your own site, so the link earned points at github.com.","/new looks like a submission route but is the newest-servers listing; the real one is /submit."]', rw_faq='[{"question":"How long does MCPServers.com approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to MCPServers.com?","answer":"Submitting is free."},{"question":"Does MCPServers.com provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 15."},{"question":"Do I need to link back to MCPServers.com?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"A closed-source or hosted-only server with no public repository."}]', rw_summary='MCPServers.com is a free MCP index where a dofollow listing requires a public GitHub repo and Google sign-in. No backlink is needed; domain rating is 15 and the optional OAuth scopes can be left unticked.', rw_fact_points='["No published review time","Free listing with a dofollow link to your GitHub repo","No badge or return link is expected","Accepts MCP servers, developer tools and AI agents"]', rw_submission_checks='["Have a public GitHub repository — it is mandatory.","Leave the extra Google scopes unticked if unwanted.","The earned link points to GitHub, not your product site."]', rw_seo_title='MCPServers.com: Free MCP Listing, DR 15', rw_seo_description='How to submit to MCPServers.com: free dofollow MCP listing from a public GitHub repo, no backlink. OAuth details from the 2026-11-16 snapshot.' WHERE slug='mcpservers-com';
UPDATE submission_sites SET rw_source_lead='A hand-checked AI and SaaS grid where the free followed listing costs you a phone number on an agency''s lead form.', rw_what_you_get='A dofollow card in an AI/SaaS category grid, decided by a human after a few days.', rw_you_need='["A live tool that is genuinely AI or SaaS — the only two types on the form","A visible privacy policy and identifiable company contact details","A phone number, which the form makes mandatory"]', rw_eligibility='You need a real AI or SaaS tool, a visible privacy policy, traceable contact details and a phone number. Anything outside those two types, or without a policy or contact details, is refused, as is anything the operator judges outside an unpublished code of conduct.', rw_submit_steps='["1 Leave the directory to submit. The header SUBMIT goes to the operator''s marketing-automation domain; that external page is the whole submission.","2 Fill the contact half: first and last name, email, company and a mandatory phone number. No account or login.","3 Fill the tool half: AI or SaaS, URL, a description capped at 100 characters, one of 25 categories and a status of Free, Freemium, Paid, Waitlist or Open Source.","4 Send and wait for the email. A human reviews it and notifies you when the listing is live; there is no dashboard, reference number or way to edit afterward."]', rw_submit_requirements='["First and last name, email and company","A mandatory phone number, digits only","A tool URL","A description of at most 100 characters","One category and one pricing status"]', rw_rejection_reasons='["Anything that is neither AI nor SaaS, sites with no privacy policy or traceable contact details, and anything the operator judges outside their unpublished code of conduct"]', rw_gotchas='["The phone number is mandatory and the form is the operator''s own lead capture on their agency domain, so you hand a marketing agency your number along with your tool.","There is no listing page — approved tools become a card in a category grid linking straight out, so the followed link is the entire prize.","The description field takes 100 characters, a tagline rather than a description; write to that limit or the form rejects it after you press Send."]', rw_faq='[{"question":"How long does Apps and Websites approval take?","answer":"Three to five days; a human reviews each submission."},{"question":"How much does it cost to submit to Apps and Websites?","answer":"Submitting is free."},{"question":"Does an Apps and Websites listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 13."},{"question":"Do I need to link back to Apps and Websites?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Anything outside AI or SaaS, no privacy policy or contact details, or an unpublished code-of-conduct breach."}]', rw_summary='Apps and Websites is a hand-checked AI/SaaS grid with a free dofollow card decided in three to five days. No backlink is required, but a phone number and privacy policy are mandatory; domain rating is 13.', rw_fact_points='["Human review takes three to five days","Free listing with a dofollow link","No badge or return link is expected","Accepts AI tools and SaaS products only"]', rw_submission_checks='["Be ready to give a phone number to the operator''s agency.","Keep the description under 100 characters.","Have a privacy policy and traceable contact details on your site."]', rw_seo_title='Apps and Websites: Free AI/SaaS Listing, DR 13', rw_seo_description='How to submit to Apps and Websites: free dofollow AI/SaaS card in 3-5 days, no backlink, phone number required. Steps from the 2026-11-16 snapshot.' WHERE slug='apps-and-websites';
UPDATE submission_sites SET rw_source_lead='A badge on your site is all their checker needs to approve the listing itself.', rw_what_you_get='An instant dofollow listing that auto-approves once their checker verifies your badge, with your founding story as the body of the page.', rw_you_need='["An account via Google or email and password","Their badge on a public page, verified from the form","A story of why you built it, which is required"]', rw_eligibility='You need an account, a badge on a public page and a required founding story. Anyone unwilling to carry the badge is excluded unless they take the $29 lane.', rw_submit_steps='["1 Sign in with Google or email and password.","2 Fill product details: URL, name, a category from a searchable tree, tags, your story, an optional launch date, social links and a logo.","3 Pick the lane, paste their badge onto a public page and press Verify Now with that page''s exact URL.","4 Review and publish. The free lane auto-approves once the badge verifies."]', rw_submit_requirements='["Your story — required prose about why you built it","A logo in PNG, JPG or WebP up to 2MB","Their badge, an SVG linking to their homepage"]', rw_rejection_reasons='["Anyone unwilling to carry the badge, unless they take the $29 lane"]', rw_gotchas='["The free lane is auto-approved rather than reviewed, so the badge is the whole gate; pull it later and nothing else holds the listing up.","Your story is a required field and is the body of the listing, so the page is only as good as what you write there.","Badge verification asks for the exact page URL carrying it, so a badge on a page they are not pointed at counts for nothing."]', rw_faq='[{"question":"How long does Sell With boost approval take?","answer":"Instant — the free listing auto-approves once the badge verifies."},{"question":"How much does it cost to submit to Sell With boost?","answer":"Free with their badge. Standard is $29 for instant approval, seven days featured and up to three resource links; Premium is $99 for thirty featured days."},{"question":"Does a Sell With boost listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 73."},{"question":"Do I need to link back to Sell With boost?","answer":"Yes — the free lane requires their badge on your site."},{"question":"What gets a submission rejected?","answer":"Refusing the badge unless you take the $29 lane."}]', rw_summary='Sell With boost is a free dofollow listing that auto-approves when their badge is verified on your site. A founding story is required; no other backlink is needed and domain rating is 73.', rw_fact_points='["Free listing auto-approves on badge verification","Dofollow link with a badge backlink required","No other return link is expected","Accepts indie products, SaaS and AI tools"]', rw_submission_checks='["Install the badge on the exact page you will point them to.","Write a real founding story — it is the listing body.","Use the free lane, or pay $29 to skip the badge."]', rw_seo_title='Sell With boost: Free Badge Listing, DR 73', rw_seo_description='How to submit to Sell With boost: free instant dofollow listing via badge verification, no other backlink. Story requirement from the 2026-11-16 snapshot.' WHERE slug='sellwithboost';
UPDATE submission_sites SET rw_source_lead='Claiming a profile you already have is free; publishing a new one on this B2B review platform costs $99.', rw_what_you_get='A dofollow B2B listing with no recurring fee, free if the platform already has a profile of you to claim.', rw_you_need='["A business email address, asked for by name","$99 unless a profile for your product already exists to claim","A product a business buyer would compare"]', rw_eligibility='You need a business email, a comparable product and either $99 for a new listing or nothing to claim an existing one. A free-mail address and unwillingness to pay for a non-existent profile are refused.', rw_submit_steps='["1 Search for your product first. Claiming an existing profile is free and publishing a new one is $99, so find out which you are doing before registering.","2 Create a vendor account at /register with your full name, a business email and a choice of what to manage; then verify your email.","3 Claim or submit from the dashboard. Claiming the existing profile is free; publishing a new listing is where the $99 approval fee applies.","4 Keep the listing. Approved entries stay live with no recurring listing charge."]', rw_submit_requirements='["A vendor account created with a business email","$99 for a new listing, or nothing to claim an existing one","A product or company name, URL and description","Optional category and ranking details that affect placement"]', rw_rejection_reasons='["A free-mail address, since registration asks for a business email, and unwillingness to pay $99 for a listing that does not yet exist"]', rw_gotchas='["Claiming is free and creating is $99, and the site is large enough that a product with traction may already be there; search first or you will pay for something you could have taken over.","Registration asks for a business email by name, so a free-mail address is the wrong footing.","The $99 is an approval fee rather than a listing fee, charged against a decision rather than a page."]', rw_faq='[{"question":"How long does SoftwareWorld approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to SoftwareWorld?","answer":"A one-time $99 approval fee for a new listing with no recurring charge; claiming an existing profile is free."},{"question":"Does a SoftwareWorld listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 73."},{"question":"Do I need to link back to SoftwareWorld?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"A free-mail address, or unwillingness to pay $99 for a new listing."}]', rw_summary='SoftwareWorld is a B2B review platform where claiming an existing profile is free and a new listing costs a one-time $99 approval fee. The dofollow link needs no backlink; domain rating is 73.', rw_fact_points='["No published review time","Dofollow listing with no backlink","Claiming is free; new listing is $99 one-time","Accepts B2B software, SaaS, professional services and enterprise tools"]', rw_submission_checks='["Search first — claiming an existing profile is free.","Use a business email, not free-mail.","The $99 is charged for approval, not a page."]', rw_seo_title='SoftwareWorld: $99 B2B Listing, DR 73', rw_seo_description='How to list on SoftwareWorld: claim free or $99 new dofollow B2B listing, no backlink. Business email required — 2026-11-16 snapshot.' WHERE slug='softwareworld';
UPDATE submission_sites SET rw_source_lead='A human-curated web directory in the old sense: 660,000 sites across 7,692 categories, reviewed by nearly 300,000 volunteer editors.', rw_what_you_get='A dofollow listing in a vast general web directory, filed by one of hundreds of thousands of volunteer editors.', rw_you_need='["A website URL — the only required form field","An email address for the free-plan confirmation link","A category, unless you let it auto-categorise"]', rw_eligibility='You need a URL and an email. Nothing structural is refused — the directory accepts any site with a URL, which is what makes it a general directory rather than a launch board.', rw_submit_steps='["1 Fill the URL and an email. /submit needs no account; title, description and category are optional and auto-fetch from the site if left blank.","2 Pick the free plan. After sending, a plan page offers Basic (free, the waiting list), Express and Featured, with a dialog nudging you off free — choose Basic.","3 Click the confirmation link emailed to that address. The free submission is only submitted once this is clicked.","4 Wait for an editor. This is a human-curated directory, so the listing waits for one of their editors rather than a timer."]', rw_submit_requirements='["A website URL","An email address for the confirmation link","Optional title and description, which auto-fetch if left blank","An optional category that can be chosen automatically"]', rw_rejection_reasons='["Nothing structural — the directory accepts any site with a URL"]', rw_gotchas='["The free submission is not in until the emailed confirmation link is clicked, a step after the form and the plan picker; stopping at the form submits nothing.","Leaving title and description blank hands the copy to their auto-fetch, which takes whatever your meta tags say.","Approval is a human editor''s decision among nearly 300,000 editors, so there is no turnaround to plan around and no status to check."]', rw_faq='[{"question":"How long does Viesearch approval take?","answer":"No review time is published; a volunteer editor decides."},{"question":"How much does it cost to submit to Viesearch?","answer":"Submitting is free; paid featured and reciprocal placements are the commercial side."},{"question":"Does a Viesearch listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 73."},{"question":"Do I need to link back to Viesearch?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Nothing structural — any site with a URL is accepted into the queue."}]', rw_summary='Viesearch is a large human-curated web directory with a free dofollow listing and no backlink requirement. Submission needs an emailed confirmation click and a volunteer editor''s approval; domain rating is 73.', rw_fact_points='["Human editor review with no published timeline","Free listing with a dofollow link","No badge or return link is expected","Accepts any website, SaaS, B2B software and services"]', rw_submission_checks='["Click the emailed confirmation link — the form alone submits nothing.","Write your own title and description rather than leaving them blank.","Expect no predictable turnaround."]', rw_seo_title='Viesearch: Free Directory Listing, DR 73', rw_seo_description='How to submit to Viesearch: free dofollow web-directory listing, no backlink. Confirmation click and editor review from the 2026-11-16 snapshot.' WHERE slug='viesearch';
UPDATE submission_sites SET rw_source_lead='An upvote board where the whole submission is one modal and the outbound link follows.', rw_what_you_get='An instant dofollow listing at the top of the daily board, if you can gather a few votes before it drops off.', rw_you_need='["A Google account — the only sign-in","A short product pitch and a live URL"]', rw_eligibility='You need a Google account and a live URL. There is no permanent shelf, so a product nobody votes for sits at zero and drops off the daily board within a day.', rw_submit_steps='["1 Sign in with Google. The Login button opens a one-item menu and Google is the only option; your handle comes from the address.","2 Press Launch. The whole submission is one modal: name, a description of at most 160 characters, the link, up to ten tags with Enter, up to two categories and an emoji.","3 Leave the backlink options alone unless you mean them. Two checkboxes offer to open you to backlink barter and paid link placements, unticked by default.","4 Press Launch again. The listing goes live at once at the top of Today''s Goats with zero points."]', rw_submit_requirements='["A live URL","A description of at most 160 characters","Up to two categories"]', rw_rejection_reasons='["Nothing formal, but with no votes a listing sits at zero and drops off the daily board within a day"]', rw_gotchas='["The description caps at 160 characters and the field scrolls rather than warning, so write it short before pasting.","Two checkboxes opt you into backlink barter and paid link placements — they are about selling links from your own site, not about your listing.","It is an upvote board, so a listing with no votes drops off within a day; budget for asking a few people.","The board is tiny, with weekly leaders on two points — easy to reach the top, but a small audience when you do."]', rw_faq='[{"question":"How long does Viral Bucket approval take?","answer":"Instant — the listing goes live as soon as you press Launch."},{"question":"How much does it cost to submit to Viral Bucket?","answer":"Submitting is free."},{"question":"Does a Viral Bucket listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 13."},{"question":"Do I need to link back to Viral Bucket?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Nothing formal, but with no votes it drops off the daily board within a day."}]', rw_summary='Viral Bucket is a free dofollow upvote board with a one-modal submission and no backlink. A listing starts at zero and drops off within a day without votes; domain rating is 13.', rw_fact_points='["Listings go live instantly","Free submission with a dofollow link","No badge or return link is expected","Accepts SaaS, indie products, AI tools and marketing tools"]', rw_submission_checks='["Write the pitch under 160 characters before pasting.","Ignore the backlink-barter checkboxes unless intended.","Plan a few votes or the listing drops off quickly."]', rw_seo_title='Viral Bucket: Free Upvote Listing, DR 13', rw_seo_description='How to submit to Viral Bucket: free instant dofollow upvote listing, no backlink. Modal fields and vote caveat from the 2026-11-16 snapshot.' WHERE slug='viral-bucket';
UPDATE submission_sites SET rw_source_lead='A 4,000-tool AI directory with no free lane, where the listing card''s link is nofollow despite what the pricing page claims.', rw_what_you_get='A listing in a large AI-tools directory, with homepage and featured placement on higher tiers — but the card link does not pass equity.', rw_you_need='["$9.9 for the cheapest listing","A person to clear the Cloudflare Turnstile on the form","An AI tool"]', rw_eligibility='You need to pay from $9.9 and clear a Cloudflare check. A product that is not an AI tool is rejected.', rw_submit_steps='["1 Pick a tier on the pricing page: Basic $9.9, Featured $19.9 or Unlimited $59.9 a month. There is no free card.","2 Get through the wall. /submit sits behind a Cloudflare Turnstile that kept verifying in an automated browser.","3 Fill and pay. Card or crypto are accepted.","4 Wait 48 hours — the stated review time on every tier."]', rw_submit_requirements='["A tool URL, name and description","A logo","A paid tier from $9.9"]', rw_rejection_reasons='["A product that is not an AI tool"]', rw_gotchas='["There is no free lane; the cheapest listing is $9.9 once and the form is behind that choice.","The listing card''s link is nofollow on every tool on the Explore page, and only sponsor links are followed — so the dofollow claim on pricing does not apply to a normal listing.","/submit is behind a Cloudflare Turnstile that did not clear in an automated browser, so the form may need a person."]', rw_faq='[{"question":"How long does AIStage approval take?","answer":"One to two days; they state 48 hours on every tier."},{"question":"How much does it cost to submit to AIStage?","answer":"Basic $9.9 once, Featured $19.9 once with seven days homepage placement, or Unlimited $59.9 a month. Crypto accepted; guest posts are separate."},{"question":"Does an AIStage listing provide a dofollow link?","answer":"No — listing card links are nofollow on a domain rated 71; only sponsor links are followed."},{"question":"Do I need to link back to AIStage?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"A product that is not an AI tool."}]', rw_summary='AIStage is a 4,000-tool AI directory with paid listings from $9.9 and a 48-hour review. Listing card links are nofollow and no backlink is required; domain rating is 71.', rw_fact_points='["Paid-only from $9.9 with a 48-hour review","Listing card links are nofollow","No badge or return link is expected","Accepts AI tools and AI websites"]', rw_submission_checks='["Expect to pay — there is no free lane.","The listing link is nofollow; do not count on link equity.","Have a person ready for the Cloudflare check."]', rw_seo_title='AIStage: $9.9 AI Listing, DR 71', rw_seo_description='How to submit to AIStage: paid $9.9+ AI listing in 48 hours, nofollow card link, no backlink. Pricing caveat from the 2026-11-16 snapshot.' WHERE slug='aistage';
UPDATE submission_sites SET rw_source_lead='The company database investors and journalists actually check — free to add yourself, nofollow on the way out.', rw_what_you_get='A company record in the database business journalists consult, with a nofollow outbound link and the credibility of being listed.', rw_you_need='["An account via Google, LinkedIn, or email and password","Real company facts, since this is a company record rather than a product listing","Agreement to their terms in a modal that blocks the app"]', rw_eligibility='You need an account, real company facts and agreement to the terms. A product with no company behind it does not fit — the six profile types are Company, Investment Firm, Person, School, Individual Investor and Event, none of which is a product.', rw_submit_steps='["1 Get past the bot check. /add-new sits on a Cloudflare session verification for several seconds, then redirects to a login wall.","2 Register with Google or LinkedIn, or an email with a name and a password of at least eight characters including a number and both cases.","3 Agree to the terms. A Welcome modal covering the terms, cancellation policy and privacy policy blocks the page until accepted.","4 Pick a profile type. Add new profile offers six; a product goes in as a Company, filled with website, description, founding details and location."]', rw_submit_requirements='["An account via Google, LinkedIn, or email and password","Agreement to the terms and privacy policy","A company name, website and description","Founding details and location"]', rw_rejection_reasons='["A product with no company behind it — none of the six profile types is a product"]', rw_gotchas='["There is no product listing; all six profile types are organisations, people or events, so a product must be filed as a company.","A terms modal blocks the whole app right after sign-up, so an agent cannot clear the front door for you.","Their bot check runs before the page does, which looks like a broken link rather than a queue."]', rw_faq='[{"question":"How long does Crunchbase approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to Crunchbase?","answer":"Adding a profile is free; a Pro subscription sells search, alerts and exports."},{"question":"Does a Crunchbase listing provide a dofollow link?","answer":"No — links from Crunchbase are nofollow on a domain rated 91."},{"question":"Do I need to link back to Crunchbase?","answer":"No backlink is required."},{"question":"What gets a profile rejected?","answer":"A product with no company behind it."}]', rw_summary='Crunchbase is the company database investors and journalists check, with a free profile and a nofollow link. A product must be filed as a company and no backlink is required; domain rating is 91.', rw_fact_points='["No published review time","Free profile with a nofollow link","No badge or return link is expected","Accepts startups, SaaS, B2B software and companies"]', rw_submission_checks='["File your product as a Company — there is no product type.","Be ready to accept a terms modal that blocks the app.","Expect no link equity; the value is being in the database."]', rw_seo_title='Crunchbase: Free Company Profile, DR 91', rw_seo_description='How to add a Crunchbase company profile: free, nofollow link, no backlink. Terms modal and profile types from the 2026-11-16 snapshot.' WHERE slug='crunchbase';
UPDATE submission_sites SET rw_source_lead='Buyer-intent reviews where B2B software gets compared — slow, bureaucratic, and gated on identity.', rw_what_you_get='A nofollow vendor profile in the review catalogue business buyers use to compare software, with the real work being the reviews you collect.', rw_you_need='["A vendor account validated through LinkedIn or a business email","Real customers willing to write reviews","A work email on the product''s own domain to claim a profile"]', rw_eligibility='You need identity validation and real customers. Consumer apps and side projects with no business buyers, and products with no customers to review them, are refused.', rw_submit_steps='["1 Get validated first. /products/new redirects to /authorize, which requires validation through LinkedIn or a business email before the page is accessible.","2 Search before creating. G2 often has an unclaimed profile already; Claim this profile sits at the top right, and the claim form wants a work email on the product''s own domain with a one-to-three-day answer.","3 Claim or create the profile once validated.","4 Fill it out: categories, features, pricing and screenshots. G2 matches products to categories, and the category is what buyers browse.","5 Collect reviews — this is the actual work. A profile with no reviews ranks nowhere."]', rw_submit_requirements='["A vendor account validated by LinkedIn or a business email","Real customers who will review","Category, features and pricing detail","Screenshots"]', rw_rejection_reasons='["Consumer apps and side projects with no business buyers, and products with no customers to review them"]', rw_gotchas='["You cannot see the vendor form until validated through LinkedIn or a business email — an identity gate no agent can clear.","The listing is not the point: a profile with no reviews does nothing. Getting listed is the easy part and changes nothing alone.","Review solicitation has rules and incentives must be disclosed; read the policy before asking customers.","A Gmail address is refused on the claim form, which checks that the email domain matches the product website."]', rw_faq='[{"question":"How long does G2 approval take?","answer":"Two to four weeks; claiming a profile answers in one to three business days."},{"question":"How much does it cost to submit to G2?","answer":"Listing is free; paid tiers buy profile control and leads."},{"question":"Does a G2 listing provide a dofollow link?","answer":"No — links from G2 are nofollow on a domain rated 91."},{"question":"Do I need to link back to G2?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Consumer apps with no business buyers, or products with no customers to review them."}]', rw_summary='G2 is the B2B review catalogue where software gets compared, with a free nofollow vendor profile and no backlink. Identity validation and real customer reviews are required; domain rating is 91.', rw_fact_points='["Approval takes two to four weeks","Free profile with a nofollow link","No badge or return link is expected","Accepts B2B software and established SaaS with customers"]', rw_submission_checks='["Validate your identity via LinkedIn or a business email first.","Search for an existing unclaimed profile before creating one.","Use a work email on your product''s own domain.","Plan how to collect genuine reviews — the listing alone does nothing."]', rw_seo_title='G2: Free Vendor Profile, DR 91', rw_seo_description='How to list on G2: free nofollow vendor profile, no backlink, identity validation required. Claim vs create and reviews from the 2026-11-16 snapshot.' WHERE slug='g2';
UPDATE submission_sites SET rw_source_lead='Two fields, no account, a followed link and a stated 48 hours — the shortest free submission in this bracket.', rw_what_you_get='An instant-queued dofollow listing written from your site''s own copy, published within 48 hours at no cost.', rw_you_need='["A live product that genuinely incorporates AI features","An email address for the publication notice"]', rw_eligibility='You need a real AI product and an email. Tools with no AI features are told outright they will not be published.', rw_submit_steps='["1 Open /submit-tool. No account, login, captcha or paid tier — the whole form is here.","2 Fill two fields: an email and your URL. That is the entire form; copy is taken from your site rather than asked for.","3 Submit. The form posts to Webflow''s form API and is replaced by a thank-you message with a promise of email notification on publication.","4 Wait 48 hours. The page states publication within that window, plus a lifelong free listing and an X and newsletter mention."]', rw_submit_requirements='["An email address","Your product URL"]', rw_rejection_reasons='["Tools with no AI features, which the submit page says outright will not be published"]', rw_gotchas='["You do not write your own listing — the form takes only an email and a URL, so the tagline and description are lifted from your page with no say in the wording.","The page states tools without AI features will not be published, with no refund of the wait: you find out by nothing appearing.","Some cards elsewhere on the site carry affiliate parameters on outbound links, so check what your own listing points to once live."]', rw_faq='[{"question":"How long does Human or Not approval take?","answer":"One to two days; publication within 48 hours is stated."},{"question":"How much does it cost to submit to Human or Not?","answer":"Submitting is free."},{"question":"Does a Human or Not listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 12."},{"question":"Do I need to link back to Human or Not?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Tools with no AI features are not published."}]', rw_summary='Human or Not is the shortest free dofollow submission here: an email and a URL, published within 48 hours with no backlink. Copy is taken from your site; domain rating is 12.', rw_fact_points='["Listings publish within 48 hours","Free submission with a dofollow link","No badge or return link is expected","Accepts AI tools only"]', rw_submission_checks='["Make sure your site copy is good — the listing is scraped from it.","Have a genuine AI feature.","Check the outbound link once live for affiliate parameters."]', rw_seo_title='Human or Not: Free AI Listing, DR 12', rw_seo_description='How to submit to Human or Not: free two-field dofollow AI listing in 48 hours, no backlink. Scraped-copy caveat from the 2026-11-16 snapshot.' WHERE slug='human-or-not';
UPDATE submission_sites SET rw_source_lead='The largest MCP marketplace, with millions of yearly visitors — and now a single paid lane to get listed.', rw_what_you_get='A page in the biggest MCP marketplace, published immediately with a verified badge and featured placement on the paid lane.', rw_you_need='["A repository URL — the only required field","An account via the Sign In control","A project that is an MCP server, remote server, client or agent"]', rw_eligibility='You need a repository URL, an account and one of the four project types the form offers. Anything outside those four types is refused.', rw_submit_steps='["1 Pick a project type. /submit opens with four tabs: MCP Server, Remote Server, MCP Client and AI Agent; the type decides the shelf.","2 Give the repository URL. It is the only required field; the name is optional and read from the repo.","3 Sign in via the Sign In control; the submission attaches to an account.","4 Pay $39. The form now carries a single card and a Pay and submit automatically control — there is no free lane and no checkbox to decline it."]', rw_submit_requirements='["A repository URL","An account on the site","One of MCP Server, Remote Server, MCP Client or AI Agent","An optional name"]', rw_rejection_reasons='["Anything that is not one of the four project types the form offers"]', rw_gotchas='["The free lane is gone. It existed as recently as August 2026; the form now offers only the $39 submission, so a free-only run should skip it.","The listing is built from a repository URL, so a closed-source hosted server needs a public repo describing itself before it can be submitted.","Outbound links on the site are nofollow despite the paid card''s followed-link claim; judge it on placement and traffic, not link equity.","The $39 buys instant publication, a verified badge and featured placement, none of which requires a review wait."]', rw_faq='[{"question":"How long does MCP.so approval take?","answer":"The paid lane publishes immediately; no review time applies."},{"question":"How much does it cost to submit to MCP.so?","answer":"$39 one-time, and as of 1 September 2026 the only lane — the form has a single Pay and submit control with no free option."},{"question":"Does an MCP.so listing provide a dofollow link?","answer":"No — links from MCP.so are nofollow on a domain rated 72."},{"question":"Do I need to link back to MCP.so?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Anything outside the four project types the form offers."}]', rw_summary='MCP.so is the largest MCP marketplace with a paid-only $39 listing that publishes instantly. No backlink is required and outbound links are nofollow; domain rating is 72.', rw_fact_points='["Paid-only at $39, published immediately","Listing links are nofollow","No badge or return link is expected","Accepts MCP servers, remote servers, clients, agents and agent skills"]', rw_submission_checks='["Expect to pay $39 — the free lane is gone.","Have a public repository URL — it is the required field.","Judge it on traffic and placement, not link equity."]', rw_seo_title='MCP.so: $39 MCP Listing, DR 72', rw_seo_description='How to submit to MCP.so: paid-only $39 instant MCP listing, nofollow link, no backlink. Four project types from the 2026-11-16 snapshot.' WHERE slug='mcp-so';
UPDATE submission_sites SET rw_source_lead='A small maker-tools directory with the fairest badge deal around: free listing, no thresholds, followed the moment you host their badge.', rw_what_you_get='A dofollow maker-tools listing that upgrades from nofollow the instant their personalised badge is verified on your site.', rw_you_need='["An account via email code, email password or Google","A square logo and a 16:9 cover image","Their personalised badge on your site, for the followed link"]', rw_eligibility='You need an account, both required images and — for dofollow — their badge. Products that do not help makers build, ship or grow are refused.', rw_submit_steps='["1 Create an account. Passwordless email codes sit alongside Google, so the account need not tie to a personal profile.","2 Fill the product step: name, a punchline under 30 characters, a roughly 70-word description, website, one category, plus a required square logo and 16:9 cover.","3 Pick the free plan. $0 with badge or $9.99 for four followed links and no badge; the free path is I''ll add the badge in the modal.","4 Land on the live listing. There is no queue — the page publishes immediately with a nofollow link.","5 Host the badge and verify. Copy your personalised badge snippet, deploy it, then click Verify Badge to upgrade the link to dofollow."]', rw_submit_requirements='["A punchline under 30 characters","A roughly 70-word description within 1,000 characters","A 256x256 square logo up to 2MB","A 1280x720 cover up to 8MB","Their personalised badge for dofollow"]', rw_rejection_reasons='["Products that do not help makers build, ship or grow"]', rw_gotchas='["The badge snippet is personalised to your own listing URL, not their homepage, so a generic badge from elsewhere will never verify.","The punchline caps at 30 characters, shorter than most taglines; write it before starting.","The page is client-rendered and badge controls appear seconds after load, so a missing Verify button usually means you looked too early."]', rw_faq='[{"question":"How long does Neeed Directory approval take?","answer":"Instant — the listing publishes as soon as you submit."},{"question":"How much does it cost to submit to Neeed Directory?","answer":"There is a free lane with a badge. $9.99 gives four followed links and drops the badge."},{"question":"Does a Neeed Directory listing provide a dofollow link?","answer":"Yes — the link upgrades to dofollow once your personalised badge is verified, on a domain rated 72."},{"question":"Do I need to link back to Neeed Directory?","answer":"Yes — the badge is what unlocks the followed link on the free lane."},{"question":"What gets a submission rejected?","answer":"Products that do not help makers build, ship or grow."}]', rw_summary='Neeed Directory is a free maker-tools directory whose listing goes live instantly and turns dofollow when you host their personalised badge. No other backlink is required; domain rating is 72.', rw_fact_points='["Listings publish instantly","Link upgrades to dofollow on badge verification","A personalised badge is required for dofollow","Accepts developer tools, design resources, SaaS, AI tools and no-code platforms"]', rw_submission_checks='["Use your own personalised badge snippet, not a generic one.","Write the punchline under 30 characters.","Wait for the badge controls to load before verifying."]', rw_seo_title='Neeed Directory: Free Badge Listing, DR 72', rw_seo_description='How to submit to Neeed Directory: free instant maker-tools listing, dofollow on badge verification, no other backlink. Steps from the 2026-11-16 snapshot.' WHERE slug='neeed-directory';
UPDATE submission_sites SET rw_source_lead='Open source, in-browser, no account required — three rules and a GitHub issue to get in.', rw_what_you_get='A dofollow listing in a curated collection of tools that need no signup to use, filed by category.', rw_you_need='["A public GitHub repository","A tool that works with no account at all","Something that runs in the browser"]', rw_eligibility='You need an open-source, browser-based tool with no account requirement. Closed-source tools, anything needing a login for its main job, and anything you must install are refused.', rw_submit_steps='["1 Check the three rules: open source, no signup, runs in the browser — stated in their issue template.","2 Open the issue template. Both the site''s SUBMIT A TOOL button and the README link go to a prefilled GitHub issue from request-to-add-a-tool.md.","3 Fill six lines: name, a one-sentence description, a direct URL, tags, the GitHub repository and one of ten categories."]', rw_submit_requirements='["A public GitHub repository","A description under 140 characters","Three to five tags","A direct URL and one of ten categories"]', rw_rejection_reasons='["Closed-source tools, anything whose main job needs an account, and anything you install rather than open in a browser"]', rw_gotchas='["Closed source is a hard no — the template has a GitHub field and every card shows a licence.","The no-account rule is about the tool itself, not a free tier; a product whose main job needs login does not qualify.","It is a GitHub issue, not a form, so your submission is public from the moment you file it.","The list is curated with hundreds of open issues, so expect to wait with no stated time."]', rw_faq='[{"question":"How long does NoSignups approval take?","answer":"No review time is published; the GitHub issue queue is the backlog."},{"question":"How much does it cost to submit to NoSignups?","answer":"Submitting is free."},{"question":"Does a NoSignups listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 12."},{"question":"Do I need to link back to NoSignups?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Closed source, requiring an account for the tool''s main job, or needing installation."}]', rw_summary='NoSignups is a free dofollow collection of open-source, browser-based tools that need no account. Submission is a public GitHub issue with no published timeline; domain rating is 12.', rw_fact_points='["Curated via GitHub issue with no published timeline","Free listing with a dofollow link","No badge or return link is expected","Accepts open-source dev tools, productivity and design tools"]', rw_submission_checks='["Ensure your tool is open source and needs no signup.","Open the prefilled GitHub issue with six lines filled.","Expect a public submission and an unstated wait."]', rw_seo_title='NoSignups: Free OSS Listing, DR 12', rw_seo_description='How to submit to NoSignups: free dofollow listing for open-source no-account browser tools via GitHub issue, no backlink. Rules from the 2026-11-16 snapshot.' WHERE slug='nosignups';
UPDATE submission_sites SET rw_source_lead='A badge and two upvotes buy a followed link and a numbered launch week.', rw_what_you_get='A dofollow listing in a numbered launch week, in exchange for a badge and two upvotes given to other founders.', rw_you_need='["An account via Google, GitHub or email","A builder profile with a first and last name","Two upvotes on other startups, a square logo and their badge on a public page"]', rw_eligibility='You need an account, a completed builder profile, two upvotes given, a logo and a badge. Anyone unwilling to carry the badge is excluded unless they take the $9 lane.', rw_submit_steps='["1 Sign in with Google, GitHub or email and password.","2 Fill the builder profile: first name, last name and a bio. Nothing can be submitted until it is saved, and the surname is required.","3 Upvote two startups from a randomised list — a gate before the form opens.","4 Describe the product: URL, square logo, name, tagline, a description up to 1,000 characters, categories and tags.","5 Pick a lane: free with the badge, $9 to skip the queue, or $299 for the social package.","6 Install and verify the badge with the URL of the page carrying it.","7 Schedule a launch week. The free lane runs in a numbered week rather than going live immediately."]', rw_submit_requirements='["A square logo in JPEG, PNG or WebP up to 2MB","A description up to 1,000 characters","Their badge, an image linking to your own listing page"]', rw_rejection_reasons='["Anyone unwilling to carry the badge, unless they take the $9 lane"]', rw_gotchas='["Every free launch week was full on 8 September 2026 — weeks 28 through 53, twenty-six weeks out, all marked FULL — so free is a queue with nothing bookable; $9 skips it entirely.","Two upvotes on other startups are required before the submission form will open.","The builder profile needs a surname and it is the public byline, so a Google display name of the product goes out as the maker unless overwritten.","The badge they generate links to your own listing page, not their homepage."]', rw_faq='[{"question":"How long does Post Your Startup approval take?","answer":"No review time is published; free launches run in numbered weeks that have been full."},{"question":"How much does it cost to submit to Post Your Startup?","answer":"Free with a verified badge and a scheduled week. $9 skips the review queue and drops the badge; $299 adds a video on their Instagram and TikTok."},{"question":"Does a Post Your Startup listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 71."},{"question":"Do I need to link back to Post Your Startup?","answer":"Yes — a verified badge is required on the free lane."},{"question":"What gets a submission rejected?","answer":"Refusing the badge unless you take the $9 lane."}]', rw_summary='Post Your Startup is a dofollow launch board where free requires a verified badge, two upvotes and a numbered week. No other backlink is needed; domain rating is 71, and free weeks have been full.', rw_fact_points='["Free launches queue in numbered full weeks","Dofollow link with a badge backlink required","Two upvotes are required before submitting","Accepts indie products, SaaS and AI tools"]', rw_submission_checks='["Expect free weeks to be full; $9 skips the queue.","Give two upvotes before the form opens.","Set a real maker name in the builder profile."]', rw_seo_title='Post Your Startup: Free Badge Launch, DR 71', rw_seo_description='How to launch on Post Your Startup: free dofollow listing with a badge and two upvotes, or $9 to skip. Weeks from the 2026-11-16 snapshot.' WHERE slug='postyourstartup';
UPDATE submission_sites SET rw_source_lead='A general business directory sold by the year, with a Startups shelf and PayPal at the door.', rw_what_you_get='A manually reviewed business listing with a deep link, in a general directory that spans businesses, startups and software.', rw_you_need='["A paid package from $49 a year","A PayPal account — the only online payment accepted","A business name, description and logo"]', rw_eligibility='You need to pay and supply business details. Adult, racist or sexist content, direct-to-consumer medication sales and affiliate-heavy or third-party-product sites are refused.', rw_submit_steps='["1 Pick a package. Submit Listing lands on the plans page: Basic $49 a year, Premium $99 a year or Growth $199 once, priced in USD or INR by region.","2 Join and pay through PayPal.","3 Fill the listing: business details, logo, description, products or services, photos, videos, social links and locations.","4 Wait one to two days. Every listing is manually reviewed in 24 to 48 hours, Monday to Friday, and a refusal comes with no reason."]', rw_submit_requirements='["A business name and description","A logo","An optional website URL","A paid package"]', rw_rejection_reasons='["Adult, racist or sexist content, direct-to-consumer medication sales, and sites that are mostly affiliate links or promote others'' products"]', rw_gotchas='["There is no free lane — Submit Listing redirects to the plans page and the cheapest way in is $49 a year.","PayPal is the only online payment accepted, so a card alone will not get through.","A refusal is final and unexplained; their guidelines say the decision is at their discretion and will not be explained.","Outbound links are nofollow, so the paid placement must justify itself without link equity."]', rw_faq='[{"question":"How long does Zumvu approval take?","answer":"One to two days; manual review is 24 to 48 hours on weekdays."},{"question":"How much does it cost to submit to Zumvu?","answer":"Basic $49 a year, Premium $99 a year, or Growth $199 once. PayPal is the only online payment."},{"question":"Does a Zumvu listing provide a dofollow link?","answer":"No — links from Zumvu are nofollow on a domain rated 72."},{"question":"Do I need to link back to Zumvu?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Adult, racist or sexist content, direct medication sales, or affiliate-heavy sites."}]', rw_summary='Zumvu is a paid general business directory from $49 a year with a dofollow-free listing reviewed in one to two days. No backlink is required and PayPal is the only payment; domain rating is 72.', rw_fact_points='["Manual review takes one to two days","Paid-only from $49/year with nofollow links","No badge or return link is expected","Accepts businesses, startups, software and websites"]', rw_submission_checks='["Expect to pay and to use PayPal.","Have a logo and business description ready.","A refusal comes without explanation; links are nofollow."]', rw_seo_title='Zumvu: $49/yr Business Listing, DR 72', rw_seo_description='How to list on Zumvu: $49+/year business directory, nofollow link, no backlink, PayPal only. Review and rules from the 2026-11-16 snapshot.' WHERE slug='zumvu';
UPDATE submission_sites SET rw_source_lead='One person''s list of the agent tooling they actually run — and there is no form to get into it.', rw_what_you_get='A dofollow entry in a deliberately small, personally curated list of AI coding tools that the owner uses themselves.', rw_you_need='["A tool the owner would install on a machine they care about","Fit one of five sections: coding agents, agent skills, plugins, MCP servers or specs"]', rw_eligibility='You need a tool the owner uses themselves in an AI coding setup. Anything outside the five sections, or a product they have no reason to run, cannot be listed.', rw_submit_steps='["1 Check you belong in one of five sections: tools, agent skills, plugins, MCP servers or resources. Nothing else has a shelf.","2 There is nothing to submit. /submit, /add and /suggest all return 404 and there is no form anywhere on the site.","3 The About page names @m0nle0z on X as the contact for questions about the list — the only route in is to be noticed and adopted."]', rw_submit_requirements='["A live URL","Fit AI coding tooling only","The owner choosing to run it themselves"]', rw_rejection_reasons='["Anything outside an AI coding setup, and any product the owner has no reason to use — they remove entries when they leave their setup"]', rw_gotchas='["There is no way to submit; the list is what one person runs and an entry leaves when it leaves that setup.","It is deliberately small — 44 entries against a 12,000-skill catalogue the author abandoned.","Sponsor logos appear on the home page with no stated way to buy one, so treat that as a private arrangement.","Outbound links are rel=noopener noreferrer but followed — the issue is not link value, it is that you cannot apply."]', rw_faq='[{"question":"How long does agentskills approval take?","answer":"No review time is published; there is no submission route at all."},{"question":"How much does it cost to submit to agentskills?","answer":"There is no submission process; sponsor logos appear but no price or route is published."},{"question":"Does an agentskills listing provide a dofollow link?","answer":"Yes — outbound entries are followed (rel=noopener noreferrer) on a domain rated 10."},{"question":"Do I need to link back to agentskills?","answer":"No backlink is required."},{"question":"What gets a tool rejected?","answer":"Anything outside AI coding tooling, or a product the owner would not use themselves."}]', rw_summary='agentskills is a small, personally curated list of AI coding tools with dofollow entries and no backlink. There is no form — entries are what the owner runs themselves; domain rating is 10.', rw_fact_points='["No submission route; owner-curated","Dofollow entries with no backlink required","No published review time","Accepts coding agents, agent skills, plugins, MCP servers and specs"]', rw_submission_checks='["There is no form — /submit, /add and /suggest all 404.","Fit one of the five AI coding sections.","Entries depend on the owner choosing to use your tool."]', rw_seo_title='agentskills: Curated AI Tooling List, DR 10', rw_seo_description='About agentskills: a personally curated dofollow list of AI coding tools with no form. Why you cannot apply — 2026-11-16 snapshot.' WHERE slug='agentskills-agnxi';
UPDATE submission_sites SET rw_source_lead='Matt Wolfe''s AI catalogue, backed by a large newsletter, where one person reviews every submission and the outbound link is an internal redirect.', rw_what_you_get='An editorial listing in a well-read AI newsletter''s catalogue, with no link equity because the Visit button redirects internally.', rw_you_need='["An AI product — all eighteen categories are AI","A name, URL, short description, category and pricing model","An email address, separate from the optional newsletter opt-in"]', rw_eligibility='You need an AI product and an email. Anything without an AI angle has no category, and a submission nobody editorially picks goes nowhere — the form says Matt reviews it, with no status page.', rw_submit_steps='["1 Open /submit-a-tool. It is a single-page form with no account or login.","2 Fill seven fields: your name optional, tool name, tool URL, a short description, one of eighteen categories, a pricing model of Free, Freemium, Paid or Open Source, and your email.","3 Clear the captcha at the bottom before Submit Tool will post.","4 Wait for an editorial decision. There is no dashboard, reference number or stated turnaround."]', rw_submit_requirements='["A tool name, URL and short description","One of eighteen AI categories","A pricing model of Free, Freemium, Paid or Open Source","An email address","An optional name and newsletter opt-in"]', rw_rejection_reasons='["Anything without an AI angle, since no category would hold it, and a submission nobody editorially picks"]', rw_gotchas='["The Visit button on a live listing points at /go/<slug> on their own domain rather than at the tool, so the placement passes no link value.","A captcha guards the form, so the last step needs a person at the keyboard.","Acceptance is one person''s editorial call with no status page or stated turnaround — a decline is indistinguishable from a wait."]', rw_faq='[{"question":"How long does Future Tools approval take?","answer":"No review time is published; one editor reviews each submission."},{"question":"How much does it cost to submit to Future Tools?","answer":"Submitting is free."},{"question":"Does a Future Tools listing provide a dofollow link?","answer":"No — links are nofollow on a domain rated 69, and the Visit button is an internal redirect."},{"question":"Do I need to link back to Future Tools?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Anything without an AI angle, or a submission the editor does not pick."}]', rw_summary='Future Tools is an AI catalogue with a large newsletter where one editor reviews every free submission. Links are nofollow internal redirects, no backlink is required, and domain rating is 69.', rw_fact_points='["Editorial review with no published timeline","Free submission with nofollow internal links","No badge or return link is expected","Accepts AI tools, productivity, marketing, design and developer tools"]', rw_submission_checks='["Have a clear AI angle to fit a category.","Be ready to solve a captcha.","Expect no link equity — the Visit button redirects internally."]', rw_seo_title='Future Tools: Free AI Listing, DR 69', rw_seo_description='How to submit to Future Tools: free editor-reviewed AI listing with a nofollow internal redirect, no backlink. Captcha and steps from the 2026-11-16 snapshot.' WHERE slug='future-tools';
UPDATE submission_sites SET rw_source_lead='A 400-product SaaS directory where the free tier lends one followed link for a badge, then re-checks that badge forever.', rw_what_you_get='A dofollow listing that is unpublished the moment their regularly checked badge disappears from your site.', rw_you_need='["An account via the Sign In control","Their badge kept on your site permanently, on the free tier","A product fitting one of about thirty categories"]', rw_eligibility='You need an account, a fitting product and — on free — a badge you can keep up. A site you cannot keep a badge on, or a product they decline, is out.', rw_submit_steps='["1 Choose a plan. /pricing lists Basic $9.90, Pro $29.90 and Free $0; each card''s button starts the submission, and the free card notes 364 tools already waiting.","2 Sign in through the Sign In control in the header or mobile menu.","3 Fill the listing with product details and one category, from AI, NoCode and DevTools through Legal, Health and Education.","4 Install and keep the badge. Free tier verification requires it, and the card states they check regularly and unpublish if it is removed.","5 Wait for review. Free listings are reviewed within 30 days and may be rejected; paid listings publish immediately."]', rw_submit_requirements='["An account on the site","A product name, URL and description","One of their categories","Their badge kept permanently, on free","An optional logo"]', rw_rejection_reasons='["A site you cannot keep a badge on, and a product they simply decline — the free card allows for both in as many words"]', rw_gotchas='["The free badge is not a one-time toll: their pricing card says they check regularly and unpublish the listing if it is removed, so the followed link is rented while you advertise them.","A free submission can be refused, with no support channel to ask why, against a 30-day review window.","The free queue is stated on the card — 364 tools waiting against a catalogue of just over 400, so most of the site''s throughput is the queue."]', rw_faq='[{"question":"How long does SaaSFame approval take?","answer":"Two to four weeks; the card states review within 30 days on free."},{"question":"How much does it cost to submit to SaaSFame?","answer":"Free with a kept badge. Basic is $9.90 once for three followed links and no badge; Pro is $29.90 with featured placement and five followed links; a $99 review article is extra."},{"question":"Does a SaaSFame listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 69, while the free badge stays live."},{"question":"Do I need to link back to SaaSFame?","answer":"Yes — the free tier requires a badge kept permanently."},{"question":"What gets a listing rejected?","answer":"A site that will not keep the badge, or a product they decline."}]', rw_summary='SaaSFame is a SaaS directory where a free dofollow listing depends on keeping their badge live; paid tiers remove that requirement. No other backlink is needed; domain rating is 69.', rw_fact_points='["Free review within 30 days; paid is immediate","Dofollow link rented while the badge stays live","A permanent badge is required on free","Accepts SaaS, AI tools, developer tools, no-code, design and marketing tools"]', rw_submission_checks='["Keep the badge live — removal unpublishes you.","Expect a 30-day free review with possible rejection.","Upgrade if you want followed links without a badge."]', rw_seo_title='SaaSFame: Free Badge Listing, DR 69', rw_seo_description='How to submit to SaaSFame: free dofollow listing for a kept badge, 30-day review, or paid instant tiers. No other backlink — 2026-11-16 snapshot.' WHERE slug='saasfame';
UPDATE submission_sites SET rw_source_lead='A marketplace for selling, buying and showing off side projects, where a Showcase listing is free and memberships ration your outreach.', rw_what_you_get='A dofollow project listing in a marketplace of side projects, with the intent — sell, co-founder, showcase or sold — deciding what the page becomes.', rw_you_need='["An account via one of five social providers or email and password","An intent chosen first: sell, co-founder, showcase or sold","A project with a name, description and category"]', rw_eligibility='You need an account and an intent. Nothing structural blocks a Showcase listing; the Sell intent expects something a buyer could actually take over.', rw_submit_steps='["1 Choose an intent. /submit/type is first and decides everything downstream: sell, find a co-founder, showcase, or record a sale.","2 Sign in with Google, GitHub, GitLab, Product Hunt or LinkedIn, or email and password.","3 Fill the project: name, description, one of eight categories and images. A sale listing also carries a price.","4 Publish. Project pages live at /project/<id>/<slug>, with the id assigned rather than derived from the name."]', rw_submit_requirements='["An account via five social providers or email and password","An intent: sell, co-founder, showcase or sold","A project name, description and one of eight categories","Images and, for a sale listing, a price"]', rw_rejection_reasons='["Nothing structural on the Showcase intent; the Sell intent expects a project a buyer could take over"]', rw_gotchas='["The first question is what kind of listing this is, and the answer changes the page — picking Sell puts a for-sale badge on a product you are not selling.","Membership tiers ration outreach, not visibility: even free can list, but it only contacts three owners and sends two direct messages a day, which matters if you are buying.","The free tier is ad-supported with large ads — a full-width sponsor panel covers the lower half of the sign-in page."]', rw_faq='[{"question":"How long does SideProjectors approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to SideProjectors?","answer":"Listing is free and memberships are about using the marketplace: Free is ad-supported with three owner contacts and two DMs a day; Starter $3/month removes ads; Scaler $6 adds saved searches; Unicorn $9 adds analytics."},{"question":"Does a SideProjectors listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 70."},{"question":"Do I need to link back to SideProjectors?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Nothing structural on Showcase; the Sell intent expects a takeable project."}]', rw_summary='SideProjectors is a free dofollow marketplace for side projects where the listing intent decides the page. No backlink is required; memberships ration outreach rather than visibility, and domain rating is 70.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","Accepts indie products, SaaS, web and mobile apps, browser extensions"]', rw_submission_checks='["Choose the right intent first — Sell adds a for-sale badge.","Ignore memberships unless you are buying or need outreach.","Expect large ads on the free tier."]', rw_seo_title='SideProjectors: Free Project Listing, DR 70', rw_seo_description='How to list on SideProjectors: free dofollow side-project listing, no backlink. Intent types and memberships from the 2026-11-16 snapshot.' WHERE slug='sideprojectors';
UPDATE submission_sites SET rw_source_lead='A tool directory whose real asset is the founder newsletter behind it, and whose free tier charges you in upvotes and a badge.', rw_what_you_get='A dofollow listing backed by a large founder newsletter, in exchange for five upvotes, their badge and manual review.', rw_you_need='["An account via email and password or Google","A square logo and a 1200x630 thumbnail","Their badge on your site and five upvotes given to other tools"]', rw_eligibility='You need an account, both images, a badge and five upvotes given. Products with no live URL are refused.', rw_submit_steps='["1 Make an account. The submit route bounces to /auth; email and password work, so the listing need not hang off a personal Google profile.","2 Fill the details: name, a 60-character description, a long description, website, a square logo by URL, a 1200x630 thumbnail, up to three categories and a pricing tier.","3 Answer the plan quiz. Three questions end on a $29 recommendation; the free path is the quiet ''or launch free'' link under the button.","4 Deselect the pre-ticked boost. Starter is $0, but a $29 one-time boost arrives pre-ticked — untick it and check the total reads $0.","5 Clear both gates. Upvote five other tools, then install their badge and let the crawler verify it; then the listing enters manual review."]', rw_submit_requirements='["A 60-character short description","A square logo by URL","A 1200x630 thumbnail by upload","Their badge live on your site","Five upvotes given to other listings","Optional X handle and long description"]', rw_rejection_reasons='["Products with no live URL"]', rw_gotchas='["The $29 boost is pre-selected on the free plan, so the button reads Continue - $29 today until you untick it.","Free bills you in attention: five upvotes on other tools before the listing is allowed live.","Your account display name becomes the public byline, so fix it before submitting."]', rw_faq='[{"question":"How long does Launch Llama approval take?","answer":"No review time is published; the listing enters manual review after both gates."},{"question":"How much does it cost to submit to Launch Llama?","answer":"Free with badge and upvotes. $29 skips review; $24/month pins you to the top."},{"question":"Does a Launch Llama listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 67."},{"question":"Do I need to link back to Launch Llama?","answer":"Yes — their badge is required on the free lane."},{"question":"What gets a submission rejected?","answer":"Products with no live URL."}]', rw_summary='Launch Llama is a directory backed by a founder newsletter where a free dofollow listing requires a badge and five upvotes. No other backlink is needed; domain rating is 67.', rw_fact_points='["Manual review after badge and upvote gates","Free listing with a dofollow link","A badge and five upvotes are required","Accepts SaaS, AI tools, developer tools, indie products and marketing tools"]', rw_submission_checks='["Untick the pre-checked $29 boost before submitting.","Give five upvotes to other tools.","Set a real maker name before submitting."]', rw_seo_title='Launch Llama: Free Badge Launch, DR 67', rw_seo_description='How to submit to Launch Llama: free dofollow listing for a badge and five upvotes, or $29 to skip. Pre-ticked boost warning from the 2026-11-16 snapshot.' WHERE slug='launch-llama';
UPDATE submission_sites SET rw_source_lead='A weekly startup board with a hundred free spots a week, paid for with a badge that carries a live upvote count.', rw_what_you_get='A dofollow listing in a weekly launch board, in exchange for their badge rendered on your site with a live upvote count.', rw_you_need='["A live product URL","Their badge live on your site on the free lane","A Google, GitHub or email account"]', rw_eligibility='You need a live URL, an account and — on free — their badge. Products with no working URL are refused.', rw_submit_steps='["1 Sign in with Google, GitHub or email. Creating an account subscribes you to their newsletter, stated in the line under the button.","2 Basics: pick a launch week from four, then website URL, startup name and tagline. An Auto-fill button drafts the lot from the URL.","3 Details: a markdown description, one of eighteen categories and up to eight tech-stack tags.","4 Media: a logo and up to six screenshots, each uploaded or given as a URL, plus an optional demo video.","5 Tier, then verify the badge. Free needs it; Featured and up skip it. Their server fetches the page you name and looks for the badge before Submit for review unlocks."]', rw_submit_requirements='["Their badge live on your site pointing at your listing, on free","A launch week from the next four","An optional square logo up to 2MB or a logo URL","Optional screenshots up to 4MB each, six maximum"]', rw_rejection_reasons='["Products with no working URL"]', rw_gotchas='["Their badge must point at your listing page rather than their homepage, so it cannot be added before the wizard reserves a slug for you.","The badge image renders a live upvote count fetched from their servers, so it is a script on your page as well as a link.","A site that hides the badge in an iframe — they name Wix and Framer — must prove ownership with a DNS TXT record instead."]', rw_faq='[{"question":"How long does Launchpadly approval take?","answer":"Three to five days."},{"question":"How much does it cost to submit to Launchpadly?","answer":"There is a free lane with a badge. Featured is $9 and skips the review and badge; Premium is $29 with an SEO review and newsletter slot; Social Boost is $149."},{"question":"Does a Launchpadly listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 67."},{"question":"Do I need to link back to Launchpadly?","answer":"Yes — the free lane requires their badge on your site."},{"question":"What gets a submission rejected?","answer":"Products with no working URL."}]', rw_summary='Launchpadly is a weekly startup board with a free dofollow listing paid for with their live-count badge. No other backlink is required; domain rating is 67 and review takes three to five days.', rw_fact_points='["Review takes three to five days","Free listing with a dofollow link","A badge backlink is required on free","Accepts startups, SaaS, AI tools and indie products"]', rw_submission_checks='["Install the badge after your listing slug is reserved — it must point to your listing.","Expect a live-count script on your page.","Wix/Framer users must prove ownership via DNS TXT."]', rw_seo_title='Launchpadly: Free Badge Launch, DR 67', rw_seo_description='How to launch on Launchpadly: free dofollow weekly board with a live-count badge, no other backlink. Steps from the 2026-11-16 snapshot.' WHERE slug='launchpadly';
UPDATE submission_sites SET rw_source_lead='Three routes in, where the plain free one is explicitly no-dofollow and the badge route is the one that actually passes link equity.', rw_what_you_get='A dofollow listing via the badge-funded free route, or immediate placement with multiple links on the paid route, in a daily launch directory.', rw_you_need='["An account via the Sign In control","One clean product URL","Their badge on your homepage, for the free route with a followed link"]', rw_eligibility='You need an account and a clean URL. A homepage you cannot add a badge to rules out the followed-link free route, which states the plain free option carries no dofollow.', rw_submit_steps='["1 Share your homepage. Step one is a single field: one clean product URL, used to prepare the listing''s starting details.","2 Choose a publishing route. Free Submission has no badge and no followed link, reviewed within seven days; Backlink Submission puts their badge on your homepage for one followed link after manual review; Paid Submission is $9.99, immediate, with six or more followed links.","3 Complete the listing they build from your URL and input: logo, description, screenshots, categories, pricing and website link.","4 Review and go live. Both free routes go through manual review; the paid route skips verification."]', rw_submit_requirements='["An account on the site","One clean product URL","Their badge on your homepage for the Backlink route","Logo, description, screenshots, categories and pricing","Promotion placement is sold separately and is not in any tier"]', rw_rejection_reasons='["A homepage you cannot add a badge to, if a followed link is the point — the plain free route states no dofollow links"]', rw_gotchas='["The route named Free Submission states no dofollow backlinks on its own card. The followed-link route is Backlink Submission, also free but wanting a badge, and the two sit side by side with the wrong one recommended by name.","Hall of Fame placement is earned by votes and is not in any submission tier, which the page says but the tier names imply otherwise.","Promotion placements — featured card, homepage strip, sidebar — are bought separately and excluded from all three routes, including the $9.99 one."]', rw_faq='[{"question":"How long does SimilarLabs approval take?","answer":"About a week on the free routes; the paid route is immediate."},{"question":"How much does it cost to submit to SimilarLabs?","answer":"Paid Submission is $9.99: no badge, no verification, live immediately with at least six followed links. The two free routes differ only in whether you display their badge, and the badge route is the one carrying a followed link."},{"question":"Does a SimilarLabs listing provide a dofollow link?","answer":"Yes, on the Backlink and Paid routes — the plain free route is explicit about no followed links. Domain rating is 68."},{"question":"Do I need to link back to SimilarLabs?","answer":"Only on the Backlink route; the plain free and paid routes need no return link."},{"question":"What gets a listing rejected?","answer":"A homepage that cannot carry a badge, if a followed link is the goal."}]', rw_summary='SimilarLabs is a daily launch directory with three routes: a plain free one with no followed link, a badge-funded free one with a followed link, and $9.99 for instant multi-link placement. Domain rating is 68.', rw_fact_points='["Free review within about a week; paid is immediate","Followed link only on the badge or paid routes","A badge is needed for the free followed link","Accepts AI tools, SaaS, developer tools, design, marketing and indie products"]', rw_submission_checks='["Pick Backlink Submission, not plain Free, if you want a followed link.","Do not expect promotion placement in any tier.","Hall of Fame is vote-earned, not purchased."]', rw_seo_title='SimilarLabs: Free Badge Launch, DR 68', rw_seo_description='How to submit to SimilarLabs: free no-dofollow route or badge-funded followed link, or $9.99 instant. Route differences from the 2026-11-16 snapshot.' WHERE slug='similarlabs';
UPDATE submission_sites SET rw_source_lead='A weekly board with thirty free verified slots, a queue about 150 deep, and a badge you install to earn the free one.', rw_what_you_get='A dofollow launch listing, free with a verified badge after a long queue, or same-week with a paid tier.', rw_you_need='["An account via Google or email and password","A product name, a tagline under 200 characters and a square logo over 512px","A live URL and their badge on your site for the free lane"]', rw_eligibility='You need an account, full product details, a logo and — on free — a badge. A product already launched here needs a paid tier, and a site you cannot badge is out on free.', rw_submit_steps='["1 Create an account. Continue with Google or email and password; sign-in is behind Cloudflare Turnstile, which the email route can stall on.","2 Step 1, product details. An AI Import box fills from your URL, then name, a 200-character tagline, a logo under 5MB and at least 512px, up to four screenshots, website, optional YouTube, a description, pricing model and a checkbox declaring this is the first submission.","3 Step 2, launch setup. Choose the tier and week. Free takes the next of 30 verified slots a week; Premium and Launch Everywhere go out the same week with no queue.","4 Verify the badge if free. The listing shows on the home page but is only verified once their badge is on your site; paid tiers verify instantly and skip the badge.","5 Step 3, submitted for review. Nothing is submitted until this step; every launch, free or paid, is reviewed before publishing."]', rw_submit_requirements='["An account via Google or email and password","A product name and tagline under 200 characters","A logo under 5MB, square, at least 512x512","A live website URL and a description","Their badge on your site for the free lane","Optional screenshots, YouTube URL, pricing and lifetime-deal block"]', rw_rejection_reasons='["A product already launched here — the checkbox declares it is a first submission, and relaunches need a paid tier, and a site you cannot badge on free"]', rw_gotchas='["Paying $19 is the difference between this week and six weeks out: free is a queue against 30 slots a week with about 150 products ahead.","The free badge is what makes the listing verified; take it down and the verification goes with it.","A product gets one free launch. The final checkbox declares it has not been submitted before, and every relaunch must be paid.","The Featured Spot is advertising, stays out of the ranking and has a sponsored link — easy to miss beside the $19 tier."]', rw_faq='[{"question":"How long does Smol Launch approval take?","answer":"One to two months on free; paid tiers launch the same week."},{"question":"How much does it cost to submit to Smol Launch?","answer":"Free with a verified badge and a queued week. Premium is $19 a launch with no queue or badge and a permanent link; Launch Everywhere is $99-$199 for done-for-you directory submissions; a $99/year Maker Pass makes every launch Premium."},{"question":"Does a Smol Launch listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 68."},{"question":"Do I need to link back to Smol Launch?","answer":"Yes — the free lane requires their badge on your site."},{"question":"What gets a listing rejected?","answer":"A product already launched here, or a site that cannot carry the badge on free."}]', rw_summary='Smol Launch is a weekly board where a free dofollow listing needs a badge and waits in a long queue; $19 launches the same week. No other backlink is required; domain rating is 68.', rw_fact_points='["Free queue runs one to two months; paid is same-week","Dofollow listing with a badge required on free","A first-submission declaration gates free","Accepts SaaS, indie products, AI tools, developer tools and no-code"]', rw_submission_checks='["Expect weeks of queue on free, or pay $19.","Keep the badge live — verification depends on it.","Confirm this is your first launch here; relaunches are paid."]', rw_seo_title='Smol Launch: Free Badge Launch, DR 68', rw_seo_description='How to launch on Smol Launch: free dofollow listing with a badge and a long queue, or $19 same-week. Rules from the 2026-11-16 snapshot.' WHERE slug='smol-launch';
UPDATE submission_sites SET rw_source_lead='Thirty dollars for a listing, fifty if you want a video with it.', rw_what_you_get='A dofollow listing with English editorial copy written to their category system, with an optional launch video added after publication.', rw_you_need='["A live product URL","Editorial context written in English","A payment of $29 or $49"]', rw_eligibility='You need a live URL, an English paragraph and payment. Anyone not paying is excluded, since both plans are paid.', rw_submit_steps='["1 Pick a package: Listing, or Listing plus a video added after publication.","2 Fill the form with a name, category, URL and an editorial context section they ask for in English.","3 Pay. The whole form is behind the payment; there is no free path through it."]', rw_submit_requirements='["A paragraph of editorial context, in English"]', rw_rejection_reasons='["Anyone not paying, since both plans are paid"]', rw_gotchas='["Both plans are paid and the cheaper one is a listing rather than a review.","They ask for editorial context in English specifically, so copy in another language needs translating first.","Category guidance is opinionated — APIs and SDKs belong in Code and IT, personal workflow tools in Productivity — and picking against it files you where nobody looks."]', rw_faq='[{"question":"How long does AIToolly approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to AIToolly?","answer":"Listing is $29.99, reduced from $49.99; Listing plus an English launch video is $49.99, reduced from $69.99. There is no free lane."},{"question":"Does an AIToolly listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 66."},{"question":"Do I need to link back to AIToolly?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Anyone not paying — both plans are paid."}]', rw_summary='AIToolly is a paid-only AI directory with a $29.99 dofollow listing or $49.99 with a launch video. No backlink is required; domain rating is 66 and copy must be in English.', rw_fact_points='["Paid-only from $29.99 with no published review time","Dofollow listing with no backlink","No badge or return link is expected","Accepts AI tools, SaaS and developer tools"]', rw_submission_checks='["Expect to pay — there is no free lane.","Write the editorial context in English.","Choose the category their guidance recommends."]', rw_seo_title='AIToolly: $29.99 AI Listing, DR 66', rw_seo_description='How to submit to AIToolly: paid $29.99 dofollow AI listing or $49.99 with video, no backlink. English copy required — 2026-11-16 snapshot.' WHERE slug='aitoolly';
UPDATE submission_sites SET rw_source_lead='A 30,000-tool AI directory whose free lane is advertised in its own statistics and cannot be found anywhere on the page.', rw_what_you_get='A paid placement in a large AI directory; the followed backlink appears only from the mid-tier plan up, and listing links are otherwise nofollow.', rw_you_need='["A Google account — the only sign-in","A tool with an AI angle, since every category is an AI bucket","A logo, a category and a pricing model"]', rw_eligibility='You need a Google account and an AI product. Anything without an AI story has no category in a directory organised entirely around AI.', rw_submit_steps='["1 Sign in with Google — the only route, creating the account in place.","2 Read pricing before looking for a form. Four cards run $29 to $149; the $29 card marks lifetime SEO backlink with a cross and the $39 card with a tick, where the followed link starts.","3 Look for the free lane. Their statistics panel quotes a 2-3 day review for free submissions, but every button on the page is a paid tier.","4 Check the dashboard for what landed. Submitted Tools shows a Total Tools count, the only reliable way to tell if anything arrived."]', rw_submit_requirements='["A Google account","A tool name and website URL","A short description","A logo and a category","A pricing model"]', rw_rejection_reasons='["Anything with no AI story, in a directory organised entirely as AI categories"]', rw_gotchas='["The followed backlink is a paid feature stated plainly in the pricing table: the $29 card has a cross against it and the $39 card a tick. The hero''s lifetime do-follow claim is describing the paid plans.","The free lane is advertised but not offered: their statistics quote a free review time and there is no free button anywhere, signed in or out.","Launch Now on the paid cards did nothing when pressed while signed in — no dialog, navigation or checkout. Budget for the submission not working rather than being quick."]', rw_faq='[{"question":"How long does AITrendyTools approval take?","answer":"One to two days, though the free review time they quote cannot be acted on."},{"question":"How much does it cost to submit to AITrendyTools?","answer":"Four one-time plans: $29 Quick Launch without a backlink, $39 with the backlink and a newsletter mention, $99 for a guest post, $149 for a sponsored newsletter feature. A free lane is implied but has no button."},{"question":"Does an AITrendyTools listing provide a dofollow link?","answer":"No — site links are nofollow on a domain rated 65; the followed backlink is sold from the $39 plan up."},{"question":"Do I need to link back to AITrendyTools?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Anything with no AI story."}]', rw_summary='AITrendyTools is a large AI directory where a followed backlink is a paid extra from $39 and ordinary listing links are nofollow. No backlink is required; domain rating is 65, and the advertised free lane has no button.', rw_fact_points='["No published action for the free lane","Paid plans from $29; followed link from $39","Listing links are nofollow, no backlink required","Accepts AI tools, developer tools and marketing tools"]', rw_submission_checks='["The followed link starts at the $39 tier, not $29.","There is no free button despite the statistics panel.","Check the dashboard to confirm anything landed."]', rw_seo_title='AITrendyTools: $39 AI Listing, DR 65', rw_seo_description='How to submit to AITrendyTools: paid $29-$149 AI listing, followed link from $39, no backlink. Missing free lane from the 2026-11-16 snapshot.' WHERE slug='aitrendytools';
UPDATE submission_sites SET rw_source_lead='A free four-step form that grades your description out of 100 before it will let you submit.', rw_what_you_get='A dofollow listing whose quality depends on an 800-character description the form scores as you write it.', rw_you_need='["An account via Google or email","A description of at least 800 characters and a tagline of 55 to 95","A logo file under 2MB"]', rw_eligibility='Nothing is refused by category, but the form will not pass step one on a thin description — 800 characters is a hard floor scored live out of 100.', rw_submit_steps='["1 Make an account. /submit shows a sign-in wall; Continue with Google or email and a nine-character password. The newsletter checkbox is pre-ticked.","2 Step 1, Core Details: name, an auto-generated slug, website, a tagline of 55 to 95 characters and the long description. An Affiliate Consent checkbox, off by default, lets them replace your link with an affiliate one.","3 Step 2, Classification: one of twelve categories, one of four pricing badges, any of seven roles with one primary, and any of five platforms.","4 Step 3, Media: a required logo by file or URL, plus an optional 1200x630 banner converted to WebP.","5 Step 4, Features and Pricing: up to four key features of 80 characters, then optional pricing plans, pros and FAQs. Add Tool submits it."]', rw_submit_requirements='["A live URL and account","A tagline of 55 to 95 characters","A description of 800 to 2,500 characters","One category, a pricing badge and optional roles and platforms","A logo in SVG, PNG or JPG up to 2MB","Optional banner, features, pricing plans, pros and FAQs"]', rw_rejection_reasons='["Nothing by category, but a description under 800 characters cannot pass step one, where the field scores it out of 100"]', rw_gotchas='["The description has an 800-character floor and a live grader scoring length, tool name, hook, structure, audience, verbs and filler out of 100; it tells you to stop opening with the product name and to name your audience.","Step 1 has an Affiliate Consent checkbox letting them replace your link with an affiliate one. It is off by default; turning it on hands over that right.","The signup form ticks its newsletter box for you — untick it if unwanted.","The sponsored panel beside the form advertises a rival directory-submission service with its own referral parameter."]', rw_faq='[{"question":"How long does FutureStack approval take?","answer":"One to two days."},{"question":"How much does it cost to submit to FutureStack?","answer":"Submitting is free."},{"question":"Does a FutureStack listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 5."},{"question":"Do I need to link back to FutureStack?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Nothing by category, but a description under 800 characters cannot pass step one."}]', rw_summary='FutureStack is a free four-step directory listing with a dofollow link and no backlink, but it grades your description and requires 800 characters. Domain rating is 5.', rw_fact_points='["Free listing in one to two days","Dofollow link with no backlink requirement","An 800-character graded description is mandatory","Accepts AI tools, agents, SaaS and marketing tools"]', rw_submission_checks='["Write a real 800+ character description, not a tagline.","Leave Affiliate Consent off unless you mean it.","Untick the pre-ticked newsletter box if unwanted."]', rw_seo_title='FutureStack: Free Graded Listing, DR 5', rw_seo_description='How to submit to FutureStack: free dofollow listing with an 800-character graded description, no backlink. Form traps from the 2026-11-16 snapshot.' WHERE slug='futurestack';
UPDATE submission_sites SET rw_source_lead='A similar-sites finder where you list yourself by searching your own domain, past a Cloudflare check and a one-letter robot question — for a nofollow link.', rw_what_you_get='A listing in a similar-sites directory, approved on the spot but passing no link equity.', rw_you_need='["A website URL — the whole submission","Content suitable for all ages","A person to clear the Cloudflare check and a word question"]', rw_eligibility='You need a URL and all-ages content. Adult, gambling and phishing sites, and anything judged unsuitable for children, are refused.', rw_submit_steps='["1 Search for your own domain. There is no submit link: /add-site says to type your URL on the homepage and press Search; an unknown domain lands on /new-site.","2 Pass the Cloudflare check. Searching an unknown domain shows a Verify you are human box that a person must tick.","3 Check the domain, then fill the form. /new-site asks for the URL and a Check First button before accepting anything, then a title, description, keywords, up to three similar sites and a robot question: the last letter of the word NOSPAM.","4 Get approved immediately — though one run found the published page used the site''s own meta title and description rather than what was typed.","5 To appear on a competitor''s list, search that site, scroll to the bottom of its page and use the form there; that one is reviewed by hand."]', rw_submit_requirements='["A website URL","A title, description and keywords","Up to three similar sites","An answer to the robot question — the last letter of NOSPAM"]', rw_rejection_reasons='["Adult, gambling and phishing sites, and anything they judge unsuitable for children"]', rw_gotchas='["An unknown domain triggers a Cloudflare human check and the form ends with a text question, both aimed at exactly this kind of automated submission.","The link is nofollow — outbound anchors carry rel=external nofollow noopener, whatever the instant approval suggests.","Getting onto a specific competitor''s alternatives page is a second, hand-reviewed submission at the bottom of that competitor''s page.","The unsuitable-for-children rule is broad; one run saw a page held until a manual safety review was requested."]', rw_faq='[{"question":"How long does Sitelike approval take?","answer":"Instant, though getting onto a competitor''s page is a separate manual review."},{"question":"How much does it cost to submit to Sitelike?","answer":"Submitting is free."},{"question":"Does a Sitelike listing provide a dofollow link?","answer":"No — links are nofollow on a domain rated 66."},{"question":"Do I need to link back to Sitelike?","answer":"No backlink is required."},{"question":"What gets a site rejected?","answer":"Adult, gambling and phishing sites, or anything judged unsuitable for children."}]', rw_summary='Sitelike is a free similar-sites directory with instant approval and a nofollow link. You list yourself by searching your own domain and passing a human check; no backlink is required and domain rating is 66.', rw_fact_points='["Instant approval after human checks","Free submission with a nofollow link","No badge or return link is expected","Accepts websites, SaaS, marketing tools and web apps"]', rw_submission_checks='["Expect a Cloudflare check and a word question.","The link earns no equity — judge it on discovery.","A competitor page listing is a separate manual submission."]', rw_seo_title='Sitelike: Free Similar-Sites Listing, DR 66', rw_seo_description='How to submit to Sitelike: free instant similar-sites listing with a nofollow link, no backlink. Human checks and steps from the 2026-11-16 snapshot.' WHERE slug='sitelike';
UPDATE submission_sites SET rw_source_lead='A tools directory that reviews in two days and gives every listing a followed link — as long as their badge is in your footer.', rw_what_you_get='A dofollow listing reviewed within two days, with the free lane priced by a permanent footer badge.', rw_you_need='["An account behind the Sign In control","A tool URL, name, a tagline under 160 and a 500+ character description","A logo under 500kb and their footer badge on the free lane"]', rw_eligibility='You need an account, full tool details, a small logo and — on free — a footer badge. A product you cannot write 500 characters about, or a site you cannot badge, is out.', rw_submit_steps='["1 Sign in. The /submit page renders signed out with every field visible, but Sign In is the real first step and nothing posts without it.","2 Tool Information, step 1 of 2: tool URL with an AI auto-fill button, then name, a 160-character tagline, a Markdown description of 500 to 5,000 characters, a logo under 500kb, up to four screenshots, one to three categories, pricing and platforms.","3 Add the optional block: discount code, founded year, YouTube demo, GitHub repo, founder''s Twitter and affiliate programme.","4 Choose a submission type, step 2: $9.99 lifetime, $19.99 featured, or free, which asks you to place their badge embed on your site.","5 Wait for the two-day review; paid lanes are effectively immediate."]', rw_submit_requirements='["An account on the site","A tool URL, name and a tagline under 160 characters","A Markdown description of 500 to 5,000 characters","A logo under 500kb in SVG, WebP, PNG or JPG","One to three categories, a pricing model and platforms","Their badge on your site for the free lane","Optional screenshots, video, repo and social details"]', rw_rejection_reasons='["A product you cannot write 500 characters about, and a site you cannot add a footer badge to unless you take the $9.99 lane"]', rw_gotchas='["The description has a 500-character floor enforced by a counter, longer than the blurb most makers arrive with and not announced before you start typing.","The free lane''s price is a permanent footer badge on your own site — the same trade the $9.99 tier buys you out of, worded as a free-plan benefit.","The logo cap is 500kb, an order of magnitude tighter than the 5MB allowed per screenshot, so the small asset is the one likely to be rejected."]', rw_faq='[{"question":"How long does ToolDirs approval take?","answer":"One to two days; the free lane states review within two days."},{"question":"How much does it cost to submit to ToolDirs?","answer":"Free with a footer badge. $9.99 once for a lifetime listing with no badge, 40% off with the EARLY1 code; Featured is $19.99, reduced to $14.99 for a first month, with premium placement and ten or more followed links."},{"question":"Does a ToolDirs listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 66."},{"question":"Do I need to link back to ToolDirs?","answer":"Yes — the free lane requires their badge in your footer."},{"question":"What gets a listing rejected?","answer":"A product you cannot describe in 500 characters, or a site that cannot carry the badge unless you pay."}]', rw_summary='ToolDirs is a tools directory with a free dofollow listing reviewed in two days and priced by a permanent footer badge. No other backlink is required; domain rating is 66.', rw_fact_points='["Two-day review on free; paid is immediate","Dofollow listing with a badge required on free","A 500-character description floor applies","Accepts AI tools, SaaS, developer tools and software"]', rw_submission_checks='["Write 500+ characters before starting — the counter enforces it.","Host their badge in your footer for the free lane.","Keep the logo under 500kb."]', rw_seo_title='ToolDirs: Free Badge Listing, DR 66', rw_seo_description='How to submit to ToolDirs: free dofollow listing with a footer badge and two-day review, or $9.99 without. Steps from the 2026-11-16 snapshot.' WHERE slug='tooldirs';
UPDATE submission_sites SET rw_source_lead='An AI directory whose free tier gives three followed links for a backlink — and keeps the listing only as long as that backlink stays live.', rw_what_you_get='Three dofollow links that last exactly as long as your backlink to them stays on your site.', rw_you_need='["A backlink to them on your site, on the free tier","An account via Google, GitHub or email and password","A live AI product with a name and description"]', rw_eligibility='You need an account, an AI product and — on free — a backlink you can keep up. A site you cannot keep a backlink on is out, since the listing is removed when the link goes.', rw_submit_steps='["1 Get past the bot check. Cloudflare interposes a security page for several seconds before anything renders.","2 Sign in. /submit redirects to /auth/login with a callback; Google, GitHub or email and password.","3 Pick a tier on /pricing. Free, Pro at GBP 9.90 once, a GBP 29.90 monthly subscription or a GBP 19.90 weekly sponsor slot; the free card is last.","4 Add the backlink and choose a date. Free requires a link to them and lets you pick a publish date, with review and listing within 72 hours."]', rw_submit_requirements='["An account via Google, GitHub or email and password","A backlink to them on your site, on free","A product name, live URL and description","An optional logo and preferred publish date"]', rw_rejection_reasons='["A site you cannot keep a backlink on, since the free listing is removed when the link goes"]', rw_gotchas='["The free listing lasts exactly as long as your backlink: their card says permanent listing as long as the backlink stays live, so the three followed links are rented rather than earned.","Prices are in pounds, not dollars, easy to misread on a site whose peers quote USD.","Cloudflare''s verification page sits in front of every route for several seconds, so the site looks down to anything that does not wait."]', rw_faq='[{"question":"How long does AIDirs approval take?","answer":"Three to five days; free states review and listing within 72 hours."},{"question":"How much does it cost to submit to AIDirs?","answer":"Free with a backlink. Pro is GBP 9.90 once for three or more followed links with no backlink and priority review; GBP 29.90 monthly covers unlimited submissions; sponsor is GBP 19.90 a week."},{"question":"Does an AIDirs listing provide a dofollow link?","answer":"Yes, three followed links on a domain rated 64, while your backlink stays live."},{"question":"Do I need to link back to AIDirs?","answer":"Yes — the free tier requires a backlink kept on your site."},{"question":"What gets a listing rejected?","answer":"A site that cannot keep the backlink live."}]', rw_summary='AIDirs is an AI directory where three dofollow links come free in exchange for a backlink you must keep live. No other requirement; domain rating is 64 and review takes three to five days.', rw_fact_points='["Free listing reviewed within 72 hours","Three followed links rented while your backlink lives","A backlink is required on free","Accepts AI tools, SaaS, developer tools and productivity tools"]', rw_submission_checks='["Keep the backlink live — removal delists you.","Prices are in GBP, not USD.","Wait out the Cloudflare check on every route."]', rw_seo_title='AIDirs: Free Backlink Listing, DR 64', rw_seo_description='How to submit to AIDirs: free three-link dofollow listing for a kept backlink, no other requirement. GBP pricing from the 2026-11-16 snapshot.' WHERE slug='aidirs';
UPDATE submission_sites SET rw_source_lead='One plan, ten dollars, and a PayPal checkout between you and a listing.', rw_what_you_get='A dofollow listing reviewed within three business days, with the category assigned by their reviewers.', rw_you_need='["A $10 payment through PayPal","A founder or company name, a contact email and a logo URL","A new tool not already listed"]', rw_eligibility='You need to pay $10 and supply basic details. Listings that already exist are rejected, since the form only takes new public tool entries.', rw_submit_steps='["1 Read the single plan. /services-plan lists exactly one option: Paid Submit at $10 once, reviewed within three business days.","2 Fill the details: tool name, website, founder or company, contact email, pricing model, a short intro, a logo URL and an optional backlink URL. The primary category is assigned by reviewers, not by you.","3 Pay through PayPal. The form action reads Continue to PayPal - $10, and payment places the submission into pending review."]', rw_submit_requirements='["A tool name and website","A founder or company name","A contact email","A logo URL","A $10 payment","Optional product details, features and a backlink URL"]', rw_rejection_reasons='["Listings that already exist — only new public tool entries go through this form"]', rw_gotchas='["There is exactly one plan and it is paid, so the sales and submit pages are the same decision: ten dollars or nothing.","The category you would choose is assigned in review, so placement is out of your hands.","Ranking is by on-site click data collected after launch, so a new listing starts with nothing."]', rw_faq='[{"question":"How long does Toolsfine approval take?","answer":"Three to five days; they state review within three business days."},{"question":"How much does it cost to submit to Toolsfine?","answer":"$10 once, the only plan. Featured placement is limited to five concurrent homepage slots and queues after approval."},{"question":"Does a Toolsfine listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 64."},{"question":"Do I need to link back to Toolsfine?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"A tool already listed — only new public entries are accepted."}]', rw_summary='Toolsfine is a paid-only $10 AI directory with a dofollow listing reviewed in three business days. No backlink is required; domain rating is 64 and the category is reviewer-assigned.', rw_fact_points='["Paid-only at $10 with a three-day review","Dofollow listing with no backlink","No badge or return link is expected","Accepts AI tools and SaaS products"]', rw_submission_checks='["Expect to pay $10 via PayPal — the only plan.","Your category is assigned by reviewers.","Only new tools are accepted."]', rw_seo_title='Toolsfine: $10 AI Listing, DR 64', rw_seo_description='How to submit to Toolsfine: $10 one-time dofollow AI listing in three days, no backlink. PayPal-only process from the 2026-11-16 snapshot.' WHERE slug='toolsfine';
UPDATE submission_sites SET rw_source_lead='The submit button is named after the gate: it reads Verify Backlink to Submit and stays dead until a crawler finds your badge.', rw_what_you_get='A dofollow listing that only exists once their badge is verified live on your site.', rw_you_need='["A Google account or an email address","Their badge on your site before the form will submit at all","A category from their fixed list"]', rw_eligibility='You need an account, a badge and a fixed-list category. A product whose name contains characters like plus signs or ampersands is refused by the name field.', rw_submit_steps='["1 Sign in with Google or an email address at /auth/signin. The profile page shows a Total Listings counter, the honest way to confirm a submission later.","2 Open Submit Listing. The header menu offers Submit Listing and Premium Submit; the free form is at /submit.","3 Fill the listing: a URL with an AI Autofill button, a featured image, a category and optional subcategory, name, tagline and a rich-text description.","4 Verify the badge, then submit. The button is disabled and labelled Verify Backlink to Submit; press Verify Backlink, and on success it becomes Verified - Ready to Submit with a Submit & Go Live button."]', rw_submit_requirements='["A product URL, name and tagline","A category from their list","Their badge live on your site before submitting","An optional featured image up to 16MB and a subcategory"]', rw_rejection_reasons='["A product whose name contains characters like plus signs or ampersands, which the name field refuses"]', rw_gotchas='["The badge is not a follow-up step: the submit button is disabled until it is live, so no listing exists without it.","The name field refuses special characters like pluses and ampersands, quietly ruling out some products.","It is one of a family run together — EarlyHunt, IndieHunt, MakerHunt, SideHunt and Rank++ — so a listing here is not independent coverage."]', rw_faq='[{"question":"How long does Uno Directory approval take?","answer":"Instant once the badge verifies."},{"question":"How much does it cost to submit to Uno Directory?","answer":"There is a free lane with a badge. A Premium Submit lane in the same menu drops the badge requirement."},{"question":"Does a Uno Directory listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 64."},{"question":"Do I need to link back to Uno Directory?","answer":"Yes — the badge is required before the form will submit."},{"question":"What gets a submission rejected?","answer":"A product name containing special characters like plus signs or ampersands."}]', rw_summary='Uno Directory is a free dofollow listing whose submit button stays disabled until a crawler verifies your badge. A backlink is required; domain rating is 64 and part of a shared directory family.', rw_fact_points='["Listings go live instantly after verification","Free listing with a dofollow link","A badge backlink is required","Accepts SaaS, AI tools, productivity and dev tools"]', rw_submission_checks='["Install the badge before starting — the form will not submit without it.","Avoid plus signs and ampersands in your product name.","Note it shares a codebase with several sister directories."]', rw_seo_title='Uno Directory: Free Badge Listing, DR 64', rw_seo_description='How to submit to Uno Directory: free dofollow listing gated on a verified badge, no other backlink. Name and family caveats from the 2026-11-16 snapshot.' WHERE slug='uno-directory';
UPDATE submission_sites SET rw_source_lead='The same three-followed-links-for-a-badge trade as its siblings, from the same codebase.', rw_what_you_get='A dofollow listing with up to three links, gated on a permanent badge, reviewed a handful at a time each day.', rw_you_need='["A Google or GitHub account, or email and password","Their badge kept on your site","A square icon and a 16:9 image, each under 1MB"]', rw_eligibility='You need an account, a badge you will keep and both images. Anything you are unwilling to keep a permanent badge for is out, since the free card will not submit without one.', rw_submit_steps='["1 Sign in with Google, GitHub or email and password at the login /submit redirects to.","2 Fill the details step: link, name, categories and tags, a short description and a markdown introduction, with optional YouTube and GitHub fields.","3 Upload the images: a 1:1 icon and a 16:9 image, each under 1MB, then Submit to create the product.","4 Verify the badge. On the plan page the free card carries Verify Backlink; passing the check turns it into Go dashboard and Wait."]', rw_submit_requirements='["A product URL, name, categories and tags","A short description and a markdown introduction","A square icon and a 16:9 image, each under 1MB","Their badge on your site","Optional YouTube and GitHub links"]', rw_rejection_reasons='["Anything you are unwilling to keep a permanent badge for, since the free card will not submit without one"]', rw_gotchas='["The free card reviews five listings a day, the same ration as its siblings, so the queue rather than the badge is what costs time.","The badge must verify before the free card will submit at all.","Its sponsor row is filled with sibling directories such as Starter Best — a fair warning about who is reading."]', rw_faq='[{"question":"How long does Days Launch approval take?","answer":"Three to five days; the free card reviews five listings a day."},{"question":"How much does it cost to submit to Days Launch?","answer":"Free with a kept badge. Pro is $9.9 once with no backlink and instant publishing; Sponsor is $19.9 a week for site-wide placement."},{"question":"Does a Days Launch listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 62."},{"question":"Do I need to link back to Days Launch?","answer":"Yes — the free lane requires their badge kept on your site."},{"question":"What gets a listing rejected?","answer":"Anything you will not keep a permanent badge for."}]', rw_summary='Days Launch is a free dofollow directory where a permanent badge unlocks the listing and review runs five a day. No other backlink is required; domain rating is 62.', rw_fact_points='["Free review at five listings a day","Dofollow link with a badge required","A permanent badge gates submission","Accepts SaaS, indie products, AI tools and marketing tools"]', rw_submission_checks='["Keep the badge live — the form will not submit without it.","Expect a daily review cap.","Note the shared codebase with sibling directories."]', rw_seo_title='Days Launch: Free Badge Listing, DR 62', rw_seo_description='How to submit to Days Launch: free dofollow listing gated on a permanent badge, five reviews a day. Process from the 2026-11-16 snapshot.' WHERE slug='dayslaunch';
UPDATE submission_sites SET rw_source_lead='The free lane trades a text link for a listing — but the submit button did nothing across three attempts.', rw_what_you_get='A dofollow listing in exchange for a text link on your homepage, if the submission actually registers.', rw_you_need='["A Google account","A text link to them on your homepage, kept there","An AI tool with a name and URL"]', rw_eligibility='You need a Google account, a kept text link and an AI product. Anything that is not an AI tool is rejected.', rw_submit_steps='["1 Choose the lane. The form carries a pill reading Fast Track by default; clicking the Free Pack card switches it and changes the pill and strapline.","2 Copy their link snippet. The free card hands over a plain anchor and states the listing is removed once the backlink is removed.","3 Sign in. The first Submit press opens a Please continue by logging in dialog with a single Continue with Google button.","4 Submit two fields: website name and URL. Their FAQ puts review at 72 hours and publication within fifteen days on the free pack."]', rw_submit_requirements='["A website name and URL","A Google account","A text link on your homepage"]', rw_rejection_reasons='["Anything that is not an AI tool"]', rw_gotchas='["The free submission could not be confirmed: three presses of Submit produced only a server-side crawl and no confirmation, error or dashboard entry.","The lane pill defaults to the paid Fast Track, so submitting without clicking Free Pack first aims at the wrong plan.","Their free card says the listing is removed once the backlink is removed, so the text link is a standing commitment."]', rw_faq='[{"question":"How long does AI Tool Trek approval take?","answer":"Two to four weeks; free states 72-hour review and publication within fifteen days."},{"question":"How much does it cost to submit to AI Tool Trek?","answer":"Free with a text link. Fast Track is $19.9 once, reduced from $29.9, for 24-hour listing and five or more followed links; Unlimited Pack is $39.9 a month with no backlink ever."},{"question":"Does an AI Tool Trek listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 60."},{"question":"Do I need to link back to AI Tool Trek?","answer":"Yes — the free lane requires a kept text link."},{"question":"What gets a submission rejected?","answer":"Anything that is not an AI tool."}]', rw_summary='AI Tool Trek is a free dofollow AI directory where a kept text link buys a listing, but the free submit could not be confirmed in testing. No other backlink is needed; domain rating is 60.', rw_fact_points='["Free review stated at 72 hours","Dofollow link with a kept text link required","Free submit did not register in testing","Accepts AI tools and SaaS products"]', rw_submission_checks='["Click the Free Pack card — the default is the paid lane.","Paste the exact text link on your homepage.","Verify in the dashboard, since confirmation failed in testing."]', rw_seo_title='AI Tool Trek: Free Link Listing, DR 60', rw_seo_description='How to submit to AI Tool Trek: free dofollow AI listing for a text link, no other backlink. Lane and submit caveats from the 2026-11-16 snapshot.' WHERE slug='aitooltrek';
UPDATE submission_sites SET rw_source_lead='Free listings are suspended by their own admission, and the paid option buys a written blog review.', rw_what_you_get='A dofollow listing within 48 hours on a paid tier, plus a verified badge — with the premium option adding a written review in someone else''s words.', rw_you_need='["A live product URL","A paid option — free listings are suspended","Something they judge business or technology related"]', rw_eligibility='You need a live URL and to clear their hand-judged business-or-technology test. Anything outside that scope, and anyone waiting for the suspended free lane, is out.', rw_submit_steps='["1 Pick an option: directory listing, or premium with a review and social promotion.","2 Submit. Either paid option lists within 48 hours.","3 Claim the verified badge mentioned on both options."]', rw_submit_requirements='["A live product URL","Payment for one of the two live options"]', rw_rejection_reasons='["Anything they do not consider business or technology related, judged by hand"]', rw_gotchas='["Free listings are suspended by their own admission, with a backlog of hundreds — the free route is closed until they clear it.","The premium option is a written review rather than a bigger listing, so somebody else describes your product in their words.","They quote their authority as DA 73, a Moz number, not the Ahrefs scale most directories use."]', rw_faq='[{"question":"How long does AllTopStartups approval take?","answer":"One to two days; paid listings go live within 48 hours."},{"question":"How much does it cost to submit to AllTopStartups?","answer":"Free is stated but suspended. The live options are a directory listing and a premium one adding a written review, a month on the homepage and promotion to their Twitter following."},{"question":"Does an AllTopStartups listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 59."},{"question":"Do I need to link back to AllTopStartups?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Anything they do not judge business or technology related."}]', rw_summary='AllTopStartups is a dofollow startup directory where free listings are suspended and paid options list within 48 hours. No backlink is required; domain rating is 59 and the premium tier adds a written review.', rw_fact_points='["Paid listings go live within 48 hours","Free lane suspended, dofollow listing on paid","No badge or return link is expected","Accepts indie products, SaaS and startups"]', rw_submission_checks='["Expect the free lane to be closed.","The premium option is a written review in their words.","No backlink is needed."]', rw_seo_title='AllTopStartups: Paid Dofollow Listing, DR 59', rw_seo_description='How to list on AllTopStartups: free suspended, paid dofollow listing in 48 hours, no backlink. Premium review details from the 2026-11-16 snapshot.' WHERE slug='alltopstartups';
UPDATE submission_sites SET rw_source_lead='150,000 apps and millions of user opinions on a high-authority domain, behind a free queue their own form measures in months.', rw_what_you_get='A nofollow app listing in a huge comparison catalogue, worth it for the search traffic if you can survive the queue and the decline list.', rw_you_need='["An account with a verified email","A product that works in English and a square icon of 128px or more","At least one existing app named as an alternative, and something reviewers see as distinct"]', rw_eligibility='You need a verified account, an English product, an icon and real alternatives. Directories, tool collections, AI listings, review sites, guides, LLM wrappers, single-purpose converters, personal sites and non-English products are all declined.', rw_submit_steps='["1 Read the decline list first, linked under What we don''t accept — about sixty categories, the longest here.","2 Make an account and verify the email. Google signup is disabled, so use GitHub, Apple or email and password.","3 Open Suggest new application from the top-right menu; signed out the item is greyed and does nothing.","4 Fill one long form: name, short and full descriptions, languages, pricing, tags, platforms, an author record, an icon and screenshots.","5 Name your alternatives. Immediately after submitting they warn an app with no alternatives is almost invisible; search a real competitor and Select All over its alternatives.","6 Decide about the $5 priority review shown in My submissions beside the normal queue."]', rw_submit_requirements='["A verified email and account","A product name and official URL","A one-sentence and a full description","Pricing, tags from a closed vocabulary and platforms","A company or author record, created inline","A square icon of 128px or more","Optional screenshots and pricing details","$5 optional for priority review"]', rw_rejection_reasons='["Directories, tool collections and AI tool listings; review and comparison sites; guides and tutorials; LLM wrappers and single-purpose converters, generators or calculators; personal sites, blogs and custom services; anything not in English"]', rw_gotchas='["The decline list explicitly names directories, review sites and guides — if your product is one of those, months of queue end in an unexplained decline.","The free queue is effectively unbounded: their form says at least a few months, repeated in My submissions.","Google signup is currently off; new accounts must come from GitHub, Apple or email and password.","Alternatives are the whole game, and the prompt only appears after you submit.","The outbound link is rel=nofollow noopener, so the case is their search traffic and nothing else.","A declined app vanishes from My submissions with no rejection state, so an empty list means approved or refused."]', rw_faq='[{"question":"How long does AlternativeTo approval take?","answer":"No review time is published; the free queue is measured in months."},{"question":"How much does it cost to submit to AlternativeTo?","answer":"Free, or $5 once for priority review with a human in one to two business days."},{"question":"Does an AlternativeTo listing provide a dofollow link?","answer":"No — links are nofollow on a domain rated 79."},{"question":"Do I need to link back to AlternativeTo?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Directories, review sites, guides, LLM wrappers, single-purpose tools, personal sites and anything not in English."}]', rw_summary='AlternativeTo is a 150,000-app comparison catalogue with a free nofollow listing behind a months-long queue. No backlink is required; domain rating is 79, and alternatives plus the decline list decide everything.', rw_fact_points='["Free queue measured in months; $5 priority review","Nofollow listing with no backlink required","Alternatives are essential for visibility","Accepts web apps, mobile apps, developer tools and open source"]', rw_submission_checks='["Read the long decline list before applying.","Verify your email and name real alternatives.","$5 buys speed, not a different outcome."]', rw_seo_title='AlternativeTo: Free App Listing, DR 79', rw_seo_description='How to submit to AlternativeTo: free nofollow app listing behind a months-long queue, no backlink. Decline list and $5 review from the 2026-11-16 snapshot.' WHERE slug='alternativeto';
UPDATE submission_sites SET rw_source_lead='A high-authority software marketplace that lists you free and nofollow, and quotes the free queue at one to twelve weeks unless you name your competitors.', rw_what_you_get='A nofollow software listing in a large marketplace, with the free queue shortened if you identify competitors.', rw_you_need='["A released product on its own domain","An English site and a contact email","At least three categories and a decent website"]', rw_eligibility='You need a released product on its own domain, an English site, a contact email and three categories. Agencies, waitlist landing pages, unreleased products, free subdomains and non-English sites are refused.', rw_submit_steps='["1 Find the real submit page. /submit is a different product — their list of 107 directories; the product form is at /services/submit.","2 Give the URL and continue. One field, no account; it restates the rejection of unreleased products and free subdomains.","3 Fill the listing: name, a 250-character tagline, at least three categories, competitors, optional LinkedIn and a contact email; name and tagline arrive pre-scraped.","4 Pick the free lane, which is the submit button. A paid card is preselected; the Free card is the plain one beside it, quoted at 1 to 12 weeks, and clicking it submits.","5 Confirm competitors and categories on the two follow-up screens, then land on a success page."]', rw_submit_requirements='["A live product URL on its own domain","A product name without explanatory suffixes","A tagline up to 250 characters","At least three categories","A contact email and competitors","An optional LinkedIn URL"]', rw_rejection_reasons='["Software agencies, waitlist landing pages, unreleased products, free subdomains such as vercel.app and non-English sites"]', rw_gotchas='["The obvious URL is wrong: /submit is their directory-submission marketing tool; the product form is /services/submit with nothing on the first page pointing to it.","Leaving competitors blank slows you to the bottom of a queue now quoted at 1 to 12 weeks.","Name and tagline arrive pre-filled from a scrape, and the name field appends rather than replaces — type without clearing and it reads YourProductYourProduct.","The lane cards are the submit buttons: clicking Free sends the form, and the paid card is the one preselected."]', rw_faq='[{"question":"How long does SaaSHub approval take?","answer":"Two to three months on free; the card quotes one to twelve weeks."},{"question":"How much does it cost to submit to SaaSHub?","answer":"Free with a nofollow listing. Priority+ at $75 reviews within 24 hours and adds newsletter consideration, a verified badge for three months and a homepage slot."},{"question":"Does a SaaSHub listing provide a dofollow link?","answer":"No — links are nofollow on a domain rated 79."},{"question":"Do I need to link back to SaaSHub?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Agencies, waitlist pages, unreleased products, free subdomains and non-English sites."}]', rw_summary='SaaSHub is a nofollow software marketplace with a free listing queued one to twelve weeks. No backlink is required; domain rating is 79, and naming competitors speeds review.', rw_fact_points='["Free queue of one to twelve weeks","Nofollow listing with no backlink requirement","Competitors and three categories are required","Accepts SaaS, web and mobile apps, developer tools and AI tools"]', rw_submission_checks='["Use /services/submit, not /submit.","Clear the scraped name field before typing.","Name competitors and pick three categories."]', rw_seo_title='SaaSHub: Free Software Listing, DR 79', rw_seo_description='How to submit to SaaSHub: free nofollow listing with a 1-12 week queue, no backlink. Correct form and competitor tips from the 2026-11-16 snapshot.' WHERE slug='saashub';
UPDATE submission_sites SET rw_source_lead='A footer text link buys the listing, and a paid Submit Pack is sold beside the free lane.', rw_what_you_get='A dofollow listing in exchange for a permanent text anchor in your footer — the entire price of entry.', rw_you_need='["Their text anchor on your site before you submit","A live product URL","No account is needed"]', rw_eligibility='You need their permanent text link and a live URL. Anyone unwilling to carry the link is excluded, since that is the whole price.', rw_submit_steps='["1 Add their anchor. They ask for it in your footer and provide a copy button.","2 Fill the form: two or three fields, no account — the name, the URL and sometimes an email.","3 Wait. Reviewed by hand, with no published window and no account to check a status against."]', rw_submit_requirements='["Their text link — an anchor, not an image badge"]', rw_rejection_reasons='["Anyone unwilling to carry a permanent text link, since that is the entire price"]', rw_gotchas='["Three fields and a footer link are the whole submission, so the listing copy is theirs to write.","They offer a Submit Pack alongside free, which is a paid bundle rather than a faster review of the same listing.","No account exists, so there is no status to check and no way to edit afterward."]', rw_faq='[{"question":"How long does AI Tool Center approval take?","answer":"No review time is published; review is by hand."},{"question":"How much does it cost to submit to AI Tool Center?","answer":"The listing is free in exchange for a text link; a paid Submit Pack is sold separately."},{"question":"Does an AI Tool Center listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 58."},{"question":"Do I need to link back to AI Tool Center?","answer":"Yes — a permanent text anchor is the entire price."},{"question":"What gets a submission rejected?","answer":"Unwillingness to carry the permanent text link."}]', rw_summary='AI Tool Center is a free dofollow AI directory whose entire price is a permanent text link in your footer. No other backlink is needed; domain rating is 58 with no published review time.', rw_fact_points='["Hand review with no published timeline","Free dofollow listing for a text link","A footer anchor is required","Accepts AI tools, SaaS and developer tools"]', rw_submission_checks='["Add their text anchor before submitting.","Expect them to write the listing copy.","There is no account or status to check."]', rw_seo_title='AI Tool Center: Free Link Listing, DR 58', rw_seo_description='How to submit to AI Tool Center: free dofollow listing for a permanent footer text link, no other backlink. Process from the 2026-11-16 snapshot.' WHERE slug='aitoolcenter';
UPDATE submission_sites SET rw_source_lead='A weekly leaderboard for developer tools, run by the community — where every launch week costs $49.', rw_what_you_get='A dofollow listing in a weekly developer-tool leaderboard, with a week slot that must be paid for in practice.', rw_you_need='["A GitHub or Google account — the only sign-ins","A live product URL and a logo","$49 for a launch week; the free queue is booked years ahead"]', rw_eligibility='You need an account, a live URL and payment. Products with no live URL are refused; a nominal free queue is booked about three years out.', rw_submit_steps='["1 Sign in with GitHub or Google. Submit links to /login, which offers only those two and says they filter out bots and fakes.","2 Find the real form. Once signed in, Submit points to /account/tools, and the form is at /account/tools/new — /submit and /tool/new both 404 even when authenticated.","3 Tell us about your tool: a 220x220 or 210x210 logo, name, a slogan, website, optional GitHub repo and a description accepting HTML; an Import from ProductHunt button auto-fills.","4 Extra stuff: a pricing type of Free, Subscription or One time fee and optional categories.","5 Media: an optional demo video and at least three screenshots, the first becoming the social preview.","6 Pick a week and pay. The selector lists 105 weeks out to 2028 with booked counts; choosing one turns the button into Launch on <date> for $49."]', rw_submit_requirements='["A GitHub or Google account and $49 per week","A live product URL and a logo","A description accepting HTML","A launch week","An optional GitHub repo and demo video"]', rw_rejection_reasons='["Products with no live URL"]', rw_gotchas='["Every one of the 105 launch weeks costs $49 out to August 2028 — there is no free week to wait for, and the button only shows the price once a week is picked.","A bare /submit and /tool/new both 404 even when signed in; the real form is /account/tools/new.","Sign-in is GitHub or Google only and explicitly filters bots, so an agent cannot get past it.","The stated developer-tools gate is stricter than the observed front page, which carries AI image and video tools.","All three pricing radios ship with value=free in the markup, so check the listing after launch; the description accepts HTML, so use <br> for breaks."]', rw_faq='[{"question":"How long does DevHunt approval take?","answer":"About a week; the free queue is booked roughly three years ahead."},{"question":"How much does it cost to submit to DevHunt?","answer":"$49 per launch week. A free queue exists at 15 tools a week but is booked about three years out, so in practice every launch is paid."},{"question":"Does a DevHunt listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 57."},{"question":"Do I need to link back to DevHunt?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Products with no live URL."}]', rw_summary='DevHunt is a weekly developer-tool leaderboard with a dofollow listing and no backlink, but every launch week costs $49 because the free queue is years long. Domain rating is 57.', rw_fact_points='["Paid $49 per launch week in practice","Dofollow listing with no backlink requirement","GitHub/Google sign-in gates the form","Accepts developer tools, open source, AI tools and SaaS"]', rw_submission_checks='["Expect to pay $49 — the free queue is years full.","Use /account/tools/new, not /submit.","Check your pricing type after launch; the radios are buggy."]', rw_seo_title='DevHunt: $49 Dev Tool Launch, DR 57', rw_seo_description='How to launch on DevHunt: $49 weekly leaderboard with a dofollow listing, no backlink. Free queue and form path from the 2026-11-16 snapshot.' WHERE slug='devhunt';
UPDATE submission_sites SET rw_source_lead='Free, no account, and the text link they ask you to paste has a typo in it.', rw_what_you_get='A dofollow listing in exchange for a text link on your site, after a hand review with no published window.', rw_you_need='["Their text link on your site before you submit","An AI-related product with substantive content built for end users","No account is needed"]', rw_eligibility='You need their text link, an AI product with real content and an end-user focus. Anything cryptocurrency-related and thin sites are rejected.', rw_submit_steps='["1 Add their link. They give the exact anchor to paste and say the free submission only succeeds once it is up.","2 Fill the form: name, a short description, your URL, an email and the URL of the page carrying their link. No account at any point.","3 Wait. Every submission is reviewed by hand with no published window."]', rw_submit_requirements='["Their text link — an anchor, not an image badge","The URL of the page carrying their anchor","A short paragraph description"]', rw_rejection_reasons='["Anything cryptocurrency-related, excluded by name, and thin sites without substantive content"]', rw_gotchas='["The anchor they hand you has a typo, reading RightAI Tools Diresctory. Their checker may match that string, so paste it exactly rather than correcting it.","Cryptocurrency products are excluded by name in their criteria, which few directories state outright.","They say submitting does not guarantee publication and publish no review window at all.","No account is needed anywhere, so there is nothing to check a status against."]', rw_faq='[{"question":"How long does RightAI approval take?","answer":"No review time is published; review is by hand."},{"question":"How much does it cost to submit to RightAI?","answer":"Submitting is free."},{"question":"Does a RightAI listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 57."},{"question":"Do I need to link back to RightAI?","answer":"Yes — their text link is required before you submit."},{"question":"What gets a submission rejected?","answer":"Cryptocurrency products and thin sites without substantive content."}]', rw_summary='RightAI is a free dofollow AI directory requiring a text link on your site before submission. No account, no published review time; domain rating is 57, and the requested anchor contains a typo.', rw_fact_points='["Hand review with no published timeline","Free dofollow listing for a text link","A text anchor is required","Accepts AI tools, SaaS and developer tools"]', rw_submission_checks='["Paste their anchor exactly, including the typo.","Avoid any cryptocurrency framing.","No account or status page to check."]', rw_seo_title='RightAI: Free Link Listing, DR 57', rw_seo_description='How to submit to RightAI: free dofollow AI listing for a text link, no account. Typo and criteria from the 2026-11-16 snapshot.' WHERE slug='right-ai';
UPDATE submission_sites SET rw_source_lead='A two-field form that looks free until you press submit and a monthly subscription appears.', rw_what_you_get='A dofollow listing, but only behind a $29.9 monthly subscription revealed at the final click.', rw_you_need='["A Google account, demanded by the submit click","A $29.9 monthly subscription","A website name and URL"]', rw_eligibility='You need a Google account, a recurring payment and an AI tool. Anything that is not an AI tool is rejected.', rw_submit_steps='["1 Open the submit page: two fields, website name and URL. Nothing on the page mentions a price.","2 Press Submit signed out. A Google login modal appears; signing in creates the account.","3 Press Submit signed in. A paywall modal replaces the action: Get plan for submit AI at $29.9 a month, with card and PayPal buttons.","4 Decide. There is no free lane behind the modal and no one-time price."]', rw_submit_requirements='["A website name","A website URL","A Google account","A $29.9 monthly subscription"]', rw_rejection_reasons='["Anything that is not an AI tool"]', rw_gotchas='["The price is invisible until the last click: the form, fields and sign-in all complete before the $29.9 monthly modal appears.","It is a subscription, not a one-time listing fee, so a single product pays monthly for a listing it only needed once.","The directory is AI-only."]', rw_faq='[{"question":"How long does Woy AI approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to Woy AI?","answer":"$29.9 a month by card or PayPal, sold as unlimited submissions with cancellation any time. There is no one-time option."},{"question":"Does a Woy AI listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 58."},{"question":"Do I need to link back to Woy AI?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Anything that is not an AI tool."}]', rw_summary='Woy AI is an AI directory whose two-field form looks free until a $29.9 monthly subscription appears at the final click. The listing is dofollow with no backlink; domain rating is 58.', rw_fact_points='["Paid-only at $29.9/month, price hidden until submit","Dofollow listing with no backlink requirement","No badge or return link is expected","Accepts AI tools and SaaS products"]', rw_submission_checks='["Expect a subscription, not a one-time fee.","The price appears only after filling the form and signing in.","Use Google sign-in — it is required to submit."]', rw_seo_title='Woy AI: $29.9/mo AI Listing, DR 58', rw_seo_description='How to submit to Woy AI: $29.9/month dofollow AI listing revealed at submit, no backlink. Hidden pricing flow from the 2026-11-16 snapshot.' WHERE slug='woy-ai';
UPDATE submission_sites SET rw_source_lead='A roadmap of directories that lists itself first, and its own row is a badge trade: place the badge, get the followed link, free.', rw_what_you_get='A dofollow listing in their own roadmap, unlocked by their badge and a comment on the listing row.', rw_you_need='["A Google account or a magic link","A startup profile completed through a four-step kit","Their badge on your site, unless you pay $19 to skip it"]', rw_eligibility='You need an account, a completed profile and either the badge or the $19 badgeless launch. Nothing publishes without one or the other.', rw_submit_steps='["1 Sign in and build the startup profile with Google or a magic link. /kit is a four-step wizard: how you found them, the basics, a conduct pledge, a skippable Chrome-extension pitch and a plan.","2 Take the free plan. Pro at $19 arrives preselected with Free above it; clicking Free relabels the button to Continue for free.","3 Open their own row in the roadmap. LaunchPanda lists itself first under Featured; expanding it reveals the badge snippet and the listing slug reserved for you.","4 Deploy the badge, then verify. The snippet is a plain anchor; their checker answers Badge verified once it is in your served HTML.","5 Mark as done and leave a comment. Verification alone publishes nothing, and the listing page 404s until the comment lands."]', rw_submit_requirements='["A website URL, tool name and your name","A tagline within 60 characters and a description within 150","One category and a pricing answer","Their badge live on your site","An optional X handle"]', rw_rejection_reasons='["Refusing the badge without paying the $19 badgeless launch, since their own listing is the badge trade and nothing publishes without one or the other"]', rw_gotchas='["Verifying the badge does not list you, and neither does marking the row done; their line is mark this directory as done and leave a comment, and until the comment lands the page 404s while your badge points at it.","Pro at $19 is preselected on the plan step with Free unhighlighted; the tell that Free took is the button changing to Continue for free.","The badge is the price of the listing, so removing it takes the followed link with it; the only way out is $19.","Building the startup profile is not launching — the account can show a finished profile and still read zero directories launched."]', rw_faq='[{"question":"How long does LaunchPanda approval take?","answer":"Instant once the badge is verified and the comment is left."},{"question":"How much does it cost to submit to LaunchPanda?","answer":"Free with a badge. Pro is $19 for a full profile and Pro badge, $39 for unlimited profiles; a $19 badgeless launch skips the badge; bulk auto-submission starts at $169."},{"question":"Does a LaunchPanda listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 55."},{"question":"Do I need to link back to LaunchPanda?","answer":"Yes — their badge is required unless you pay $19."},{"question":"What gets a submission rejected?","answer":"Refusing the badge without paying for the badgeless launch."}]', rw_summary='LaunchPanda is a directory roadmap whose own listing is a free badge trade, giving a dofollow link once verified and commented. No other backlink is needed; domain rating is 55.', rw_fact_points='["Instant listing after badge and comment","Free listing with a dofollow link","A badge is required unless you pay $19","Accepts SaaS, indie products, AI tools and marketing tools"]', rw_submission_checks='["Verify the badge, mark the row done AND leave a comment.","Select Free explicitly — Pro $19 is preselected.","Keep the badge live or pay $19 to remove it."]', rw_seo_title='LaunchPanda: Free Badge Launch, DR 55', rw_seo_description='How to list on LaunchPanda: free dofollow roadmap listing via a badge, comment required. Preselected plan warning from the 2026-11-16 snapshot.' WHERE slug='launchpanda';
UPDATE submission_sites SET rw_source_lead='Two fields and a homepage link, with no account to check anything against.', rw_what_you_get='A dofollow listing written by the operator from just your name and URL, in exchange for a permanent text anchor.', rw_you_need='["Their text anchor on your site before you submit","A live product URL","No account is needed"]', rw_eligibility='You need their permanent text link and a live URL. Anyone unwilling to carry the link is excluded, since that is the whole price.', rw_submit_steps='["1 Add their anchor. They print it with a copy button and say the free submission only succeeds once it is on your homepage.","2 Fill the form: two or three fields, no account — the name, the URL and sometimes an email.","3 Wait. Reviewed by hand with no published window and no account to check status."]', rw_submit_requirements='["Their text link — an anchor, not an image badge"]', rw_rejection_reasons='["Anyone unwilling to carry a permanent text link, since that is the entire price"]', rw_gotchas='["The form is two fields — a name and a URL — so everything else on the listing is written by them.","The anchor has to go on your homepage specifically, not a footer anywhere.","No account exists, so there is no way to check the review or correct the listing later."]', rw_faq='[{"question":"How long does What Is Ai Tools approval take?","answer":"Three to five days; review is by hand."},{"question":"How much does it cost to submit to What Is Ai Tools?","answer":"Submitting is free in exchange for a text link."},{"question":"Does a What Is Ai Tools listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 55."},{"question":"Do I need to link back to What Is Ai Tools?","answer":"Yes — a permanent text anchor on your homepage is the price."},{"question":"What gets a submission rejected?","answer":"Unwillingness to carry the permanent text link."}]', rw_summary='What Is Ai Tools is a free dofollow AI directory where a two-field form and a permanent homepage text link buy a listing written by the operator. Domain rating is 55.', rw_fact_points='["Hand review takes three to five days","Free dofollow listing for a text link","A homepage anchor is required","Accepts AI tools, SaaS and developer tools"]', rw_submission_checks='["Place the anchor on your homepage, not just any page.","Expect them to write the listing copy.","No account or status page to check."]', rw_seo_title='What Is Ai Tools: Free Link Listing, DR 55', rw_seo_description='How to submit to What Is Ai Tools: free dofollow listing for a permanent homepage text link, no account. Steps from the 2026-11-16 snapshot.' WHERE slug='whatisaitools';
UPDATE submission_sites SET rw_source_lead='A Chinese-language index of over 15,000 AI products where the free lane is a plain reciprocal text link and outbound links follow.', rw_what_you_get='A dofollow listing in a large Chinese AI index, free in exchange for a reciprocal text link.', rw_you_need='["Their text link on a page of your site, for the free lane","The URL of the page carrying that link","A contact email"]', rw_eligibility='You need a page for their anchor, that page''s URL and an email. A site you will not put their link on is out, since free is a link exchange and nothing else.', rw_submit_steps='["1 Open /promote and switch to the free tab. The page opens on a $6.99 paid panel; the free lane is a separate second tab with a different form.","2 Take their anchor snippet — a plain text link to their homepage with AiHeron as the anchor text. There is no image badge.","3 Put the link on a page and note that page''s URL. They ask for the address of the page where you added the link, not your homepage by default.","4 Fill contact and product URL: an email and the address of the product being submitted.","5 Submit and expect a same-day appearance — they promise new arrivals within 24 hours with no queue, against an hour on the paid lane."]', rw_submit_requirements='["A contact email and the product URL","Their text link live on one of your pages","The URL of the page carrying that link"]', rw_rejection_reasons='["A site you will not put their anchor on, since the free lane is a link exchange"]', rw_gotchas='["The page opens on the paid panel, so the first thing you see is $6.99; the free lane is a separate tab and missing it is how this reads as paid-only.","The paid tier exists to remove the reciprocal link — their benefits list a permanent link with no backlink required.","The whole site and both forms are in Chinese with no language switch; the audience is Chinese-speaking, which is the real question.","They ask for the page URL carrying your link, so it has to be live before you submit, not after."]', rw_faq='[{"question":"How long does AiHeron approval take?","answer":"Same day — the free lane promises new arrivals within 24 hours."},{"question":"How much does it cost to submit to AiHeron?","answer":"Free with a reciprocal link. $6.99, reduced from $12.99, removes the link and adds up to three links, a seven-day featured slot and hourly review."},{"question":"Does an AiHeron listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 54."},{"question":"Do I need to link back to AiHeron?","answer":"Yes — the free lane is a reciprocal link exchange."},{"question":"What gets a submission rejected?","answer":"A site you will not put their anchor on."}]', rw_summary='AiHeron is a large Chinese AI index with a free dofollow listing in exchange for a reciprocal text link and same-day appearance. No other backlink is needed; domain rating is 54.', rw_fact_points='["Free listings appear within 24 hours","Dofollow link with a reciprocal link required","The free lane is a link exchange","AI tools, SaaS, marketing and developer tools"]', rw_submission_checks='["Switch to the free tab — the page opens on paid.","Install their anchor before submitting and give the page URL.","Expect a Chinese-language audience."]', rw_seo_title='AiHeron: Free AI Listing, DR 54', rw_seo_description='How to submit to AiHeron: free dofollow AI listing for a reciprocal text link, same-day, Chinese-language. Free-tab tip from the 2026-11-16 snapshot.' WHERE slug='aiheron';
UPDATE submission_sites SET rw_source_lead='A weekly AI chart that asks which model and which coding agent built your product — and offers an honest agent-submission option.', rw_what_you_get='A dofollow entry in a weekly merit-ranked AI chart, with the builder stack declared alongside it.', rw_you_need='["A Google account — the only sign-in","A summary of 200 characters or fewer","An attestation that you have reviewed security best practices"]', rw_eligibility='You need a Google account, a short summary and a security attestation. Work reviewers judge unoriginal is refused, since submissions are checked for originality.', rw_submit_steps='["1 Sign in with Google. SUBMIT does nothing while signed out and /submit bounces back to the chart.","2 Say who is submitting from four honest options: founder or team, on behalf of a founder, community member, or agent or automated submission.","3 Title, URL and a summary: title caps at 100, summary at 200, and the counter only turns red after you overshoot.","4 Declare the builder stack — up to two each of model or provider, IDE or agent, and stack or hosting.","5 Thumbnail, stage, links and a required tick that you have reviewed security best practices, then submit. It lands on a page reading Awaiting Review."]', rw_submit_requirements='["A project title within 100 characters and a URL","A summary within 200 characters","An answer to who is submitting","A tick confirming security review","Optional thumbnail, model/IDE/hosting choices and maker links"]', rw_rejection_reasons='["Work reviewers judge unoriginal, since submissions are checked for originality before approval"]', rw_gotchas='["The summary caps at 200 characters and the counter only goes red once over, so a pasted blurb usually needs trimming on the spot.","Signed out, SUBMIT is inert and /submit silently redirects to the chart — a login wall that looks like a broken route.","The model list is versioned and dated, so your exact model may be absent; pick the nearest real one, since the stack is the point.","About a thousand projects compete for a hundred slots, and the $19 tier buys discovery rather than ranking, which their copy says plainly."]', rw_faq='[{"question":"How long does Hot100.ai approval take?","answer":"One to two days; a $19 tier buys discovery, not ranking."},{"question":"How much does it cost to submit to Hot100.ai?","answer":"Free, with charts kept merit-based. $19 once adds agent-readable metadata, priority indexing, a badge and an optimised title without affecting ranking."},{"question":"Does a Hot100.ai listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 53."},{"question":"Do I need to link back to Hot100.ai?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Work reviewers judge unoriginal."}]', rw_summary='Hot100.ai is a weekly merit-ranked AI chart where you declare the model and coding agent that built your product. A free dofollow listing needs a Google account; domain rating is 53.', rw_fact_points='["Free listing reviewed in one to two days","Dofollow link with no backlink requirement","Originality is checked before approval","Accepts AI tools, indie products, developer tools and SaaS"]', rw_submission_checks='["Sign in first — SUBMIT is inert when signed out.","Trim your summary to 200 characters.","Declare a real model and agent from the dated lists."]', rw_seo_title='Hot100.ai: Free Weekly AI Chart, DR 53', rw_seo_description='How to submit to Hot100.ai: free dofollow weekly AI chart listing, no backlink. Builder stack and originality check from the 2026-11-16 snapshot.' WHERE slug='hot100-ai';
UPDATE submission_sites SET rw_source_lead='Twenty dollars for a permanent followed link, and no free tier under it.', rw_what_you_get='A permanent dofollow listing added within 48 hours, with an optional paid bundle for short-term ad placement.', rw_you_need='["A payment of at least $19.90 — there is no free tier"]', rw_eligibility='You need to pay $19.90 or more. Anyone looking for a free listing is excluded, since there is not one.', rw_submit_steps='["1 Pick a plan: one-time Submit at $19.90 or the bundle at $39.90.","2 Pay. They quote adding the listing within 48 hours."]', rw_submit_requirements='["A payment of at least $19.90 one-time"]', rw_rejection_reasons='["Anyone looking for a free listing, because there is not one"]', rw_gotchas='["There is no free lane, and the struck-through higher price is the permanent state rather than an offer.","The bundle''s ad placements last thirty days while the listing is permanent, so most of the extra $20 rents attention rather than buying a link."]', rw_faq='[{"question":"How long does SeekTool.ai approval take?","answer":"One to two days; they quote adding within 48 hours."},{"question":"How much does it cost to submit to SeekTool.ai?","answer":"$19.90 once, reduced from $26.90, for a permanent dofollow listing; the $39.90 bundle adds thirty days of homepage, sidebar and category ads."},{"question":"Does a SeekTool.ai listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 53."},{"question":"Do I need to link back to SeekTool.ai?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Anyone looking for a free listing — there is none."}]', rw_summary='SeekTool.ai is a paid-only AI directory with a permanent $19.90 dofollow listing added within 48 hours. No backlink is required; domain rating is 53.', rw_fact_points='["Paid-only from $19.90 with a 48-hour add","Permanent dofollow listing, no backlink","No badge or return link is expected","Accepts AI tools and SaaS products"]', rw_submission_checks='["Expect to pay — there is no free tier.","The bundle''s ads last 30 days; the listing is permanent either way."]', rw_seo_title='SeekTool.ai: $19.90 AI Listing, DR 53', rw_seo_description='How to submit to SeekTool.ai: $19.90 one-time permanent dofollow listing in 48 hours, no backlink. Plans from the 2026-11-16 snapshot.' WHERE slug='seektool';
UPDATE submission_sites SET rw_source_lead='An established AI index with no free lane at all, from $9.99 up.', rw_what_you_get='A dofollow listing where the price buys description length and review speed, from 800 characters and 48 hours upward.', rw_you_need='["Payment, since there is no free tier","An account","A name, a URL and a description within your tier''s limit"]', rw_eligibility='You need an account, payment and a description within your tier''s length. Anyone looking for a free listing is excluded.', rw_submit_steps='["1 Pick a tier: Basic $9.99, Fast $15.99 or Verified $59.99, all one-time. The form below is the same either way.","2 Fill it with a name, URL, a 120-character tagline and a markdown description capped by tier.","3 Pay and wait. They quote 48 hours on Basic and 24 on the two higher tiers."]', rw_submit_requirements='["A payment from $9.99 one-time","A tagline of at most 120 characters","A description of 800 to 5,000 characters by tier"]', rw_rejection_reasons='["Anyone looking for a free listing, because there is not one"]', rw_gotchas='["There is no free tier, and every listed price is struck through from a higher one, so the discount is permanent.","What you pay for is length and speed: 800 characters and 48 hours at the bottom, 5,000 characters and a Verified badge at the top.","They quote Domain Authority rather than Domain Rating and link an Ahrefs page to prove it — different metrics on different scales."]', rw_faq='[{"question":"How long does AI Tools Time approval take?","answer":"One to two days; 48 hours on Basic, 24 on higher tiers."},{"question":"How much does it cost to submit to AI Tools Time?","answer":"Basic $9.99 once for 48-hour human review; Fast $15.99 for 24 hours and thirty days in their selection; Verified $59.99 for a badge, 5,000 characters and analytics. No free tier."},{"question":"Does an AI Tools Time listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 51."},{"question":"Do I need to link back to AI Tools Time?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Anyone looking for a free listing."}]', rw_summary='AI Tools Time is a paid-only AI directory from $9.99 where the fee buys description length and review speed. The dofollow listing needs no backlink; domain rating is 51.', rw_fact_points='["Paid-only from $9.99 with 24-48 hour review","Dofollow listing with no backlink requirement","No badge or return link is expected","Accepts AI tools, SaaS and developer tools"]', rw_submission_checks='["Expect to pay — there is no free tier.","Choose the tier by how much description space you need.","Their authority claim is DA, not DR."]', rw_seo_title='AI Tools Time: $9.99 AI Listing, DR 51', rw_seo_description='How to submit to AI Tools Time: paid $9.99+ dofollow AI listing in 24-48 hours, no backlink. Tier differences from the 2026-11-16 snapshot.' WHERE slug='aitoolstime';
UPDATE submission_sites SET rw_source_lead='The same three-step badge gate as a sibling site, run by the same operator, pointed at AI apps for work.', rw_what_you_get='A dofollow listing for work-focused AI apps, gated on a followed badge pointing at your reserved listing URL.', rw_you_need='["An account via Google","Their badge on your homepage or footer, linking followed to your reserved listing URL","An icon, a screenshot and short product copy"]', rw_eligibility='You need a Google account, a followed badge and the assets. A site that cannot carry the badge never opens the form, and anything outside practical work apps is out of scope.', rw_submit_steps='["1 Sign in. /submit is a sign-in card with Log in with Google as the only visible provider.","2 Give the homepage. Step one takes the product homepage — the page their crawler will check.","3 Take the badge. Step two reserves /ai/<slug> and prints light and dark snippets that must link to it followed.","4 Verify, then write the listing. Verify Badge unlocks step three: name, summary, overview, icon, screenshot, pricing and categories."]', rw_submit_requirements='["An account","A product homepage URL","Their badge live and followed, pointing at the reserved listing URL","A name up to 40 characters and a summary up to 150","An overview up to 1,500 characters","An icon and a screenshot","A pricing model and at least one category"]', rw_rejection_reasons='["A site that cannot carry their followed badge, since the form never opens without it, and anything outside practical work apps"]', rw_gotchas='["Nothing about the product can be entered until the badge is verified, so a first visit always ends at step two.","The badge has to link to your reserved /ai/<slug> URL, which does not exist until step two generates it.","It shares a codebase and operator with a sibling site; doing both means two badges and two listings that read identically."]', rw_faq='[{"question":"How long does Appa List approval take?","answer":"One to two weeks."},{"question":"How much does it cost to submit to Appa List?","answer":"Submitting is free with a badge."},{"question":"Does an Appa List listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 51."},{"question":"Do I need to link back to Appa List?","answer":"Yes — a followed badge is required."},{"question":"What gets a listing rejected?","answer":"A site that cannot carry the badge, or anything outside work-focused AI apps."}]', rw_summary='Appa List is a work-focused AI app directory where a free dofollow listing requires a followed badge verified before the form opens. Domain rating is 51.', rw_fact_points='["One-to-two-week review","Free listing with a dofollow link","A followed badge gates the form","Accepts AI tools, productivity apps, SaaS and marketing tools"]', rw_submission_checks='["Install the badge pointing at your reserved /ai/<slug> URL.","Expect the form to stay closed until verification.","Note it shares an operator with a sibling directory."]', rw_seo_title='Appa List: Free Badge AI Listing, DR 51', rw_seo_description='How to submit to Appa List: free dofollow work-AI listing gated on a followed badge, no other backlink. Steps from the 2026-11-16 snapshot.' WHERE slug='appa-list';
UPDATE submission_sites SET rw_source_lead='An AI and SaaS directory built on comparisons and alternative pages, whose free tier rents its followed link against a Featured badge.', rw_what_you_get='A dofollow listing reviewed within two weeks, in exchange for their Featured badge on your site.', rw_you_need='["An account via Google or an emailed magic link","Their Featured badge on your site, for the free tier","A live product URL"]', rw_eligibility='You need an account, a live URL and — on free — their badge. Nothing is published as a content bar; the only stated conditions are the badge and, on the SEO package, giving them free product access.', rw_submit_steps='["1 Reach the form from the homepage by clicking Submit in their navigation. Loading /submit directly crashes to a blank shell.","2 Sign in with Google or an emailed magic link.","3 Fill the listing: website, name, tagline, a short description, a rich-text Detailed Content block, a category and your own pricing model; Twitter, GitHub and a discount code are optional.","4 Pick the free plan. Start for Free opens a badge dialog with four styles.","5 Deploy the badge, then Verify. Copy code turns into Verify once used, and Verify moves the tool from Draft to Review."]', rw_submit_requirements='["An account","A live product URL","A tagline and short description","Their Featured badge on your site, verified, for the free tier"]', rw_rejection_reasons='["Nothing published as a content bar — the only stated conditions are the badge on free and free product access on the SEO package"]', rw_gotchas='["The free tier''s followed link is rented against their Featured badge.","Closing the badge dialog leaves the listing saved as Draft rather than submitted, with nothing on screen saying so; it only enters review when the badge check passes.","The $59 SEO package is not only money — their line is Requirement: Free product access for testing, so a paid product also gives away a licence."]', rw_faq='[{"question":"How long does BestskyTools approval take?","answer":"One to two weeks; free states review within two weeks."},{"question":"How much does it cost to submit to BestskyTools?","answer":"Free with a Featured badge for one followed link. $14.90 once gives four followed links, 24-hour review, no badge and a lifetime listing; $59 adds a written review and SEO work in exchange for free product access."},{"question":"Does a BestskyTools listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 52."},{"question":"Do I need to link back to BestskyTools?","answer":"Yes — the free tier requires their Featured badge."},{"question":"What gets a listing rejected?","answer":"Nothing published as a content bar; conditions are the badge and, on SEO, free product access."}]', rw_summary='BestskyTools is an AI/SaaS comparison directory where a free dofollow listing requires a Featured badge and a two-week review. No other backlink is needed; domain rating is 52.', rw_fact_points='["Two-week review on free","Dofollow link with a badge required","A badge gates Draft to Review","Accepts AI tools, SaaS, developer tools and marketing tools"]', rw_submission_checks='["Click Submit in the nav — /submit directly crashes.","Complete Verify or the listing stays Draft.","The SEO package requires giving free product access."]', rw_seo_title='BestskyTools: Free Badge Listing, DR 52', rw_seo_description='How to submit to BestskyTools: free dofollow AI listing with a Featured badge and two-week review, no other backlink. Steps from the 2026-11-16 snapshot.' WHERE slug='bestskytools';
UPDATE submission_sites SET rw_source_lead='The whole pitch is the link, and the free lane is the one that gives it.', rw_what_you_get='An instant dofollow listing with no review — the badge check is the only gate.', rw_you_need='["A URL, an email, a name, a tagline and one of fourteen categories","Their badge on your site, unless you pay $9"]', rw_eligibility='You need basic details and either the badge or $9. Anyone who will do neither has no lane.', rw_submit_steps='["1 Open the form via the homepage Launch button. There is no account and no /submit page.","2 Six fields: website, email, product name, tagline, category and an optional X handle.","3 Pick a lane: free with the badge, $9 without it, or $59 for a featured slot.","4 Verify and publish. They hand over the badge snippet; Verify and publish looks for it and puts the listing live immediately."]', rw_submit_requirements='["Their badge — a 188x56 SVG, light or dark","A one-line tagline","An email, required","One of fourteen categories"]', rw_rejection_reasons='["Anyone who will neither carry the badge nor pay, since those are the only two lanes"]', rw_gotchas='["There is no review or queue: the badge check is the whole gate and the listing is live the second it passes.","The homepage sells sponsor tiles from $1 and shows what each is held for, so the top is an auction rather than a ranking.","Nothing is stored before the badge step, so closing the tab means refilling the six fields."]', rw_faq='[{"question":"How long does EasyDoFollow approval take?","answer":"Instant — the listing goes live when the badge check passes."},{"question":"How much does it cost to submit to EasyDoFollow?","answer":"Free with their badge, $9 once to skip it while keeping the followed link, or $59 for thirty days pinned on the homepage. All three give the same link."},{"question":"Does an EasyDoFollow listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 51."},{"question":"Do I need to link back to EasyDoFollow?","answer":"Yes on the free lane — the badge is the gate."},{"question":"What gets a submission rejected?","answer":"Refusing both the badge and payment."}]', rw_summary='EasyDoFollow is an instant dofollow listing where the badge check is the only gate. No review and no other backlink; domain rating is 51.', rw_fact_points='["Listings publish instantly on badge check","Free lane gives the same followed link as paid","A badge or payment is required","Accepts SaaS, indie products, AI tools and developer tools"]', rw_submission_checks='["Install the badge for the free lane, or pay $9.","Fill six fields in one session — nothing is saved early.","Ignore sponsor tiles unless you want promotion."]', rw_seo_title='EasyDoFollow: Free Instant Listing, DR 51', rw_seo_description='How to submit to EasyDoFollow: free instant dofollow listing with a badge, or $9 without. No review — 2026-11-16 snapshot.' WHERE slug='easydofollow';
UPDATE submission_sites SET rw_source_lead='A ninth site from the same operator, filed as launches rather than tools.', rw_what_you_get='A dofollow launch listing gated on a badge verified before the form even opens.', rw_you_need='["An account via Google and nothing else","Their badge on your site, verified before the form opens","A screenshot, a square icon and up to four categories"]', rw_eligibility='You need a Google account, a badge and the assets. Anyone who will not carry the badge is excluded — there is no paid lane to buy past it.', rw_submit_steps='["1 Sign in. Log in with Google is the only option; the auth route goes straight there.","2 Enter the URL. Step one takes your homepage and nothing else, then generates a badge pointing at a listing URL you have not created yet.","3 Put the badge up and verify. Step two will not pass until their checker finds that exact anchor; the listing fields do not exist until it does.","4 Fill and submit. Step three wants a name, screenshot, icon, up to four categories, a pricing model, 150 characters of summary and 1,500 of description."]', rw_submit_requirements='["An account on the site","Their 200x54 PNG badge, light or dark","A screenshot up to 10MB and a square icon up to 5MB","A summary up to 150 characters and an about up to 1,500","Up to four categories"]', rw_rejection_reasons='["Anyone who will not carry the badge, since there is no paid lane to buy past it"]', rw_gotchas='["The badge is step two, not the last step: the listing fields do not render until the checker finds the anchor, so there is nothing to preview or save first.","The badge points at a listing URL that does not exist yet, so it 404s while you wait for review.","No review window is published anywhere; the only receipt is a success page.","Every page carries a house ad for the operator''s bulk submission service — what the directory is really selling."]', rw_faq='[{"question":"How long does My Launch Stash approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to My Launch Stash?","answer":"Submitting is free with a badge; there is no paid lane."},{"question":"Does a My Launch Stash listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 51."},{"question":"Do I need to link back to My Launch Stash?","answer":"Yes — a verified badge is mandatory."},{"question":"What gets a listing rejected?","answer":"Refusing the badge — there is no paid alternative."}]', rw_summary='My Launch Stash is a free dofollow launch directory where a verified badge gates the entire form, with no paid alternative. Domain rating is 51 and no review time is published.', rw_fact_points='["No published review time","Free listing with a dofollow link","A badge gates the form, no paid bypass","Accepts SaaS, AI tools, developer tools and indie products"]', rw_submission_checks='["Install the badge before you can see the listing fields.","Expect the badge URL to 404 until launch.","Google sign-in is the only account route."]', rw_seo_title='My Launch Stash: Free Badge Launch, DR 51', rw_seo_description='How to submit to My Launch Stash: free dofollow launch gated on a verified badge, no paid bypass. Process from the 2026-11-16 snapshot.' WHERE slug='mylaunchstash';
UPDATE submission_sites SET rw_source_lead='A million users deep in open-source alternatives, with a nofollow listing link — the reason to be here is the audience.', rw_what_you_get='A nofollow listing among open-source alternatives to proprietary software, carrying repo, licence, tech stack and the tools you replace.', rw_you_need='["An open-source product with a public repository","An account via Google, GitHub or a magic link","A proprietary product yours is an alternative to"]', rw_eligibility='You need an open-source product with a public repo and a proprietary tool it replaces. Anything closed source has nothing to list, since the whole site is community-curated open-source alternatives.', rw_submit_steps='["1 Sign in. /submit redirects to /auth/login with a magic link, Continue with Google or Continue with GitHub.","2 Submit the project behind that account. Live pages show what a listing carries: repo, licence, tech stack, tags and the proprietary tools it replaces.","3 Wait for the community pass. Listings are curated rather than auto-published, with collections like Self-hosted, AI-native, Coming Soon and a Product Graveyard."]', rw_submit_requirements='["An account","A public repository","An open-source licence","The proprietary product yours replaces"]', rw_rejection_reasons='["Anything closed source, since a product without a public repo has nothing to list"]', rw_gotchas='["It is open source only; a closed-source product has nothing to submit whatever its category.","The listing link is nofollow — live tool pages link out with rel=noopener nofollow and a UTM parameter, so this is audience, not SEO.","They keep a Product Graveyard for projects that died, so a listing follows your project after you stop maintaining it."]', rw_faq='[{"question":"How long does OpenAlternative approval take?","answer":"Two to four weeks; listings are community-curated."},{"question":"How much does it cost to submit to OpenAlternative?","answer":"Submitting is free."},{"question":"Does an OpenAlternative listing provide a dofollow link?","answer":"No — links are nofollow on a domain rated 51."},{"question":"Do I need to link back to OpenAlternative?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Anything closed source."}]', rw_summary='OpenAlternative is a large community-curated list of open-source alternatives with a nofollow listing and no backlink. Domain rating is 51; the value is the audience, and review takes two to four weeks.', rw_fact_points='["Two-to-four-week community curation","Nofollow listing with no backlink requirement","Open source only, with a public repo","Accepts open-source projects and alternatives to proprietary software"]', rw_submission_checks='["Have a public repo and a clear licence.","Name the proprietary product you replace.","Expect no link equity; the audience is the point."]', rw_seo_title='OpenAlternative: Free OSS Listing, DR 51', rw_seo_description='How to submit to OpenAlternative: free nofollow listing in a curated open-source alternatives index, no backlink. Steps from the 2026-11-16 snapshot.' WHERE slug='openalternative';
UPDATE submission_sites SET rw_source_lead='A daily chart of about seven launches, where the free slot is a week out and the listing link carries no rel attribute at all.', rw_what_you_get='A dofollow launch in a small daily chart, with the outbound anchor carrying no rel attribute.', rw_you_need='["An email-and-password account — no social option","A launch date from their calendar","A one-paragraph description and a website you will let them screenshot"]', rw_eligibility='You need an account, a date and a description. Anything you are unwilling to have screenshotted is out, since scheduling approves a site screenshot shown with the product.', rw_submit_steps='["1 Create the account by hand at /join with email, password and a terms checkbox — no Google or GitHub option.","2 Open the launch panel from the rocket. There is no /submit route; a pinned rocket button opens the form as a popup.","3 Fill four fields: product URL, a one-paragraph description, a launch date and a tick for whether you are the maker.","4 Pick the earliest free date. Everything before the first slot is greyed out; a week out was the earliest offered, with a warning that review can delay it.","5 Schedule the free launch. The button reads Schedule free launch with a $39 homepage feature as a checkbox above it; the panel clears and promises an email if added."]', rw_submit_requirements='["A product URL and a one-paragraph description","A launch date from their calendar","An email-and-password account","An optional maker tick"]', rw_rejection_reasons='["Anything you are unwilling to have screenshotted, since scheduling approves a website screenshot shown with the product"]', rw_gotchas='["There is no submit page to find — the form lives behind a rocket button pinned to the bottom left, with nothing in navigation pointing at it.","Scheduling is an approval to screenshot your site, in small print under the button; they take it and show it with the product.","Nothing appears on your profile after scheduling — it still reads that your tools will show up here, since an editor must approve first and the only confirmation is an email that may not come.","The calendar hides the queue by greying out early dates, so the delay is visible only as an absence."]', rw_faq='[{"question":"How long does CtrlAlt approval take?","answer":"About a week; the earliest free slot was a week out."},{"question":"How much does it cost to submit to CtrlAlt?","answer":"Free to schedule. $39 buys a homepage feature, skips the review queue and adds a newsletter shoutout — a checkbox in the launch panel, not a separate tier."},{"question":"Does a CtrlAlt listing provide a dofollow link?","answer":"Yes — the outbound anchor carries no rel attribute at all, on a domain rated 50."},{"question":"Do I need to link back to CtrlAlt?","answer":"No backlink is required."},{"question":"What gets a launch rejected?","answer":"Anything you will not let them screenshot."}]', rw_summary='CtrlAlt is a small daily launch chart where a free slot is about a week out. The listing link is followed with no rel attribute and no backlink is required; domain rating is 50.', rw_fact_points='["Free launch about a week out","Dofollow link with no rel attribute, no backlink","A site screenshot is required","Accepts indie products, SaaS, AI tools and marketing tools"]', rw_submission_checks='["Find the rocket button — there is no /submit page.","Consent to a screenshot of your site.","Expect an editor approval before the profile updates."]', rw_seo_title='CtrlAlt: Free Daily Launch, DR 50', rw_seo_description='How to launch on CtrlAlt: free daily chart slot about a week out, followed link, no backlink. Hidden form and screenshot rule from the 2026-11-16 snapshot.' WHERE slug='ctrlalt';
UPDATE submission_sites SET rw_source_lead='A one-person directory of Christian apps that takes recommendations on a six-field form and tells you up front there will be no reply.', rw_what_you_get='A dofollow listing in a curated Christian-app directory, with no promise of a decision or acknowledgment.', rw_you_need='["An app aimed at Christians or churches","Public and out of beta for at least two months","A short argument for why it belongs"]', rw_eligibility='You need a Christian or church-facing app that has been public for two months. TestFlight, beta, waitlist and request-access builds, and anything the curator judges out of place, are refused.', rw_submit_steps='["1 Open the recommendation form. It is a Tally form titled Recommend an App; no account, no upload, and the intro says it is free with no timeline, no status updates and no reply.","2 Name the app and argue for it: app name, URL and a free-text answer to why it belongs — the whole pitch.","3 Answer the two-month question, a required yes/no on whether the app has been public and out of alpha and beta for at least two months.","4 Declare yourself and answer the AI question — whether you made it and whether it generates content with AI. An email is optional, for questions only."]', rw_submit_requirements='["An app name and URL","Why it belongs on faith.tools","A yes to being public and out of beta for two months","An optional email"]', rw_rejection_reasons='["TestFlight, beta, waitlist or request-access builds, and anything the curator does not think belongs"]', rw_gotchas='["The two-month rule is a real gate asked as a self-declared yes/no; a launch-week app is ineligible and TestFlight or waitlist builds do not start the clock.","The form says there is no timeline, no status update and no reply, so there is nothing to chase and no way to tell a rejection from a queue.","You are asked outright whether the app generates content with AI — a filtering question, not idle curiosity."]', rw_faq='[{"question":"How long does faith.tools approval take?","answer":"No review time is published; they say there will be no status updates or reply."},{"question":"How much does it cost to submit to faith.tools?","answer":"Submitting is free."},{"question":"Does a faith.tools listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 49."},{"question":"Do I need to link back to faith.tools?","answer":"No backlink is required."},{"question":"What gets an app rejected?","answer":"Beta or waitlist builds, and anything the curator judges out of place."}]', rw_summary='faith.tools is a one-person curated directory of Christian apps with a free dofollow listing and no backlink. A two-month public history is required; domain rating is 49.', rw_fact_points='["No timeline, status or reply","Free listing with a dofollow link","No badge or return link is expected","Accepts Christian and church-facing apps"]', rw_submission_checks='["Have two months of public, out-of-beta history.","Make the why-it-belongs answer count.","Expect no acknowledgment either way."]', rw_seo_title='faith.tools: Free Christian App Listing, DR 49', rw_seo_description='How to submit to faith.tools: free dofollow Christian-app listing, no backlink. Two-month rule and no-reply policy from the 2026-11-16 snapshot.' WHERE slug='faith-tools';
UPDATE submission_sites SET rw_source_lead='Five upvotes on other startups buy the credits that unlock the form, and the listing that follows carries a link with no rel attribute at all.', rw_what_you_get='A dofollow startup listing that publishes at once, once you have earned five credits by voting on other launches.', rw_you_need='["An account via Google or email and password","Five credits, earned one per vote on other startups","A live product URL"]', rw_eligibility='You need an account and five credits. Nothing is published as a content bar beyond the terms; the real gate is the credit balance, without which the form cannot be reached.', rw_submit_steps='["1 Sign in with Google or email and password. Nothing about voting works while signed out.","2 Upvote five startups. The thumbs on /startups become clickable once signed in; five votes buy the credits the form needs.","3 Fill the form: home page, startup name, short and full descriptions, services, tags, employees, founded year, stage, funding, country, category and a logo.","4 Submit. The listing appears at once with a View your startup page link to it."]', rw_submit_requirements='["An account and five credits from upvoting","A live product URL and a logo","A short and a full description"]', rw_rejection_reasons='["Nothing published as a content bar beyond the terms; the only gate is the credit balance, without which the form is unreachable"]', rw_gotchas='["The submission form does not exist until the account holds five credits, and credits come only from upvoting other startups — budget a few minutes reading other launches first.","The form asks for funding rounds, total funding and stage. Optional, but it is a startup-database shape, so expect fields a solo maker has no answer to."]', rw_faq='[{"question":"How long does Promote Project approval take?","answer":"Same day — the listing appears at once once you submit."},{"question":"How much does it cost to submit to Promote Project?","answer":"Free once you have five credits, earned by voting rather than bought. A separate Feature My Startup product is sold through Stripe for placement above the feed."},{"question":"Does a Promote Project listing provide a dofollow link?","answer":"Yes — the outbound link carries no rel attribute at all, on a domain rated 49."},{"question":"Do I need to link back to Promote Project?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Nothing content-wise; the credit balance is the only gate."}]', rw_summary='Promote Project is a startup board where five upvotes unlock a free dofollow listing that publishes instantly. No backlink is required; domain rating is 49.', rw_fact_points='["Instant listing after five credits","Dofollow link with no backlink required","Voting on others gates submission","Accepts indie projects, SaaS, AI tools and startups"]', rw_submission_checks='["Upvote five startups to unlock the form.","Expect startup-database fields like funding and stage.","No backlink needed."]', rw_seo_title='Promote Project: Free Startup Listing, DR 49', rw_seo_description='How to submit to Promote Project: free instant dofollow startup listing unlocked by five upvotes, no backlink. Credit system from the 2026-11-16 snapshot.' WHERE slug='promote-project';
UPDATE submission_sites SET rw_source_lead='An editorially reviewed SaaS list you apply to by email form, with a nofollow at the end of it.', rw_what_you_get='A nofollow listing in an editor-reviewed marketing SaaS catalogue, if the editors judge you a fit.', rw_you_need='["A live URL","A name and a business email they can reply to","A product in one of five categories: email marketing, SEO, SMM, CRO or other"]', rw_eligibility='You need a live URL, a business email and a product in one of the five categories. Anything the editors decide is not a fit is refused — that is the whole rule, unpublished.', rw_submit_steps='["1 Open Get Listed at /submit-your-tool/. There is no account anywhere on the site.","2 Fill the application: name, business email, WhatsApp number, company or product name, website, one of five categories, description, key features and pricing. Only name and email are truly required.","3 Submit and wait without a receipt. The page answers Your submission was successful in place; no email arrives, no reference is shown, and they reply only if you are eligible."]', rw_submit_requirements='["Your name and a business email","An optional WhatsApp number","A company or product name and website","One of five product categories","A description, key features and a pricing answer"]', rw_rejection_reasons='["Anything the editors decide is not a fit, which is the whole rule and is not published anywhere"]', rw_gotchas='["The form asks for a WhatsApp number. Not required, and the submission goes through empty, but nothing says so — the only field wanting a personal phone number.","There is no receipt or stated review time: the success message renders in place, no email follows, no reference exists, and a rejection looks identical to being ignored.","Key features is a free-text box with no example or counter, and published cards show no feature list — what they render is four scores out of ten you have no input into."]', rw_faq='[{"question":"How long does RelevantSaaS approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to RelevantSaaS?","answer":"Submitting is free."},{"question":"Does a RelevantSaaS listing provide a dofollow link?","answer":"No — links from RelevantSaaS are nofollow."},{"question":"Do I need to link back to RelevantSaaS?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Anything the editors decide is not a fit."}]', rw_summary='RelevantSaaS is an editor-reviewed marketing SaaS catalogue with a free nofollow listing and no backlink. No receipt or published review time; eligibility is entirely at the editors'' discretion.', rw_fact_points='["Editor review with no published timeline","Free listing with a nofollow link","No badge or return link is expected","Accepts email marketing, SEO, SMM and CRO tools"]', rw_submission_checks='["A business email is expected; WhatsApp is optional.","Expect no receipt or reference.","Your feature list is not shown — editorial scores are."]', rw_seo_title='RelevantSaaS: Free Marketing Listing', rw_seo_description='How to submit to RelevantSaaS: free editor-reviewed nofollow SaaS listing, no backlink. Application and no-receipt caveat from the 2026-11-16 snapshot.' WHERE slug='relevantsaas';
UPDATE submission_sites SET rw_source_lead='A straight swap in their own words: one followed link for one followed link, policed by a crawler that unpublishes you the day the badge comes down.', rw_what_you_get='A dofollow listing that lasts only while their dofollow badge stays live on your site.', rw_you_need='["Their badge live on your site with rel=dofollow, before the form will pass step one","The page URL pointing their verifier at","A live product site"]', rw_eligibility='You need a dofollow badge on a live page and a product site. Crypto, adult and gambling sites, and anything they judge not a fit, are removed and refunded.', rw_submit_steps='["1 Pick the lane. Step one of three is a comparison table; Select Free Listing is a small text link under the free column, Get Premium the large orange button.","2 Take the badge and verify. Choosing free replaces the table with a badge panel and copy prompts for Lovable, Cursor, Claude and Gemini; paste the page URL carrying it and press Verify badge.","3 Fill the listing. Verification opens the details form: link, name, categories, tags, a 256-character description, a 2,000-character markdown introduction, a 1:1 icon and 16:9 image, an email and two checkboxes.","4 Choose the lane again. Submit lands on a second plan screen showing Status: Verified; Submit and Wait is free, Pay and Publish Right Now is $9.99.","5 Read the confirmation: Submission Received, reviewed within two weeks, with a reminder that removing the badge delists the product."]', rw_submit_requirements='["Their badge on a live page with rel=dofollow","The URL of that page","A product name and link","At least one category and tag","A description up to 256 characters and an introduction up to 2,000","A 1:1 icon and 16:9 image, 1MB each","A contact email"]', rw_rejection_reasons='["Crypto, adult and gambling sites, and anything they judge not a fit, which they say they remove and refund"]', rw_gotchas='["Nothing about your product is asked until the badge is verified — the details form does not exist before then, so a run without the badge deployed cannot pass step one.","The badge is permanent and crawler-policed: their panel says the listing is unpublished immediately if it is removed.","You choose free or paid twice — a text link under the free column at the start, then a second screen offering $9.99 to publish now.","The icon wants 1:1 and the image 16:9, both under 1MB, and neither slot says so until you are looking at it."]', rw_faq='[{"question":"How long does SaaSBison approval take?","answer":"One to two weeks on the free queue; $9.99 publishes instantly."},{"question":"How much does it cost to submit to SaaSBison?","answer":"Free with a permanent dofollow badge and manual review. $9.99 once gives instant approval, three followed links, an AI-written listing and no badge."},{"question":"Does a SaaSBison listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 50, while your badge stays live."},{"question":"Do I need to link back to SaaSBison?","answer":"Yes — a permanent dofollow badge is the price."},{"question":"What gets a listing rejected?","answer":"Crypto, adult, gambling, or anything they judge not a fit."}]', rw_summary='SaaSBison is a free dofollow listing paid for with a permanent dofollow badge, policed by a crawler. No other backlink is needed; domain rating is 50 and review takes one to two weeks.', rw_fact_points='["Free review within two weeks; paid is instant","Dofollow link rented while your badge is live","A dofollow badge is required","Accepts SaaS, AI tools, developer tools and marketing tools"]', rw_submission_checks='["Deploy a rel=dofollow badge before starting — it gates the form.","Expect removal to delist you immediately.","Prepare a 1:1 icon and 16:9 image under 1MB."]', rw_seo_title='SaaSBison: Free Badge Listing, DR 50', rw_seo_description='How to submit to SaaSBison: free dofollow listing for a permanent dofollow badge, two-week review. Crawler and image rules from the 2026-11-16 snapshot.' WHERE slug='saasbison';
UPDATE submission_sites SET rw_source_lead='A 2,200-resource design directory run by one curator, with a seven-field form and followed outbound links.', rw_what_you_get='A dofollow listing among design tools, judged by one curator on usefulness.', rw_you_need='["A live tool or resource a designer would use in real work"]', rw_eligibility='You need a design-related, genuinely useful tool. Anything not design-related, or that the curator does not judge useful, is refused.', rw_submit_steps='["1 Open the suggest form at /suggest-a-tool — one page, no account, no upload. The header states the bar: only design-related and genuinely useful tools are considered.","2 Fill seven fields: URL, tool name, a 120-character description, a category and a pricing tag are required; email and a message are optional.","3 Pick from two dropdowns: eighteen categories and six pricing values, both real selects with no free-text option.","4 Submit and wait. A Webflow form post with no confirmation number and no queue to watch; the curator reviews by hand with no published turnaround."]', rw_submit_requirements='["A link URL and a tool name","A description up to 120 characters","One of eighteen categories and one of six pricing values","An optional email and message"]', rw_rejection_reasons='["Anything not design-related, and anything the curator does not judge genuinely useful"]', rw_gotchas='["The name field caps at 30 characters and the email field at 30 too, both truncating silently on entry rather than refusing, so a long address lands invalid.","There is no confirmation of any kind after the post and no status page, so a submission that never landed looks like one waiting in the queue."]', rw_faq='[{"question":"How long does TOOOLS.design approval take?","answer":"No review time is published; one curator reviews by hand."},{"question":"How much does it cost to submit to TOOOLS.design?","answer":"Submitting is free."},{"question":"Does a TOOOLS.design listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 47."},{"question":"Do I need to link back to TOOOLS.design?","answer":"No backlink is required."},{"question":"What gets a tool rejected?","answer":"Anything not design-related or not judged genuinely useful."}]', rw_summary='TOOOLS.design is a one-curator design resource directory with a free seven-field submission and a dofollow link. No backlink is required; domain rating is 47 with no published review time.', rw_fact_points='["Hand review with no published timeline","Free submission with a dofollow link","No badge or return link is expected","Accepts design tools, resources and AI design tools"]', rw_submission_checks='["Keep the name and email under 30 characters.","Pick from the fixed category and pricing selects.","Expect no confirmation or status page."]', rw_seo_title='TOOOLS.design: Free Design Listing, DR 47', rw_seo_description='How to submit to TOOOLS.design: free dofollow design-tool listing, no backlink. Seven-field form and silent truncation from the 2026-11-16 snapshot.' WHERE slug='toools-design';
UPDATE submission_sites SET rw_source_lead='A German-registered AI index where the followed link is free and a backlink only buys speed.', rw_what_you_get='A dofollow listing with no backlink required, where adding their footer link just speeds up review.', rw_you_need='["An account via Google, GitHub or email","A name, a description and a live URL","Nothing else — the backlink is optional"]', rw_eligibility='You need an account and basic details. Anything with no AI in it has no shelf, since all seventeen categories are AI.', rw_submit_steps='["1 Enter the URL in one field, then Continue free submission. They check the site is up and offer to fetch your copy.","2 Sign in with Google, GitHub or email; the panel says this does not start a paid placement.","3 Five steps. Essentials first: website, name, an optional 150-character slogan and a description up to 1,000 characters.","4 Wait for their team to verify and enrich the listing. A footer link, if you took it, is checked after submission."]', rw_submit_requirements='["An account on the site","A slogan up to 150 characters and a description up to 1,000"]', rw_rejection_reasons='["Anything with no AI in it, since every one of their seventeen shelves is an AI category"]', rw_gotchas='["The five-step form would not advance past step one in testing: fields rendered blank, counters updated, and Next did nothing with no error.","The link to them is a fast-track, not a price — the follow is free either way, the reverse of most directories this size.","The auto-fill button writes your listing from your homepage, so the copy under your product is theirs unless you type over it.","They quote one to two weeks for standard review against 48 hours with their footer link."]', rw_faq='[{"question":"How long does Best-AI.org approval take?","answer":"One to two weeks standard, or 48 hours with their footer link."},{"question":"How much does it cost to submit to Best-AI.org?","answer":"Submitting is free; a footer link only speeds review, it does not buy the listing."},{"question":"Does a Best-AI.org listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 45."},{"question":"Do I need to link back to Best-AI.org?","answer":"No backlink is required — it only fast-tracks review."},{"question":"What gets a listing rejected?","answer":"Anything with no AI angle."}]', rw_summary='Best-AI.org is a German-registered AI index where a free dofollow listing needs no backlink — a footer link only speeds review from two weeks to 48 hours. Domain rating is 45.', rw_fact_points='["One-to-two-week review, 48 hours with a link","Free listing with a dofollow link and no backlink","The backlink is a fast-track, not a fee","Accepts AI tools, SaaS, developer tools and marketing tools"]', rw_submission_checks='["No backlink needed — add one only to speed review.","Type over the auto-filled copy from your homepage.","The form stalled in testing; retry if Next does nothing."]', rw_seo_title='Best-AI.org: Free AI Listing, DR 45', rw_seo_description='How to submit to Best-AI.org: free dofollow AI listing with no backlink, 1-2 week review. Link-as-fast-track from the 2026-11-16 snapshot.' WHERE slug='best-ai-org';
UPDATE submission_sites SET rw_source_lead='An indie directory that ranks by dwell time rather than votes, and refuses any product whose site will not load in an iframe.', rw_what_you_get='A dofollow listing with a live iframe preview, ranked by how long people stay rather than by votes.', rw_you_need='["A site that renders in an iframe, without frame-blocking headers","An account via Google or email and password","A logo and a tagline under 120 characters"]', rw_eligibility='You need an embeddable site, an account, a logo and a tagline. Sites sending X-Frame-Options or restrictive frame-ancestors, and URLs already submitted, are refused.', rw_submit_steps='["1 Create an account at /auth/sign-up with Google or email and password. The form is at /app/create, unreachable signed out; /app/submit is a 404.","2 Paste the URL and wait for the iframe check. BuildHop fetches your site as you type and reports whether it can be previewed.","3 Upload the logo first — PNG, JPG, WebP or GIF, resized to a 256x256 WebP. The upload re-mounts the form, so do it before filling text fields.","4 Fill the five remaining fields: product name up to 80, tagline up to 120, one of twelve categories, maker name up to 40 and an optional X link that makes the name clickable.","5 Submit for review. You land on the record''s page marked Pending review, editable until approval; the same record appears under Recent Submissions, which is the count to check."]', rw_submit_requirements='["A live URL that allows iframe embedding","A logo image","A product name up to 80 and a tagline up to 120 characters","One of twelve categories and a maker name up to 40","An optional X profile link"]', rw_rejection_reasons='["Sites sending frame-blocking headers, which the form refuses before submission, and URLs already submitted by someone else"]', rw_gotchas='["Your site has to load inside their iframe; the form checks for frame-blocking headers as you paste the URL, and X-Frame-Options blocks submission entirely.","Uploading the logo re-mounts the whole form and empties every field already filled, so it must go first.","The two extra dofollow links on the form are listings on two sister sites: submitting here hands your URL to both, not just BuildHop."]', rw_faq='[{"question":"How long does BuildHop approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to BuildHop?","answer":"Submitting is free."},{"question":"Does a BuildHop listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 43."},{"question":"Do I need to link back to BuildHop?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Frame-blocking headers or a URL already submitted."}]', rw_summary='BuildHop is an indie directory ranked by dwell time with a free dofollow listing and no backlink. Your site must allow iframe embedding; domain rating is 43.', rw_fact_points='["No published review time","Free listing with a dofollow link","An iframe-friendly site is mandatory","Accepts indie products, developer tools, AI tools and SaaS"]', rw_submission_checks='["Remove X-Frame-Options before applying.","Upload the logo first — it resets the form.","Your URL is shared with two sister sites."]', rw_seo_title='BuildHop: Free Indie Listing, DR 43', rw_seo_description='How to submit to BuildHop: free dofollow indie listing, no backlink. iframe requirement and form reset from the 2026-11-16 snapshot.' WHERE slug='buildhop';
UPDATE submission_sites SET rw_source_lead='A dofollow AI directory whose only agent-usable sign-in route was returning a callback error.', rw_what_you_get='A dofollow listing behind a Google or Discord login, though the Google callback failed in testing.', rw_you_need='["An account via Google or Discord — the only two options","A live product URL"]', rw_eligibility='You need one of the two OAuth accounts. Nothing is stated on the public side.', rw_submit_steps='["1 Sign in first. /submit redirects to /signin, offering Discord and Google and nothing else — no email or password form at all.","2 The form is behind the wall. Nothing about the submission fields is visible until the session exists."]', rw_submit_requirements='["A Google or Discord account","A live product URL"]', rw_rejection_reasons='["Nothing stated on the public side"]', rw_gotchas='["Signing in with Google completed on Google''s side then bounced back to /signin with a callback error, still signed out, twice in a row — leaving Discord as the only working way in.","There are exactly two sign-in options and no email fallback, so a provider that fails leaves no other door.","A number of listings point at a product belonging to the same operator, so the directory is partly a shop window for its own product."]', rw_faq='[{"question":"How long does BasedTools approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to BasedTools?","answer":"Submitting is free."},{"question":"Does a BasedTools listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 42."},{"question":"Do I need to link back to BasedTools?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Nothing stated publicly."}]', rw_summary='BasedTools is a free dofollow AI directory with no backlink, but a Google-or-Discord login gates the form and the Google callback failed in testing. Domain rating is 42.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","Accepts AI tools and SaaS products"]', rw_submission_checks='["Use Discord if the Google callback fails.","There is no email sign-in fallback.","Expect a partly self-promotional catalogue."]', rw_seo_title='BasedTools: Free AI Listing, DR 42', rw_seo_description='How to submit to BasedTools: free dofollow AI listing, no backlink. OAuth sign-in caveat from the 2026-11-16 snapshot.' WHERE slug='basedtools';
UPDATE submission_sites SET rw_source_lead='A micro-SaaS directory built around your tech stack, where review is unlocked by upvoting three strangers.', rw_what_you_get='A listing in a stack-tagged micro-SaaS catalogue, unlocked for review by cheering three other products.', rw_you_need='["An account created during the flow","A square logo of 256px or more and at least one screenshot","A tagline of 10 to 80 characters and a description of 50 to 1,000"]', rw_eligibility='You need an account, logo, screenshot and copy within limits. Anything manual curation judges off-topic for micro-SaaS is refused.', rw_submit_steps='["1 Fill product information: name, a 10 to 80 character tagline, a rich-text description of 50 to 1,000 characters, your URL, one of about forty categories and an optional pricing note.","2 Declare your stack across tabs for frameworks, languages, databases, infrastructure, APIs, payments and AI — optional but the whole point of the directory.","3 Create the account. Submitting signed out saves the draft and redirects to /register with Google, X or email and password; the draft is restored but media must be reattached.","4 Add brand and media — a step that only exists once signed in: a required square logo and at least one screenshot.","5 Submit, then earn the review. A Turnstile passes on its own, but the success page says review is locked until you cheer three other products."]', rw_submit_requirements='["A product name, tagline and description within limits","A website URL and one category","A square logo of 256px or more and a screenshot up to 5MB","An account created during submission","Optional tech stack and badge"]', rw_rejection_reasons='["Anything manual curation judges off-topic for micro-SaaS"]', rw_gotchas='["Nothing reaches review until you cheer three other products, and Cheer silently does nothing until your profile has a handle, display name and bio — otherwise the counter stays at 0/3.","The logo and screenshot are required but the step asking for them appears only after account creation, so a signed-out run reaches the last button thinking it is finished.","The badge that upgrades the link to dofollow points at your own listing rather than their homepage, so you host a link back to yourself."]', rw_faq='[{"question":"How long does BuildVoyage approval take?","answer":"One to two days, once the three cheers unlock review."},{"question":"How much does it cost to submit to BuildVoyage?","answer":"Submitting is free."},{"question":"Does a BuildVoyage listing provide a dofollow link?","answer":"No — listing links are nofollow on a domain rated 41; a badge can upgrade it."},{"question":"Do I need to link back to BuildVoyage?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Anything judged off-topic for micro-SaaS."}]', rw_summary='BuildVoyage is a stack-tagged micro-SaaS directory with a free listing whose review unlocks after cheering three other products. No backlink is required; domain rating is 41.', rw_fact_points='["Review in one to two days after three cheers","Free listing with nofollow links","No backlink required; a badge can upgrade the link","Accepts micro-SaaS, indie projects, dev tools and no-code tools"]', rw_submission_checks='["Complete your profile before cheering — otherwise the counter stays 0/3.","Create the account early; media must be reattached after.","The dofollow badge links back to your own listing."]', rw_seo_title='BuildVoyage: Free Micro-SaaS Listing, DR 41', rw_seo_description='How to submit to BuildVoyage: free micro-SaaS listing with a stack, unlocked by cheering three products. No backlink — 2026-11-16 snapshot.' WHERE slug='buildvoyage';
UPDATE submission_sites SET rw_source_lead='A Chinese-language equivalent of Product Hunt, with a followed link and no sign-in route an agent can take.', rw_what_you_get='A dofollow listing on a weekly board competing for upvotes, read by a Chinese-speaking audience.', rw_you_need='["An account via GitHub, Weibo, QQ or email and password","A product name and URL","A tagline, an about block and Chinese-language category and tags"]', rw_eligibility='You need one of the four account routes and Chinese-language listing details. Nothing is formally stated as a rejection reason.', rw_submit_steps='["1 Make an account. The login page offers GitHub, Weibo and QQ alongside email and password; Google is not among them.","2 Post the product with a name, URL, tagline, about block, one category and tags, all from Chinese-language lists.","3 It goes on the weekly board, competing on upvotes across weekly, monthly and yearly leaderboards."]', rw_submit_requirements='["An account via GitHub, Weibo, QQ or email and password","A product name and URL","A tagline and an about-the-product description","One category and tags"]', rw_rejection_reasons='["Nothing stated, though every listing on the site is written in Chinese"]', rw_gotchas='["Every listing, category, tag and comment is in Simplified Chinese, so English copy stands apart and the upvoters are a Chinese-speaking audience.","There is no Google sign-in — GitHub, Weibo, QQ or email and password — so an agent cannot create the account for you.","The community is small; the homepage reported 98,018 visits for all of 2025, so this is a niche audience, not a traffic source."]', rw_faq='[{"question":"How long does Xinquji approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to Xinquji?","answer":"Submitting is free."},{"question":"Does an Xinquji listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 41."},{"question":"Do I need to link back to Xinquji?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Nothing stated; the audience and content are Chinese-language."}]', rw_summary='Xinquji is a Chinese-language Product Hunt equivalent with a free dofollow listing and no backlink. The account must be created by you; domain rating is 41.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","Accepts SaaS, AI tools, developer tools and indie projects"]', rw_submission_checks='["Expect to write Chinese-language copy.","Create the account yourself — no agent-friendly sign-in.","Treat it as a niche audience, not major traffic."]', rw_seo_title='Xinquji: Free Chinese Launch, DR 41', rw_seo_description='How to submit to Xinquji: free dofollow Chinese-language Product Hunt equivalent, no backlink. Sign-in and audience from the 2026-11-16 snapshot.' WHERE slug='xinquji';
UPDATE submission_sites SET rw_source_lead='A large AI directory with MCP and Agent Skills sections — and no way in that does not cost money.', rw_what_you_get='A dofollow listing whose tier buys listing speed and featured time, with details collected only after payment.', rw_you_need='["An account via Google, GitHub or email","A payment, since the cheapest tier is the entry","A live product they reserve the right to decline"]', rw_eligibility='You need an account and payment. Gambling and betting tools, malicious software, and anyone unwilling to pay are refused — there is no free tier at any speed.', rw_submit_steps='["1 Sign in with Google, GitHub or email. The submit page is a modal until you do.","2 Pick a tier: Basic $10, FastTrack $19 or Boosted $49, all one-time. The page is a pitch deck with traffic figures before it is a form.","3 Pay, then fill. Their FAQ has an entry for what to do after payment, so listing details come after the card."]', rw_submit_requirements='["An account on the site","A payment of $10, $19 or $49 one-time","A live product"]', rw_rejection_reasons='["Gambling and betting tools, malicious software, and anyone unwilling to pay — there is no free tier"]', rw_gotchas='["There is no free tier at all; the cheapest way in is $10 and no unpaid queue is offered.","Listing details are collected after payment rather than before, so you cannot see the form you are buying.","They reserve the right to decline a request, stated plainly in the FAQ, which puts the refund question on you before paying.","The submit page opens as a sign-in modal over a sales page, so it reads like a form long before there is one."]', rw_faq='[{"question":"How long does EliteAI.tools approval take?","answer":"One to two days; Basic lists in one to three days, FastTrack within 24 working hours."},{"question":"How much does it cost to submit to EliteAI.tools?","answer":"Three one-time tiers, no free one: $10 Basic, $19 FastTrack with a week featured, $49 Boosted with thirty days featured."},{"question":"Does an EliteAI.tools listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 40."},{"question":"Do I need to link back to EliteAI.tools?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Gambling, betting, malicious software, or unwillingness to pay."}]', rw_summary='EliteAI.tools is a paid-only AI directory with a dofollow listing from $10 and no backlink. Details are collected after payment; domain rating is 40.', rw_fact_points='["Paid-only from $10 with a one-to-three-day listing","Dofollow listing with no backlink requirement","No badge or return link is expected","Accepts SaaS, AI tools, developer tools and indie products"]', rw_submission_checks='["Expect to pay — there is no free tier.","Details are requested after payment.","They reserve the right to decline; ask about refunds first."]', rw_seo_title='EliteAI.tools: $10 AI Listing, DR 40', rw_seo_description='How to submit to EliteAI.tools: paid $10+ dofollow AI listing, no backlink. Post-payment form and MCP sections from the 2026-11-16 snapshot.' WHERE slug='eliteaitools';
UPDATE submission_sites SET rw_source_lead='A no-code catalogue with plain dofollow links, behind an account you cannot create with Google.', rw_what_you_get='A dofollow listing in the Book of NoCode, filed under software, agency, resource or product stack.', rw_you_need='["An account, required before any form is shown","A product in one of four buckets: software, agency, resource or product stack"]', rw_eligibility='You need an account and a no-code product in one of four buckets. Anything with no no-code angle is a stretch — a general SaaS product does not fit.', rw_submit_steps='["1 Pick which of the four you are: NoCode Software, Agency, Resource or Product Stack. They are different forms, so choosing wrong means starting again.","2 Make an account first — To Submit, you have to be Logged In sits under the buttons, so you can edit later and get comments and upvotes.","3 Sign up by email link or by setting a password. There is no Google, GitHub or other single sign-on anywhere.","4 Fill the form for your type, visible only once signed in, including a category from roughly a hundred."]', rw_submit_requirements='["An account on the site","A submission type from the four buckets","A product URL and a category from about a hundred"]', rw_rejection_reasons='["Anything with no no-code angle, since the whole catalogue is the Book of NoCode"]', rw_gotchas='["There is no single sign-on — an emailed link or a password you set — so this cannot be handed to an agent limited to Google.","You choose one of four submission types before anything else, and they are separate forms rather than a field you can change later.","Their contact for anything that goes wrong is a named personal email address."]', rw_faq='[{"question":"How long does NoCodeList approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to NoCodeList?","answer":"Submitting is free."},{"question":"Does a NoCodeList listing provide a dofollow link?","answer":"Yes, a plain dofollow link on a domain rated 37."},{"question":"Do I need to link back to NoCodeList?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Anything with no no-code angle."}]', rw_summary='NoCodeList is a no-code catalogue with a free dofollow listing and no backlink. An account is required but cannot be made with Google; domain rating is 37.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","Accepts no-code tools, platforms and design resources"]', rw_submission_checks='["Create an account by email link or password — no SSO.","Choose the right one of four forms first.","Have a genuine no-code angle."]', rw_seo_title='NoCodeList: Free No-Code Listing, DR 37', rw_seo_description='How to submit to NoCodeList: free dofollow no-code listing, no backlink, email/password account required. Four types from the 2026-11-16 snapshot.' WHERE slug='nocodelist';
UPDATE submission_sites SET rw_source_lead='One person''s hand-picked gallery of Open Graph images, where the whole submission is a URL and the judgement is on one image.', rw_what_you_get='A dofollow listing in a design-focused OG-image gallery, if your social card is good enough to sit beside Stripe''s.', rw_you_need='["An Open Graph image worth featuring","A live URL whose OG tags resolve, since the form previews them"]', rw_eligibility='You need a strong OG image and a URL with resolving tags. A site with no OG image, or a generic one, is refused — the image is the entire submission.', rw_submit_steps='["1 Open /submit. It asks for a URL and an optional Twitter handle; no account, email field or category.","2 Type the URL and watch the preview. A panel under the field fetches and renders your live OG image — a free check that your tags resolve.","3 Add a handle if you want the credit. The Twitter field is optional and its help text says it is so they can tag you.","4 Send it. The form is replaced in place by a Merci message — the only confirmation, with no email, reference or queue."]', rw_submit_requirements='["A live URL with resolving OG tags","An optional Twitter handle"]', rw_rejection_reasons='["A site with no OG image, or a generic one — the image is the entire submission"]', rw_gotchas='["It is hand-picked by one person with no account, email or reference anywhere, so a submission that is not chosen simply never appears and nothing tells you.","Only the image is judged. A strong product behind a default framework OG card gets nowhere, and there is no field in which to argue for it."]', rw_faq='[{"question":"How long does OGimage.gallery approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to OGimage.gallery?","answer":"Submitting is free."},{"question":"Does an OGimage.gallery listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 35."},{"question":"Do I need to link back to OGimage.gallery?","answer":"No backlink is required."},{"question":"What gets a site rejected?","answer":"No OG image, or a generic one."}]', rw_summary='OGimage.gallery is a one-person hand-picked gallery of Open Graph images with a free dofollow listing and no backlink. Only your OG image is judged; domain rating is 35.', rw_fact_points='["Hand-picked with no published timeline","Free submission with a dofollow link","No badge or return link is expected","Accepts websites, SaaS, design work and portfolios"]', rw_submission_checks='["Check the live OG-image preview before sending.","The image is all that is judged — make it strong.","Expect no confirmation beyond the on-page message."]', rw_seo_title='OGimage.gallery: Free Design Listing, DR 35', rw_seo_description='How to submit to OGimage.gallery: free dofollow listing in a hand-picked Open Graph image gallery, no backlink. Steps from the 2026-11-16 snapshot.' WHERE slug='ogimage-gallery';
UPDATE submission_sites SET rw_source_lead='One URL field behind a sign-up, three followed links on the listing, and no confirmation afterwards.', rw_what_you_get='A dofollow listing built entirely from your URL, written by them rather than by you.', rw_you_need='["A live URL they can read","An account via Google or email and password with a terms checkbox"]', rw_eligibility='You need a live URL and an account. Anything that is not software a solopreneur would buy is out, since that is the whole shelf.', rw_submit_steps='["1 Paste the URL. The form at /submit has one field, with a line saying they will start collecting all the goods from it.","2 Sign up when asked. Submit product signed out opens a Sign up to continue dialog: Google, or email and password with a terms checkbox. The URL is only taken once signed in.","3 Press Submit product. Signed in, nothing visible happens — no redirect, no message, and the field clears unreliably."]', rw_submit_requirements='["A live product URL","An account via Google or email and password"]', rw_rejection_reasons='["Anything that is not software a solopreneur would buy, which is the whole shelf"]', rw_gotchas='["The form looks accountless and is not — Submit product opens a sign-up dialog the first time; sign up or in before expecting anything to land.","There is no confirmation once signed in: the page does not change, redirect or show a message, so the only proof is a 200 response you cannot see.","Because nothing acknowledges the press, it is easy to submit the same URL three times before you are sure it landed.","You write nothing but the URL — every word on the listing is theirs."]', rw_faq='[{"question":"How long does FiveTaco approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to FiveTaco?","answer":"Submitting is free."},{"question":"Does a FiveTaco listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 34."},{"question":"Do I need to link back to FiveTaco?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Anything that is not software a solopreneur would buy."}]', rw_summary='FiveTaco is a free dofollow software directory where you submit only a URL behind a sign-up, with no confirmation afterward. No backlink is required; domain rating is 34.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","Accepts SaaS, marketing and productivity software"]', rw_submission_checks='["Sign up before submitting — the URL is not taken until then.","Do not press Submit repeatedly; there is no confirmation.","Expect them to write all the listing copy."]', rw_seo_title='FiveTaco: Free Software Listing, DR 34', rw_seo_description='How to submit to FiveTaco: free dofollow software listing from a URL, no backlink. Sign-up and no-confirmation caveat from the 2026-11-16 snapshot.' WHERE slug='fivetaco';
UPDATE submission_sites SET rw_source_lead='Turkey''s Product Hunt: a free four-step launch form for products by Turkish founders.', rw_what_you_get='A dofollow launch listing on a board reserved for products by Turkish founders.', rw_you_need='["A live URL","A Google or GitHub account","A Turkish founder behind the product"]', rw_eligibility='You need a live URL, an account and a Turkish founder — the site''s own description limits the board to products by Turkish founders.', rw_submit_steps='["1 Sign in with Google or GitHub on the English login route.","2 Project Info: name, URL with an AI Auto-fill, a short description, a 1:1 logo under 1MB and up to eight 16:9 product images.","3 Continue through Details, Launch Date and Review before submitting.","4 The default language is Turkish; the English mirror and language toggle are available."]', rw_submit_requirements='["A project name and website URL","A short description","A 1:1 logo under 1MB","Optional 16:9 product images, up to eight"]', rw_rejection_reasons='["A product with no Turkish founder, by the site''s own description of itself"]', rw_gotchas='["The site is for products launched by Turkish founders, stated on the about page and in every footer — but the form does not say so, so an off-topic product can be filled in and submitted.","The pricing page says plans are coming soon while the FAQ already answers questions about featuring purchases and refunds, so the free lane''s terms may change.","The default language is Turkish; use the English mirror if needed."]', rw_faq='[{"question":"How long does Product-Tower approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to Product-Tower?","answer":"Submitting is free; paid plans are marked coming soon."},{"question":"Does a Product-Tower listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 33."},{"question":"Do I need to link back to Product-Tower?","answer":"No backlink is required."},{"question":"What gets a launch rejected?","answer":"A product with no Turkish founder."}]', rw_summary='Product-Tower is a Turkish-founded-product launch board with a free dofollow listing and no backlink. Only products with a Turkish founder fit; domain rating is 33.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","For products by Turkish founders"]', rw_submission_checks='["Have a Turkish founder behind the product.","Use the English mirror if Turkish is a barrier.","Paid terms may change — plans are coming soon."]', rw_seo_title='Product-Tower: Free Turkish Launch, DR 33', rw_seo_description='How to launch on Product-Tower: free dofollow launch for Turkish-founded products, no backlink. Eligibility and form from the 2026-11-16 snapshot.' WHERE slug='product-tower';
UPDATE submission_sites SET rw_source_lead='A dofollow from day one — if their sign-in will let you have an account at all.', rw_what_you_get='A dofollow listing with no backlink, though the Google sign-in currently refuses access.', rw_you_need='["An account, which the Google sign-in currently refuses","An email-and-password route if Google fails"]', rw_eligibility='You need an account. Anything that cannot get past the sign-in stops here today.', rw_submit_steps='["1 Try to sign in. /submit redirects to /login, offering Continue with Google above an email-and-password form.","2 Watch it refuse. The Google round trip completes and lands on an AccessDenied error reading You do not have permission to sign in — reproduced twice.","3 The password route is the only remaining way in, since Google fails."]', rw_submit_requirements='["An account via Google or email and password"]', rw_rejection_reasons='["Anything that cannot get past the sign-in, which is where this stops today"]', rw_gotchas='["Google sign-in refuses accounts outright: the consent screen completes then drops you on an AccessDenied page, twice on clean attempts, leaving only a password.","Nothing about the form, its fields or its review time can be seen outside an account — the footer''s dofollow promise is the only readable offer.","The site is a property of a larger network rather than a standalone board, worth weighing for how long the listing will be maintained."]', rw_faq='[{"question":"How long does Puthusu approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to Puthusu?","answer":"Submitting is free."},{"question":"Does a Puthusu listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 33."},{"question":"Do I need to link back to Puthusu?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Anything that cannot get past the sign-in."}]', rw_summary='Puthusu is a free dofollow listing with no backlink, but the Google sign-in currently fails, leaving only a password account. Domain rating is 33.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","Sign-in gates everything and currently fails on Google"]', rw_submission_checks='["Expect Google sign-in to fail; use a password.","No form is visible before an account.","It is part of a larger network of sites."]', rw_seo_title='Puthusu: Free Dofollow Listing, DR 33', rw_seo_description='About Puthusu: free dofollow listing with no backlink, but Google sign-in currently fails. Access details from the 2026-11-16 snapshot.' WHERE slug='puthusu';
UPDATE submission_sites SET rw_source_lead='Seven fields, no account, and a free queue of three weeks against $2 for a day.', rw_what_you_get='A dofollow listing, queued three weeks free or posted within 24 hours for $2.', rw_you_need='["A live URL","An email address","One image"]', rw_eligibility='You need a URL, an email and an image. Nothing is published about who is refused.', rw_submit_steps='["1 Fill seven fields: tool name, email, website, an optional description, an image, one of 72 categories and a pricing model. No account at any point.","2 Press Next. The tool is saved here, before any plan: the next screen opens with Your tool is in.","3 Choose a plan: Free at three weeks, Pro $2 for 24 hours or Max $5. Continue for free needs no card.","4 Read the success page with an optional badge builder — no id, no promised email and no dashboard."]', rw_submit_requirements='["A tool name, email and website URL","An image","One of 72 categories and a pricing model","An optional description"]', rw_rejection_reasons='["Nothing published about who is refused"]', rw_gotchas='["The tool is saved the moment you press Next, before the plan step; backing out to fix a field means a second, duplicate submission.","The free queue is three weeks with nothing showing it moving — no account, dashboard or promised email beyond the address you typed."]', rw_faq='[{"question":"How long does Dynamite AI approval take?","answer":"Two to four weeks; free is reviewed within three weeks, Pro within 24 hours."},{"question":"How much does it cost to submit to Dynamite AI?","answer":"Free in three weeks with no support; $2 once for 24-hour posting, a permanent dofollow link and support; $5 adds three featured days and round-the-clock support."},{"question":"Does a Dynamite AI listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 31, permanent on Pro and up."},{"question":"Do I need to link back to Dynamite AI?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Nothing published about who is refused."}]', rw_summary='Dynamite AI is a free dofollow AI listing queued three weeks, or $2 for 24-hour posting. No backlink is required; domain rating is 31.', rw_fact_points='["Free queue of three weeks; $2 for a day","Dofollow link with no backlink requirement","No badge or return link is expected","Accepts AI tools, SaaS, developer tools and marketing tools"]', rw_submission_checks='["Get fields right before Next — the tool saves immediately.","The free queue is three weeks with no status to check.","$2 buys speed and a permanent followed link."]', rw_seo_title='Dynamite AI: Free AI Listing, DR 31', rw_seo_description='How to submit to Dynamite AI: free dofollow AI listing in three weeks or $2 for a day, no backlink. Seven-field form from the 2026-11-16 snapshot.' WHERE slug='dynamite-ai';
UPDATE submission_sites SET rw_source_lead='A hand-picked library of design resources whose whole intake is a four-field Notion form, free, with a dofollow link.', rw_what_you_get='A dofollow listing in a curated design-resource library, if the curator chooses your link.', rw_you_need='["A resource a designer would actually open","A URL to share — name and email are only for being told if it publishes"]', rw_eligibility='You need a design resource. Anything outside design — the library is Figma files, icon sets, AI design tools and typography — is out.', rw_submit_steps='["1 Open the Notion form. The Submit link is a short link to a Notion-hosted form; no account or dashboard.","2 Fill four fields: name, email, the URL to share and an open anything else box. Name and email are only used to tell you if it gets published.","3 Wait with nothing to check — no reference number, status page or stated review time; the only signal is an email, and only if they publish it."]', rw_submit_requirements='["The resource URL","An optional name and email for publication notice","An optional note on why it belongs"]', rw_rejection_reasons='["Anything outside design — Figma resources, icon sets, typography and AI design tools are the scope"]', rw_gotchas='["It is a recommendation box, not a submission form: their copy says they will check it out and potentially add it, there is no confirmation, and only the URL matters.","The scope is genuinely design; a product merely useful to designers is not the same thing, and a wrong-fit submission disappears silently."]', rw_faq='[{"question":"How long does Fountn approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to Fountn?","answer":"Submitting is free."},{"question":"Does a Fountn listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 32."},{"question":"Do I need to link back to Fountn?","answer":"No backlink is required."},{"question":"What gets a resource rejected?","answer":"Anything outside design resources."}]', rw_summary='Fountn is a hand-picked design-resource library with a free dofollow listing and no backlink. Intake is a four-field Notion form with no status; domain rating is 32.', rw_fact_points='["Hand-picked with no published timeline","Free listing with a dofollow link","No badge or return link is expected","Accepts Figma resources, icon sets, typography and AI design tools"]', rw_submission_checks='["Make it a genuine design resource, not just designer-useful.","Only the URL matters; name and email are optional.","Expect no confirmation or status."]', rw_seo_title='Fountn: Free Design Resource, DR 32', rw_seo_description='How to submit to Fountn: free dofollow design-resource listing via a four-field Notion form, no backlink. Scope from the 2026-11-16 snapshot.' WHERE slug='fountn';
UPDATE submission_sites SET rw_source_lead='One person reads every submission, and the form says so: fill it yourself, because an automated one gets dropped.', rw_what_you_get='A dofollow listing in a hand-reviewed AI tools index.', rw_you_need='["A live URL","A working email you actually read","A person to fill the form"]', rw_eligibility='You need a live URL, a real email and a human submitter. Off-topic products, automated submissions, and NSFW, gambling, weapons and crypto platforms are refused.', rw_submit_steps='["1 Read the rules above the form: AI-focused only, no bot submissions — they say automated entries are not processed and may trigger an IP ban — and a working email.","2 One form: a tool name capped at 30 characters, tool URL, email, then a 16:9 screenshot and a square icon, both resized on upload with a Ready badge showing new dimensions.","3 Submit Tool answers Submission Successful and says review is by hand with the result by email. No time is given."]', rw_submit_requirements='["A tool name up to 30 characters","A tool URL and a working email","A 16:9 screenshot resized to 1920x1080","A 1:1 icon resized to 512x512"]', rw_rejection_reasons='["Anything off-topic for AI, automated submissions, and NSFW, gambling, weapons or crypto platforms"]', rw_gotchas='["They say in their own words that automated entries are not processed and mass bot submissions may trigger IP bans — fill this yourself or watch it being filled.","A temporary or non-working email is flagged as spam, so the address must be one somebody reads.","Crypto platforms are refused outright alongside NSFW and gambling."]', rw_faq='[{"question":"How long does AI Navbar approval take?","answer":"No review time is published; review is by hand with results by email."},{"question":"How much does it cost to submit to AI Navbar?","answer":"Submitting is free."},{"question":"Does an AI Navbar listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 30."},{"question":"Do I need to link back to AI Navbar?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Off-topic AI products, automated submissions, and NSFW, gambling, weapons or crypto."}]', rw_summary='AI Navbar is a hand-reviewed AI tools index with a free dofollow listing and no backlink. A person must fill the form and use a working email; domain rating is 30.', rw_fact_points='["Hand review with no published timeline","Free listing with a dofollow link","No badge or return link is expected","Accepts AI tools and AI-related tools"]', rw_submission_checks='["Fill the form as a person — bots may be banned.","Use a real email; temporary addresses are flagged.","Prepare a 16:9 screenshot and a square icon."]', rw_seo_title='AI Navbar: Free AI Listing, DR 30', rw_seo_description='How to submit to AI Navbar: free hand-reviewed dofollow AI listing, no backlink. No-bots rule and images from the 2026-11-16 snapshot.' WHERE slug='ainavbar';
UPDATE submission_sites SET rw_source_lead='Sells itself as the Product Hunt alternative, and the followed link is real.', rw_what_you_get='A dofollow launch listing on a board pitched as a Product Hunt alternative.', rw_you_need='["A live public URL","An account"]', rw_eligibility='You need a live URL and an account. Nothing is published about who is refused.', rw_submit_steps='["1 Open the create page. The Submit control leads to /create, not /submit.","2 Fill the launch. The form renders client-side, so its fields are not in the page source.","3 Wait. No review time is published."]', rw_submit_requirements='["A live public URL","An account"]', rw_rejection_reasons='["Nothing published about who is refused"]', rw_gotchas='["The submit control lands on /create, so a guessed /submit path is not where the form lives.","The site sells advertising and keeps a directories section, so a free launch sits next to paid placement.","Launches, tools and coming-soon are three separate shelves, so check which one you land on."]', rw_faq='[{"question":"How long does Go Publicly approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to Go Publicly?","answer":"Submitting is free; advertising is sold separately."},{"question":"Does a Go Publicly listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 29."},{"question":"Do I need to link back to Go Publicly?","answer":"No backlink is required."},{"question":"What gets a launch rejected?","answer":"Nothing published about who is refused."}]', rw_summary='Go Publicly is a self-styled Product Hunt alternative with a free dofollow launch and no backlink. The form is at /create and no review time is published; domain rating is 29.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","Accepts SaaS, indie products, AI tools and web apps"]', rw_submission_checks='["Use /create, not /submit.","Check which shelf you land on — launch, tool or coming-soon.","No backlink needed."]', rw_seo_title='Go Publicly: Free Launch, DR 29', rw_seo_description='How to launch on Go Publicly: free dofollow launch, no backlink. /create form path from the 2026-11-16 snapshot.' WHERE slug='go-publicly';
UPDATE submission_sites SET rw_source_lead='A business-AI directory whose whole submission is one form on the homepage, with links that carry no rel at all.', rw_what_you_get='A dofollow listing filed under a business department, with the outbound anchor carrying no rel attribute.', rw_you_need='["A live URL the form validates","A product a business would buy, filed under Marketing, Sales, Strategy or Management","A description you are happy to have published as written"]', rw_eligibility='You need a live URL, a business product and publishable copy. A consumer product with no business use has no Type to file it under.', rw_submit_steps='["1 Go to the homepage, not a submit page. Submit Tool in the header is an anchor to a form further down the same page; no account anywhere.","2 Fill seven fields: full name, email, website URL, business name, description, then Type and Categories as searchable multi-selects.","3 Add a logo under a megabyte if you have one — the 1MB cap rejects a full-size PNG export.","4 Submit and keep your own record. The form posts and clears with no account, dashboard or reference number."]', rw_submit_requirements='["A full name, email and website URL","A business name and description","At least one Type from Marketing, Sales, Strategy or Management","Optional categories and a logo under 1MB"]', rw_rejection_reasons='["A consumer product with no business use, which has no Type to file it under"]', rw_gotchas='["There is no confirmation of any kind — the form clears and says nothing, with no account or dashboard, so note what you sent before pressing it.","The logo cap is 1MB, low enough to reject an ordinary PNG export; resize before starting.","Type and Categories look like dropdowns but are searchable multi-selects — a choice counts only once it appears as a chip."]', rw_faq='[{"question":"How long does AI for Businesses approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to AI for Businesses?","answer":"Submitting is free."},{"question":"Does an AI for Businesses listing provide a dofollow link?","answer":"Yes — the outbound link carries no rel attribute at all, on a domain rated 27."},{"question":"Do I need to link back to AI for Businesses?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"A consumer product with no business use."}]', rw_summary='AI for Businesses is a business-AI directory with a free dofollow listing and no backlink, filed under a department. The form is on the homepage with no confirmation; domain rating is 27.', rw_fact_points='["No published review time","Dofollow link with no rel attribute, no backlink","No badge or return link is expected","Accepts AI tools, B2B software and marketing tools"]', rw_submission_checks='["Note your submission before pressing — the form clears silently.","Resize your logo under 1MB first.","Pick a Type from the four departments."]', rw_seo_title='AI for Businesses: Free Listing, DR 27', rw_seo_description='How to submit to AI for Businesses: free dofollow business-AI listing, no backlink. Homepage form and multi-selects from the 2026-11-16 snapshot.' WHERE slug='ai-for-businesses';
UPDATE submission_sites SET rw_source_lead='A niche directory of over a thousand AI writing tools with a six-field form and a followed Visit link.', rw_what_you_get='A dofollow listing among AI writing tools, with copy written by them from your site.', rw_you_need='["A live URL","An email address","One of three categories"]', rw_eligibility='You need a live URL, an email and one of the three AI-writer categories. Anything that is not an AI writing tool is refused on a fit review.', rw_submit_steps='["1 Open Add Your Tool. The header link jumps to a form on the homepage; no account.","2 Fill six fields: email, tool URL, one of three categories, an optional demo video link, an X handle and a free-text message.","3 Wait for the review. The FAQ says the team reviews for fit and adds the tool if it aligns; no time is stated and nothing is emailed by the form."]', rw_submit_requirements='["An email and a tool URL","A category — fully automated, AI blog generator or AI writer","An optional demo video link and X handle","A message"]', rw_rejection_reasons='["Anything that is not an AI writing tool, on a team fit review"]', rw_gotchas='["The three categories are all kinds of AI writer, so a product that is not one has nowhere to sit.","The form takes a URL and a message but no name, tagline or description, so listing copy is written by them from your site — one walk saw a page named after one tool describing another.","A $49 Stripe button labelled Get it now is on every page with no explanation of what it buys, and the FAQ mentions no paid lane."]', rw_faq='[{"question":"How long does AI Blog Generators approval take?","answer":"No review time is published; the team reviews for fit."},{"question":"How much does it cost to submit to AI Blog Generators?","answer":"Submitting is free; an unexplained $49 button exists but no paid listing is documented."},{"question":"Does an AI Blog Generators listing provide a dofollow link?","answer":"Yes, a dofollow Visit link on a domain rated 28."},{"question":"Do I need to link back to AI Blog Generators?","answer":"No backlink is required."},{"question":"What gets a tool rejected?","answer":"Anything that is not an AI writing tool."}]', rw_summary='AI Blog Generators is a niche AI-writing-tools directory with a free dofollow listing and no backlink. Copy is written by them from your site; domain rating is 28.', rw_fact_points='["Fit review with no published timeline","Free listing with a dofollow link","No badge or return link is expected","Accepts AI blog generators, AI writers and automated content tools"]', rw_submission_checks='["Fit one of the three AI-writer categories.","Expect them to write the listing copy from your site.","The $49 button is unexplained — free submission exists."]', rw_seo_title='AI Blog Generators: Free Writer Listing, DR 28', rw_seo_description='How to submit to AI Blog Generators: free dofollow AI-writing-tool listing, no backlink. Categories and scraped copy from the 2026-11-16 snapshot.' WHERE slug='aibloggenerators';
UPDATE submission_sites SET rw_source_lead='Built for tools that just shipped, and the links do follow.', rw_what_you_get='A dofollow listing for a recently launched AI product, with no backlink required.', rw_you_need='["An AI product, ideally recently launched","A live public URL","An account"]', rw_eligibility='You need an account and a live AI product. The pitch is rising and new tools, so a long-established product is off-theme.', rw_submit_steps='["1 Sign in. /submit redirects to /auth/login with a callback back to the submit page.","2 Fill the listing behind that account.","3 Wait. No review time is published."]', rw_submit_requirements='["A live public URL","An AI product","An account"]', rw_rejection_reasons='["The pitch is rising and new tools, so a long-established product is off-theme"]', rw_gotchas='["The directory is pitched at newly released tools, so a product that launched a year ago competes against the site''s own framing.","The submit path redirects to a login, so the form cannot be read before making an account.","No review time is published, so nothing can be chased afterwards."]', rw_faq='[{"question":"How long does AINewTool approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to AINewTool?","answer":"Submitting is free."},{"question":"Does an AINewTool listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 27."},{"question":"Do I need to link back to AINewTool?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"A long-established product is off-theme for a new-tools directory."}]', rw_summary='AINewTool is a free dofollow directory for newly launched AI tools, with no backlink requirement. The form is behind a login and no review time is published; domain rating is 27.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","Accepts recently launched AI tools and SaaS"]', rw_submission_checks='["Best fit if you just launched.","Make an account before seeing the form.","No timeline to chase."]', rw_seo_title='AINewTool: Free New AI Listing, DR 27', rw_seo_description='How to submit to AINewTool: free dofollow listing for newly launched AI tools, no backlink. Login and theme from the 2026-11-16 snapshot.' WHERE slug='ainewtool';
UPDATE submission_sites SET rw_source_lead='A three-step dashboard form whose Paid option insists on a number.', rw_what_you_get='A dofollow product listing with no backlink, if you can express your price as a number.', rw_you_need='["An account","A live public URL","A numeric price and currency if you choose Paid — the form has no way to say custom quote"]', rw_eligibility='You need an account, a URL and — if Paid — a number. Nothing is published about who is refused.', rw_submit_steps='["1 Sign in. The dashboard is behind the header control; the old /products/submit guess renders a Product Not Found page.","2 Basic Info at /dashboard/products/add: name and a short description, an image URL and a website link.","3 Metadata and Visibility: tags and tech stack as comma-separated text, a status of Active, Inactive or Coming Soon and one of seven categories.","4 Pricing and Launch: Free, Paid or Freemium. Paid reveals a required numeric Amount and a currency; Launch Product stays disabled until it is filled."]', rw_submit_requirements='["An account and a product name with a short description","An optional hosted image URL and a website link","Optional tags and tech stack","A status and one of seven categories","A pricing model — Paid needs a number and a currency"]', rw_rejection_reasons='["Nothing published about who is refused"]', rw_gotchas='["A paid product has to be a number: Paid reveals a required Amount and currency with no way to describe a quote, range or contact-us, so such products must pick Freemium or invent a figure.","The logo is an image URL, not an upload, so the file must be hosted publicly first.","The product page''s outbound control reads Get Started, so it looks like a signup for their site until you check where it points.","Advertising is sold from the main navigation, so feed ordering is not purely editorial."]', rw_faq='[{"question":"How long does Kick Product approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to Kick Product?","answer":"Submitting is free; advertising is sold separately."},{"question":"Does a Kick Product listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 28."},{"question":"Do I need to link back to Kick Product?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Nothing published about who is refused."}]', rw_summary='Kick Product is a free dofollow product listing with no backlink, submitted through a three-step dashboard form. Paid products need a numeric price; domain rating is 28.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","Accepts SaaS, indie products and AI tools"]', rw_submission_checks='["Paid needs a number — no custom-quote option.","Host your logo URL publicly.","Use /dashboard/products/add, not the old path."]', rw_seo_title='Kick Product: Free Dofollow Listing, DR 28', rw_seo_description='How to submit to Kick Product: free dofollow listing, no backlink. Numeric pricing rule and dashboard form from the 2026-11-16 snapshot.' WHERE slug='kick-product';
UPDATE submission_sites SET rw_source_lead='A 182-model LLM index with a free dofollow listing, and categories that only make sense if you actually built a model.', rw_what_you_get='A dofollow listing in a language-model index, filed under a property of the model itself.', rw_you_need='["An actual language model, since every category names a model property","A URL and a contact email"]', rw_eligibility='You need a real language model, a URL and an email. Products that are not models have nowhere honest to file themselves.', rw_submit_steps='["1 Follow Submit LLM. The header link is an in-page anchor to a form near the foot of the home page.","2 Fill the form: email, URL, a category, an open-source or proprietary choice, an optional video link, a Twitter handle and a message. No account or captcha.","3 Pick a category that is true — Text-based, Audio-based, Visual-based, Transformer-based, Seq2seq, NLU, NLG, Multilingual, Few-Shot, Zero-Shot, Domain-specific or Ethical Considerations.","4 Wait with nothing published. The submission posts to a Google Sheet through a form host; no review time, account or reference exists."]', rw_submit_requirements='["A contact email and the model URL","One category from the model-property list","An open-source or proprietary answer","Optional video link and Twitter handle"]', rw_rejection_reasons='["Products that are not models — the category list has nowhere honest to put them"]', rw_gotchas='["Every category names a property of a language model, so a product that is not one has no honest option and must choose between untrue claims.","The submission goes into a Google Sheet through a form host rather than the site, with no confirmation, reference or account and no stated review time.","The site links out to its owner''s paid submission service under Submit Website to Directories — an affiliate link, not part of the listing."]', rw_faq='[{"question":"How long does LLM Models Directory approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to LLM Models Directory?","answer":"Submitting is free."},{"question":"Does an LLM Models Directory listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 27."},{"question":"Do I need to link back to LLM Models Directory?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Products that are not language models."}]', rw_summary='LLM Models Directory is a free dofollow index of language models, with no backlink. Categories describe model properties, so only real models fit; domain rating is 27.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","Accepts actual language models only"]', rw_submission_checks='["Only apply if you built a real model.","Pick a category that is actually true.","Submission goes to a Google Sheet — no confirmation."]', rw_seo_title='LLM Models Directory: Free Listing, DR 27', rw_seo_description='How to submit to LLM Models Directory: free dofollow listing for real language models, no backlink. Category rules from the 2026-11-16 snapshot.' WHERE slug='llmmodels';
UPDATE submission_sites SET rw_source_lead='A veteran curator''s free-tools community where the links are dofollow and every front-page post is still his own.', rw_what_you_get='A dofollow listing in a curated free-tools community, published as a post that waits for approval.', rw_you_need='["An account created with an email and password","A tool with a genuinely free tier — the whole site is zero-cost tools"]', rw_eligibility='You need an account and a tool with a real free tier. Anything with no free tier at all is out, since collecting those is the site''s purpose.', rw_submit_steps='["1 Register at /register with an email, a password and a confirmation. There is no single sign-on.","2 Press New Post and get a draft. It is a header button with no URL; pressing it creates an empty draft immediately and silently.","3 Fill the editor: a title in benefit: product-name form, a URL and a rich-text body, with a category, tags and a sticky toggle; auto-save is on.","4 Save and publish. The post moves to its own /item URL reading This post has been submitted and is currently waiting for an approval, with no queue position or stated review time."]', rw_submit_requirements='["An account on the site","A title in benefit, colon, product-name form","A product URL and a body describing the tool","Optional category and tags from existing lists"]', rw_rejection_reasons='["Anything with no free tier at all, which is what the site exists to collect"]', rw_gotchas='["Registration is email and password only — no single sign-on — so this cannot be handed to an agent that only does Google.","Publishing does not publish: the post sits at its own URL reading waiting for an approval, with no queue position or review time.","Pressing New Post creates an empty draft the moment you click, so a mis-click leaves a blank post in Drafts you must clear yourself."]', rw_faq='[{"question":"How long does T5 by Robin Good approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to T5 by Robin Good?","answer":"Submitting is free."},{"question":"Does a T5 by Robin Good listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 28."},{"question":"Do I need to link back to T5 by Robin Good?","answer":"No backlink is required."},{"question":"What gets a tool rejected?","answer":"Anything with no free tier at all."}]', rw_summary='T5 by Robin Good is a free-tools community with a free dofollow listing and no backlink. Posts wait for approval with no stated time; domain rating is 28.', rw_fact_points='["Approval with no published timeline","Free listing with a dofollow link","No badge or return link is expected","Accepts free tools, AI tools, productivity and marketing tools"]', rw_submission_checks='["Have a genuine free tier.","Avoid stray clicks on New Post — it creates blank drafts.","Expect a wait-for-approval state after publishing."]', rw_seo_title='T5 by Robin Good: Free Tool Post, DR 28', rw_seo_description='How to submit to T5 by Robin Good: free dofollow free-tools post, no backlink. Email-only signup and approval from the 2026-11-16 snapshot.' WHERE slug='robin-good-t5';
UPDATE submission_sites SET rw_source_lead='Sold to teams, built from the same parts as nine siblings.', rw_what_you_get='A dofollow listing behind a Google login, on a site shared with nine near-identical directories.', rw_you_need='["A live public URL","A Google account — the only sign-in offered"]', rw_eligibility='You need a live URL and a Google account. Nothing is published about who is refused.', rw_submit_steps='["1 Open the submit page. /submit renders a Log in to Submit panel rather than a form.","2 Log in with Google — the only provider, alongside a Create an account link.","3 Fill the listing behind the login; its fields cannot be read in advance.","4 Wait. No review time is published anywhere."]', rw_submit_requirements='["A live public URL","A Google account","A category from their tree"]', rw_rejection_reasons='["Nothing published about who is refused"]', rw_gotchas='["The submit page shows a login panel and no fields, so there is no way to see what the form asks before committing an account.","Every page carries a sponsored ad for a paid service submitting SaaS to about 140 directories — a competitor marked sponsored nofollow.","Ten sites share the same codebase and copy, differing only in name and accent colour, so a run across them buys far less reach than the count suggests."]', rw_faq='[{"question":"How long does Tool Dynamo approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to Tool Dynamo?","answer":"Submitting is free."},{"question":"Does a Tool Dynamo listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 27."},{"question":"Do I need to link back to Tool Dynamo?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Nothing published about who is refused."}]', rw_summary='Tool Dynamo is a free dofollow listing behind a Google login, with no backlink. It shares a codebase with nine siblings; domain rating is 27.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","Accepts SaaS, AI tools, developer tools and web apps"]', rw_submission_checks='["Sign in with Google to see the form.","Reach overlaps heavily with nine sister sites.","No timeline to plan around."]', rw_seo_title='Tool Dynamo: Free Dofollow Listing, DR 27', rw_seo_description='How to submit to Tool Dynamo: free dofollow listing behind a Google login, no backlink. Shared-engine caveat from the 2026-11-16 snapshot.' WHERE slug='tool-dynamo';
UPDATE submission_sites SET rw_source_lead='A dofollow listing behind a login with an image captcha and mostly Chinese social sign-ins.', rw_what_you_get='A dofollow listing whose form is visible only after an account is created through a captcha-gated registration.', rw_you_need='["A live public URL","An account — via GitHub, QQ, WeChat, Weibo or Baidu, or email and password with a captcha"]', rw_eligibility='You need an account and a live URL. Nothing is published about who is refused.', rw_submit_steps='["1 Open /contribute. It shows notes and comments, but the submission area says login is required.","2 Register or sign in with a username, phone or email and a password, plus a distorted-text image captcha.","3 Or use a social account — GitHub, QQ, WeChat, Weibo or Baidu are offered; no Google.","4 Fill the submission form, visible only once signed in."]', rw_submit_requirements='["A live public URL","An account on the site","One of five social accounts or email and password"]', rw_rejection_reasons='["Nothing published about who is refused"]', rw_gotchas='["Nothing about the submission can be seen without an account — the page loads its guidance and comments and puts a login notice where the form should be.","Registration is gated by a distorted-text captcha, so only a person at the keyboard can create the account.","The five social sign-ins are GitHub, QQ, WeChat, Weibo and Baidu — four assume a Chinese platform account, and there is no Google.","The page is titled friendly-link application rather than tool submission, which here usually implies a reciprocal link is expected."]', rw_faq='[{"question":"How long does AINavTool approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to AINavTool?","answer":"Submitting is free."},{"question":"Does an AINavTool listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 25."},{"question":"Do I need to link back to AINavTool?","answer":"No backlink is stated, though the friendly-link framing implies one."},{"question":"What gets a submission rejected?","answer":"Nothing published about who is refused."}]', rw_summary='AINavTool is a free dofollow AI directory whose form sits behind a captcha-gated account with mostly Chinese social sign-ins. No backlink is stated; domain rating is 25.', rw_fact_points='["No published review time","Free listing with a dofollow link","Captcha-gated account required","Accepts AI tools, SaaS and developer tools"]', rw_submission_checks='["A person must solve the registration captcha.","Expect Chinese social sign-ins; there is no Google.","The friendly-link framing may imply reciprocity."]', rw_seo_title='AINavTool: Free AI Listing, DR 25', rw_seo_description='How to submit to AINavTool: free dofollow AI listing behind a captcha-gated login, no stated backlink. Sign-in options from the 2026-11-16 snapshot.' WHERE slug='ainavtool';
UPDATE submission_sites SET rw_source_lead='A directory of European alternatives to American software — a narrow but genuinely differentiated door.', rw_what_you_get='A dofollow listing in a directory defined by geography, where your EU angle is the whole claim.', rw_you_need='["An account","A European angle: EU company, EU hosting or EU data residency","A live product URL"]', rw_eligibility='You need an account and a European connection. Products with no EU company, hosting or data residency are refused.', rw_submit_steps='["1 Check the premise. The directory lists European alternatives to American software, so a product with no EU angle is off-topic however good.","2 Note the domain. They moved from the old .co to euroalternative.eu, which now redirects; use the .eu address.","3 Sign in. /submit redirects to /auth/login with an email sign-in and a hidden captcha field, gating the submission entirely."]', rw_submit_requirements='["An account","A European angle","A live product URL"]', rw_rejection_reasons='["Products with no European company, hosting or data residency"]', rw_gotchas='["The domain moved — the old .co redirects to .eu, so anything pointing at the old address is stale.","The premise is geographic: without an EU company, EU hosting or EU data residency there is nothing to claim.","The form sits behind an email sign-in with a hidden captcha field, so requirements cannot be read in advance.","It is built on a shared directory starter and sits alongside several sibling sites, so expect the same flow across that family."]', rw_faq='[{"question":"How long does EuroAlternative approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to EuroAlternative?","answer":"Submitting is free."},{"question":"Does a EuroAlternative listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 25."},{"question":"Do I need to link back to EuroAlternative?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Products with no EU company, hosting or data residency."}]', rw_summary='EuroAlternative is a dofollow directory of European alternatives to US software, with a free listing and no backlink. An EU company, hosting or data residency is required; domain rating is 25.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","Accepts SaaS and European alternatives to US software"]', rw_submission_checks='["Use the .eu domain — the old one redirects.","Have a real EU company, hosting or data-residency angle.","The form is behind an email sign-in with a captcha."]', rw_seo_title='EuroAlternative: Free EU Listing, DR 25', rw_seo_description='How to submit to EuroAlternative: free dofollow listing for European software alternatives, no backlink. EU eligibility from the 2026-11-16 snapshot.' WHERE slug='euroalternative';
UPDATE submission_sites SET rw_source_lead='A curated catalogue with a sponsored shelf running beside the free one.', rw_what_you_get='A dofollow listing in a curated catalogue, managed from a dashboard after sign-up.', rw_you_need='["A live public URL","An account made with an email and password"]', rw_eligibility='You need an account and a live URL. Nothing is published about who is refused.', rw_submit_steps='["1 Make an account. The submit route redirects to a login with email and password and no social provider visible.","2 Submit from the dashboard, which the login is described as granting access to.","3 Wait. No review time is published."]', rw_submit_requirements='["A live public URL","An account via email and password"]', rw_rejection_reasons='["Nothing published about who is refused"]', rw_gotchas='["Sign-up is an email and password form with no Google or GitHub option, so a person must make the account first.","The catalogue runs a sponsored and promoted shelf beside the free one, so the ordering is partly paid.","No review time is published, so there is nothing to chase once the listing is sent."]', rw_faq='[{"question":"How long does EverFeatured approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to EverFeatured?","answer":"Submitting is free; sponsored and promoted placement is sold separately."},{"question":"Does an EverFeatured listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 26."},{"question":"Do I need to link back to EverFeatured?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Nothing published about who is refused."}]', rw_summary='EverFeatured is a curated catalogue with a free dofollow listing and no backlink, managed from a dashboard. Email sign-up only; domain rating is 26.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","Accepts SaaS, indie products and AI tools"]', rw_submission_checks='["Create an email-and-password account — no social sign-in.","Expect partly paid ordering.","No timeline to chase."]', rw_seo_title='EverFeatured: Free Curated Listing, DR 26', rw_seo_description='How to submit to EverFeatured: free dofollow curated listing, no backlink. Email signup and sponsored shelf from the 2026-11-16 snapshot.' WHERE slug='everfeatured';
UPDATE submission_sites SET rw_source_lead='German-language, free, followed — and they rewrite your listing themselves.', rw_what_you_get='A dofollow listing in a German AI directory where editors write the final description in German from your brief.', rw_you_need='["A live public URL","A name and a description of 600 characters or fewer — treated as a briefing, not the final copy"]', rw_eligibility='You need a live URL and a short pitch. Tools the editors judge unsuitable are the only stated filter.', rw_submit_steps='["1 Open /einreichen. Four fields, no account or sign-in anywhere.","2 Give a name, URL and a short description capped at 600 characters, as the label states.","3 Pick one of 21 categories — Marketing & SEO, Produktivitaet, Entwickler Tools, Marktplatz and Agents are among them.","4 Submit. The form is replaced by a thank-you saying they will review it and add it if suitable."]', rw_submit_requirements='["A tool name up to 120 characters","A website URL","A short description up to 600 characters","One of 21 categories"]', rw_rejection_reasons='["Tools the editors judge unsuitable, the only filter they state"]', rw_gotchas='["The site and listings are entirely in German and the editors rewrite each entry in several hundred words. Your 600 characters are a briefing for that rewrite, so anything that must be said precisely belongs in it.","There is no account and no confirmation email field, so once the thank-you replaces the form there is no way to check on it or correct anything."]', rw_faq='[{"question":"How long does ki-suche.io approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to ki-suche.io?","answer":"Submitting is free."},{"question":"Does a ki-suche.io listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 25."},{"question":"Do I need to link back to ki-suche.io?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Tools the editors judge unsuitable."}]', rw_summary='ki-suche.io is a free German-language AI directory with a dofollow listing and no backlink. Editors rewrite your 600-character brief into German copy; domain rating is 25.', rw_fact_points='["Editor review with no published timeline","Free listing with a dofollow link","No badge or return link is expected","Accepts AI tools with a German-language listing"]', rw_submission_checks='["Write the 600-character brief carefully — editors rewrite it.","Expect a German-language listing.","No account or confirmation to check later."]', rw_seo_title='ki-suche.io: Free German AI Listing, DR 25', rw_seo_description='How to submit to ki-suche.io: free dofollow German AI listing, no backlink. Editors rewrite your brief — 2026-11-16 snapshot.' WHERE slug='ki-suche';
UPDATE submission_sites SET rw_source_lead='Paste a repo URL and you are done, or fill the long form and hit a required phone field.', rw_what_you_get='A nofollow MCP listing, reachable instantly through a repo URL on the quick path.', rw_you_need='["An MCP server or client","A public GitHub repository for the quick path","An account via GitHub or Google"]', rw_eligibility='You need an MCP server or client and an account. A product that does not speak MCP has nothing to list here.', rw_submit_steps='["1 Sign in. /submit redirects to /auth/login with GitHub and Google; Google creates the account in one click asking only name and email.","2 Pick a lane. GitHub Repository is the quick submit asking only for the repo URL; Manual Entry is the long form.","3 Quick path: paste the full repository URL in the form https://github.com/owner/repo and press Submit.","4 Manual path: MCP name, author, contact phone and a logo are required, with an optional description, tags, a self-hosted server URL and a platform-hosted JSON config below.","5 Wait. There is a review referred to on the form but no published duration."]', rw_submit_requirements='["A GitHub repository URL in owner/repo form for the quick path","A logo on the manual form, or a generated one","A contact phone on the manual form only","A description of at least about 30 characters","An account via GitHub or Google"]', rw_rejection_reasons='["A product that does not speak MCP — the site indexes only MCP servers and clients"]', rw_gotchas='["The manual form requires a contact phone number so an admin can reach you during review — personal data most directories never ask for. The GitHub quick path avoids it.","The Author field is prefilled from your sign-in account name and printed as the maker, so a product-named account publishes the product as the person.","The two methods are tabs, not steps, and the quick one is selected by default, so the long form''s demands are invisible until you switch.","Outbound links are nofollow, so the listing earns discovery, not link equity."]', rw_faq='[{"question":"How long does MCP Store approval take?","answer":"No review time is published; there is a review step."},{"question":"How much does it cost to submit to MCP Store?","answer":"Submitting is free."},{"question":"Does an MCP Store listing provide a dofollow link?","answer":"No — links are nofollow on a domain rated 26."},{"question":"Do I need to link back to MCP Store?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"A product that is not an MCP server or client."}]', rw_summary='MCP Store is a free MCP server/client directory with a nofollow listing and no backlink. The repo quick path avoids the phone field on the manual form; domain rating is 26.', rw_fact_points='["Review with no published timeline","Free listing with a nofollow link","No badge or return link is expected","Accepts MCP servers, clients and developer tools"]', rw_submission_checks='["Use the GitHub quick path to avoid the phone field.","Check the Author field — it becomes the public maker.","Expect no link equity."]', rw_seo_title='MCP Store: Free MCP Listing, DR 26', rw_seo_description='How to submit to MCP Store: free nofollow MCP listing via repo or long form, no backlink. Phone-field caveat from the 2026-11-16 snapshot.' WHERE slug='mcp-store';
UPDATE submission_sites SET rw_source_lead='A feed of what builders shipped, where the links out still follow.', rw_what_you_get='A dofollow listing in a small feed of recently shipped products, with no backlink required.', rw_you_need='["A live public URL","Something shipped recently","A way to contact them, since there is no form"]', rw_eligibility='You need a live URL and something recently shipped. Nothing is published about who is refused.', rw_submit_steps='["1 Find the route. There is no submit link in the homepage navigation and the common paths do not resolve.","2 Use their contact. With no form signposted, the practical route is to write to them.","3 Wait. No review time is published."]', rw_submit_requirements='["A live public URL","Something shipped recently"]', rw_rejection_reasons='["Nothing published about who is refused"]', rw_gotchas='["There is no submit form signposted anywhere, so getting listed means finding a contact route rather than filling anything in.","The feed is small, so a listing is worth the followed link more than the traffic.","No review time is published, and with no form there is no confirmation to receive either."]', rw_faq='[{"question":"How long does Shipitsoon approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to Shipitsoon?","answer":"Submitting is free."},{"question":"Does a Shipitsoon listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 26."},{"question":"Do I need to link back to Shipitsoon?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Nothing published about who is refused."}]', rw_summary='Shipitsoon is a small shipped-products feed with a free dofollow listing and no backlink. There is no form — you contact them — and no review time is published; domain rating is 26.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","Accepts indie products, developer tools and SaaS"]', rw_submission_checks='["There is no form — find their contact route.","Judge it on the link, not traffic.","No confirmation or timeline to expect."]', rw_seo_title='Shipitsoon: Free Shipped-Product Listing, DR 26', rw_seo_description='How to get listed on Shipitsoon: free dofollow shipped-product listing via contact, no backlink. No form — 2026-11-16 snapshot.' WHERE slug='shipitsoon';
UPDATE submission_sites SET rw_source_lead='A free app shelf where the visit link is a plain follow.', rw_what_you_get='A dofollow listing with a write-up produced by the site rather than by you.', rw_you_need='["A live public URL","An email"]', rw_eligibility='You need a live URL and an email. Nothing is published about who is refused.', rw_submit_steps='["1 Open the form. /submit describes itself as a free directory and asks for an email.","2 Send the app. The form is short; the write-up is theirs to produce.","3 Wait. No review time is published."]', rw_submit_requirements='["A live public URL","An email"]', rw_rejection_reasons='["Nothing published about who is refused"]', rw_gotchas='["Each listing carries a write-up written by the site rather than your own copy, so what is published about the product is not what you submitted.","The submit page exposes only an email field in its markup, so the rest of the flow is not visible before you start.","No review time is published anywhere on the site."]', rw_faq='[{"question":"How long does SpacerrApps approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to SpacerrApps?","answer":"Submitting is free."},{"question":"Does a SpacerrApps listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 26."},{"question":"Do I need to link back to SpacerrApps?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Nothing published about who is refused."}]', rw_summary='SpacerrApps is a free dofollow app directory with no backlink, where the site writes your listing copy. No review time is published; domain rating is 26.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","Accepts mobile apps, SaaS and productivity tools"]', rw_submission_checks='["Expect them to write the listing copy.","Only an email field is visible before starting.","No timeline to chase."]', rw_seo_title='SpacerrApps: Free App Listing, DR 26', rw_seo_description='How to submit to SpacerrApps: free dofollow app listing, no backlink. Site-written copy from the 2026-11-16 snapshot.' WHERE slug='spacerrapps';
UPDATE submission_sites SET rw_source_lead='Seven hundred tools, followed links, and an account before the form.', rw_what_you_get='A dofollow listing in an AI-only directory, filed under one of a long, specific category tree.', rw_you_need='["An AI product","A live public URL","An account and a category from their tree"]', rw_eligibility='You need an account, a live URL and an AI product. The category tree is entirely AI, so a product with no AI surface has no shelf.', rw_submit_steps='["1 Register. The submit page carries Login and Register links; the form sits behind them.","2 Pick a category. The tree is long and specific, so choose before starting rather than during.","3 Fill and send. No review time is published on the page."]', rw_submit_requirements='["A live public URL","An AI product","An account","A category from their tree"]', rw_rejection_reasons='["The category tree is entirely AI, so a product with no AI surface has no shelf"]', rw_gotchas='["Registering is a WordPress account with no social provider, so an agent cannot get past it and a person must make it.","The category list is long and very specific, so a product spanning several must pick one and lose the others.","No review time is published, and there is no dashboard visible before an account, so nothing can be checked in advance."]', rw_faq='[{"question":"How long does FindMyAITool.io approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to FindMyAITool.io?","answer":"Submitting is free."},{"question":"Does a FindMyAITool.io listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 23."},{"question":"Do I need to link back to FindMyAITool.io?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"A product with no AI surface."}]', rw_summary='FindMyAITool.io is a free dofollow AI directory with no backlink, gated behind a WordPress account. Choose one category from a long specific tree; domain rating is 23.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","Accepts AI tools and SaaS products"]', rw_submission_checks='["A person must create the WordPress account.","Pick one category from the long tree.","No timeline to check."]', rw_seo_title='FindMyAITool.io: Free AI Listing, DR 23', rw_seo_description='How to submit to FindMyAITool.io: free dofollow AI listing, no backlink. Account and category tree from the 2026-11-16 snapshot.' WHERE slug='findmyaitool';
UPDATE submission_sites SET rw_source_lead='A weekly ecommerce design gallery that takes four fields, no account, and links out followed.', rw_what_you_get='A dofollow listing as a featured storefront, with credit links for the designer and developer.', rw_you_need='["A live ecommerce storefront — the gallery is about shop design","An email address"]', rw_eligibility='You need a live storefront and an email. Anything that is not a storefront — SaaS, apps and tools — has nothing to submit here.', rw_submit_steps='["1 Open the SUBMIT STORE dialog. It is a header button, not a page; there is no /submit route, and it opens a small modal in place.","2 Fill four fields. Store URL and your email are required; designer URL and developer URL are optional and become the CREDITS line under the listing.","3 Wait for the weekly pass. The site updates weekly and curates what it takes, with no individual confirmation."]', rw_submit_requirements='["A live storefront URL","An email address","An optional designer URL and developer URL, printed as credits"]', rw_rejection_reasons='["Anything that is not a storefront — SaaS, apps and tools have nothing to submit here"]', rw_gotchas='["Two of the four fields credit the designer and developer rather than the shop, so an in-house store leaves them blank and loses the extra links other listings carry.","The gallery is curated and weekly, and nothing confirms a submission or reports a rejection — the only way to find out is to watch for the card."]', rw_faq='[{"question":"How long does Storefront.Design approval take?","answer":"About a week; the gallery updates weekly."},{"question":"How much does it cost to submit to Storefront.Design?","answer":"Submitting is free."},{"question":"Does a Storefront.Design listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 24."},{"question":"Do I need to link back to Storefront.Design?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Anything that is not an ecommerce storefront."}]', rw_summary='Storefront.Design is a weekly curated ecommerce design gallery with a free dofollow listing and no backlink. Storefronts only; domain rating is 24.', rw_fact_points='["Weekly curated review","Free submission with a dofollow link","No badge or return link is expected","Accepts ecommerce stores and online shops only"]', rw_submission_checks='["Have a live storefront — SaaS and tools do not fit.","Fill the designer/developer URLs to gain credit links.","Watch for the card; there is no confirmation."]', rw_seo_title='Storefront.Design: Free Shop Listing, DR 24', rw_seo_description='How to submit to Storefront.Design: free dofollow ecommerce storefront listing, no backlink. Weekly curation from the 2026-11-16 snapshot.' WHERE slug='storefront-design';
UPDATE submission_sites SET rw_source_lead='The tenth face of one directory engine, with nothing new behind the paint.', rw_what_you_get='A dofollow listing behind a Google login, on a site shared with nine near-identical directories.', rw_you_need='["A live public URL","A Google account — the only sign-in offered"]', rw_eligibility='You need a live URL and a Google account. Nothing is published about who is refused.', rw_submit_steps='["1 Open the submit page. /submit renders a Log in to Submit panel rather than a form.","2 Log in with Google — the only provider, alongside a Create an account link.","3 Fill the listing behind the login; its fields cannot be read in advance.","4 Wait. No review time is published anywhere on the site."]', rw_submit_requirements='["A live public URL","A Google account","A category from their tree"]', rw_rejection_reasons='["Nothing published about who is refused"]', rw_gotchas='["The submit page shows a login panel and no fields, so there is no way to see what the form asks before committing an account.","Every page carries a sponsored ad for a paid service submitting SaaS to about 140 directories — a competitor marked sponsored nofollow.","Ten sites share the same codebase and copy, differing only in name and accent colour, so a run across them buys far less reach than the count suggests."]', rw_faq='[{"question":"How long does Tool Ignite approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to Tool Ignite?","answer":"Submitting is free."},{"question":"Does a Tool Ignite listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 24."},{"question":"Do I need to link back to Tool Ignite?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Nothing published about who is refused."}]', rw_summary='Tool Ignite is a free dofollow listing behind a Google login, with no backlink. The tenth site on a shared engine; domain rating is 24.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","Accepts SaaS, AI tools, developer tools and web apps"]', rw_submission_checks='["Sign in with Google to see the form.","Reach overlaps heavily with nine sister sites.","No timeline to plan around."]', rw_seo_title='Tool Ignite: Free Dofollow Listing, DR 24', rw_seo_description='How to submit to Tool Ignite: free dofollow listing behind a Google login, no backlink. Shared-engine caveat from the 2026-11-16 snapshot.' WHERE slug='tool-ignite';
UPDATE submission_sites SET rw_source_lead='The lightest paint of the ten, with the identical form behind it.', rw_what_you_get='A dofollow listing behind a Google login, on a site shared with nine near-identical directories.', rw_you_need='["A live public URL","A Google account — the only sign-in offered"]', rw_eligibility='You need a live URL and a Google account. Nothing is published about who is refused.', rw_submit_steps='["1 Open the submit page. /submit renders a Log in to Submit panel rather than a form.","2 Log in with Google — the only provider, alongside a Create an account link.","3 Fill the listing behind the login; its fields cannot be read in advance.","4 Wait. No review time is published anywhere on the site."]', rw_submit_requirements='["A live public URL","A Google account","A category from their tree"]', rw_rejection_reasons='["Nothing published about who is refused"]', rw_gotchas='["The submit page shows a login panel and no fields, so there is no way to see what the form asks before committing an account.","Every page carries a sponsored ad for a paid service submitting SaaS to about 140 directories — a competitor marked sponsored nofollow.","Ten sites share the same codebase and copy, differing only in name and accent colour, so a run across them buys far less reach than the count suggests."]', rw_faq='[{"question":"How long does Tool Parade approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to Tool Parade?","answer":"Submitting is free."},{"question":"Does a Tool Parade listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 23."},{"question":"Do I need to link back to Tool Parade?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Nothing published about who is refused."}]', rw_summary='Tool Parade is a free dofollow listing behind a Google login, with no backlink. The tenth site on a shared engine; domain rating is 23.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","Accepts SaaS, AI tools, developer tools and web apps"]', rw_submission_checks='["Sign in with Google to see the form.","Reach overlaps heavily with nine sister sites.","No timeline to plan around."]', rw_seo_title='Tool Parade: Free Dofollow Listing, DR 23', rw_seo_description='How to submit to Tool Parade: free dofollow listing behind a Google login, no backlink. Shared-engine caveat from the 2026-11-16 snapshot.' WHERE slug='tool-parade';
UPDATE submission_sites SET rw_source_lead='An index by name, a clone by build, and a Google login either way.', rw_what_you_get='A dofollow listing behind a Google login, on one of ten sites sharing the same engine.', rw_you_need='["A live public URL","A Google account — the only sign-in offered"]', rw_eligibility='You need a live URL and a Google account. Nothing is published about who is refused.', rw_submit_steps='["1 Open the submit page. /submit renders a Log in to Submit panel rather than a form.","2 Log in with Google — the only provider, alongside a Create an account link.","3 Fill the listing behind the login; its fields cannot be read in advance.","4 Wait. No review time is published anywhere on the site."]', rw_submit_requirements='["A live public URL","A Google account","A category from their tree"]', rw_rejection_reasons='["Nothing published about who is refused"]', rw_gotchas='["The submit page shows only a login panel, so the form''s questions are invisible until you commit an account.","Every page carries a sponsored ad for a paid service submitting to about 140 directories, a competitor marked sponsored nofollow.","Ten sites share the same code and copy, differing only in name and accent colour, so a run across them buys far less reach than the count suggests."]', rw_faq='[{"question":"How long does Toolkit Index approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to Toolkit Index?","answer":"Submitting is free."},{"question":"Does a Toolkit Index listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 24."},{"question":"Do I need to link back to Toolkit Index?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Nothing published about who is refused."}]', rw_summary='Toolkit Index is a free dofollow listing behind a Google login, with no backlink. One of ten sites on a shared engine; domain rating is 24.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","Accepts SaaS, AI tools, developer tools and web apps"]', rw_submission_checks='["Sign in with Google to see the form.","Reach overlaps heavily with nine sister sites.","No timeline to plan around."]', rw_seo_title='Toolkit Index: Free Dofollow Listing, DR 24', rw_seo_description='How to submit to Toolkit Index: free dofollow listing behind a Google login, no backlink. Shared-engine caveat from the 2026-11-16 snapshot.' WHERE slug='toolkit-index';
UPDATE submission_sites SET rw_source_lead='No account, thirteen fields, and an outbound link that carries no rel attribute at all.', rw_what_you_get='A dofollow listing submitted through a long form without needing an account.', rw_you_need='["An AI product","A live public URL"]', rw_eligibility='You need an AI product and a live URL. Nothing is published about who is refused.', rw_submit_steps='["1 Open the form at /submit — it renders the fields without an account.","2 Fill the basics: URL, name, tagline and description are the first four of about thirteen fields.","3 Send it. No review time is published."]', rw_submit_requirements='["A live public URL","A name","A tagline","A description"]', rw_rejection_reasons='["Nothing published about who is refused"]', rw_gotchas='["There is a Sign In control in the header but the form works without it, so it is easy to make an account you never needed.","No review time is published anywhere, so there is nothing to chase after sending.","The form runs to about thirteen fields, several unlabelled in the markup, so it takes longer than the four visible ones suggest."]', rw_faq='[{"question":"How long does Top AI Tools approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to Top AI Tools?","answer":"Submitting is free."},{"question":"Does a Top AI Tools listing provide a dofollow link?","answer":"Yes — the outbound anchor carries no rel attribute at all, on a domain rated 24."},{"question":"Do I need to link back to Top AI Tools?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Nothing published about who is refused."}]', rw_summary='Top AI Tools is a free no-account AI directory with a dofollow listing and no backlink. The form has about thirteen fields; domain rating is 24.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","Accepts AI tools and SaaS products"]', rw_submission_checks='["No account needed — ignore the header Sign In.","Expect a long form with some unlabelled fields.","No timeline to chase."]', rw_seo_title='Top AI Tools: Free AI Listing, DR 24', rw_seo_description='How to submit to Top AI Tools: free no-account dofollow AI listing, no backlink. Long-form caveat from the 2026-11-16 snapshot.' WHERE slug='top-ai-tools-net';
UPDATE submission_sites SET rw_source_lead='A good free form whose submit endpoint answers 500.', rw_what_you_get='A dofollow listing in theory — the free form is complete, but the submit endpoint failed repeatedly in testing.', rw_you_need='["A live public URL","A logo and a cover image","A maker name"]', rw_eligibility='You need a URL, logo, cover and a maker name. Nothing is published about who is refused.', rw_submit_steps='["1 Pick what you are submitting: three routes at /submit/tool, /submit/community and /submit/podcast. No account or sign-in.","2 Fill the tool details — logo, name, website, a tagline up to 60 characters, a description and a cover image, then one of thirty categories.","3 Answer the two extras: an open-source thumbs up or down, and a pricing choice of Free, Paid or a shrug. No freemium option.","4 Name the maker. Created By is required and takes a name or handle; a social URL and your email are optional.","5 Press Submit and read the toast. It posts to a serverless function; a pink Failed, please try again toast means the endpoint answered 500 and nothing was recorded."]', rw_submit_requirements='["A logo and tool name","A website URL and tagline up to 60 characters","A description and cover image","One of thirty categories","A Created By name or handle","An optional creator social URL and email"]', rw_rejection_reasons='["Nothing published about who is refused"]', rw_gotchas='["The form is complete and free but the submission does not go through: validation passes, then the endpoint answered HTTP 500 twice with a Failed toast.","The catalogue itself is unreliable — the same browser showed a full grid of tools once and endless Loading tools the next, so a listing may not be visible on a given day.","There is no account, so nothing can be checked afterward; the optional email is the only channel that exists.","Pricing is Free, Paid or a shrug — no freemium — so a product with both has to misstate itself either way."]', rw_faq='[{"question":"How long does Appydev approval take?","answer":"No review time is published; the submit endpoint failed in testing."},{"question":"How much does it cost to submit to Appydev?","answer":"Submitting is free."},{"question":"Does an Appydev listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 21, if the submission lands."},{"question":"Do I need to link back to Appydev?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Nothing published about who is refused."}]', rw_summary='Appydev is a free dofollow developer-tools directory with no backlink, but its submit endpoint returned 500 in testing. No account to check status; domain rating is 21.', rw_fact_points='["No published review time; submit failed in testing","Free listing with a dofollow link","No badge or return link is expected","Accepts developer tools, design, marketing, productivity and no-code tools"]', rw_submission_checks='["The submit endpoint failed repeatedly — retry or use the email channel.","No freemium pricing option exists.","The catalogue sometimes fails to load."]', rw_seo_title='Appydev: Free Tool Listing, DR 21', rw_seo_description='How to submit to Appydev: free dofollow listing, no backlink. Submit endpoint failure from the 2026-11-16 snapshot.' WHERE slug='appydev';
UPDATE submission_sites SET rw_source_lead='Free to publish a startup, and the outbound links actually follow.', rw_what_you_get='A dofollow startup listing framed as telling your vision, with no backlink required.', rw_you_need='["A live public URL","An account created through their Django signup form"]', rw_eligibility='You need an account and a live URL. Nothing is published about who is refused; the framing is early-stage, so a mature product is off-pitch rather than ineligible.', rw_submit_steps='["1 Make an account. Submitting is behind /signup/ — an ordinary Django email form with no social provider.","2 Publish the startup with a name, story and links, framed as telling your vision rather than filling a spec sheet.","3 Consider promotion separately. Paid plans live on their own promotion pricing page and are not part of the free submission."]', rw_submit_requirements='["A live public URL","An account","A description of the startup and its story"]', rw_rejection_reasons='["Nothing published about who is refused; the framing is early-stage, so a mature product is off-pitch"]', rw_gotchas='["Sign-up is an email-and-password form with no Google or GitHub option, so an agent cannot get past it.","No review or publication time is stated anywhere, including the pricing page, so there is nothing to plan a launch around.","Promotion plans are a separate purchase on a separate page, so the free submission gets none of what those pages advertise."]', rw_faq='[{"question":"How long does Earlylaunch approval take?","answer":"No review or publication time is published."},{"question":"How much does it cost to submit to Earlylaunch?","answer":"Submitting is free; promotion is sold separately."},{"question":"Does an Earlylaunch listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 21."},{"question":"Do I need to link back to Earlylaunch?","answer":"No backlink is required."},{"question":"What gets a startup rejected?","answer":"Nothing published; a mature product is off-pitch for an early-stage board."}]', rw_summary='Earlylaunch is a free dofollow startup board with no backlink, framed for early-stage products. Email-only signup; domain rating is 21.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","Accepts startups, indie products and SaaS"]', rw_submission_checks='["Create an email-and-password account — no social sign-in.","Tell your story, not just specs.","Promotion is a separate purchase."]', rw_seo_title='Earlylaunch: Free Dofollow Startup, DR 21', rw_seo_description='How to submit to Earlylaunch: free dofollow startup listing, no backlink. Email-only signup from the 2026-11-16 snapshot.' WHERE slug='earlylaunch';
UPDATE submission_sites SET rw_source_lead='A password and a Turnstile box stand between you and the form.', rw_what_you_get='A dofollow listing whose form sits behind an account with both a password and a human check.', rw_you_need='["A live public URL","An account made with a name, email and password","A Cloudflare Turnstile challenge on signup"]', rw_eligibility='You need an account and a live URL. Nothing is published about who is refused.', rw_submit_steps='["1 Open the submit page. /submit renders a sign-up form rather than a submission form.","2 Make an account with a name, email and password, plus a Cloudflare Turnstile challenge.","3 Submit the product on the form behind that account."]', rw_submit_requirements='["A live public URL","An account with a name, email and password","A Turnstile challenge on signup"]', rw_rejection_reasons='["Nothing published about who is refused"]', rw_gotchas='["The submit page is a sign-up form, so the submission''s own questions are invisible until you commit an account.","Signup carries both Turnstile and a password — the two things an agent cannot do — on the same screen.","A first-visit modal sells a 36-hour jump to the front for publishing a feature update, so ordering is partly bought and a new listing sinks as others buy it."]', rw_faq='[{"question":"How long does findasaas approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to findasaas?","answer":"Submitting is free; a paid feature-update boost is sold separately."},{"question":"Does a findasaas listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 21."},{"question":"Do I need to link back to findasaas?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Nothing published about who is refused."}]', rw_summary='findasaas is a free dofollow SaaS directory with no backlink, gated behind a password-and-Turnstile signup. Ordering is partly paid; domain rating is 21.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","Accepts SaaS, AI tools, developer tools and marketing tools"]', rw_submission_checks='["A person must pass Turnstile and set a password.","The form is invisible until signup.","Expect paid boosts to outrank free listings."]', rw_seo_title='findasaas: Free SaaS Listing, DR 21', rw_seo_description='How to submit to findasaas: free dofollow SaaS listing, no backlink. Password and Turnstile gate from the 2026-11-16 snapshot.' WHERE slug='findasaas';
UPDATE submission_sites SET rw_source_lead='A WordPress launch board with a dofollow product link and a password-only account.', rw_what_you_get='A dofollow launch listing with no backlink, on a WordPress site that also runs forums and news.', rw_you_need='["A live URL","An account with a username or email and a password"]', rw_eligibility='You need an account and a live URL. Nothing is published, and the form is invisible until an account exists, so the rules cannot be checked first.', rw_submit_steps='["1 Register at /login/ with a username or email and a password. No Google, GitHub or magic link.","2 Submit at /submit-new-product/ behind the login — until signed in it only says You must be logged in to submit a product."]', rw_submit_requirements='["An account with a username and password, no OAuth"]', rw_rejection_reasons='["Nothing published, and the submission form is invisible until an account exists, so the rules cannot be checked first"]', rw_gotchas='["An account means a password — there is no social sign-in, which is the whole obstacle here.","The submit page shows nothing about its questions until logged in, so a pack cannot be prepared in advance.","It runs on WordPress with forums and a news section, so a listing sits in a busier, older-feeling site than most launch boards.","Not to be confused with a smaller board at a similar domain that is also in this directory."]', rw_faq='[{"question":"How long does InstantLaun.ch approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to InstantLaun.ch?","answer":"Submitting is free."},{"question":"Does an InstantLaun.ch listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 21."},{"question":"Do I need to link back to InstantLaun.ch?","answer":"No backlink is required."},{"question":"What gets a launch rejected?","answer":"Nothing published; the form is hidden until signup."}]', rw_summary='InstantLaun.ch is a free dofollow WordPress launch board with no backlink, gated behind a password account. No rules visible before signup; domain rating is 21.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","Accepts indie products, SaaS, AI tools and startups"]', rw_submission_checks='["Create a password account — no OAuth.","Rules are hidden until you sign in.","Mind the similarly named smaller board."]', rw_seo_title='InstantLaun.ch: Free Launch Listing, DR 21', rw_seo_description='How to submit to InstantLaun.ch: free dofollow launch listing, no backlink. Password-only signup from the 2026-11-16 snapshot.' WHERE slug='instantlaun-ch';
UPDATE submission_sites SET rw_source_lead='A builder directory ranked by clicks, with a followed link and a sign-in only at the last click.', rw_what_you_get='A dofollow builder listing ranked by clicks, with a profile tied to your name and country.', rw_you_need='["A product website, repo or app-store page","A Google account or email, asked for at the last click","A builder name and country"]', rw_eligibility='You need a real product URL and a builder identity. A deploy-host address such as vercel.app is refused as the product website.', rw_submit_steps='["1 Product details: a website — a repo or app-store page counts, a vercel.app link does not — optional Fill with AI, name, an 80-character one-liner, an 800-character description and up to three categories.","2 Media: a logo and up to four screenshots, locked until sign-in, so the listing defaults to your site''s icon; then the product''s X handle and contact email.","3 You: a name or brand, a required country with Global on the list, your X handle and email, a funding stage, whether you are raising and the terms box.","4 Submit and sign in. Submit product first flags missing images, then opens sign-in via Google or an emailed link; the listing posts and stays editable."]', rw_submit_requirements='["A product website, name and one-liner up to 80 characters","A description up to 800 characters and up to three categories","A country","An optional logo and up to four screenshots","Optional X handle and email"]', rw_rejection_reasons='["A deploy-host address such as vercel.app as the product website"]', rw_gotchas='["Images need the sign-in that arrives only at the last click, so they are a second pass; listings with images reportedly get about twice the opens.","A deploy link is refused as the product website — vercel.app does not count, but a repo or app-store page does.","Your X handle is published as you with its avatar pulled in, so a borrowed handle credits a stranger."]', rw_faq='[{"question":"How long does WhatAreYouBuilding.AI approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to WhatAreYouBuilding.AI?","answer":"Submitting is free."},{"question":"Does a WhatAreYouBuilding.AI listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 21."},{"question":"Do I need to link back to WhatAreYouBuilding.AI?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"A deploy-host address such as vercel.app as the product website."}]', rw_summary='WhatAreYouBuilding.AI is a click-ranked builder directory with a free dofollow listing and no backlink. A real product URL is required — no vercel.app; domain rating is 21.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","Accepts indie products, AI tools, SaaS and developer tools"]', rw_submission_checks='["Use a real domain, repo or app-store URL — not vercel.app.","Add images in a second pass after signing in.","Use an X handle you actually own."]', rw_seo_title='WhatAreYouBuilding.AI: Free Builder Listing, DR 21', rw_seo_description='How to submit to WhatAreYouBuilding.AI: free dofollow builder listing, no backlink. Deploy-host rule from the 2026-11-16 snapshot.' WHERE slug='whatareyoubuilding';
UPDATE submission_sites SET rw_source_lead='A large Chinese AI index, free to enter, and it wants a WeChat ID.', rw_what_you_get='A dofollow listing after manual review in a Chinese-language AI index.', rw_you_need='["An AI product","A live public URL","A contact method, ideally a WeChat ID"]', rw_eligibility='You need an AI product, a live URL and a contact channel. The whole site is in Chinese for a Chinese-reading audience, which is the real fit question.', rw_submit_steps='["1 Open the submit page. /service/submit offers submit, paid promotion, update and other services at once; the free lane is the last block.","2 Fill the short form: a product icon, the product name, the product link and a contact method — the whole form.","3 Wait for manual review. The free path says it enters human review and is listed once it passes; no duration is given."]', rw_submit_requirements='["A live public URL and a product name","A product icon uploaded on the form","A contact method, with a WeChat ID asked for first"]', rw_rejection_reasons='["The site and audience are Chinese-language, so an English-only product sits where most readers cannot use it"]', rw_gotchas='["The contact field asks for a WeChat ID so their assistant can reach you — awkward without one, and it is the only channel named.","Everything including form labels and the review notice is in Chinese, so the flow is not guessable without reading it.","Paid promotion is presented alongside free on the same page, so it is easy to start booking a paid slot by mistake."]', rw_faq='[{"question":"How long does Maomu approval take?","answer":"No review time is published; review is manual."},{"question":"How much does it cost to submit to Maomu?","answer":"Submitting is free; paid promotion is offered separately."},{"question":"Does a Maomu listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 20."},{"question":"Do I need to link back to Maomu?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"No formal rule, but the audience is Chinese-language."}]', rw_summary='Maomu is a large Chinese-language AI index with a free dofollow listing and no backlink. A WeChat ID is the preferred contact; domain rating is 20.', rw_fact_points='["Manual review with no published timeline","Free listing with a dofollow link","No badge or return link is expected","Accepts AI tools, agents and MCP servers"]', rw_submission_checks='["A WeChat ID is the expected contact method.","Expect a Chinese-language form and audience.","Do not confuse free submit with the paid promotion block."]', rw_seo_title='Maomu: Free Chinese AI Listing, DR 20', rw_seo_description='How to submit to Maomu: free dofollow Chinese AI index listing, no backlink. WeChat contact from the 2026-11-16 snapshot.' WHERE slug='maomu';
UPDATE submission_sites SET rw_source_lead='A reviews site rather than a listings page, free and followed, gated behind an email you have to open.', rw_what_you_get='A dofollow review-page listing, but only after an email verification link is clicked.', rw_you_need='["An AI tool","A description and up to ten key features","An email you can open, because submission is verified by link","One of twenty categories"]', rw_eligibility='You need an AI tool, copy, an email and a category. Anything failing their unstated review criteria is refused — the form warns without listing them.', rw_submit_steps='["1 Open the form. /submit is a single page with no login: app name, description, website, one of twenty categories, free-plan and free-trial flags, an optional starting price, up to ten key features and your email.","2 Add features one at a time. Key Features is a chip input — type a feature and press Enter, up to ten; they render as a list on the review page.","3 Submit for review. Turnstile solves itself above the button; submitting replaces the form with a thank-you.","4 Verify by email or nothing happens. Until the link is clicked there is no review and no listing."]', rw_submit_requirements='["An app name, description and website URL","One of twenty categories","An email that can receive the verification link","Optional key features, free/trial flags and a starting price"]', rw_rejection_reasons='["Anything that does not meet their unstated review criteria, which the form warns about without listing"]', rw_gotchas='["The submission is double opt-in and the verification email may never arrive — one run got the confirmation but no email, with no resend, status page or dashboard, so a stalled submission stalls silently.","They present as reviewers, not a directory, and add a tool only if it meets criteria never stated. There is no queue page or status."]', rw_faq='[{"question":"How long does AI Pulse approval take?","answer":"No review time is published; review starts only after email verification."},{"question":"How much does it cost to submit to AI Pulse?","answer":"Submitting is free."},{"question":"Does an AI Pulse listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 17."},{"question":"Do I need to link back to AI Pulse?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Anything failing their unstated review criteria."}]', rw_summary='AI Pulse is a free dofollow AI reviews site with no backlink, gated behind an email verification link. Review is editorial with unstated criteria; domain rating is 17.', rw_fact_points='["Editorial review after email verification","Free listing with a dofollow link","No badge or return link is expected","Accepts AI tools and SaaS"]', rw_submission_checks='["Open the verification email — nothing happens until you do.","Write features as capabilities, not marketing lines.","No status page if the email never arrives."]', rw_seo_title='AI Pulse: Free AI Review Listing, DR 17', rw_seo_description='How to submit to AI Pulse: free dofollow AI review listing, no backlink. Email verification gate from the 2026-11-16 snapshot.' WHERE slug='ai-pulse';
UPDATE submission_sites SET rw_source_lead='Free listing in two to four weeks, or $19 to jump the queue.', rw_what_you_get='A design-tools listing, free after a two-to-four-week wait or in 24 to 48 hours on the paid tier.', rw_you_need='["A live public URL","A product a designer would use"]', rw_eligibility='You need a live URL and a design or web-building product. Anything outside those shelves has nowhere to be filed.', rw_submit_steps='["1 Open the submit page. It lays out the free lane and two paid ones side by side.","2 Choose the free lane. It sits under the paid cards, labelled Submit for Free, with the 14 to 30 day wait stated.","3 Fill the form via the Submit Now control; the cards are duplicated visually on this Framer site.","4 Wait, which they attribute to submission volume rather than a review policy."]', rw_submit_requirements='["A live public URL","A design or web-building product","A free wait of 14 to 30 days","An optional $19 queue skip for 24 to 48 hours"]', rw_rejection_reasons='["The shelves are design and web building only, so a product outside that has nowhere to be filed"]', rw_gotchas='["The two paid cards sit above the free option, so the free lane is easy to scroll past even though it is real.","Only the paid tiers advertise a permanent backlink, so check the free listing''s own row once it is up.","The wait is 14 to 30 days by their own admission, making this a poor fit for anything timed to a launch day."]', rw_faq='[{"question":"How long does BestWebDesignTools approval take?","answer":"Two to four weeks; $19 cuts it to 24 to 48 hours."},{"question":"How much does it cost to submit to BestWebDesignTools?","answer":"Free with a 14 to 30 day wait; $19 jumps the queue."},{"question":"Does a BestWebDesignTools listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 18, though only paid tiers advertise it as permanent."},{"question":"Do I need to link back to BestWebDesignTools?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"A product outside design and web building."}]', rw_summary='BestWebDesignTools is a design-tools directory with a free dofollow listing after a two-to-four-week wait, or $19 to skip. No backlink is required; domain rating is 18.', rw_fact_points='["Free wait of two to four weeks; $19 is faster","Dofollow listing with no backlink requirement","No badge or return link is expected","Accepts design tools, web apps and no-code tools"]', rw_submission_checks='["Find the free lane below the paid cards.","Check your row''s link status once live.","Do not use this for a launch-day deadline."]', rw_seo_title='BestWebDesignTools: Free Design Listing, DR 18', rw_seo_description='How to submit to BestWebDesignTools: free dofollow design-tool listing in 2-4 weeks, or $19 to skip. No backlink — 2026-11-16 snapshot.' WHERE slug='best-web-design-tools';
UPDATE submission_sites SET rw_source_lead='A directory of directories that prints each entry''s DR beside it — and whose submission form is currently closed.', rw_what_you_get='A dofollow listing alongside other directories, with your domain rating displayed next to your entry.', rw_you_need='["A live directory of your own","A domain rating worth displaying — the index prints one beside every entry"]', rw_eligibility='You need a directory. Anything that is not a directory has nothing to submit here.', rw_submit_steps='["1 Find the Submit link. The only submission control is a Submit link in the header pointing to a Tally form.","2 Check the form is open. On the last walk it answered This form is now closed; there is no alternative route, email or account anywhere.","3 Wait for it to reopen. Nothing says when or whether; watching the Submit link is the only option."]', rw_submit_requirements='["A live directory URL","Whatever the Tally form asks for once it reopens, which could not be read while closed"]', rw_rejection_reasons='["Anything that is not a directory — this index lists directories only"]', rw_gotchas='["The form is closed: the Submit link reaches a Tally form saying This form is now closed, with no email, account or alternative route.","The index lists directories only, so a normal product has nothing to submit.","Every entry shows its domain rating beside it, so a weak domain is displayed as such next to competitors."]', rw_faq='[{"question":"How long does Directories approval take?","answer":"No review time is published; the form is currently closed."},{"question":"How much does it cost to submit to Directories?","answer":"Submitting is free when the form is open."},{"question":"Does a Directories listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 17."},{"question":"Do I need to link back to Directories?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Anything that is not a directory."}]', rw_summary='Directories is a dofollow index of directories with no backlink, printing each entry''s domain rating. The submission form is currently closed; domain rating is 17.', rw_fact_points='["Submission form currently closed","Free listing with a dofollow link","No badge or return link is expected","Lists directories only"]', rw_submission_checks='["The form is closed — check back before planning around it.","Only directories qualify.","Your domain rating will be displayed publicly."]', rw_seo_title='Directories: Free Directory Listing, DR 17', rw_seo_description='About Directories: free dofollow index of directories, no backlink. Submission form currently closed — 2026-11-16 snapshot.' WHERE slug='directories-so';
UPDATE submission_sites SET rw_source_lead='A B2B review site whose Visit website goes through a click tracker.', rw_what_you_get='A nofollow review page that sends business-buyer traffic through a tracked redirect, with the framing written by them.', rw_you_need='["An account via Google or a professional email and password","A live product URL","A business buyer — this is not for anyone who needs the link"]', rw_eligibility='You need an account, a live URL and a product with a business buyer. Anyone needing link equity rather than traffic is out.', rw_submit_steps='["1 Sign up with Google or a professional email and password — they ask for a work address.","2 Get listed through the vendor route behind that account.","3 Wait for editorial review; no window is published."]', rw_submit_requirements='["A professional email address"]', rw_rejection_reasons='["A product with no business buyer, and anyone who needs the link rather than the traffic"]', rw_gotchas='["The Visit website control on a listing goes through their /external_click/ redirect and is nofollow — traffic, but no link.","Product pages carry their own written review, so the framing of your product is theirs.","Sign-up asks for a professional email specifically, so a personal address may be refused."]', rw_faq='[{"question":"How long does Findstack approval take?","answer":"No review time is published; review is editorial."},{"question":"How much does it cost to submit to Findstack?","answer":"Submitting is free."},{"question":"Does a Findstack listing provide a dofollow link?","answer":"No — links are nofollow through a click tracker on a domain rated 77."},{"question":"Do I need to link back to Findstack?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"A product with no business buyer, or a submitter who needs the link."}]', rw_summary='Findstack is a free B2B review directory with a nofollow tracked link and no backlink. Worth it for business-buyer traffic, not SEO; domain rating is 77.', rw_fact_points='["Editorial review with no published timeline","Free listing with a nofollow tracked link","No badge or return link is expected","Accepts B2B products and SaaS"]', rw_submission_checks='["Use a work email for signup.","The Visit link is tracked and nofollow — traffic only.","They write the review copy."]', rw_seo_title='Findstack: Free B2B Review, DR 77', rw_seo_description='How to submit to Findstack: free B2B review listing, nofollow tracked link, no backlink. Work-email signup from the 2026-11-16 snapshot.' WHERE slug='findstack';
UPDATE submission_sites SET rw_source_lead='Free unless you tick the box, and it wants a screenshot rather than a logo.', rw_what_you_get='A dofollow AI-tool listing with a thumbnail, free if you leave the paid checkbox unticked.', rw_you_need='["An AI tool or a Custom GPT","A live public URL","A screenshot or thumbnail image, not a logo"]', rw_eligibility='You need to declare whether it is an AI tool or a Custom GPT in the OpenAI store — a product that is neither has no answer to that required question.', rw_submit_steps='["1 Open /submit. It needs no account.","2 Say what it is: your name, email, the tool name, whether it is an AI tool or a Custom GPT, and the link.","3 Write it short: up to three tags, a one-sentence description and a description of at most three sentences, both stated on the form.","4 Upload a screenshot. The image field asks for a thumbnail or screenshot and says explicitly not a logo.","5 Choose the lane. Leave the paid listing checkbox unticked to submit free."]', rw_submit_requirements='["A live public URL and your name and email","A one-sentence and a three-sentence description","Up to three tags","A thumbnail or screenshot, not a logo"]', rw_rejection_reasons='["A product that is neither an AI tool nor a Custom GPT in the OpenAI store has no answer to a required question"]', rw_gotchas='["The image field refuses a logo — it wants a thumbnail or screenshot, so a pack carrying only an icon has nothing to give.","Both descriptions are capped in sentences, one and three, a tighter budget than character limits suggest.","The paid checkbox sits at the bottom just above Submit, so it is easy to agree to $7.99 while finishing."]', rw_faq='[{"question":"How long does GPTAcademy approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to GPTAcademy?","answer":"Free if you leave the paid-listing checkbox unticked; that box adds a $7.99 paid tier."},{"question":"Does a GPTAcademy listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 18."},{"question":"Do I need to link back to GPTAcademy?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"A product that is neither an AI tool nor a Custom GPT."}]', rw_summary='GPTAcademy is a free dofollow AI-tool directory with no backlink, requiring a screenshot and a one/three-sentence description. The paid box is easy to tick accidentally; domain rating is 18.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","Accepts AI tools and Custom GPTs"]', rw_submission_checks='["Prepare a screenshot, not a logo.","Keep descriptions to one and three sentences.","Leave the $7.99 checkbox unticked."]', rw_seo_title='GPTAcademy: Free AI Listing, DR 18', rw_seo_description='How to submit to GPTAcademy: free dofollow AI listing with a screenshot, no backlink. Paid-box warning from the 2026-11-16 snapshot.' WHERE slug='gptacademy';
UPDATE submission_sites SET rw_source_lead='Narrow by design: AI infrastructure only, free, and the link follows.', rw_what_you_get='A dofollow listing in an AI-infrastructure index, with no backlink required.', rw_you_need='["A genuinely AI-infrastructure product","A live public URL","An email"]', rw_eligibility='You need real AI infrastructure, a URL and an email. The eight categories are all infrastructure, so a general SaaS product has no shelf here.', rw_submit_steps='["1 Open /submit — it needs no account and says the listing is free with no strings attached.","2 Fill it with a product name, URL, a description and an email, plus a checkbox asking whether you are open to a backlink.","3 Submit. No review time is published and there is no dashboard to watch."]', rw_submit_requirements='["A live public URL and a product name","An email","An optional backlink checkbox"]', rw_rejection_reasons='["The eight categories are all infrastructure, so a general SaaS product, even AI-flavoured, has no shelf"]', rw_gotchas='["The categories are all genuine infrastructure, so an AI-adjacent product will be filed nowhere — the likeliest cause of silence.","A checkbox asks whether you are open to a backlink; decide before submitting.","No review time is published and there is no account or dashboard, so there is nothing to check afterward."]', rw_faq='[{"question":"How long does Infrabase.ai approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to Infrabase.ai?","answer":"Submitting is free."},{"question":"Does an Infrabase.ai listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 18."},{"question":"Do I need to link back to Infrabase.ai?","answer":"No backlink is required, though a checkbox asks if you are open to one."},{"question":"What gets a listing rejected?","answer":"A product that is not genuinely AI infrastructure."}]', rw_summary='Infrabase.ai is a free dofollow AI-infrastructure index with no backlink. Only real infrastructure fits its eight categories; domain rating is 18.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","Accepts AI infrastructure, developer tools and open source"]', rw_submission_checks='["Be genuinely infrastructure, not just AI-adjacent.","Decide on the open-to-backlink checkbox.","No status page to check."]', rw_seo_title='Infrabase.ai: Free AI Infra Listing, DR 18', rw_seo_description='How to submit to Infrabase.ai: free dofollow AI-infrastructure listing, no backlink. Narrow scope from the 2026-11-16 snapshot.' WHERE slug='infrabase';
UPDATE submission_sites SET rw_source_lead='A design gallery that links out dofollow, with a sign-in that landed on a maintenance page.', rw_what_you_get='A dofollow listing in a look-first design gallery — if the sign-in and form are working.', rw_you_need='["A live URL and an account via Google, GitHub or email and password","A site that looks the part — this is a design jury"]', rw_eligibility='You need an account and a visually strong site. They curate on looks, so a plain or templated landing page will not be picked however good the product.', rw_submit_steps='["1 Sign in with Google, GitHub or email and password at /auth/login.","2 Submit at /submit behind the login. On 30 August 2026 the form could not be reached: Google sign-in redirected to a maintenance page while the rest of the site was up."]', rw_submit_requirements='["An account via Google, GitHub or email and password"]', rw_rejection_reasons='["They curate on how the site looks, so a plain or templated landing page will not be picked no matter what it does"]', rw_gotchas='["Google sign-in landed on maintenance.html on 30 August 2026, so the form could not be reached at all while the rest of the site stayed up.","It is a look-first gallery — every card is tagged Minimal, Dark, Motion, GSAP or Tailwind; an ordinary landing page is being submitted to a design jury.","Outbound links carry no rel, so the link is dofollow — unusually generous for a gallery."]', rw_faq='[{"question":"How long does InspoWeb approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to InspoWeb?","answer":"Submitting is free."},{"question":"Does an InspoWeb listing provide a dofollow link?","answer":"Yes — outbound links carry no rel attribute, on a domain rated 17."},{"question":"Do I need to link back to InspoWeb?","answer":"No backlink is required."},{"question":"What gets a site rejected?","answer":"A plain or templated landing page — selection is purely visual."}]', rw_summary='InspoWeb is a look-first design gallery with a free dofollow listing and no backlink. Sign-in hit a maintenance page in testing; domain rating is 17.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","Accepts web products, design tools, portfolios and agencies"]', rw_submission_checks='["Sign-in may hit a maintenance page — retry.","Your site''s look is the whole criterion.","The outbound link is dofollow."]', rw_seo_title='InspoWeb: Free Design Gallery, DR 17', rw_seo_description='How to submit to InspoWeb: free dofollow design-gallery listing, no backlink. Sign-in issue from the 2026-11-16 snapshot.' WHERE slug='inspoweb';
UPDATE submission_sites SET rw_source_lead='Four fields on a Tally form, no account, and the only thing it wants to know is what your MCP server does.', rw_what_you_get='A listing in an MCP server index after a review, with no published timeline.', rw_you_need='["An MCP server","A URL for it","A contact email"]', rw_eligibility='You need an MCP server, a URL and an email. Anything that is not a Model Context Protocol server is refused.', rw_submit_steps='["1 Open the embedded Tally form with four required fields: server name, URL, description and email.","2 Describe the server in one free-text field — name the tools it exposes and whether they need an account.","3 Send. The confirmation says the submission has been received and the server will be reviewed and displayed later."]', rw_submit_requirements='["A server name","A URL for the server or its docs","A description","A contact email"]', rw_rejection_reasons='["Anything that is not a Model Context Protocol server"]', rw_gotchas='["Nothing on the page or in the confirmation gives a review time, so there is no date to plan around.","Outbound links are nofollow, so the listing earns discovery, not link equity."]', rw_faq='[{"question":"How long does MCP Server Hub approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to MCP Server Hub?","answer":"Submitting is free."},{"question":"Does an MCP Server Hub listing provide a dofollow link?","answer":"No — links are nofollow on a domain rated 18."},{"question":"Do I need to link back to MCP Server Hub?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Anything that is not an MCP server."}]', rw_summary='MCP Server Hub is a free nofollow MCP server index with no backlink, submitted through a four-field Tally form. No review time is published; domain rating is 18.', rw_fact_points='["No published review time","Free listing with a nofollow link","No badge or return link is expected","Accepts MCP servers, agents and developer tools"]', rw_submission_checks='["Name the tools your server exposes in the description.","No account needed — just four fields.","Expect no link equity."]', rw_seo_title='MCP Server Hub: Free MCP Listing, DR 18', rw_seo_description='How to submit to MCP Server Hub: free nofollow MCP listing via a four-field form, no backlink. Steps from the 2026-11-16 snapshot.' WHERE slug='mcp-server-hub';
UPDATE submission_sites SET rw_source_lead='A small curated resource shelf where the links still follow.', rw_what_you_get='A dofollow listing in a hand-kept WordPress resource shelf, provided it fits a collection.', rw_you_need='["A live public URL","A collection it belongs in"]', rw_eligibility='You need a live URL and a fitting collection. Nothing is published about who is refused; if it fits no collection there is nowhere to file you.', rw_submit_steps='["1 Open /submit-product/. The Submit link in navigation opens it in a new tab with an embedded Google Form; no account needed.","2 Fill it with the resource, its URL, a description and your own name and email. There is no collection field and no logo.","3 Wait. It is a hand-kept WordPress site and no review time is published anywhere."]', rw_submit_requirements='["A live public URL","A resource name and description","Your name and email"]', rw_rejection_reasons='["Nothing published about who is refused; the resource has to fit a collection or there is nowhere to file you"]', rw_gotchas='["The WordPress form on /submit/ is a decoy — it sits in a hidden popup no button opens and posts to an endpoint that answers 403. The real form is the Google Form on /submit-product/, where every Submit button actually goes.","No review time is published on the form, the site or anywhere else, so there is no date to chase."]', rw_faq='[{"question":"How long does Startup Collections approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to Startup Collections?","answer":"Submitting is free."},{"question":"Does a Startup Collections listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 18."},{"question":"Do I need to link back to Startup Collections?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Nothing published; it must fit a collection."}]', rw_summary='Startup Collections is a small curated resource shelf with a free dofollow listing and no backlink. The real form is a Google Form on /submit-product/; domain rating is 18.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","Accepts SaaS, marketing tools, startups and indie products"]', rw_submission_checks='["Use /submit-product/ — /submit/ is a broken decoy.","Make sure your resource fits a collection.","No timeline to chase."]', rw_seo_title='Startup Collections: Free Resource Listing, DR 18', rw_seo_description='How to submit to Startup Collections: free dofollow resource listing, no backlink. Correct Google Form route from the 2026-11-16 snapshot.' WHERE slug='startup-collections';
UPDATE submission_sites SET rw_source_lead='Free, no account, a followed link — and a self-certification that your tool is safe for production before it will send.', rw_what_you_get='A dofollow listing after manual verification, gated on a captcha and a safety certification you tick yourself.', rw_you_need='["A live, working product you can certify is safe for production","A pricing answer typed as free text"]', rw_eligibility='You need a working AI tool and must certify it operational and production-safe. Anything not an AI tool, or not yet operational, is out.', rw_submit_steps='["1 Open /submit-tool. It carries the form and needs no account, despite Login and Sign Up on the site, laid out in three blocks: Identity, Classification and Details.","2 Fill four required fields: tool name, website URL, a pricing string typed free-text, and a confirmation checkbox. Tagline, category, full description and a 16:9 cover are optional.","3 Certify the tool. The required checkbox reads I confirm this tool is operational, safe for production use, and complies with AI safety guidelines — a claim the maker makes.","4 Solve the reCAPTCHA and send. They state every submission is manually verified for quality, API uptime and security before listing, but publish no time."]', rw_submit_requirements='["A product name and website URL","A pricing answer as free text","The operational and safety confirmation","Optional one-line description, category, full description and cover image"]', rw_rejection_reasons='["Anything that is not an AI tool, and anything not yet operational, since the required checkbox certifies it is"]', rw_gotchas='["A visible reCAPTCHA sits above submit, so however much is prepared in advance, a person must finish it by hand.","The required checkbox is a certification about your product, not agreement to terms — you are claiming it is operational, production-safe and AI-safety compliant.","Pricing is typed free text, so write it clearly, for example Freemium or $29/mo."]', rw_faq='[{"question":"How long does AI WareHub approval take?","answer":"No review time is published; submissions are manually verified."},{"question":"How much does it cost to submit to AI WareHub?","answer":"Submitting is free."},{"question":"Does an AI WareHub listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 15."},{"question":"Do I need to link back to AI WareHub?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Anything that is not an AI tool, or not yet operational."}]', rw_summary='AI WareHub is a free dofollow AI directory with no backlink, gated on a captcha and a production-safety self-certification. Manual verification, no published time; domain rating is 15.', rw_fact_points='["Manual verification with no published timeline","Free listing with a dofollow link","No badge or return link is expected","Accepts AI tools only"]', rw_submission_checks='["A person must solve the reCAPTCHA.","Tick the safety certification knowingly.","Write pricing clearly as free text."]', rw_seo_title='AI WareHub: Free AI Listing, DR 15', rw_seo_description='How to submit to AI WareHub: free dofollow AI listing, no backlink. Captcha and safety certification from the 2026-11-16 snapshot.' WHERE slug='ai-warehub';
UPDATE submission_sites SET rw_source_lead='A community-edited alternatives wiki with thousands of software items, free to join and nofollow all the way out.', rw_what_you_get='A nofollow wiki entry that other members can edit after you publish it.', rw_you_need='["An account with a display name, email and password","A live product with a homepage","A category and platform list"]', rw_eligibility='You need an account, a live software product and a fitting category. Anything that is not software is out — the whole site compares software against software.', rw_submit_steps='["1 Create an account at the right URL. /register is a 404; the working path is /signup/ with a display name, email and password — no Google or social route.","2 Go to the dashboard at /account/ and note the total counter before starting — the only proof a submission landed.","3 Name the software, which already creates a draft. Pressing Next on the name-only first screen writes a row into Saved Drafts immediately.","4 Fill the long form: icon, category, short and full descriptions, homepage and pricing URLs, type, monetization, status, platforms, screenshots, videos, features and links.","5 Submit. The row leaves Saved Drafts for Pending Submissions as Pending Approval; once live the entry becomes a wiki page others can edit."]', rw_submit_requirements='["An account with a display name, email and password","A software name and a category from about sixty","A short and a full description, both required","A homepage URL","Optional icon, pricing URL, screenshots, videos, features and alternatives"]', rw_rejection_reasons='["Anything that is not a piece of software — the whole site compares software against software"]', rw_gotchas='["Sign-up means setting a password with no Google or social route, so an agent that cannot type credentials is out.","Entries are wiki pages, not your listing: each prints who composed and last edited it, so someone else can rewrite your description.","No review time is published anywhere — the dashboard submission list is the only place to look.","Naming the software is already a commitment: Next on the first screen writes a draft, so browsing and backing out leaves a half-finished row."]', rw_faq='[{"question":"How long does Alternative.me approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to Alternative.me?","answer":"Submitting is free."},{"question":"Does an Alternative.me listing provide a dofollow link?","answer":"No — links are nofollow on a domain rated 75."},{"question":"Do I need to link back to Alternative.me?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Anything that is not software."}]', rw_summary='Alternative.me is a free nofollow community wiki of software alternatives with no backlink. Entries are editable by others; password signup, no review time; domain rating is 75.', rw_fact_points='["No published review time","Free listing with a nofollow link","No badge or return link is expected","Accepts SaaS, web, desktop and mobile software"]', rw_submission_checks='["Use /signup/, not /register.","Your entry can be edited by other members.","Note the dashboard counter — Next creates a draft immediately."]', rw_seo_title='Alternative.me: Free Software Entry, DR 75', rw_seo_description='How to submit to Alternative.me: free nofollow software wiki entry, no backlink. Signup and draft caveats from the 2026-11-16 snapshot.' WHERE slug='alternative-me';
UPDATE submission_sites SET rw_source_lead='A B2B marketplace where a SaaS listing starts at 560 euros a year and every outbound link is nofollow.', rw_what_you_get='A nofollow B2B listing aimed at agencies choosing tools, bought through an annual membership.', rw_you_need='["A budget from 560 euros a year","A product agencies or brands would buy","A category in their tools taxonomy"]', rw_eligibility='You need to pay annually and offer something agency-side. Consumer-facing products and pre-revenue side projects are refused.', rw_submit_steps='["1 Find the tools door, not the agency one. /join/ is for agencies; /join-tools/ is for SaaS and AI tools. There is no free form anywhere.","2 Pick an annual tier. Four yearly cards with a JOIN button; they differ in category slots, press-release rights and support level.","3 Go through their sales flow. JOIN leads to membership signup rather than a product form, so listing content is collected after the commercial step."]', rw_submit_requirements='["A paid annual membership from 560 euros","A product name, URL and description","One or more categories from their tools taxonomy","Press-release content on higher tiers"]', rw_rejection_reasons='["Anything consumer-facing — the directory is built for agencies choosing tools — and pre-revenue side projects, given the annual entry price"]', rw_gotchas='["There is no free tier or trial listing: the cheapest entry is 560 euros a year, and the price is annual rather than one-off, so it lapses.","Every sampled outbound link carries rel=nofollow noopener, including on the paid side, so the money buys no link equity.","No review or go-live time is published anywhere in the join flow, so there is nothing to plan around before paying."]', rw_faq='[{"question":"How long does Digital Agency Network approval take?","answer":"No review or go-live time is published."},{"question":"How much does it cost to submit to Digital Agency Network?","answer":"Tool listings are annual: 560 euros Gold, 650 Standard, 1,860 Premium, 2,980 Platinum. Tiers buy category slots; press releases start at Gold and higher tiers add an account manager."},{"question":"Does a Digital Agency Network listing provide a dofollow link?","answer":"No — all sampled outbound links are nofollow on a domain rated 76."},{"question":"Do I need to link back to Digital Agency Network?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Consumer-facing products and pre-revenue side projects."}]', rw_summary='Digital Agency Network is a paid-only B2B agency-tools marketplace from 560 euros a year, with nofollow links and no backlink. Domain rating is 76; no go-live time is published.', rw_fact_points='["Paid-only annual membership, no go-live time","Nofollow links with no backlink requirement","Tiers buy category slots, not link equity","Accepts B2B SaaS, AI tools and agency tools"]', rw_submission_checks='["Expect a 560-euro annual contract, not a one-off.","All links are nofollow — judge it on agency-buyer reach.","Content is collected after payment."]', rw_seo_title='Digital Agency Network: €560/yr Listing, DR 76', rw_seo_description='How to list on Digital Agency Network: €560+/year B2B tool listing, nofollow link, no backlink. Tiers from the 2026-11-16 snapshot.' WHERE slug='digital-agency-network';
UPDATE submission_sites SET rw_source_lead='Custom GPTs only — and the link you earn points at OpenAI, not at you.', rw_what_you_get='A dofollow listing pointing to your GPT on OpenAI, worth it for the audience rather than your own domain.', rw_you_need='["A published custom GPT in the GPT store"]', rw_eligibility='You need a published custom GPT. The URL field accepts only a chat.openai.com/g/ address, so anything else has nowhere to go.', rw_submit_steps='["1 Fill three fields: the GPT''s chat.openai.com/g/ URL, a sentence on how it helps someone reach a goal, and optionally a demo video or shared chat. No account.","2 Wait for the curator. They say every submission is reviewed by hand, and the whole site is built and curated by one person."]', rw_submit_requirements='["A GPT URL in chat.openai.com/g/ form","One sentence on what the GPT helps someone achieve","An optional video or shared-chat demo"]', rw_rejection_reasons='["A product that is not a custom GPT has nothing to put in the one required URL field"]', rw_gotchas='["The link goes to OpenAI, not to you — every listing points at chat.openai.com, so this is audience, not backlink.","Only custom GPTs are accepted; there is no second lane for anything else.","One person curates a top-one-percent list, so a submission is a suggestion, not a queue position, and most will not be taken.","A shared chat counts as a demo — cheaper than recording a video."]', rw_faq='[{"question":"How long does Featured GPTs approval take?","answer":"No review time is published; review is by hand."},{"question":"How much does it cost to submit to Featured GPTs?","answer":"Submitting is free."},{"question":"Does a Featured GPTs listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 16 — but it points to OpenAI, not your site."},{"question":"Do I need to link back to Featured GPTs?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Anything that is not a published custom GPT."}]', rw_summary='Featured GPTs is a free hand-curated list of custom GPTs with a dofollow link that points to OpenAI, not your domain. No backlink is required; domain rating is 16.', rw_fact_points='["Hand review with no published timeline","Dofollow link to OpenAI, not your site","No badge or return link is expected","Accepts published custom GPTs only"]', rw_submission_checks='["The link points to OpenAI — judge it on audience.","Use a shared chat as a cheap demo.","Most suggestions are not taken."]', rw_seo_title='Featured GPTs: Free GPT Listing, DR 16', rw_seo_description='How to submit to Featured GPTs: free curated custom-GPT listing, dofollow link to OpenAI, no backlink. Scope from the 2026-11-16 snapshot.' WHERE slug='featured-gpts';
UPDATE submission_sites SET rw_source_lead='Free, followed, entirely in Chinese — and it ends at an image captcha.', rw_what_you_get='A dofollow listing in a Chinese-language AI index, if a person can clear the captcha at the end.', rw_you_need='["An AI product","A person who can read the Chinese form and solve an image captcha"]', rw_eligibility='You need an AI product and someone who can read the form. The site is Chinese-language for a Chinese-reading audience, so a product with no Chinese surface is out of place.', rw_submit_steps='["1 Open /submit_website/ — it shows the form without an account; there is a login link but the fields are reachable signed out.","2 Fill it with an icon, a name, the link with a one-click autofill beside it, an 80-character summary, a longer description, one category, tags, a nickname and a contact method.","3 Pass the captcha. An image captcha sits above the submit button — this is where an agent stops."]', rw_submit_requirements='["A live URL and an 80-character summary","An uploaded icon","A nickname and a contact method","An image captcha a person must solve"]', rw_rejection_reasons='["The site and audience are Chinese-language, so a product with no Chinese-language surface is out of place"]', rw_gotchas='["An image captcha guards submit, so however the rest is filled, a person must be at the keyboard for the last step.","Some cards carry the operator''s own referral codes on outbound links — worth knowing before judging the neighbourhood.","The paid lane is a WeChat tip rather than a checkout: a small donation with your domain in the note, and 300 CNY and up if you want contact.","Everything, including category names and the review notice, is in Chinese."]', rw_faq='[{"question":"How long does iForAI approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to iForAI?","answer":"Submitting is free; paid promotion is a WeChat tip."},{"question":"Does an iForAI listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 15."},{"question":"Do I need to link back to iForAI?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"No formal rule, but the audience is Chinese-language."}]', rw_summary='iForAI is a free dofollow Chinese-language AI index with no backlink. A person must solve an image captcha; domain rating is 15.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","Accepts AI tools, agents and directories"]', rw_submission_checks='["A person must solve the image captcha.","Expect a fully Chinese-language flow.","Some outbound links carry referral codes."]', rw_seo_title='iForAI: Free Chinese AI Listing, DR 15', rw_seo_description='How to submit to iForAI: free dofollow Chinese AI listing, no backlink. Image captcha from the 2026-11-16 snapshot.' WHERE slug='iforai';
UPDATE submission_sites SET rw_source_lead='An 800-tool directory where free costs a permanent badge and a place in a queue 364 deep.', rw_what_you_get='A dofollow listing rented against a permanent badge, after a review that can take a month.', rw_you_need='["An account via Google, GitHub or email and password","A live URL and a short description of 80 to 160 characters","A long 1,000 to 4,000 character introduction and a 16:9 image","Their badge kept on your site permanently, on free"]', rw_eligibility='You need an account, long-form copy, an image and — on free — a badge you will keep. A maker who will not host one, or a product with nothing to say at length, is out.', rw_submit_steps='["1 Sign in. /submit bounces to /auth/login with a callback; Google and GitHub are one-click buttons under the email form.","2 Fill the details, step 1 of 3: link, name, categories and tags as searchable multi-selects, an 80 to 160 character description, a 1,000 to 4,000 character markdown introduction and one 16:9 image under 1MB.","3 Pick a plan, step 2 of 3. Submit creates a draft and opens the plan step; Basic and Pro are Pay & Publish Right Now, while free is Choose Free Plan on the right.","4 Verify the badge, then submit. A panel gives a light or dark snippet pointing at your listing URL; until found, the free button reads Verify Badge First.","5 Wait out the queue. The free card says review within 30 days, may reject, offers no support, and printed 364 free submissions already waiting."]', rw_submit_requirements='["An account","A product name and live URL","A description of 80 to 160 characters","A markdown introduction of 1,000 to 4,000 characters","One 16:9 PNG or JPEG image under 1MB","At least one of thirty categories","Their badge kept permanently on free"]', rw_rejection_reasons='["A maker who will not host a badge on free, and a product with nothing to say at length — the introduction has a 1,000-character floor"]', rw_gotchas='["The free badge is not one-off — their card says they check regularly and unpublish if it is removed, so free is rent.","The card prints its own queue length, 364 waiting against a 30-day review, and says a submission may simply be rejected.","An AI Autofill button sits inside the link field and writes the name, description and introduction from whatever URL is there."]', rw_faq='[{"question":"How long does ToolFame approval take?","answer":"Two to four weeks; the free card states review within 30 days."},{"question":"How much does it cost to submit to ToolFame?","answer":"Free with a kept badge. Basic $14.90 once for three links, no badge and instant listing; Pro $39.90 for five links and features; article, auto-submit and sponsor extras above that."},{"question":"Does a ToolFame listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 75, while the badge stays live."},{"question":"Do I need to link back to ToolFame?","answer":"Yes — a permanent badge is required on free."},{"question":"What gets a listing rejected?","answer":"No badge, or a product that cannot fill 1,000 characters."}]', rw_summary='ToolFame is an 800-tool directory where a free dofollow listing costs a permanent badge and a long queue. No other backlink is needed; domain rating is 75.', rw_fact_points='["Free review within 30 days; paid is instant","Dofollow link rented while the badge is live","A permanent badge is required on free","Accepts AI tools, SaaS, developer tools and more"]', rw_submission_checks='["Keep the badge live — removal delists you.","Write a real 1,000+ character introduction.","Check the AI autofilled fields before submitting."]', rw_seo_title='ToolFame: Free Badge Listing, DR 75', rw_seo_description='How to submit to ToolFame: free dofollow listing for a permanent badge and a 364-deep queue, or instant paid. Steps from the 2026-11-16 snapshot.' WHERE slug='toolfame';
UPDATE submission_sites SET rw_source_lead='Lifetime deals only — if your product is a subscription, this is not your directory.', rw_what_you_get='A dofollow listing in a directory whose whole filter is pay-once pricing.', rw_you_need='["A one-time payment or lifetime deal, not a subscription","A live URL"]', rw_eligibility='You need one-time or lifetime pricing. The whole premise is pay once, use forever, so a monthly or annual subscription has no shelf here.', rw_submit_steps='["1 Check your pricing first. The site exists for one-time payments and lifetime deals; a subscription is out of scope.","2 Use List your product. It is the only route in and a client-side control rather than a link, so it does not appear in the page source."]', rw_submit_requirements='["A live URL","Pricing that is one-time or lifetime"]', rw_rejection_reasons='["A subscription, since the whole premise is pay once, use forever"]', rw_gotchas='["Subscriptions are out — the pricing filter is the whole product, so submitting a monthly plan wastes everyone''s time.","List your product is a JavaScript control, not an anchor, so a crawler or curl will find no submission route.","The categories are ordinary software categories, so the pricing model is the only thing that decides fit."]', rw_faq='[{"question":"How long does 1payment.tools approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to 1payment.tools?","answer":"Submitting is free."},{"question":"Does a 1payment.tools listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 13."},{"question":"Do I need to link back to 1payment.tools?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Any subscription product."}]', rw_summary='1payment.tools is a free dofollow directory for lifetime-deal and one-time-payment products, with no backlink. Subscriptions do not fit; domain rating is 13.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","Accepts one-time-payment SaaS, AI tools and productivity software"]', rw_submission_checks='["Only one-time or lifetime pricing qualifies.","List your product is a JS control, not a link.","Categories are generic; pricing decides fit."]', rw_seo_title='1payment.tools: Free Lifetime Deal Listing, DR 13', rw_seo_description='How to submit to 1payment.tools: free dofollow listing for lifetime-deal products, no backlink. Subscriptions excluded — 2026-11-16 snapshot.' WHERE slug='1payment-tools';
UPDATE submission_sites SET rw_source_lead='An AI-agent catalogue with thousands of agents and skills, a leaderboard and an arena — whose form exists only once you are signed in.', rw_what_you_get='A nofollow listing in a large agent catalogue, filed under its taxonomy with a score and install path.', rw_you_need='["An account — the submit page shows a Sign In to Continue gate","An AI agent or agent skill","A live product with an install path or URL"]', rw_eligibility='You need an account and an agent or skill. Anything that is neither is out, since the taxonomy is built around both.', rw_submit_steps='["1 Open /submit-agent. It renders its heading and a Sign In to Continue button where the form would be; there is no form without an account.","2 Dismiss the newsletter modal, which covers the page on load and re-renders on navigation, including over the submit gate.","3 Sign in via the header''s Login control; /login itself returns 404.","4 Fill the agent listing. Entries render a category, a score out of 100, an install command and a NEW marker, so expect to provide an install path and description."]', rw_submit_requirements='["An account on the directory","An agent or skill name, URL and description","A category from their agent taxonomy","An optional install command"]', rw_rejection_reasons='["Anything that is not an agent or a skill, since the taxonomy is built around both"]', rw_gotchas='["The submit page shows only a heading and a sign-in button, so the form''s questions and any cost are invisible until you have an account.","A newsletter modal covers the page on load and returns on navigation, so the first clicks of any session go into dismissing it.","The site states some links are affiliate links, so do not assume a listing''s outbound link is plain."]', rw_faq='[{"question":"How long does AI Agents Directory approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to AI Agents Directory?","answer":"The free lane''s terms are behind sign-in. Publicly, advertising is sold with a capped number of ecosystem-partner slots, plus sponsor and write-for-us routes."},{"question":"Does an AI Agents Directory listing provide a dofollow link?","answer":"No — links are nofollow on a domain rated 74."},{"question":"Do I need to link back to AI Agents Directory?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Anything that is not an agent or a skill."}]', rw_summary='AI Agents Directory is a nofollow agent and skill catalogue with a sign-in-gated form and no backlink. Domain rating is 74; some outbound links are affiliate.', rw_fact_points='["No published review time","Free lane terms hidden behind sign-in","Nofollow link with no backlink requirement","Accepts AI agents, skills and developer tools"]', rw_submission_checks='["Sign in before you can see the form.","Dismiss the recurring newsletter modal.","Check whether your entry''s link is affiliate-flagged."]', rw_seo_title='AI Agents Directory: Free Agent Listing, DR 74', rw_seo_description='How to submit to AI Agents Directory: nofollow agent/skill listing behind sign-in, no backlink. Gate and modal from the 2026-11-16 snapshot.' WHERE slug='ai-agents-directory';
UPDATE submission_sites SET rw_source_lead='A dofollow AI company index whose submission form cannot be sent — its captcha reports Invalid site key.', rw_what_you_get='A dofollow listing in theory, but the form''s broken reCAPTCHA means no submission can go through.', rw_you_need='["A live, working product","A phone number, marked required, which a pack usually lacks"]', rw_eligibility='You need a working AI product and a phone number. Anything with no AI angle is refused — if the form worked.', rw_submit_steps='["1 Open the user submit page. SUBMIT YOUR AI COMPANY in the header goes to /user-submit/, a WordPress front-end posting form framed around companies, not tools.","2 Fill a company record: a post title, a category from a 59-item AI taxonomy, company name, website, an address, phone, email and a description.","3 Hit the broken captcha. The reCAPTCHA renders ERROR for site owner: Invalid site key instead of a checkbox, so no token can be produced.","4 Watch the button do nothing. Create Post fires zero network requests and leaves the page unchanged, with no error."]', rw_submit_requirements='["A product or company name and a category from a 59-item taxonomy","A website URL","A phone number and an email","A description","An optional postal address"]', rw_rejection_reasons='["Anything with no artificial-intelligence angle"]', rw_gotchas='["The form cannot be submitted by anyone: the reCAPTCHA shows an invalid-site-key error and Create Post fires no request with no error, so it reads as your mistake.","It asks for a phone number and full postal address — more than a product pack carries and more than most makers want public.","The latest sitemap entries date to December 2024 and the homepage still links a defunct Google social URL, so the index has not been updated in a long time."]', rw_faq='[{"question":"How long does AI Directory approval take?","answer":"No review time is published; the form cannot currently be submitted."},{"question":"How much does it cost to submit to AI Directory?","answer":"Submitting is free."},{"question":"Does an AI Directory listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 13, if the form ever works."},{"question":"Do I need to link back to AI Directory?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Anything with no AI angle."}]', rw_summary='AI Directory is a dofollow AI company index with no backlink, but its submit form has a broken reCAPTCHA and cannot be sent. Domain rating is 13.', rw_fact_points='["Form currently broken by invalid captcha","Dofollow link with no backlink requirement","Phone number requested","AI products with an active index"]', rw_submission_checks='["The form cannot be submitted — the captcha is broken.","A phone number is requested.","The index appears stale."]', rw_seo_title='AI Directory: Free Listing, DR 13', rw_seo_description='About AI Directory: free dofollow AI listing with no backlink, but the submit captcha is broken. Details from the 2026-11-16 snapshot.' WHERE slug='ai-directory-org';
UPDATE submission_sites SET rw_source_lead='Customer-experience AI only, and it means it — with a one-time sign-in code by email.', rw_what_you_get='A dofollow listing in a narrow CX-AI catalogue built to be read by machines as well as people.', rw_you_need='["An email address to receive a one-time sign-in code","A product that touches support, helpdesk, chat or voice"]', rw_eligibility='You need an email and a customer-experience product. Every category is CX-shaped, so a product that does not touch support, helpdesk, chat or voice has nowhere to go.', rw_submit_steps='["1 Check the fit first. The categories are chatbots, helpdesk AI, voice AI, agents and a dozen more, all CX-shaped.","2 Sign in by code. /submit asks for an email and mails a one-time code; there is no password or social sign-in.","3 Fill the form behind the code."]', rw_submit_requirements='["A live URL and an email for the one-time code"]', rw_rejection_reasons='["Every category is a customer-experience one, so a product outside support, helpdesk, chat or voice has nowhere to go"]', rw_gotchas='["The scope is narrow on purpose — a general tool with an AI feature is not a CX product and reads as noise.","Sign-in is a one-time code by email, so submitting means a mailbox round trip rather than a password.","They publish an llms.txt and say the directory is updated daily, so it is built for machine readers as much as people."]', rw_faq='[{"question":"How long does AI Products for CX approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to AI Products for CX?","answer":"Submitting is free."},{"question":"Does an AI Products for CX listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 13."},{"question":"Do I need to link back to AI Products for CX?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"A product that is not customer-experience AI."}]', rw_summary='AI Products for CX is a narrow dofollow CX-AI directory with no backlink, using email one-time-code sign-in. Machine-readable; domain rating is 13.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","Accepts CX AI: chatbots, helpdesk, voice and agents"]', rw_submission_checks='["Be genuinely CX-focused, not just AI-flavoured.","Expect an email code round trip.","The site is built for machine readers too."]', rw_seo_title='AI Products for CX: Free Listing, DR 13', rw_seo_description='How to submit to AI Products for CX: free dofollow customer-experience AI listing, no backlink. Code sign-in from the 2026-11-16 snapshot.' WHERE slug='aicxstack';
UPDATE submission_sites SET rw_source_lead='One long page of startup AI tools, every link bare dofollow, and a four-field contact form at the bottom.', rw_what_you_get='A dofollow listing whose entire copy is whatever you type into a free-text message.', rw_you_need='["A live, working product with an AI angle useful to startups"]', rw_eligibility='You need an AI product relevant to startup growth. Anything with nothing to do with AI or growth is refused.', rw_submit_steps='["1 Find the form on the homepage. There is no submit page; Send Your Tool in the nav is an anchor to a section near the bottom of the single long page.","2 Fill four fields: name, email, your tool URL and a free-text message. It is a Contact Form 7 form with no account and an invisible reCAPTCHA badge rather than a checkbox.","3 Press Send. It posts to the WordPress REST contact route, sets data-status=sent and prints a thank-you while clearing the fields.","4 Wait with no published time — the message is the whole submission, and whatever you wrote is all the operator has to build the listing from."]', rw_submit_requirements='["Your name and an email address","A product URL","A message describing the product, since there are no structured fields"]', rw_rejection_reasons='["Products with nothing to do with AI or startup growth"]', rw_gotchas='["The message box is the entire listing copy — no name, tagline, category or description fields — so whatever you type is all the operator has.","There is no submit page to bookmark; the only route is a homepage anchor that is easy to miss and impossible to deep-link reliably.","Several existing entries link through the operator''s affiliate parameters rather than the plain URL, so check what your own points at."]', rw_faq='[{"question":"How long does AItoGrow approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to AItoGrow?","answer":"Submitting is free."},{"question":"Does an AItoGrow listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 14."},{"question":"Do I need to link back to AItoGrow?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Products with nothing to do with AI or startup growth."}]', rw_summary='AItoGrow is a free dofollow startup-AI list with no backlink, submitted through a four-field homepage contact form. The message is your entire listing copy; domain rating is 14.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","Accepts AI tools and marketing tools for startups"]', rw_submission_checks='["Write your whole pitch in the message box.","The form is an anchor on the homepage, not a page.","Check your live link for affiliate parameters."]', rw_seo_title='AItoGrow: Free Startup AI Listing, DR 14', rw_seo_description='How to submit to AItoGrow: free dofollow AI listing via a homepage contact form, no backlink. Message-as-copy caveat from the 2026-11-16 snapshot.' WHERE slug='aitogrow';
UPDATE submission_sites SET rw_source_lead='An 831-tool directory that publishes its own traffic and rations free submissions to a handful a day.', rw_what_you_get='A dofollow listing reviewed in seven days, in exchange for a footer badge and an available free slot.', rw_you_need='["An account via the Sign In control","Their badge in your website footer on the free lane","A product name, URL and description"]', rw_eligibility='You need an account, a badge you can host and a free slot that day. A site you cannot badge is out unless you pay $9.99, and a full day''s quota is out.', rw_submit_steps='["1 Choose a plan. /pricing lists three paid tiers and the free lane below them under an Or divider; the free card carries the badge embeds.","2 Sign in; the submission attaches to an account.","3 Fill the listing with product details and one of 24 categories.","4 Take a badge embed — dark, light and transparent — and add a followed link back in your footer.","5 Wait seven days for manual approval, which the free card states outright."]', rw_submit_requirements='["An account on the site","A product name, URL and description","One of 24 categories","Their badge in your footer on the free lane","An optional logo"]', rw_rejection_reasons='["A site you cannot add a footer badge to unless you pay $9.99, and a day when someone else has taken the free slot"]', rw_gotchas='["The free lane is capped at five submissions a day across all users, with a public counter — it read 5/5 used midweek while a personal limit still showed 0/1, so arriving late means coming back tomorrow.","Free listings face manual approval on top of the seven-day wait, so the badge can go up and the listing still not appear."]', rw_faq='[{"question":"How long does Dofollow.Tools approval take?","answer":"About a week; the free card states seven days plus manual approval."},{"question":"How much does it cost to submit to Dofollow.Tools?","answer":"Free with a footer badge. One Time Pro $9.99 for a lifetime listing with no badge; Monthly Promotion $5 a month; Featured $29 a month."},{"question":"Does a Dofollow.Tools listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 73."},{"question":"Do I need to link back to Dofollow.Tools?","answer":"Yes — the free lane requires their badge in your footer."},{"question":"What gets a listing rejected?","answer":"No footer badge, or a day when the free quota is used."}]', rw_summary='Dofollow.Tools is a free dofollow directory with a footer badge and a seven-day manual review, rationing free slots each day. No other backlink is needed; domain rating is 73.', rw_fact_points='["Seven-day review with manual approval","Free listing with a dofollow link","A footer badge is required on free","Accepts AI tools, SaaS, no-code, developer tools and more"]', rw_submission_checks='["Free slots fill fast — check the public counter.","Install the footer badge before review.","Approval is manual even after seven days."]', rw_seo_title='Dofollow.Tools: Free Badge Listing, DR 73', rw_seo_description='How to submit to Dofollow.Tools: free dofollow listing with a footer badge and daily free-slot quota. Review from the 2026-11-16 snapshot.' WHERE slug='dofollow-tools';
UPDATE submission_sites SET rw_source_lead='Thousands of listings and a large startup newsletter behind a free form that needs no account and gives a followed link.', rw_what_you_get='A dofollow listing reviewed for a large AI directory with a newsletter audience, with no backlink required.', rw_you_need='["A live, working product","A description within 220 characters","A company email address"]', rw_eligibility='You need a working AI product, a short description and a company email. Anything that is not an AI tool is refused.', rw_submit_steps='["1 Open /submit. It carries the whole form with no account, login or captcha — unusual for a directory this size.","2 Fill four required fields: tool name, website, a description capped at 220 characters and a company email.","3 Add optional depth: a markdown full description up to 3,000 characters with live preview, four social links and three checkbox groups for market, price and features.","4 Submit and read the toast. A green message says the tool will be reviewed and published soon with an email to follow; it posts to /submit as a server action."]', rw_submit_requirements='["A product name and URL","A description up to 220 characters","A company email","Optional long description, social links and checkbox groups","An optional affiliate-programme link, marked not shared publicly"]', rw_rejection_reasons='["Anything that is not an AI tool"]', rw_gotchas='["The short description caps at 220 characters, tighter than the 260 many packs are written to, so the standard blurb needs cutting down.","The form asks for your affiliate-programme signup link, marked not shared publicly — the operator asking to monetise your listing, not a field the listing needs.","No review time is stated and the only acknowledgement is a toast plus an email promise, so a stalled submission looks like a successful one."]', rw_faq='[{"question":"How long does ListedAI approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to ListedAI?","answer":"Submitting is free."},{"question":"Does a ListedAI listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 13."},{"question":"Do I need to link back to ListedAI?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Anything that is not an AI tool."}]', rw_summary='ListedAI is a free dofollow AI directory with a newsletter audience and no backlink. The short description caps at 220 characters; domain rating is 13.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","Accepts AI tools only"]', rw_submission_checks='["Cut your short description to 220 characters.","The affiliate link field is optional and not public.","Expect only a toast, no status page."]', rw_seo_title='ListedAI: Free AI Listing, DR 13', rw_seo_description='How to submit to ListedAI: free dofollow AI listing, no backlink. 220-character cap and no account from the 2026-11-16 snapshot.' WHERE slug='listedai';
UPDATE submission_sites SET rw_source_lead='A showcase for things built with Bolt.new, free and followed, and closed to everything else.', rw_what_you_get='A dofollow showcase entry for a project genuinely built with Bolt.new.', rw_you_need='["A project actually built with Bolt.new — the whole premise","A title, email, a short and a long description and a URL"]', rw_eligibility='You need a Bolt.new project. The submit page states outright that only projects built with Bolt will be accepted and displayed.', rw_submit_steps='["1 Check the one rule. /submit-project says only projects built with Bolt will be accepted and displayed — no second tier, no exception.","2 Fill six fields: project title, email, short description, long description and website URL, with optional X and Reddit handles. No account, logo or screenshots.","3 Submit and wait for a human. One maker reviews and replies by email; no turnaround, queue page or reference."]', rw_submit_requirements='["A project title and website URL","A contact email","A short and a long description","Optional X and Reddit handles"]', rw_rejection_reasons='["Anything not built with Bolt — the submit page states it outright"]', rw_gotchas='["Only Bolt.new projects are accepted, in bold on the form; claiming otherwise is the kind of thing one maker reviewing by hand will notice.","There is no account or dashboard — you submit into an email queue with no stated turnaround.","It is genuinely free and the outbound link carries no rel attribute, a clean dofollow for five minutes of work."]', rw_faq='[{"question":"How long does Made with Bolt approval take?","answer":"No review time is published; one maker reviews by email."},{"question":"How much does it cost to submit to Made with Bolt?","answer":"Submitting is free."},{"question":"Does a Made with Bolt listing provide a dofollow link?","answer":"Yes — the outbound link carries no rel attribute, on a domain rated 14."},{"question":"Do I need to link back to Made with Bolt?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Anything not built with Bolt.new."}]', rw_summary='Made with Bolt is a free dofollow showcase for Bolt.new projects, with no backlink. One-person email review, no published timeline; domain rating is 14.', rw_fact_points='["Hand review with no published timeline","Free listing with a dofollow link","No badge or return link is expected","Accepts Bolt.new-built projects only"]', rw_submission_checks='["Only Bolt.new projects qualify.","Submit into an email queue — no status page.","The outbound link is dofollow."]', rw_seo_title='Made with Bolt: Free Project Listing, DR 14', rw_seo_description='How to submit to Made with Bolt: free dofollow showcase for Bolt.new projects, no backlink. Eligibility from the 2026-11-16 snapshot.' WHERE slug='made-with-bolt';
UPDATE submission_sites SET rw_source_lead='A model-and-agent ranking workspace, not a place to list a product.', rw_what_you_get='A dofollow entry for a model or agent that can be measured in their task evaluations — not a product listing.', rw_you_need='["A model or agent that can be run against their task evaluations"]', rw_eligibility='You need an evaluable model or agent. It ranks by measured task performance, so a product that merely uses AI has nothing for the rankings to measure.', rw_submit_steps='["1 Check what it actually lists. The nav is Decide, Test, Monitor and Explore — choosing a model, comparing models, task rankings, real-task evaluation, report verification and an upgrade radar.","2 There is no product submission. The site has no submit route for an ordinary product; what it indexes is models and agents it evaluates."]', rw_submit_requirements='["A live URL","A fit with models and agents only"]', rw_rejection_reasons='["It ranks models and agents by measured task performance, so a product that merely uses AI has nowhere to sit"]', rw_gotchas='["This is not a product directory but a workspace for deciding between AI models, with rankings from their own evaluations.","There is no submit form for a tool — unless you ship an evaluable model or agent, there is nothing to apply for.","The site runs in eight interface languages with more English-content previews, worth knowing if judging its audience from English alone."]', rw_faq='[{"question":"How long does OpenGPT approval take?","answer":"No review time is published; there is no ordinary product submission."},{"question":"How much does it cost to submit to OpenGPT?","answer":"There is no product-submission route."},{"question":"Does an OpenGPT listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 14, for listed models and agents."},{"question":"Do I need to link back to OpenGPT?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"A product that is not an evaluable model or agent."}]', rw_summary='OpenGPT is an AI model-and-agent ranking workspace with a dofollow entry and no backlink. It indexes evaluated models and agents, not ordinary products; domain rating is 14.', rw_fact_points='["No product-submission route","Dofollow entry with no backlink","Ranks by measured task performance","Accepts AI models and agents only"]', rw_submission_checks='["Only evaluable models or agents apply.","There is no tool submit form.","Judge the audience beyond the English pages."]', rw_seo_title='OpenGPT: Model Ranking Entry, DR 14', rw_seo_description='About OpenGPT: an AI model/agent ranking workspace, not a product directory. Dofollow entry, no backlink — 2026-11-16 snapshot.' WHERE slug='opengpt';
UPDATE submission_sites SET rw_source_lead='A side-project showcase behind an email-and-password account, with no social sign-in.', rw_what_you_get='A dofollow showcase entry for a side project, with no backlink required.', rw_you_need='["An account with an email and password — no social sign-in"]', rw_eligibility='You need an account. The site is framed around passion projects, so a polished commercial product is a poor fit for the room.', rw_submit_steps='["1 Register. /projects/submit redirects to a login page with email and password and a Register here link; no Google or GitHub option.","2 Add the project. The Add Project button on the home page goes to the same submit route once signed in."]', rw_submit_requirements='["A live URL and an account with email and password"]', rw_rejection_reasons='["It is framed around passion projects, so a polished commercial product is a poor fit for the room"]', rw_gotchas='["There is no social sign-in — getting in means a password account nobody can create for you.","The audience is explicitly side and passion projects, a different room from a launch board.","The home page mixes the showcase with an affiliate course pitch, so read what the site is really selling before investing time."]', rw_faq='[{"question":"How long does SideProjects.net approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to SideProjects.net?","answer":"Submitting is free."},{"question":"Does a SideProjects.net listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 13."},{"question":"Do I need to link back to SideProjects.net?","answer":"No backlink is required."},{"question":"What gets a project rejected?","answer":"A polished commercial product is a poor fit for a passion-project showcase."}]', rw_summary='SideProjects.net is a free dofollow side-project showcase with no backlink, behind a password-only account. A passion project fits better than a commercial product; domain rating is 13.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","Accepts side projects, indie products and web apps"]', rw_submission_checks='["Create a password account — no SSO.","A passion-project framing fits best.","The site also sells an affiliate course."]', rw_seo_title='SideProjects.net: Free Side-Project Listing, DR 13', rw_seo_description='How to submit to SideProjects.net: free dofollow side-project listing, no backlink. Email-only account from the 2026-11-16 snapshot.' WHERE slug='sideprojects-net';
UPDATE submission_sites SET rw_source_lead='A very large enterprise-software taxonomy behind a WordPress account.', rw_what_you_get='A dofollow listing in an enterprise-software taxonomy, filed under one of its many categories.', rw_you_need='["An account with an email and password — no social sign-in"]', rw_eligibility='You need an account and a fitting category. The taxonomy is enterprise software, so an indie tool with no category looks out of place among hundreds of AI and analytics entries.', rw_submit_steps='["1 Find your category first. The tree is enormous with public counts, so decide where you would sit before making an account.","2 Register. /create-listing/ answers You must first login or register before you can submit anything — a WordPress account with email and password.","3 Create the listing behind the account."]', rw_submit_requirements='["A live URL and an account with email and password"]', rw_rejection_reasons='["The taxonomy is enterprise software categories, so an indie tool with no category looks out of place"]', rw_gotchas='["There is no social sign-in — getting in means a password account nobody can make for you.","The categories are enterprise-buyer categories, several holding hundreds of listings, so a new entry lands deep in a long list.","/contact/ returns 404 despite being linked, so do not count on reaching anybody."]', rw_faq='[{"question":"How long does TheSaaSDirectory approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to TheSaaSDirectory?","answer":"Submitting is free."},{"question":"Does a TheSaaSDirectory listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 13."},{"question":"Do I need to link back to TheSaaSDirectory?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"An indie tool with no fitting enterprise category."}]', rw_summary='TheSaaSDirectory is a free dofollow enterprise-software directory with no backlink, behind a WordPress account. Categories are buyer-oriented and deep; domain rating is 13.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","Accepts SaaS products and startups"]', rw_submission_checks='["Pick an enterprise category before signing up.","Password account only — no SSO.","/contact/ is broken; do not rely on it."]', rw_seo_title='TheSaaSDirectory: Free SaaS Listing, DR 13', rw_seo_description='How to submit to TheSaaSDirectory: free dofollow enterprise-SaaS listing, no backlink. Category tree from the 2026-11-16 snapshot.' WHERE slug='thesaasdirectory';
UPDATE submission_sites SET rw_source_lead='A large Chinese AI tool directory taking submissions through a Feishu form, with no promise of inclusion.', rw_what_you_get='A nofollow listing in a big Chinese AI index, if they choose to include you.', rw_you_need='["A Chinese one-line intro of 20 characters or fewer","A contact method, WeChat preferred","A submitter name of five characters or fewer"]', rw_eligibility='You need a Chinese-language submission. Mirror sites, wrapper apps, WeChat mini-programs and AI courses are refused.', rw_submit_steps='["1 Open the form. /submit on their domain redirects to a questionnaire on a Feishu form host.","2 Fill it in Chinese: product name, official site, category, a one-line intro up to 20 characters, a detailed intro covering features, use, pricing and scenarios, your name up to five characters, your contact and a date.","3 Send it and wait. No account, no confirmation and no stated review time; they say submitting does not guarantee inclusion."]', rw_submit_requirements='["A product name and official site","A category and a one-line intro up to 20 characters","A detailed introduction","A submitter name up to five characters and a contact method"]', rw_rejection_reasons='["Mirror sites and wrapper apps, WeChat mini-programs and AI courses"]', rw_gotchas='["The form lives off their domain with no account and no reply — it is an application and they say inclusion is not guaranteed.","The one-line intro caps at 20 Chinese characters, which no English tagline fits.","Paid inclusion is by email only with no published price."]', rw_faq='[{"question":"How long does AI-bot.cn approval take?","answer":"No review time is published; inclusion is not guaranteed."},{"question":"How much does it cost to submit to AI-bot.cn?","answer":"The form is free. Paid inclusion, ads and partnerships go by email with no published price."},{"question":"Does an AI-bot.cn listing provide a dofollow link?","answer":"No — links are nofollow on a domain rated 71."},{"question":"Do I need to link back to AI-bot.cn?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Mirror sites, wrapper apps, WeChat mini-programs and AI courses."}]', rw_summary='AI-bot.cn is a large Chinese AI directory with a free nofollow listing and no backlink, submitted through a Feishu form with no inclusion guarantee. Domain rating is 71.', rw_fact_points='["No review time; inclusion not guaranteed","Free listing with a nofollow link","No badge or return link is expected","Accepts Chinese-language AI tools and sites"]', rw_submission_checks='["Write a 20-character Chinese one-line intro.","WeChat is the preferred contact.","Expect no confirmation or reply."]', rw_seo_title='AI-bot.cn: Free Chinese AI Listing, DR 71', rw_seo_description='How to submit to AI-bot.cn: free nofollow Chinese AI directory listing, no backlink. Feishu form from the 2026-11-16 snapshot.' WHERE slug='ai-bot-cn';
UPDATE submission_sites SET rw_source_lead='A five-slots-a-day launch board that writes an AI-friendly Markdown page for every project — and gives the free tier a conditional link.', rw_what_you_get='A launch page structured as Markdown for AI citation, with a followed link only if you meet two conditions and rank top three.', rw_you_need='["An account at the signup route","Their badge on your site — one of two conditions for a free followed link","A live project with a name and description"]', rw_eligibility='You need an account, a project and — for the free followed link — a badge and a top-three daily finish. Nothing structural is refused; the constraint is five free slots a day.', rw_submit_steps='["1 Sign up and open the form at /projects/submit; there is also an AI-assisted option from the homepage.","2 Fill the project. The generated page is detail-rich Markdown structured for AI citations, so the description does more work than on a card-only board.","3 Choose a plan and date. Free has five slots a day, Premium $17 has ten within 60 days, Premium Plus $34 has three. In practice the free picker is full for the year and a checkbox assigns a date at least 200 days out.","4 Add the badge. The last step verifies a link to them on your homepage; on free the followed link needs both the badge and a top-three daily ranking.","5 Launch at 08:00 UTC — all launches go live the same hour.","6 Or trade content for a premium launch: launch nofollow, post about them on a subreddit, publish a blog post with a followed link, and email the three links — they judge whether it qualifies."]', rw_submit_requirements='["An account and a project name, live URL and description","Their badge on your site for the conditional free link","An optional logo and launch-card images"]', rw_rejection_reasons='["Nothing structural — the constraint is five free slots a day against a 365-day scheduling window"]', rw_gotchas='["The free followed link needs a top-three daily finish AND their badge, two conditions stated as a numbered list that reads like one.","You do not pick a free date — the picker is full all year and a checkbox assigns one at least 200 days out, which also gives up relaunches.","The free premium launch is paid in content: a nofollow launch first, a subreddit post, a followed blog post, then email three links; only posts they judge thoughtful count, and the blog post is a permanent link out of your domain.","Relaunches are paid with cooldowns — ten on Premium at 14 days, ten on Premium Plus at 7; free gets one launch."]', rw_faq='[{"question":"How long does Aura++ approval take?","answer":"Six months or more on free; the assigned date is at least 200 days out."},{"question":"How much does it cost to submit to Aura++?","answer":"Free with conditions. Premium $17 a launch with a guaranteed followed link and promotion; Premium Plus $34 with spotlight and faster relaunches. A content-for-premium offer also exists."},{"question":"Does an Aura++ listing provide a dofollow link?","answer":"No by default — site links are nofollow; a followed link needs the paid tier or the two free conditions plus top-three ranking."},{"question":"Do I need to link back to Aura++?","answer":"Yes — a badge or plain followed text link is required, and governs the free link."},{"question":"What gets a listing rejected?","answer":"Nothing structural; free slots are simply capped at five a day."}]', rw_summary='Aura++ is a five-slot-a-day launch board with AI-friendly Markdown pages and a nofollow default. A free followed link needs a badge, top-three ranking and a 200+ day wait; domain rating is 72.', rw_fact_points='["Free wait of six months or more","Site links nofollow; followed link is conditional or paid","A badge is required for the free conditional link","Accepts SaaS, indie products, AI tools and more"]', rw_submission_checks='["The free followed link needs two conditions plus top-three.","The free date is assigned, not chosen, at 200+ days out.","The content-for-premium offer needs a permanent followed blog post."]', rw_seo_title='Aura++: Free Launch, DR 72', rw_seo_description='How to launch on Aura++: AI-friendly Markdown launch page, nofollow by default, conditional free followed link. Rules from the 2026-11-16 snapshot.' WHERE slug='aura-plus-plus';
UPDATE submission_sites SET rw_source_lead='A newspaper-styled founder directory that credits every listing to an account, with magic-link sign-in.', rw_what_you_get='A dofollow founder-tool listing with no backlink, credited to your account profile.', rw_you_need='["An account via magic link, not a password","Your name and email typed into the form, even when signed in"]', rw_eligibility='You need an account and a tool a founder would put in a stack — hosting, database, payments, support. A product of another kind has nowhere to sit.', rw_submit_steps='["1 Create the account from /account. There is no password: enter an address, press Email me a magic link, then click through to land signed in as your handle.","2 Open /submit/tool. The other lanes on /submit are a story, a stack and a product; the tool lane puts a row in the directory.","3 Fill the card with a name, URL, one of twelve categories, a one-line description, a pricing pill, two to four comma-separated tags and who it is for: Solo Founder, Small Team or Agency.","4 Type your name and email at the bottom, both required even while signed in, then submit. A RECEIVED panel says review takes 7 to 14 days."]', rw_submit_requirements='["A live URL, a one-sentence description and two to four tags"]', rw_rejection_reasons='["The directory is organised around founder stack tools, so a product of another kind has nowhere to sit"]', rw_gotchas='["Sign-in is magic-link only with no password, so every later visit means opening a mail again.","Being signed in does not fill the form: the last two fields — your name and email — are required and the button does nothing while empty.","Approval is editorial and slow — 7 to 14 days, with the confirmation careful to say if we publish it.","A Ship or Die community checkbox above the name field claims community membership; leave it alone unless you are in it."]', rw_faq='[{"question":"How long does FoundersHub approval take?","answer":"One to two weeks; the confirmation says 7 to 14 days."},{"question":"How much does it cost to submit to FoundersHub?","answer":"Submitting is free."},{"question":"Does a FoundersHub listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 11."},{"question":"Do I need to link back to FoundersHub?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"A product that is not a founder stack tool."}]', rw_summary='FoundersHub is a free dofollow founder-tool directory with no backlink, using magic-link accounts and a 7-to-14-day editorial review. Domain rating is 11.', rw_fact_points='["Editorial review in 7 to 14 days","Free listing with a dofollow link","No badge or return link is expected","Accepts SaaS, dev, startup and productivity tools"]', rw_submission_checks='["Expect a magic-link email on every sign-in.","Fill name and email at the bottom even when signed in.","Leave the community checkbox unticked unless you belong."]', rw_seo_title='FoundersHub: Free Founder Tool, DR 11', rw_seo_description='How to submit to FoundersHub: free dofollow founder-tool listing, no backlink. Magic-link account from the 2026-11-16 snapshot.' WHERE slug='foundershub';
UPDATE submission_sites SET rw_source_lead='A weekly startup launch feed where the free listing is genuinely free — and the followed link is the first thing you lose by not paying.', rw_what_you_get='A free weekly launch listing that sends no link equity; the dofollow link, instant publish and badges are paid.', rw_you_need='["An account, since the listing carries a founder profile","A live product with a name, description and media","A launch week, since the feed is organised by week"]', rw_eligibility='You need an account and a live product. Nothing structural blocks the free tier — it is open, and the paid tier is about placement, not acceptance.', rw_submit_steps='["1 Create an account. The listing hangs off a profile; the signed-in nav is Feed, Search, Chat, Launch, Analytics, Affiliates and Profile.","2 Start a launch. /submit takes product details; the feed is organised by launch week with medals for the top three.","3 Choose free or featured. Free forever with no card, or $29 for seven days featured with instant publish and a guaranteed followed link.","4 Wait for the week. The free tier does not publish instantly — instant publish is one of the things under the paid tiers."]', rw_submit_requirements='["An account and founder profile","A product name, live URL and description","Media for the product page","Optional logo and screenshots"]', rw_rejection_reasons='["Nothing structural on free — it is open, and the paid tier is about placement, not acceptance"]', rw_gotchas='["The free tier carries no followed link — the guaranteed dofollow sits in the $29 column of their own comparison table, with instant publish and verified badges.","Free listings do not publish immediately; instant publish is paid, so a free launch waits for its week.","The site runs session recording and says so in a persistent banner on every page, including the submission flow."]', rw_faq='[{"question":"How long does FoundrList approval take?","answer":"About a week — free launches wait for their week rather than publishing instantly."},{"question":"How much does it cost to submit to FoundrList?","answer":"Free forever. $29 for seven days featured adds instant publish, badges, top placement and a guaranteed followed link; a fourteen-day tier extends it."},{"question":"Does a FoundrList listing provide a dofollow link?","answer":"No on the free tier — the dofollow link is a paid feature."},{"question":"Do I need to link back to FoundrList?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Nothing structural on free — it is open."}]', rw_summary='FoundrList is a free weekly startup launch feed with no backlink, but the free listing is nofollow and waits for its week. A $29 tier buys the followed link; domain rating is 72.', rw_fact_points='["Free listing waits for its launch week","Free listing is nofollow; no backlink required","A $29 tier buys instant publish and the followed link","Accepts SaaS, indie products, AI tools and startups"]', rw_submission_checks='["The free tier carries no followed link.","Expect a wait until your launch week.","A session-recording banner runs site-wide."]', rw_seo_title='FoundrList: Free Weekly Launch, DR 72', rw_seo_description='How to launch on FoundrList: free weekly listing with nofollow link, no backlink. $29 buys the dofollow — 2026-11-16 snapshot.' WHERE slug='foundrlist';
UPDATE submission_sites SET rw_source_lead='A high-traffic AI directory that stopped taking free submissions, sold out its cheaper tier, and links out nofollow at every price.', rw_what_you_get='A nofollow listing bought purely for audience reach, with editorial approval and a refund if rejected.', rw_you_need='["A commercial AI product, not a hobby project","$497 — the cheaper tier is sold out","Features editors will not judge inappropriate for their audience"]', rw_eligibility='You need a commercial AI product and payment. Hobbyist tools and products outside AI are refused, and no free listing exists.', rw_submit_steps='["1 Read the two prices: Basic at $247 for publication within seven days, marked sold out, and Verified at $497 for two business days.","2 Pay before you submit. Their disclosure ties form and payment together — you agree to terms by submitting and paying.","3 Wait for editorial. Every submission is approved by editors, who reserve the right to remove a listing later if features stop suiting the audience.","4 Claim a refund if refused — full and automatic on rejection, but none once accepted and published."]', rw_submit_requirements='["A live AI product","$497 for the only tier on sale","An optional video and tutorials they will place"]', rw_rejection_reasons='["Anything hoping for a free listing, which they no longer offer; hobbyist tools; products outside AI"]', rw_gotchas='["There is no free lane — the FAQ says plainly they no longer offer free submissions.","The cheaper tier is sold out, so the real entry price today is $497, not the $247 the page leads with.","The link is nofollow whatever you pay — tool pages carry rel=nofollow, so this is an audience buy.","The refund covers rejection only; once published the fee is gone and they can still remove the listing later."]', rw_faq='[{"question":"How long does Futurepedia approval take?","answer":"About a week; Verified publishes within two business days."},{"question":"How much does it cost to submit to Futurepedia?","answer":"$247 Basic, published within seven days, currently sold out; $497 Verified within two business days with an enhanced page and verified check; enterprise on a call."},{"question":"Does a Futurepedia listing provide a dofollow link?","answer":"No — links are nofollow at every price, on a domain rated 72."},{"question":"Do I need to link back to Futurepedia?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Hobbyist tools, products outside AI, or anyone expecting a free listing."}]', rw_summary='Futurepedia is a paid-only AI directory from $497 with a nofollow listing and no backlink. Editorial approval with refund on rejection; domain rating is 72.', rw_fact_points='["Paid-only at $497; cheaper tier sold out","Nofollow link with no backlink requirement","Editorial approval with rejection refund","Accepts commercial AI products only"]', rw_submission_checks='["Expect to pay $497 — no free lane, cheaper tier gone.","The link is nofollow — buy for audience only.","Refund applies only if rejected, not after publication."]', rw_seo_title='Futurepedia: $497 AI Listing, DR 72', rw_seo_description='How to submit to Futurepedia: paid $497 nofollow AI listing, no backlink. Sold-out tier from the 2026-11-16 snapshot.' WHERE slug='futurepedia';
UPDATE submission_sites SET rw_source_lead='A launch board whose free queue was 1,513 products deep, and whose form quotes the price of skipping it in pounds.', rw_what_you_get='A free launch listing that needs a badge and five visits to other launches, with a dofollow link sold as an add-on.', rw_you_need='["An account via Google or an emailed link","A square logo and a 16:9 featured image","A description of at least fifty characters","Their badge on your site and five visits to other launches"]', rw_eligibility='You need an account, media, a badge and five confirmation visits. Nothing is structurally refused, but a listing is not guaranteed — their form says so.', rw_submit_steps='["1 Sign in first. /submit is a wall until you do; Google works or they email a sign-in link.","2 Fill one long page: name, a 60-character tagline, a description over fifty characters, up to five key features, logo, featured image, URL, category and four optional questions.","3 Untick the upgrade. The next screen opens with Skip the queue pre-ticked at 99 pounds and four more paid boxes; the button reads Submit for Free once they are clear.","4 Visit five launches. A gate, not a suggestion — the submission is not confirmed until the counter reads 5 of 5, each Check it out marking one.","5 Take the badge and note the date. The confirmation names your launch date and hands over a badge marked required for free submissions."]', rw_submit_requirements='["An account and product name and URL","A tagline up to 60 characters and a description over fifty","A square logo and a 16:9 featured image under 5MB each","One category","Their badge on your site","Optional features, X handle and discount code"]', rw_rejection_reasons='["Nothing published — a SaaS, marketplace, app, service or newsletter are all welcome; and a listing is not guaranteed, which their form says explicitly"]', rw_gotchas='["The queue is the product: their upgrade screen said 1,513 startups ahead and gave a date two months out.","Skip the queue is pre-ticked at 99 pounds with a total already showing — the free lane starts as a checkout until you untick it.","Submitting is not the last step: until five other launches are opened the listing is unconfirmed, and nothing warns you first.","The free listing is not dofollow — that is one of the paid add-ons at 99 pounds, and prices are in pounds."]', rw_faq='[{"question":"How long does Tiny Startups approval take?","answer":"No review time is published; the queue ran about 1,513 deep and two months out."},{"question":"How much does it cost to submit to Tiny Startups?","answer":"Free with a badge and five visits. Add-ons in GBP: 99 to skip the queue, 99 for a permanent dofollow listing, 199 for four partner backlinks, 129 for a newsletter feature, 99 for a review article."},{"question":"Does a Tiny Startups listing provide a dofollow link?","answer":"No on free — the dofollow link is a 99-pound add-on."},{"question":"Do I need to link back to Tiny Startups?","answer":"Yes — their badge is required for free submissions."},{"question":"What gets a listing rejected?","answer":"Nothing structural, but a listing is not guaranteed."}]', rw_summary='Tiny Startups is a launch board where free requires a badge and five visits, with a long queue and nofollow link. Dofollow costs extra; domain rating is 71.', rw_fact_points='["Free queue over 1,500 deep","Free listing is nofollow; a badge is required","A dofollow link is a paid add-on","Accepts indie products, SaaS, AI, mobile apps and newsletters"]', rw_submission_checks='["Untick the pre-checked 99-pound upgrade.","Visit five other launches to confirm.","The free link is nofollow — dofollow is paid."]', rw_seo_title='Tiny Startups: Free Badge Launch, DR 71', rw_seo_description='How to launch on Tiny Startups: free listing with a badge and five visits, long queue, nofollow link. GBP add-ons from the 2026-11-16 snapshot.' WHERE slug='tiny-startups';
UPDATE submission_sites SET rw_source_lead='A Spanish-language gallery for things built with AI coding tools.', rw_what_you_get='A dofollow showcase entry for a project built with listed AI coding tools, read by a small Spanish-speaking audience.', rw_you_need='["A project built with AI coding tools","A maker name and a short project description"]', rw_eligibility='You need a project built with one of their AI coding tools. The whole premise is how you built it, so a product with no AI tool in its build has no honest answer to the central question.', rw_submit_steps='["1 Open /submit/ with no account. The page defaults to Spanish with an English toggle in the header, but the form and what readers see stay Spanish.","2 Fill the maker block: your name is required, email optional and admin-only, LinkedIn and X optional and public.","3 Fill the project block: a title, description, up to three of twelve categories and a stage — Idea, MVP or Producción.","4 Say what you built it with. Pick from nine listed tools and add others as free-text chips; this is the point of the site, so leaving it empty wastes the listing.","5 Add the URL, an optional demo video and up to five images. Enviar Proyecto lands on a thank-you page saying a human will review it and write first."]', rw_submit_requirements='["A live URL","Up to three categories from twelve","Up to five images","A maker name and a project description"]', rw_rejection_reasons='["A product with no AI coding tool in its build — the central question has no honest answer"]', rw_gotchas='["Everything readers see is in Spanish, so write the description in Spanish or accept reading as an outsider.","The link is dofollow for most listings but not all: of 43 live projects, 14 hosted on preview domains carried nofollow. A product on its own domain gets the follow.","Approval is a person reading it, with no queue page and no stated wait — the confirmation only promises they will write before publishing.","It is one maker''s project with a few dozen entries — a small Spanish-speaking audience, not a traffic source."]', rw_faq='[{"question":"How long does Vibe Coding Gallery approval take?","answer":"No review time is published; a person reviews and writes before publishing."},{"question":"How much does it cost to submit to Vibe Coding Gallery?","answer":"Submitting is free."},{"question":"Does a Vibe Coding Gallery listing provide a dofollow link?","answer":"Yes for products on their own domain, on a domain rated 11 — preview-host entries are nofollow."},{"question":"Do I need to link back to Vibe Coding Gallery?","answer":"No backlink is required."},{"question":"What gets a project rejected?","answer":"A build with no AI coding tool involved."}]', rw_summary='Vibe Coding Gallery is a free dofollow Spanish-language showcase for projects built with AI coding tools, with no backlink. Use your own domain for the follow; domain rating is 11.', rw_fact_points='["Human review with no published timeline","Free listing dofollow on own domain","No badge or return link is expected","Accepts projects built with listed AI coding tools"]', rw_submission_checks='["Write the description in Spanish.","Use your own domain — preview hosts get nofollow.","Name the AI tools you built with."]', rw_seo_title='Vibe Coding Gallery: Free AI-Built Listing, DR 11', rw_seo_description='How to submit to Vibe Coding Gallery: free dofollow Spanish showcase for AI-built projects, no backlink. Own-domain rule from the 2026-11-16 snapshot.' WHERE slug='vibe-coding-gallery';
UPDATE submission_sites SET rw_source_lead='A one-operator AI listicle where a tool with an affiliate programme gets its link swapped for the operator''s own affiliate URL.', rw_what_you_get='A dofollow listing whose outbound link may be replaced with the operator''s affiliate URL if you run an affiliate programme.', rw_you_need='["A live, working product"]', rw_eligibility='You need a working AI tool. Anything that is not AI, or that the operator judges outside unpublished criteria, is refused.', rw_submit_steps='["1 Open /submit-ai-tool/. The copy says only that they will try to add it if it fits their criteria; those criteria are never stated.","2 Fill seven fields on an embedded Tally form: your name, email, tool name, tool link, category as free text, a short description and additional notes. No account, login or captcha.","3 Fill Additional Notes, which is required despite looking optional. Submitting without it returns Please enter a value against that field with no other clue.","4 Submit and read the banner. Tally replaces the form with Form submitted / Thanks for completing this form; nothing is emailed and no reference is issued."]', rw_submit_requirements='["Your name and email","A product name and URL","A category typed as free text","A short description","Additional notes — required despite reading as optional"]', rw_rejection_reasons='["Anything that is not an AI tool, and anything the operator judges outside their unpublished criteria"]', rw_gotchas='["Additional Notes reads optional but is required — omitting it fails with Please enter a value and no indication which field failed.","Where a tool runs an affiliate programme the operator links to their own affiliate URL rather than your domain, so your entry''s link can point elsewhere.","The criteria and review time are never published, so there is nothing to check your entry against and no date to expect."]', rw_faq='[{"question":"How long does AI Tools List approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to AI Tools List?","answer":"Submitting is free."},{"question":"Does an AI Tools List listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 9, though it may be an affiliate URL."},{"question":"Do I need to link back to AI Tools List?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Anything that is not an AI tool, or outside their unpublished criteria."}]', rw_summary='AI Tools List is a free dofollow AI listicle with no backlink, but it swaps your link for an affiliate URL if you run a programme. Unpublished criteria; domain rating is 9.', rw_fact_points='["No published criteria or review time","Free listing with a dofollow link","No badge or return link is expected","Affiliate URLs may replace your link"]', rw_submission_checks='["Fill Additional Notes — it is required.","Expect your link to become an affiliate URL if you have a programme.","No status or timeline to check."]', rw_seo_title='AI Tools List: Free AI Listing, DR 9', rw_seo_description='How to submit to AI Tools List: free dofollow AI listing, no backlink. Affiliate-link caveat from the 2026-11-16 snapshot.' WHERE slug='aitoolslist';
UPDATE submission_sites SET rw_source_lead='A ChatGPT and chatbot database where the only way in is an email to a sibling site''s address, and the link back is followed.', rw_what_you_get='A dofollow listing obtained by emailing a suggestion, with no backlink required.', rw_you_need='["A live, working product","An email client to send the suggestion from"]', rw_eligibility='You need a working product with a ChatGPT, chatbot or GPT-4 angle. Anything without one is refused.', rw_submit_steps='["1 Find the one control. A bar across every page reads Suggest a resource or tool? Click here — the only submission route; there is no form or submit page.","2 Send the suggestion by email. The link is a mailto to a sibling site''s address with the subject preset to Resource Or Tool Suggestion.","3 Wait with nothing to watch. An account exists for bookmarking and a Discord, but neither shows a queue; no review time is stated."]', rw_submit_requirements='["A product name and URL and a short description","A category and a pricing answer, which listings render","An email client, since submission is a plain message"]', rw_rejection_reasons='["Products with no ChatGPT, chatbot or GPT-4 angle"]', rw_gotchas='["There is no submission form anywhere — the only route is a mailto link in the top bar, so there are no fields to fill.","That mailto goes to a different domain from the one you are submitting to, which reads like a mistake and is easy to talk yourself out of sending.","Creating an account here buys bookmarking, updates and a Discord invite, not a submission — signing up looks like the way in and is not."]', rw_faq='[{"question":"How long does chatai[apps] approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to chatai[apps]?","answer":"Submitting is free."},{"question":"Does a chatai[apps] listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 9."},{"question":"Do I need to link back to chatai[apps]?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Products with no ChatGPT, chatbot or GPT-4 angle."}]', rw_summary='chatai[apps] is a chatbot directory where a free dofollow listing is requested by emailing a sibling site''s address. No backlink; domain rating is 9.', rw_fact_points='["Email-only submission with no published review time","Free listing with a dofollow link","No badge or return link is expected","Accepts ChatGPT, chatbot and GPT-4 products"]', rw_submission_checks='["Submit by emailing the suggestion — there is no form.","The address is on a sibling domain; it is intentional.","An account is for bookmarking, not submission."]', rw_seo_title='chatai[apps]: Free Chatbot Listing, DR 9', rw_seo_description='How to submit to chatai[apps]: free dofollow chatbot listing by email, no backlink. Email-route caveat from the 2026-11-16 snapshot.' WHERE slug='chataiapps';
UPDATE submission_sites SET rw_source_lead='A designer community where submissions go to editors rather than to a feed, and every outbound link is nofollow.', rw_what_you_get='A nofollow link picked by editors for a designer audience, if they judge your link worth running.', rw_you_need='["An account created with an email and password","Something a designer would actually open"]', rw_eligibility='You need an account and something ambitious designers should see. A product launch dressed as a link is refused.', rw_submit_steps='["1 Join first. Submit and Sign in sit next to Join in the header, and the form belongs to an account.","2 Send the link. Their prompt is to send something ambitious designers should see — the editorial bar, stated up front.","3 Wait to be chosen. Their copy says submissions go to the editors and the best make the edition, so this is a nomination, not a post."]', rw_submit_requirements='["An account created with an email and password","A link worth an editor''s attention","An optional comment on why it matters, which is what gets a link picked"]', rw_rejection_reasons='["A product launch dressed as a link — the prompt asks for something ambitious designers should see"]', rw_gotchas='["Submitting is not posting: submissions go to editors and only the best make the edition, so most links never appear and nothing tells you yours did not.","Sign-up is email and password with no social route, so an agent that cannot type credentials is out.","Links are nofollow, and the only followed-looking slots carry rel=sponsored — paid inventory, not the editorial feed."]', rw_faq='[{"question":"How long does Designer News approval take?","answer":"No review time is published; editors choose what runs."},{"question":"How much does it cost to submit to Designer News?","answer":"Submitting is free."},{"question":"Does a Designer News listing provide a dofollow link?","answer":"No — links are nofollow on a domain rated 69."},{"question":"Do I need to link back to Designer News?","answer":"No backlink is required."},{"question":"What gets a link rejected?","answer":"A product launch dressed as a link rather than something ambitious designers should see."}]', rw_summary='Designer News is a designer community where free dofollow-free submissions are editor-picked, with no backlink. No published timeline; domain rating is 69.', rw_fact_points='["Editorial nomination with no published timeline","Free submission with a nofollow link","No badge or return link is expected","Accepts design work, tools and articles"]', rw_submission_checks='["Pitch something designers should see, not a launch.","Password signup only — no SSO.","The link is nofollow; sponsored slots are paid."]', rw_seo_title='Designer News: Free Design Link, DR 69', rw_seo_description='How to submit to Designer News: free editor-picked design link, nofollow, no backlink. Editorial bar from the 2026-11-16 snapshot.' WHERE slug='designer-news';
UPDATE submission_sites SET rw_source_lead='A Monday launch board where the free tier''s headline backlink is a prize for the week''s top three, nothing more.', rw_what_you_get='A nofollow launch entry, with a followed link and badges awarded only to the week''s top three.', rw_you_need='["An account — launches carry karma and streaks","A live tool with a name, description and logo","A launch week, since launches run Monday to Monday"]', rw_eligibility='You need an account and a maker-style tool. The whole taxonomy is next-generation tooling, so anything outside that is off-topic.', rw_submit_steps='["1 Create an account. The site runs karma and streaks per maker, so the launch attaches to an account, not an anonymous form.","2 Pick a tier on /pricing: Basic Launch at $0, Premium Launch at $19 or the $299 TikTok and blog feature. Each card ends in its own submit button, so the tier is chosen before the form.","3 Fill the launch with product details, logo, category and week. Launches run Monday to Monday and the queue is public.","4 Launch Monday and compete. The week''s leaderboard decides everything: the top three get exclusive badges, a followed link and an extra week on the landing page."]', rw_submit_requirements='["An account","A product name, description and live URL","A logo and a category","A launch week","An embeddable badge every launch receives"]', rw_rejection_reasons='["Anything that is not a tool a maker would launch — the whole taxonomy is next-generation tooling"]', rw_gotchas='["The homepage promises a badge and a DR 68 followed link for launching, but the pricing page puts both behind a top-three weekly finish; on free the link is a contest prize, not a listing benefit.","Launches are weekly from Monday, so a mid-week free submission waits for the next cohort rather than going live when approved.","Every launch gets an embeddable badge to display; it is offered rather than required."]', rw_faq='[{"question":"How long does NxGn Tools approval take?","answer":"About a week; launches run in Monday-to-Monday cycles."},{"question":"How much does it cost to submit to NxGn Tools?","answer":"Free Basic Launch. Premium Launch $19 once for top-of-queue, two permanent followed links, featured placement, AI-written articles and a logo crown; a $299 tier adds a TikTok and blog feature with Premium included."},{"question":"Does an NxGn Tools listing provide a dofollow link?","answer":"Not by default — site links are nofollow; a followed link goes to the week''s top three."},{"question":"Do I need to link back to NxGn Tools?","answer":"No backlink is required; an embeddable badge is offered to every launch."},{"question":"What gets a launch rejected?","answer":"Anything outside next-generation maker tooling."}]', rw_summary='NxGn Tools is a weekly maker launch board where the free listing is nofollow and the followed link is a top-three prize. No backlink required; domain rating is 69.', rw_fact_points='["Weekly Monday launches with no published review time","Free listing is nofollow; link is a top-three prize","No backlink required; badge offered","Accepts AI tools, SaaS, developer and indie tools"]', rw_submission_checks='["The free followed link is a contest prize, not a benefit.","A mid-week submission waits for Monday.","All links site-wide are nofollow."]', rw_seo_title='NxGn Tools: Free Weekly Launch, DR 69', rw_seo_description='How to launch on NxGn Tools: free weekly nofollow entry, followed link for the top three, no backlink. Rules from the 2026-11-16 snapshot.' WHERE slug='nxgn-tools';
UPDATE submission_sites SET rw_source_lead='A huge local business directory with an AI-tools category bolted on, where every outbound link is nofollow — and a personal email cannot even add a business.', rw_what_you_get='A nofollow local listing, free only to an account on your own company-domain email.', rw_you_need='["An account on an email at the product''s own domain — a Gmail address signs in then gets refused","A business name, category and physical address","A website URL and a description"]', rw_eligibility='You need a company-domain email and a physical address. Personal-email accounts are refused at Add Business, and anyone needing a followed link is out.', rw_submit_steps='["1 Create an account with Google or email: full name, email, password, confirmation and a zipcode, plus the terms box.","2 Add the business via the header +Add Business control, which only works signed in; the guessable /add-business path 404s.","3 Pick a category from about 160 fixed options, from Accommodations to Artificial Intelligence (AI) Tools, and a location; listings render a street address.","4 Consider premium, which puts you under Top Featured Businesses with a Top 10 Best headline — behind the login and a credit system."]', rw_submit_requirements='["An account on a company-domain email — personal addresses refused","A business name, category and physical address","A website URL and description","Optional logo and images"]', rw_rejection_reasons='["An account made with a personal email — it gets a dashboard and no way to add a business — and anyone who needs a followed link"]', rw_gotchas='["The free listing is for company-domain emails only. A Gmail account signs in, gets a dashboard, then is turned away at Add Business with a banner telling you to create a new account on your business address; the account email cannot be changed.","No tier buys a followed link — listings across categories and premium tiers all rendered their website link nofollow.","Listings are built around a physical address, so a software product with no office must file itself at a location it does not occupy.","Premium is 100 credits priced at $49 once, buying Top Featured placement, images, a contact form and anchor-text links in the description."]', rw_faq='[{"question":"How long does Trueen approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to Trueen?","answer":"Joining and the Free Listing are free, but only to a company-domain email. Premium is 100 credits at $49 once for Top Featured placement and extras; VIP and leads products are extra."},{"question":"Does a Trueen listing provide a dofollow link?","answer":"No — every sampled outbound link is nofollow on a domain rated 69."},{"question":"Do I need to link back to Trueen?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"A personal-email account, or needing a followed link."}]', rw_summary='Trueen is a large local business directory with a nofollow listing and no backlink. Free requires a company-domain email and a physical address; domain rating is 69.', rw_fact_points='["No published review time","Free listing is nofollow, no backlink","A company-domain email is required","For local businesses, B2B software and AI tools"]', rw_submission_checks='["Use an email at your own domain — Gmail is refused.","Have a physical address for the listing.","No tier buys a followed link."]', rw_seo_title='Trueen: Free Business Listing, DR 69', rw_seo_description='How to submit to Trueen: free nofollow business listing, no backlink. Company-email requirement from the 2026-11-16 snapshot.' WHERE slug='trueen';
UPDATE submission_sites SET rw_source_lead='A marketplace for buying and selling small startups on verified revenue — listing means publishing your MRR and asking price.', rw_what_you_get='A nofollow listing that prints your revenue, asking price and multiple to a buyer audience.', rw_you_need='["Revenue you are willing to publish and verify","A willingness to be listed for sale","An account, since listing runs through a dashboard"]', rw_eligibility='You need verified revenue and a price. Anything with no revenue, or a maker unwilling to make numbers public, is out.', rw_submit_steps='["1 Open an account. The Add startup control leads into a dashboard; the guessable direct path 404s, so use the site''s own control.","2 Connect the revenue. The premise is verified rather than claimed revenue, so the listing is built around proving the number.","3 Set a price. Listings render revenue, asking price and a multiple side by side, currently from $650 to $2.3M at 0.2x to 9.4x.","4 Go through review. Listings are curated rather than automatic, which is what the verified claim rests on."]', rw_submit_requirements='["An account","Verified revenue for the product","An asking price","A category and a live product URL","Optional tech stack and marketing channels, which the site indexes on"]', rw_rejection_reasons='["A product with no revenue, or a maker who does not want revenue, price and multiple made public"]', rw_gotchas='["This is an acquisition marketplace, not a launch board — listing means publishing your revenue, price and multiple on a public page.","Every outbound link carries rel=nofollow and a ref parameter, so the page passes nothing to your domain.","Revenue must be verified rather than typed, which is the whole basis of the site''s traffic."]', rw_faq='[{"question":"How long does TrustMRR approval take?","answer":"No review time is published; listings are curated."},{"question":"How much does it cost to submit to TrustMRR?","answer":"Listing a startup for sale is the product, with pricing behind the dashboard. They also sell an API, an MCP server, an affiliate programme and legal templates."},{"question":"Does a TrustMRR listing provide a dofollow link?","answer":"No — links are nofollow with a ref parameter, on a domain rated 70."},{"question":"Do I need to link back to TrustMRR?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"A product with no revenue, or an unwillingness to publish the numbers."}]', rw_summary='TrustMRR is a marketplace for selling startups on verified revenue, with a nofollow listing and no backlink. It publishes your MRR and asking price; domain rating is 70.', rw_fact_points='["Curated with no published review time","Nofollow listing with no backlink requirement","Revenue must be verified and public","Accepts revenue-generating SaaS, apps and AI tools"]', rw_submission_checks='["Be ready to publish and verify your revenue.","The listing shows your price and multiple publicly.","The outbound link is nofollow."]', rw_seo_title='TrustMRR: Verified Revenue Listing, DR 70', rw_seo_description='How to list on TrustMRR: nofollow startup-for-sale listing with verified revenue, no backlink. What''s published from the 2026-11-16 snapshot.' WHERE slug='trustmrr';
UPDATE submission_sites SET rw_source_lead='A launch calendar where the free plan is greyed out on every date and $39 buys the slot and the followed link.', rw_what_you_get='A dofollow listing on a paid Featured launch; free listings exist in name but carry a nofollow link.', rw_you_need='["An account, with a full name, username and unique nickname saved in Settings","A product name, slug, a tagline up to 60 and a description up to 600","A live URL and $39 for a Featured launch, since free was unavailable on every date"]', rw_eligibility='You need a completed profile and a product. Nothing structural is published; the flow is open to anyone with an account.', rw_submit_steps='["1 Sign in and finish the profile. /start/product redirects to /login with Google, X, GitHub, LinkedIn or email and password; a new account goes to /settings until a full name, username and unique nickname are saved.","2 Give the URL. The wizard opens on a Product URL field and checks whether the product already exists.","3 Seven steps: main info, links, media, makers, built with, finance and launch.","4 Pick a date then a plan. Each day lists Free and Featured; clicking opens a dialog with Featured $39 preselected and Free disabled, titled Free is not available on the selected launch date.","5 Wait for their team''s review; no time is published."]', rw_submit_requirements='["An account with a completed profile","A product name and URL slug","A tagline up to 60 and a description up to 600 characters","A live website URL","Up to three topics","Optional thumbnail and gallery images","$39 for the Featured plan, the only one selectable on the dates checked"]', rw_rejection_reasons='["Nothing structural is published; the flow is open to anyone with an account"]', rw_gotchas='["The free plan exists on the page but not in practice: Free showed unavailable on all thirty offered dates, with Featured $39 preselected.","The followed link is a Featured perk sold as a permanent dofollow backlink; a free product link is nofollow.","The wizard keeps state in the page — a reload drops everything, with no drafts, so all seven steps must be done in one sitting.","A new account is bounced to Settings before the wizard, so it asks for a profile first, not the product."]', rw_faq='[{"question":"How long does Versily approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to Versily?","answer":"Free $0 was disabled on all thirty dates offered; Featured $39 once buys thirty days on the homepage, a badge, priority search and a permanent followed link."},{"question":"Does a Versily listing provide a dofollow link?","answer":"No on free — the product link is nofollow; a followed link comes with Featured."},{"question":"Do I need to link back to Versily?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Nothing structural is published."}]', rw_summary='Versily is a launch calendar where free is greyed out on every date and $39 buys the Featured slot and followed link. No backlink required; domain rating is 70.', rw_fact_points='["Free unavailable; $39 Featured in practice","Free link nofollow; Featured is dofollow","No badge or return link is expected","Accepts SaaS, indie products, AI tools and more"]', rw_submission_checks='["Budget for $39 — free was disabled on every date.","Complete your profile before the wizard.","Finish all seven steps in one sitting."]', rw_seo_title='Versily: $39 Featured Launch, DR 70', rw_seo_description='How to launch on Versily: $39 Featured dofollow launch, no backlink. Free greyed out from the 2026-11-16 snapshot.' WHERE slug='versily';
UPDATE submission_sites SET rw_source_lead='A large AI directory indexed by job and task, where the free queue runs 30 to 90 days and every outbound link is an internal redirect.', rw_what_you_get='A nofollow listing reached through an internal redirect, queued 30 to 90 days free.', rw_you_need='["An account — the submit flow starts from Sign Up","An AI product — the whole taxonomy is AI categories, jobs and tasks","A live URL, name and description"]', rw_eligibility='You need an account and an AI product. Anything without an AI angle has no category, and a tool failing their unpublished standards is out.', rw_submit_steps='["1 Open /submit. It is a plan chooser, not a form: Free Listing at $0 a month or Fast Lane at $129 once, each with its own Submit Now button.","2 Sign up via the header control beside Submit Tool; the submission attaches to the account.","3 Fill the tool details — name, URL, description and the categories, jobs and tasks it belongs to, which is what the site indexes by.","4 Wait out the queue. Free states a 30 to 90 day listing time and that placement is not guaranteed; Fast Lane is 24 to 48 hours."]', rw_submit_requirements='["An account","A tool name, live URL and description","Categories, and ideally the jobs and tasks it serves","Optional logo and screenshots"]', rw_rejection_reasons='["Anything without an AI angle, or a tool failing their unpublished listing standards"]', rw_gotchas='["The Visit Website button points at an internal /go/ redirect on their own domain, so the listing passes no link value whatever tier.","The free card states the quiet part: no guaranteed placement and a 30 to 90 day queue — waiting three months and never appearing is a stated outcome.","The $129 refund is conditional on the tool not meeting standards that are not published anywhere in the flow."]', rw_faq='[{"question":"How long does AI Tools approval take?","answer":"Two to three months on free; Fast Lane is 24 to 48 hours."},{"question":"How much does it cost to submit to AI Tools?","answer":"Free at $0 with a 30-90 day queue and no placement guarantee; Fast Lane $129 once for 24-48 hour placement, guaranteed or refunded, with verified page and newsletter eligibility."},{"question":"Does an AI Tools listing provide a dofollow link?","answer":"No — links are nofollow internal redirects on a domain rated 67."},{"question":"Do I need to link back to AI Tools?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Anything without an AI angle, or a tool failing their unpublished standards."}]', rw_summary='AI Tools is a job-and-task-indexed AI directory with a free nofollow listing behind a 30-90 day queue. No backlink required; domain rating is 67.', rw_fact_points='["Free queue of 30 to 90 days","Nofollow internal redirect, no backlink","No guaranteed placement on free","Accepts AI tools, automation and productivity tools"]', rw_submission_checks='["The Visit link is an internal redirect — no link equity.","Free explicitly offers no placement guarantee.","The $129 refund bar is unpublished."]', rw_seo_title='AI Tools: Free Job-Indexed Listing, DR 67', rw_seo_description='How to submit to AI Tools: free nofollow AI listing in a 30-90 day queue, no backlink. Internal redirect from the 2026-11-16 snapshot.' WHERE slug='aitools-inc';
UPDATE submission_sites SET rw_source_lead='A curated directory whose free lane costs a badge and a week, and labels you Unverified.', rw_what_you_get='A dofollow listing that is publicly marked Unverified on the free tier until you pay for the Verified badge.', rw_you_need='["An account via email and password or one of five OAuth providers","Their badge on your homepage for the free lane"]', rw_eligibility='You need an account and — on free — a badge. Anything manual review finds off-topic is refused, since every listing is quality-checked for relevance.', rw_submit_steps='["1 Create a free account. Submit Your Website lands on a create-account step: name, email, password and terms, or Google, GitHub, X, LinkedIn or Discord.","2 Site details: URL with an AI Analyze that fills the rest, name, tagline, one searchable category, up to five tags, technologies and AI tools, a markdown description, logo, up to five preview images, a launch date and social links.","3 Pick a plan: Starter $19, Premium $39, Exclusive $99 or Featured Monthly $30, with the free card underneath — paid for in trade, their badge, a week or more of review and an Unverified label.","4 Submit for Free, then the badge. The listing saves as Pending Review; paste the badge, press I installed it, verify now, and it publishes about seven days later."]', rw_submit_requirements='["A website URL, name and tagline","One category and a 100 to 1,000 character markdown description","A 512x512 logo and up to five preview images","Their badge on your homepage for the free lane","Optional tags, technologies and AI tools"]', rw_rejection_reasons='["Anything manual review finds off-topic — every listing is quality-checked for relevance"]', rw_gotchas='["A free listing is publicly marked Unverified beside paid Verified Business badges, and only a paid plan removes that label.","The submission form does not exist until the account does — Submit Your Website lands on account creation.","Featured Monthly at $30 buys placement only; no followed link comes with it."]', rw_faq='[{"question":"How long does CodeTrendy approval take?","answer":"About a week after badge verification."},{"question":"How much does it cost to submit to CodeTrendy?","answer":"Free in trade for a badge, a week-plus review and an Unverified label. Starter $19 once adds instant publication, a Verified badge, no badge requirement and a followed link; higher tiers add featured time."},{"question":"Does a CodeTrendy listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 67, while the free badge stays live."},{"question":"Do I need to link back to CodeTrendy?","answer":"Yes — their badge is required on the free lane."},{"question":"What gets a listing rejected?","answer":"Anything manual review finds off-topic."}]', rw_summary='CodeTrendy is a curated directory where a free dofollow listing costs a badge and carries an Unverified label. No other backlink is needed; domain rating is 67.', rw_fact_points='["Free review about a week after badge verification","Dofollow link with a badge required on free","A public Unverified label on free","Accepts startups, SaaS, indie products and websites"]', rw_submission_checks='["Free listings are marked Unverified publicly.","Install the badge to publish after review.","Featured Monthly buys placement, not a link."]', rw_seo_title='CodeTrendy: Free Badge Listing, DR 67', rw_seo_description='How to submit to CodeTrendy: free dofollow listing for a badge, week-long review, Unverified label. Rules from the 2026-11-16 snapshot.' WHERE slug='codetrendy';
